INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辉煌", "is_correct": true, "explanation": "正确。“灯火辉煌”指灯光明亮、华丽，与“像白天一样亮”相符。"}, {"text": "昏暗", "is_correct": false, "explanation": "语义：“昏暗”与“像白天一样亮”直接矛盾。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”多用于夜色、环境，不说灯火漆黑。"}, {"text": "朴素", "is_correct": false, "explanation": "搭配：“朴素”指风格简单，不能用来修饰灯火。"}], "explanations": {"辉煌": "正确。“灯火辉煌”指灯光明亮、华丽，与“像白天一样亮”相符。", "昏暗": "语义：“昏暗”与“像白天一样亮”直接矛盾。", "漆黑": "搭配：“漆黑”多用于夜色、环境，不说灯火漆黑。", "朴素": "搭配：“朴素”指风格简单，不能用来修饰灯火。"}, "sentence_index": 0, "correct_answer": "辉煌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小孩很辉煌，每天都哭个不停。", "explanation": "这里应该用〈吵闹〉。辉煌不用来形容小孩的状态。"}, {"text": "这束花的香味很辉煌，屋里都闻得到。", "explanation": "这里应该用〈浓郁〉。辉煌形容灯光、宫殿等光彩夺目的事物，不用来形容香味。"}, {"text": "早晨的空气很辉煌，让人精神一振。", "explanation": "这里应该用〈清新〉。辉煌多指灯光、宫殿等大而亮的场面，不用来形容空气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辉煌", "is_correct": true, "explanation": "正确。装修华丽、灯光明亮，与“水晶灯特别大”相符。"}, {"text": "简陋", "is_correct": false, "explanation": "语义：“简陋”与“水晶灯特别大”的高档感矛盾。"}, {"text": "阴暗", "is_correct": false, "explanation": "语义：“阴暗”与水晶灯的明亮相矛盾。"}, {"text": "破旧", "is_correct": false, "explanation": "搭配：“破旧”多指物体老化，不说装得十分破旧，且与“水晶灯特别大”不协调。"}], "explanations": {"辉煌": "正确。装修华丽、灯光明亮，与“水晶灯特别大”相符。", "简陋": "语义：“简陋”与“水晶灯特别大”的高档感矛盾。", "阴暗": "语义：“阴暗”与水晶灯的明亮相矛盾。", "破旧": "搭配：“破旧”多指物体老化，不说装得十分破旧，且与“水晶灯特别大”不协调。"}, "sentence_index": 6, "correct_answer": "辉煌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的态度很辉煌，大家都很喜欢她。", "explanation": "这里应该用〈和善〉。辉煌不用来形容态度。"}, {"text": "她的声音很辉煌，像小鸟一样好听。", "explanation": "这里应该用〈甜美〉。辉煌不用来形容声音的悦耳程度。"}, {"text": "这杯咖啡很辉煌，喝起来有点苦。", "explanation": "这里应该用〈苦涩〉。辉煌不用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们参观了一座很辉煌宫殿。", "corrected_sentence": "我们参观了一座很辉煌的宫殿。", "error_description": "“很辉煌”修饰名词“宫殿”时要加“的”，应说“很辉煌的宫殿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山下的小城灯火辉煌辉煌，夜里特别漂亮。", "corrected_sentence": "山下的小城灯火辉煌，夜里特别漂亮。", "error_description": "“辉煌”是双音节形容词，不能重叠成“辉煌辉煌”，这里只说“灯火辉煌”一次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92934, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡", "is_correct": true, "explanation": "“暗淡”与“辉煌”是反义词，指不出色、不光彩，与“成就极其出色”相反。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”与“辉煌”没有反义关系，不能构成对立。"}, {"text": "浅", "is_correct": false, "explanation": "“浅”与“辉煌”没有反义关系，不能构成对立。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”与“辉煌”没有反义关系，不能构成对立。"}], "correct_answer": "暗淡", "explanations": {"暗淡": "“暗淡”与“辉煌”是反义词，指不出色、不光彩，与“成就极其出色”相反。", "硬": "“硬”与“辉煌”没有反义关系，不能构成对立。", "浅": "“浅”与“辉煌”没有反义关系，不能构成对立。", "甜": "“甜”与“辉煌”没有反义关系，不能构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92934, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡", "is_correct": true, "explanation": "“暗淡”与“辉煌”是反义词，指不出色、不光彩，与“成绩辉煌”相反。"}, {"text": "冷", "is_correct": false, "explanation": "“冷”与“辉煌”没有反义关系，不能构成对立。"}, {"text": "远", "is_correct": false, "explanation": "“远”与“辉煌”没有反义关系，不能构成对立。"}, {"text": "苦", "is_correct": false, "explanation": "“苦”与“辉煌”没有反义关系，不能构成对立。"}], "correct_answer": "暗淡", "explanations": {"暗淡": "“暗淡”与“辉煌”是反义词，指不出色、不光彩，与“成绩辉煌”相反。", "冷": "“冷”与“辉煌”没有反义关系，不能构成对立。", "远": "“远”与“辉煌”没有反义关系，不能构成对立。", "苦": "“苦”与“辉煌”没有反义关系，不能构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92934, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容成就、成绩等极其出色。", "primary_collocate": null, "pronunciation": "huī huáng", "ipa": "xweɪ˥ xwɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家公司过去十年取得了辉煌的成绩。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的一生很辉煌，做出了很多贡献。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国队在比赛中取得了辉煌的胜利。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老科学家有辉煌的成就，大家都很尊敬他。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年轻时的舞蹈生涯非常辉煌。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的学校有一段辉煌的历史。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支球队曾经很辉煌，拿过五次冠军。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力工作，想为公司创造辉煌的未来。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然过去很辉煌，但是现在这家老店生意不好。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奥运会上，他拿到金牌，成绩辉煌，全国都为他高兴。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "輝煌", "label": "繁体"}], "register": "书面", "sense_fingerprint": "成就、成绩、历史等极其出色，令人骄傲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辉煌", "is_correct": true, "explanation": "正确。“辉煌”形容成绩极其出色，与“取得了……的成绩”相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气或物体含水多，不能修饰成绩。"}, {"text": "魁梧", "is_correct": false, "explanation": "体貌：“魁梧”形容人的身材高大，不能修饰成绩。"}, {"text": "荒凉", "is_correct": false, "explanation": "搭配：“荒凉”多指地方、景色的冷清，不能修饰成绩。"}], "explanations": {"辉煌": "正确。“辉煌”形容成绩极其出色，与“取得了……的成绩”相符。", "潮湿": "搭配：“潮湿”形容空气或物体含水多，不能修饰成绩。", "魁梧": "体貌：“魁梧”形容人的身材高大，不能修饰成绩。", "荒凉": "搭配：“荒凉”多指地方、景色的冷清，不能修饰成绩。"}, "sentence_index": 0, "correct_answer": "辉煌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗水很辉煌，喝下去很解渴。", "explanation": "这里应该用〈清凉〉。辉煌形容成就出色或光彩夺目，不用来形容水的温度和感觉。"}, {"text": "她的脾气很辉煌，大家都不敢惹她。", "explanation": "这里应该用〈火爆〉。辉煌用于成就、成绩时指极其出色，不用来形容脾气。"}, {"text": "这碗汤很辉煌，喝起来特别香。", "explanation": "这里应该用〈鲜美〉。辉煌不用来形容汤的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辉煌", "is_correct": true, "explanation": "正确。“拿过五次冠军”说明球队曾经成绩极其出色，与“很辉煌”相符。"}, {"text": "寒酸", "is_correct": false, "explanation": "语义：“寒酸”指穷困、不体面，与“拿过五次冠军”的成绩矛盾。"}, {"text": "黯淡", "is_correct": false, "explanation": "语义：“黯淡”指不光彩、不出色，与“拿过五次冠军”矛盾。"}, {"text": "萧条", "is_correct": false, "explanation": "搭配：“萧条”多指市场、经济或地方冷清，一般不用来形容球队。"}], "explanations": {"辉煌": "正确。“拿过五次冠军”说明球队曾经成绩极其出色，与“很辉煌”相符。", "寒酸": "语义：“寒酸”指穷困、不体面，与“拿过五次冠军”的成绩矛盾。", "黯淡": "语义：“黯淡”指不光彩、不出色，与“拿过五次冠军”矛盾。", "萧条": "搭配：“萧条”多指市场、经济或地方冷清，一般不用来形容球队。"}, "sentence_index": 6, "correct_answer": "辉煌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗粥很辉煌，喝起来很暖和。", "explanation": "这里应该用〈清淡〉。辉煌不用来形容食物的口味。"}, {"text": "小鸟的叫声很辉煌，早上一听就很舒服。", "explanation": "这里应该用〈清脆〉。辉煌不用来形容声音。"}, {"text": "这块蛋糕很辉煌，大家都抢着吃。", "explanation": "这里应该用〈香甜〉。辉煌不用来形容食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位运动员多年来创造了辉煌辉煌的纪录。", "corrected_sentence": "这位运动员多年来创造了辉煌的纪录。", "error_description": "“辉煌”是双音节形容词，不能重叠成“辉煌辉煌”，这里只说“辉煌的纪录”一次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奥运会上，他拿到金牌，取得了辉煌地成绩，全国都为他高兴。", "corrected_sentence": "奥运会上，他拿到金牌，取得了辉煌的成绩，全国都为他高兴。", "error_description": "“辉煌”修饰名词“成绩”要用“的”，不用“地”（“地”用于动词前作状语）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "面对", "is_correct": true, "explanation": "反义。逃避是躲开，面对是正视、直接应对，二者意思相反。"}, {"text": "完成", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指悠闲地走路。"}, {"text": "购买", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指买东西。"}], "correct_answer": "面对", "explanations": {"面对": "反义。逃避是躲开，面对是正视、直接应对，二者意思相反。", "完成": "同为动词，但与逃避没有反义关系。", "散步": "同为动词，但与逃避没有反义关系，指悠闲地走路。", "购买": "同为动词，但与逃避没有反义关系，指买东西。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "面对", "is_correct": true, "explanation": "反义。逃避是躲开，面对是正视、直接应对，二者意思相反。"}, {"text": "阅读", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指看书报。"}, {"text": "修理", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指把坏的东西弄好。"}, {"text": "打扫", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指清除垃圾和灰尘。"}], "correct_answer": "面对", "explanations": {"面对": "反义。逃避是躲开，面对是正视、直接应对，二者意思相反。", "阅读": "同为动词，但与逃避没有反义关系，指看书报。", "修理": "同为动词，但与逃避没有反义关系，指把坏的东西弄好。", "打扫": "同为动词，但与逃避没有反义关系，指清除垃圾和灰尘。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逃避是遇到不想做的事，就躲开不去面对。", "primary_collocate": null, "pronunciation": "táo bì", "ipa": "tʰɑʊ̯˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "他怕考试，所以逃避复习。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别总是逃避做家务。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟一听写作业就逃避。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直逃避和老板见面。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难题，不要逃避。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在逃避给妈妈打电话。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明为了逃避洗碗，说自己头疼。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想再逃避了，今天就去说。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他逃避跟朋友见面，因为怕借钱。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥逃避工作，整天在家玩游戏。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃避了", "label": "体标"}, {"form": "逃避过", "label": "体标"}, {"form": "逃避着", "label": "体标"}], "register": "中性", "sense_fingerprint": "遇到不想做的具体事情就躲开不做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd93837-ff1f-44d8-9b8c-6d7a0431f7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。逃避（táo bì）：遇到不想做的事就躲开不做。"}, {"text": "投币", "is_correct": false, "explanation": "投币（tóu bì）与逃避（táo bì）第一个音节韵母不同（ao 与 ou），意思是投入硬币。"}, {"text": "倒闭", "is_correct": false, "explanation": "倒闭（dǎo bì）第一个音节声母 d 与 t 不同，且声调为第三声，意思是企业停业破产。"}, {"text": "淘米", "is_correct": false, "explanation": "淘米（táo mǐ）第二个音节声母 m 与 b 不同，且声调为第三声，意思是用水洗米。"}, {"text": "逃逸", "is_correct": false, "explanation": "逃逸（táo yì）第二个音节少了声母 b，读 yì，意思是逃跑、溜走。"}], "explanations": {"逃避": "正确。逃避（táo bì）：遇到不想做的事就躲开不做。", "投币": "投币（tóu bì）与逃避（táo bì）第一个音节韵母不同（ao 与 ou），意思是投入硬币。", "倒闭": "倒闭（dǎo bì）第一个音节声母 d 与 t 不同，且声调为第三声，意思是企业停业破产。", "淘米": "淘米（táo mǐ）第二个音节声母 m 与 b 不同，且声调为第三声，意思是用水洗米。", "逃逸": "逃逸（táo yì）第二个音节少了声母 b，读 yì，意思是逃跑、溜走。"}, "sentence_index": null, "correct_answer": "逃避"}, "level_3": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。“他怕考试，所以逃避复习”：因为怕考试而躲开复习，语义通顺。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示乐在其中，与“怕考试”的因果关系相矛盾，句子不通。"}, {"text": "迎接", "is_correct": false, "explanation": "搭配：“迎接”多接挑战、客人，不能说“迎接复习”。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”接的是人或言行，“嘲笑复习”不成立，与“怕考试”的因果也不通，句子不通。"}], "explanations": {"逃避": "正确。“他怕考试，所以逃避复习”：因为怕考试而躲开复习，语义通顺。", "享受": "语义：“享受”表示乐在其中，与“怕考试”的因果关系相矛盾，句子不通。", "迎接": "搭配：“迎接”多接挑战、客人，不能说“迎接复习”。", "嘲笑": "搭配：“嘲笑”接的是人或言行，“嘲笑复习”不成立，与“怕考试”的因果也不通，句子不通。"}, "sentence_index": 0, "correct_answer": "逃避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该勇敢地逃避困难。", "explanation": "这里应该用〈面对〉。逃避表示躲开不愿做的事，与“勇敢地”矛盾；面对困难才用“面对”。"}, {"text": "我每周都积极逃避班级活动。", "explanation": "这里应该用〈参加〉。逃避用于躲开不愿做的事，不能用来说主动投入的班级活动。"}, {"text": "他迅速逃避迎面飞来的礼物。", "explanation": "这里应该用〈接住〉。逃避表示躲开不愿面对的事，人们不会躲开想要的礼物，应说“接住”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。逃避（táo bì）：遇到不想做的事就躲开不做。"}, {"text": "淘洗", "is_correct": false, "explanation": "淘洗（táo xǐ）第二个音节声母 x 与 b 不同，且声调为第三声，意思是用水冲洗并筛去杂质。"}, {"text": "台币", "is_correct": false, "explanation": "台币（tái bì）第一个音节韵母为 ai，与 ao 不同，意思是台湾地区的货币。"}, {"text": "逃匿", "is_correct": false, "explanation": "逃匿（táo nì）第二个音节声母 n 与 b 不同，意思是逃跑并隐藏。"}, {"text": "桃李", "is_correct": false, "explanation": "桃李（táo lǐ）第二个音节声母 l 与 b 不同，且声调为第三声，意思是桃树和李树。"}], "explanations": {"逃避": "正确。逃避（táo bì）：遇到不想做的事就躲开不做。", "淘洗": "淘洗（táo xǐ）第二个音节声母 x 与 b 不同，且声调为第三声，意思是用水冲洗并筛去杂质。", "台币": "台币（tái bì）第一个音节韵母为 ai，与 ao 不同，意思是台湾地区的货币。", "逃匿": "逃匿（táo nì）第二个音节声母 n 与 b 不同，意思是逃跑并隐藏。", "桃李": "桃李（táo lǐ）第二个音节声母 l 与 b 不同，且声调为第三声，意思是桃树和李树。"}, "sentence_index": null, "correct_answer": "逃避"}, "level_3": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。“小明为了逃避洗碗，说自己头疼”：找借口躲开洗碗这件事，动机与行为相符，语义通顺。"}, {"text": "热爱", "is_correct": false, "explanation": "语义：“小明为了热爱洗碗，说自己头疼”动机自相矛盾，句子不通。"}, {"text": "咨询", "is_correct": false, "explanation": "搭配：“咨询”多接问题、意见，不能说“咨询洗碗”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”接的是场所、展品，不能说“参观洗碗”。"}], "explanations": {"逃避": "正确。“小明为了逃避洗碗，说自己头疼”：找借口躲开洗碗这件事，动机与行为相符，语义通顺。", "热爱": "语义：“小明为了热爱洗碗，说自己头疼”动机自相矛盾，句子不通。", "咨询": "搭配：“咨询”多接问题、意见，不能说“咨询洗碗”。", "参观": "搭配：“参观”接的是场所、展品，不能说“参观洗碗”。"}, "sentence_index": 6, "correct_answer": "逃避"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家热情地逃避远道而来的客人。", "explanation": "这里应该用〈迎接〉。逃避是躲开不愿面对的事，不能用来描述热情欢迎客人。"}, {"text": "大家在广场上逃避胜利。", "explanation": "这里应该用〈庆祝〉。逃避表示躲开，不能用于值得高兴的胜利。"}, {"text": "我们要逃避时间。", "explanation": "这里应该用〈珍惜〉。逃避不能用于时间这类躲不开的对象，应说“珍惜时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直逃避得这件事。", "corrected_sentence": "他一直逃避这件事。", "error_description": "错误形式“逃避得这件事”，多出了“得”。正确形式“逃避这件事”。“得”只用于动词后接补语，“逃避”直接带宾语时不加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不敢逃避了责任。", "corrected_sentence": "他不敢逃避责任。", "error_description": "错误形式：“不敢逃避了责任”，在动词后多加了“了”。正确形式：“不敢逃避责任”。原因：“不敢”是否定的能愿动词，表示没有胆量去做，与表示完成的“了”不能搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
