INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92936, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "躲开不愿或不敢面对的事物。", "primary_collocate": null, "pronunciation": "táo bì", "ipa": "tʰɑʊ̯˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "他用喝酒来逃避现实。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事就要负责，不能逃避责任。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她逃避着失败带来的痛苦。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人去世后，他一直逃避那段回忆。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "逃避问题，问题不会消失。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是逃避自己的错误。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对困难，你不能只想逃避。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把工作放一边，想逃避压力。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "逃避了十年，他终于说出真话。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到失败就逃避，是不会进步的。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃避了", "label": "体标"}, {"form": "逃避过", "label": "体标"}, {"form": "逃避着", "label": "体标"}], "register": "中性", "sense_fingerprint": "躲开现实、责任、失败等不敢面对的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd93837-ff1f-44d8-9b8c-6d7a0431f7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92936, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。逃避（táo bì）：躲开不敢面对的现实、责任等。"}, {"text": "倒闭", "is_correct": false, "explanation": "倒闭（dǎo bì）第一个音节声母 d 与 t 不同，且声调为第三声，意思是企业停业破产。"}, {"text": "淘米", "is_correct": false, "explanation": "淘米（táo mǐ）第二个音节声母 m 与 b 不同，且声调为第三声，意思是用水洗米。"}, {"text": "逃逸", "is_correct": false, "explanation": "逃逸（táo yì）第二个音节少了声母 b，读 yì，意思是逃跑、溜走。"}, {"text": "台币", "is_correct": false, "explanation": "台币（tái bì）第一个音节韵母为 ai，与 ao 不同，意思是台湾地区的货币。"}], "explanations": {"逃避": "正确。逃避（táo bì）：躲开不敢面对的现实、责任等。", "倒闭": "倒闭（dǎo bì）第一个音节声母 d 与 t 不同，且声调为第三声，意思是企业停业破产。", "淘米": "淘米（táo mǐ）第二个音节声母 m 与 b 不同，且声调为第三声，意思是用水洗米。", "逃逸": "逃逸（táo yì）第二个音节少了声母 b，读 yì，意思是逃跑、溜走。", "台币": "台币（tái bì）第一个音节韵母为 ai，与 ao 不同，意思是台湾地区的货币。"}, "sentence_index": null, "correct_answer": "逃避"}, "level_3": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。“他用喝酒来逃避现实”：喝酒是躲开现实的做法，语义通顺。"}, {"text": "面对", "is_correct": false, "explanation": "语义：“面对”与“用喝酒”躲避现实的做法相反，句子说不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多接景物、作品，不能说“欣赏现实”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受现实”与“用喝酒”的用意不符，句子不通。"}], "explanations": {"逃避": "正确。“他用喝酒来逃避现实”：喝酒是躲开现实的做法，语义通顺。", "面对": "语义：“面对”与“用喝酒”躲避现实的做法相反，句子说不通。", "欣赏": "搭配：“欣赏”多接景物、作品，不能说“欣赏现实”。", "享受": "语义：“享受现实”与“用喝酒”的用意不符，句子不通。"}, "sentence_index": 0, "correct_answer": "逃避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "观众们全都逃避她的精彩表演。", "explanation": "这里应该用〈欣赏〉。逃避表示躲开不愿面对的事，不能用于值得观看的精彩表演，应说“欣赏她的精彩表演”。"}, {"text": "我们要逃避这段珍贵的友谊。", "explanation": "这里应该用〈珍惜〉。逃避表示躲开不愿面对的事，不能用于珍贵的友谊。"}, {"text": "大家热情地逃避新来的同学。", "explanation": "这里应该用〈迎接〉。逃避是躲开，不能用来描述热情欢迎新同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92936, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。逃避（táo bì）：躲开不敢面对的现实、责任等。"}, {"text": "投币", "is_correct": false, "explanation": "投币（tóu bì）与逃避（táo bì）第一个音节韵母不同（ao 与 ou），意思是投入硬币。"}, {"text": "淘洗", "is_correct": false, "explanation": "淘洗（táo xǐ）第二个音节声母 x 与 b 不同，且声调为第三声，意思是用水冲洗并筛去杂质。"}, {"text": "逃匿", "is_correct": false, "explanation": "逃匿（táo nì）第二个音节声母 n 与 b 不同，意思是逃跑并隐藏。"}, {"text": "桃李", "is_correct": false, "explanation": "桃李（táo lǐ）第二个音节声母 l 与 b 不同，且声调为第三声，意思是桃树和李树。"}], "explanations": {"逃避": "正确。逃避（táo bì）：躲开不敢面对的现实、责任等。", "投币": "投币（tóu bì）与逃避（táo bì）第一个音节韵母不同（ao 与 ou），意思是投入硬币。", "淘洗": "淘洗（táo xǐ）第二个音节声母 x 与 b 不同，且声调为第三声，意思是用水冲洗并筛去杂质。", "逃匿": "逃匿（táo nì）第二个音节声母 n 与 b 不同，意思是逃跑并隐藏。", "桃李": "桃李（táo lǐ）第二个音节声母 l 与 b 不同，且声调为第三声，意思是桃树和李树。"}, "sentence_index": null, "correct_answer": "逃避"}, "level_3": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。“面对困难，你不能只想逃避”：与句中的“面对”形成对照，语义通顺。"}, {"text": "迎接", "is_correct": false, "explanation": "配价：“迎接”需要带宾语（如“迎接挑战”），句末没有宾语，不能这样单独使用。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”需要带宾语，句末没有宾语，不能这样单独使用。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与“面对困难”的语境不符，句子不通。"}], "explanations": {"逃避": "正确。“面对困难，你不能只想逃避”：与句中的“面对”形成对照，语义通顺。", "迎接": "配价：“迎接”需要带宾语（如“迎接挑战”），句末没有宾语，不能这样单独使用。", "欢迎": "配价：“欢迎”需要带宾语，句末没有宾语，不能这样单独使用。", "嘲笑": "语义：“嘲笑”与“面对困难”的语境不符，句子不通。"}, "sentence_index": 6, "correct_answer": "逃避"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家一起逃避这次成功。", "explanation": "这里应该用〈庆祝〉。逃避表示躲开不愿面对的事，不能用于值得高兴的成功。"}, {"text": "大家都在逃避她的勇气。", "explanation": "这里应该用〈赞美〉。逃避不能用于勇气这类值得称赞的品质。"}, {"text": "老师当众逃避了我的进步。", "explanation": "这里应该用〈表扬〉。逃避表示躲开，不能用于老师对进步的肯定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总是逃避得自己的责任。", "corrected_sentence": "他总是逃避自己的责任。", "error_description": "错误形式“逃避得自己的责任”，多出了“得”。正确形式“逃避自己的责任”。“得”只用于动词后接补语，“逃避”直接带宾语时不加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她逃避这个问题过。", "corrected_sentence": "她逃避这个问题。", "error_description": "错误形式：“逃避这个问题过”，“过”位于宾语之后，位置错误。“过”表示经历，须紧跟动词，可改为“逃避过这个问题”；若句意不需要表示经历，则直接删去“过”，改为“她逃避这个问题。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
