INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市周围靠近市区的区域。", "primary_collocate": null, "pronunciation": "jiāo qū", "ipa": "tɕjɑʊ˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这座城市的郊区正在快速发展。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机场建在城市的郊区。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在郊区的一所学校当老师。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "郊区的房价比市区便宜很多。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁已经修到郊区了。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京郊区有很多公园和农场。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把工厂搬到了郊区。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区和郊区的交通都很方便。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院在郊区，离市中心有点远。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天从郊区坐车去市区上班。", "target_word": "郊区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个郊区", "label": "量词（个）"}, {"form": "郊區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市周围、靠近市区的行政或地理区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92938, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "郊区", "is_correct": true, "explanation": "郊区（jiāo qū）：城市周围靠近市区的区域。"}, {"text": "教区", "is_correct": false, "explanation": "jiào（第四声）与 jiāo（第一声）声调不同，教区指宗教的管辖区域，意思不同。"}, {"text": "娇妻", "is_correct": false, "explanation": "娇妻（jiāo qī）：受宠爱的妻子；qī 与 qū 只差韵母，声调相同，意思不同。"}, {"text": "叫屈", "is_correct": false, "explanation": "叫屈（jiào qū）：诉说委屈、喊冤；jiào（第四声）与 jiāo（第一声）声调不同，意思也完全不同。"}], "explanations": {"郊区": "郊区（jiāo qū）：城市周围靠近市区的区域。", "教区": "jiào（第四声）与 jiāo（第一声）声调不同，教区指宗教的管辖区域，意思不同。", "娇妻": "娇妻（jiāo qī）：受宠爱的妻子；qī 与 qū 只差韵母，声调相同，意思不同。", "叫屈": "叫屈（jiào qū）：诉说委屈、喊冤；jiào（第四声）与 jiāo（第一声）声调不同，意思也完全不同。"}, "sentence_index": null, "correct_answer": "郊区"}, "level_3": {"options": [{"text": "郊区", "is_correct": true, "explanation": "郊区可以快速发展，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是城市，不会快速发展，句意矛盾。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不能“快速发展”，句意矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“快速发展”搭配的是城市、产业，手机不能作为这里的发展主体。"}], "explanations": {"郊区": "郊区可以快速发展，符合句意。", "厨房": "语义：厨房不是城市，不会快速发展，句意矛盾。", "课本": "语义：课本是书，不能“快速发展”，句意矛盾。", "手机": "搭配：“快速发展”搭配的是城市、产业，手机不能作为这里的发展主体。"}, "sentence_index": 0, "correct_answer": "郊区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司在一张郊区建了新工厂。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，郊区不能用“张”来数。"}, {"text": "我家附近有一颗郊区。", "explanation": "这里应该用〈个〉。“颗”用于小而圆的东西，郊区不能用“颗”来数。"}, {"text": "这根郊区很长。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，郊区不能用“根”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "郊区", "is_correct": true, "explanation": "工厂可以搬到郊区，符合句意。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜装不下工厂，句意矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“搬到”的地点应是地面上的空间，天空不能搬入工厂。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包装不下工厂，句意矛盾。"}], "explanations": {"郊区": "工厂可以搬到郊区，符合句意。", "衣柜": "语义：衣柜装不下工厂，句意矛盾。", "天空": "搭配：“搬到”的地点应是地面上的空间，天空不能搬入工厂。", "书包": "语义：书包装不下工厂，句意矛盾。"}, "sentence_index": 6, "correct_answer": "郊区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的朋友住在一条郊区，很安静。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，郊区不能用“条”来数。"}, {"text": "这只郊区有很多人家。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对物品中的一件，郊区不能用“只”来数。"}, {"text": "我们把一把郊区买下来了。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，郊区不能用“把”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的学校郊区，离家很远。", "corrected_sentence": "我的学校在郊区，离家很远。", "error_description": "介词遗漏：表示地点要用“在”引出，应说“在郊区”，不能直接说“学校郊区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条地铁线已经修郊区了。", "corrected_sentence": "这条地铁线已经修到郊区了。", "error_description": "补语遗漏：表示地点要用“到”引出动作的终点，应说“修到郊区”，不能只说“修郊区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
