INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "含碳量较低、坚硬而有韧性的铁碳合金。", "primary_collocate": null, "pronunciation": "gāng", "ipa": "kɑŋ˥", "syllable_count": 1, "sentences": [{"text": "钢里的含碳量比生铁低。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把铁水炼成了钢。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每年生产五百万吨钢。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢又硬又有韧性，所以能做桥。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢含碳少，比生铁更结实。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用铁和碳炼出了好钢。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刀要用好钢来做才不容易断。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批钢的质量很好。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大楼用了很多钢。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的钢卖到了很多国家。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一吨钢", "label": "量词"}, {"form": "一块钢", "label": "量词"}, {"form": "钢材", "label": "复合"}, {"form": "钢铁", "label": "复合"}, {"form": "鋼", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由铁炼成、含碳量较低的合金材料（工业用）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd93837-ff1f-44d8-9b8c-6d7a0431f7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。钢（gāng）：含碳量较低、坚硬而有韧性的铁碳合金。"}, {"text": "工", "is_correct": false, "explanation": "工（gōng）韵母为 ong，与 ang 不同，意思是工作、工业。"}, {"text": "当", "is_correct": false, "explanation": "当（dāng）声母为 d，与 g 不同，意思是担任、应当。"}, {"text": "港", "is_correct": false, "explanation": "港（gǎng）声调为第三声，与第一声不同，意思是港口。"}, {"text": "干", "is_correct": false, "explanation": "干（gān）韵尾为 n，与 ng 不同，意思是干燥、做。"}], "explanations": {"钢": "正确。钢（gāng）：含碳量较低、坚硬而有韧性的铁碳合金。", "工": "工（gōng）韵母为 ong，与 ang 不同，意思是工作、工业。", "当": "当（dāng）声母为 d，与 g 不同，意思是担任、应当。", "港": "港（gǎng）声调为第三声，与第一声不同，意思是港口。", "干": "干（gān）韵尾为 n，与 ng 不同，意思是干燥、做。"}, "sentence_index": null, "correct_answer": "钢"}, "level_3": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。“钢里的含碳量比生铁低”：钢的含碳量低于生铁，语义通顺。"}, {"text": "生铁", "is_correct": false, "explanation": "语义：句子用“生铁”作比较对象，主语也是生铁，自相矛盾。"}, {"text": "碳", "is_correct": false, "explanation": "语义：碳本身是单质，“碳里的含碳量比生铁低”不合常理。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“含碳量”多用于说合金，不能用来说玻璃。"}], "explanations": {"钢": "正确。“钢里的含碳量比生铁低”：钢的含碳量低于生铁，语义通顺。", "生铁": "语义：句子用“生铁”作比较对象，主语也是生铁，自相矛盾。", "碳": "语义：碳本身是单质，“碳里的含碳量比生铁低”不合常理。", "玻璃": "搭配：“含碳量”多用于说合金，不能用来说玻璃。"}, "sentence_index": 0, "correct_answer": "钢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只钢。", "explanation": "这里应该用〈块〉。钢是材料，量词用“块”或“吨”，“只”多用于动物。"}, {"text": "他用钢写字。", "explanation": "这里应该用〈钢笔〉。钢是金属材料，不能直接用来写字。"}, {"text": "工厂生产了一朵钢。", "explanation": "这里应该用〈吨〉。钢按重量计量，“朵”用于花，不能用于钢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。钢（gāng）：含碳量较低、坚硬而有韧性的铁碳合金。"}, {"text": "杠", "is_correct": false, "explanation": "杠（gàng）声调为第四声，与第一声不同，意思是粗棍子、横线。"}, {"text": "汤", "is_correct": false, "explanation": "汤（tāng）声母为 t，与 g 不同，意思是汤水。"}, {"text": "高", "is_correct": false, "explanation": "高（gāo）韵尾由 ng 变为 o，意思是高矮的高。"}, {"text": "康", "is_correct": false, "explanation": "康（kāng）声母为 k，与 g 不同，意思是健康、安康。"}], "explanations": {"钢": "正确。钢（gāng）：含碳量较低、坚硬而有韧性的铁碳合金。", "杠": "杠（gàng）声调为第四声，与第一声不同，意思是粗棍子、横线。", "汤": "汤（tāng）声母为 t，与 g 不同，意思是汤水。", "高": "高（gāo）韵尾由 ng 变为 o，意思是高矮的高。", "康": "康（kāng）声母为 k，与 g 不同，意思是健康、安康。"}, "sentence_index": null, "correct_answer": "钢"}, "level_3": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。“刀要用好钢来做才不容易断”：好钢做刀不易断，语义通顺。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不能用来做刀，“刀要用好纸来做”说不通。"}, {"text": "面粉", "is_correct": false, "explanation": "搭配：做刀的材料多说金属、钢铁，不说用面粉做刀。"}, {"text": "木炭", "is_correct": false, "explanation": "语义：木炭不能做刀，句子说的是用好材料做刀，木炭不符合。"}], "explanations": {"钢": "正确。“刀要用好钢来做才不容易断”：好钢做刀不易断，语义通顺。", "纸": "语义：纸不能用来做刀，“刀要用好纸来做”说不通。", "面粉": "搭配：做刀的材料多说金属、钢铁，不说用面粉做刀。", "木炭": "语义：木炭不能做刀，句子说的是用好材料做刀，木炭不符合。"}, "sentence_index": 6, "correct_answer": "钢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一棵钢。", "explanation": "这里应该用〈块〉。“棵”用于树木，不能用于钢这种材料。"}, {"text": "他每天弹钢。", "explanation": "这里应该用〈钢琴〉。钢是材料，不能用“弹”。"}, {"text": "工厂里有一座钢。", "explanation": "这里应该用〈块〉。“座”用于山、房屋等大型固定物，不用于钢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了两本钢。", "corrected_sentence": "他买了两块钢。", "error_description": "错误形式：“两本钢”，量词“本”用于书册。正确形式：“两块钢”，钢作为材料用“块”计量。原因：量词要与名词类别匹配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
