INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商是买东西、卖东西的事。", "primary_collocate": null, "pronunciation": "shāng", "ipa": "ʂɑŋ˥", "syllable_count": 1, "sentences": [{"text": "古代人重农轻商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃工作，改行从商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲从商，母亲教书。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想当官，只想从商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家世代为商，很有钱。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士农工商是古代的说法。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了法律，后来改行从商。", "target_word": "商", "complexity_tier": "T3", "furigana": "tā xué le fǎlǜ hòulái gǎi háng cóng shāng", "sentence_source": "generated"}, {"text": "他先当老师，三年后改为从商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古代，商不受人重视。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从政不容易，从商也不容易。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "商业", "label": "复合"}, {"form": "商人", "label": "复合"}], "register": "书面", "sense_fingerprint": "买卖东西这件事，与农、工、政相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商", "is_correct": true, "explanation": "商（shāng）指买卖、商业，是正确答案。"}, {"text": "上", "is_correct": false, "explanation": "上（shàng，第四声）与 shāng 声调不同，意思是上面。"}, {"text": "赏", "is_correct": false, "explanation": "赏（shǎng，第三声）与 shāng 声调不同，意思是欣赏或赏赐。"}, {"text": "山", "is_correct": false, "explanation": "山（shān）与 shāng 韵母不同（an 与 ang），意思是山。"}, {"text": "桑", "is_correct": false, "explanation": "桑（sāng）与 shāng 声母不同（s 与 sh），意思是桑树。"}], "explanations": {"商": "商（shāng）指买卖、商业，是正确答案。", "上": "上（shàng，第四声）与 shāng 声调不同，意思是上面。", "赏": "赏（shǎng，第三声）与 shāng 声调不同，意思是欣赏或赏赐。", "山": "山（shān）与 shāng 韵母不同（an 与 ang），意思是山。", "桑": "桑（sāng）与 shāng 声母不同（s 与 sh），意思是桑树。"}, "sentence_index": null, "correct_answer": "商"}, "level_3": {"options": [{"text": "树", "is_correct": false, "explanation": "语义：“重农轻”后接的是与“农”相对的行业，“树”不属于这一类。"}, {"text": "商", "is_correct": true, "explanation": "商指买卖的事，与“农”相对，“重农轻商”是古代的说法。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是行业或事务，与“重农轻”的意思不合。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“重…轻…”后接的是行业或事务，“花”不能这样搭配。"}], "explanations": {"树": "语义：“重农轻”后接的是与“农”相对的行业，“树”不属于这一类。", "商": "商指买卖的事，与“农”相对，“重农轻商”是古代的说法。", "石头": "语义：石头不是行业或事务，与“重农轻”的意思不合。", "花": "搭配：“重…轻…”后接的是行业或事务，“花”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我感冒了，今天在医院从商。", "explanation": "这里应该用〈看病〉。“从商”指做买卖，在医院看病不能说“从商”。"}, {"text": "他在工地从商，负责砌墙。", "explanation": "这里应该用〈做工〉。“从商”指做买卖，砌墙是工人的工作，不能用“从商”。"}, {"text": "我每天早上去学校从商。", "explanation": "这里应该用〈上课〉。“从商”指做买卖，去学校上课不能用“从商”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "商", "is_correct": true, "explanation": "商（shāng）指买卖、商业，是正确答案。"}, {"text": "张", "is_correct": false, "explanation": "张（zhāng）与 shāng 声母不同（zh 与 sh），是量词。"}, {"text": "香", "is_correct": false, "explanation": "香（xiāng）与 shāng 声母不同（x 与 sh），意思是香气。"}, {"text": "尚", "is_correct": false, "explanation": "尚（shàng，第四声）与 shāng 声调不同，意思是还、尚且。"}, {"text": "生", "is_correct": false, "explanation": "生（shēng）与 shāng 韵母不同（eng 与 ang），意思是生活或出生。"}], "explanations": {"商": "商（shāng）指买卖、商业，是正确答案。", "张": "张（zhāng）与 shāng 声母不同（zh 与 sh），是量词。", "香": "香（xiāng）与 shāng 声母不同（x 与 sh），意思是香气。", "尚": "尚（shàng，第四声）与 shāng 声调不同，意思是还、尚且。", "生": "生（shēng）与 shāng 韵母不同（eng 与 ang），意思是生活或出生。"}, "sentence_index": null, "correct_answer": "商"}, "level_3": {"options": [{"text": "山", "is_correct": false, "explanation": "语义：“改行从”后接的是行业或职业，“山”不是职业。"}, {"text": "商", "is_correct": true, "explanation": "商指买卖，“改行从商”指转去做买卖，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不是行业，“改行从水”的说法不通。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“从”后接的是行业或职业，“雨”不能这样搭配。"}], "explanations": {"山": "语义：“改行从”后接的是行业或职业，“山”不是职业。", "商": "商指买卖，“改行从商”指转去做买卖，符合句意。", "水": "语义：水不是行业，“改行从水”的说法不通。", "雨": "搭配：“从”后接的是行业或职业，“雨”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她从商多年，每天在学校里给学生上数学课。", "explanation": "这里应该用〈教书〉。“从商”指做买卖，给学生上课要说“教书”。"}, {"text": "他在农村从商，每天下地种田。", "explanation": "这里应该用〈务农〉。“从商”指做买卖，种田要说“务农”。"}, {"text": "他在医院从商，每天给病人看病。", "explanation": "这里应该用〈行医〉。“从商”指做买卖，给病人看病要说“行医”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕业以后做商十年了。", "corrected_sentence": "他毕业以后从商十年了。", "error_description": "错误：“做商”，正确：“从商”。“从商”是固定说法，指从事买卖，“商”不能和“做”搭配，应说“从商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年才商从，现在开了一家店。", "corrected_sentence": "他去年才从商，现在开了一家店。", "error_description": "错误：“商从”，语序颠倒，应为“从商”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
