INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商业；做买卖的行当，也指做买卖的人。", "primary_collocate": null, "pronunciation": "shāng", "ipa": "ʂɑŋ˥", "syllable_count": 1, "sentences": [{"text": "这位老人早年为商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农、工、商都要发展。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他辞去公务员的工作，选择了从商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷年轻时从商，走了很多地方。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，官和商常常来往。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，农和商都很辛苦。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王毕业后从商，开了一家店。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个村子里农多商少。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国古代有四民：士、农、工、商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的儿子不想种地，想去从商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "商业", "label": "复合"}, {"form": "商人", "label": "复合"}], "register": "书面", "sense_fingerprint": "商业这一行，或做买卖的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商", "is_correct": true, "explanation": "商（shāng）指商业、做买卖的行当，是正确答案。"}, {"text": "尚", "is_correct": false, "explanation": "尚（shàng，第四声）与 shāng 声调不同，意思是还、尚且。"}, {"text": "赏", "is_correct": false, "explanation": "赏（shǎng，第三声）与 shāng 声调不同，意思是欣赏或赏赐。"}, {"text": "张", "is_correct": false, "explanation": "张（zhāng）与 shāng 声母不同（zh 与 sh），是量词。"}, {"text": "生", "is_correct": false, "explanation": "生（shēng）与 shāng 韵母不同（eng 与 ang），意思是生活或出生。"}], "explanations": {"商": "商（shāng）指商业、做买卖的行当，是正确答案。", "尚": "尚（shàng，第四声）与 shāng 声调不同，意思是还、尚且。", "赏": "赏（shǎng，第三声）与 shāng 声调不同，意思是欣赏或赏赐。", "张": "张（zhāng）与 shāng 声母不同（zh 与 sh），是量词。", "生": "生（shēng）与 shāng 韵母不同（eng 与 ang），意思是生活或出生。"}, "sentence_index": null, "correct_answer": "商"}, "level_3": {"options": [{"text": "山", "is_correct": false, "explanation": "语义：“为”后接职业或身份，山不是职业，句意不通。"}, {"text": "商", "is_correct": true, "explanation": "商指做买卖的行当或人，“早年为商”指年轻时做生意，符合句意。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不是职业或身份，“早年为花”的说法不通。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“为”后接职业或身份，“水”不能作职业，不构成搭配。"}], "explanations": {"山": "语义：“为”后接职业或身份，山不是职业，句意不通。", "商": "商指做买卖的行当或人，“早年为商”指年轻时做生意，符合句意。", "花": "语义：花不是职业或身份，“早年为花”的说法不通。", "水": "搭配：“为”后接职业或身份，“水”不能作职业，不构成搭配。"}, "sentence_index": 0, "correct_answer": "商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爷爷年轻时在学校从商，教学生读书。", "explanation": "这里应该用〈教书〉。“从商”指做买卖，教书不能用“从商”。"}, {"text": "我爷爷年轻时在田里从商，每天种地收粮。", "explanation": "这里应该用〈种地〉。“从商”指做买卖，种地不能用“从商”。"}, {"text": "我爷爷年轻时在工厂从商，负责修理机器。", "explanation": "这里应该用〈工作〉。“从商”指做买卖，在工厂修理机器不能用“从商”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92942, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "商", "is_correct": true, "explanation": "商（shāng）指商业、做买卖的行当，是正确答案。"}, {"text": "上", "is_correct": false, "explanation": "上（shàng，第四声）与 shāng 声调不同，意思是上面。"}, {"text": "香", "is_correct": false, "explanation": "香（xiāng）与 shāng 声母不同（x 与 sh），意思是香气。"}, {"text": "山", "is_correct": false, "explanation": "山（shān）与 shāng 韵母不同（an 与 ang），意思是山。"}, {"text": "桑", "is_correct": false, "explanation": "桑（sāng）与 shāng 声母不同（s 与 sh），意思是桑树。"}], "explanations": {"商": "商（shāng）指商业、做买卖的行当，是正确答案。", "上": "上（shàng，第四声）与 shāng 声调不同，意思是上面。", "香": "香（xiāng）与 shāng 声母不同（x 与 sh），意思是香气。", "山": "山（shān）与 shāng 韵母不同（an 与 ang），意思是山。", "桑": "桑（sāng）与 shāng 声母不同（s 与 sh），意思是桑树。"}, "sentence_index": null, "correct_answer": "商"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能去做买卖，“毕业后从石头”的说法不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是行当或职业，与“毕业后从”的搭配不合。"}, {"text": "商", "is_correct": true, "explanation": "商指做买卖的行当，“毕业后从商，开了一家店”符合句意。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“从”后接的是行当或职业，“雨”不能这样搭配。"}], "explanations": {"石头": "语义：石头不能去做买卖，“毕业后从石头”的说法不通。", "树": "语义：树不是行当或职业，与“毕业后从”的搭配不合。", "商": "商指做买卖的行当，“毕业后从商，开了一家店”符合句意。", "雨": "搭配：“从”后接的是行当或职业，“雨”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的儿子不想种地，想去部队从商。", "explanation": "这里应该用〈当兵〉。“从商”指做买卖，去部队不能用“从商”。"}, {"text": "父亲去年开始在学校从商，教数学。", "explanation": "这里应该用〈教书〉。“从商”指做买卖，教数学要说“教书”。"}, {"text": "他在这家超市里从商，负责修理冰箱。", "explanation": "这里应该用〈工作〉。“从商”指做买卖，在超市修理冰箱不能用“从商”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他早年商从，后来去了国外。", "corrected_sentence": "他早年从商，后来去了国外。", "error_description": "错误：“商从”，语序颠倒，应为“从商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市的商活动非常活跃。", "corrected_sentence": "这座城市的商业活动非常活跃。", "error_description": "错误：“商活动”。“商”作定语修饰“活动”不自然，应说“商业活动”，不能丢掉“业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
