INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "锡是一种软软的、银白色的金属。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "锡是一种软软的金属。", "target_word": "锡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块锡很软，用刀就能切开。", "target_word": "锡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人用锡做了一个小杯子。", "target_word": "锡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "锡的颜色是银白色的。", "target_word": "锡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在桌上放着一块锡。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锡很软，用手就能弯。", "target_word": "锡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小盒子是用锡做的。", "target_word": "锡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "锡很常见，工厂里经常能用到。", "target_word": "锡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了一块银白色的锡。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锡放在火上，很快就会熔化。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块锡", "label": "量词"}, {"form": "锡纸", "label": "复合"}, {"form": "錫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一种软的银白色金属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "锡", "is_correct": true, "explanation": "锡，xī（第一声），一种软软的银白色金属。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，意思是练习。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，意思是清洗。"}, {"text": "系", "is_correct": false, "explanation": "xì（第四声）与 xī（第一声）声调不同，意思是系统、系上。"}, {"text": "星", "is_correct": false, "explanation": "xīng 比 xī 多了韵尾 ng，意思是星星。"}, {"text": "心", "is_correct": false, "explanation": "xīn 比 xī 多了韵尾 n，意思是心脏、心意。"}], "explanations": {"锡": "锡，xī（第一声），一种软软的银白色金属。", "习": "xí（第二声）与 xī（第一声）声调不同，意思是练习。", "洗": "xǐ（第三声）与 xī（第一声）声调不同，意思是清洗。", "系": "xì（第四声）与 xī（第一声）声调不同，意思是系统、系上。", "星": "xīng 比 xī 多了韵尾 ng，意思是星星。", "心": "xīn 比 xī 多了韵尾 n，意思是心脏、心意。"}, "sentence_index": null, "correct_answer": "锡"}, "level_3": {"options": [{"text": "锡", "is_correct": true, "explanation": "锡是一种软的银白色金属，与“软软的金属”相符。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不是金属，与“金属”矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头一般是硬的，不说“软软的石头”，与句中“软软的”不搭。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花是植物纤维，不是金属。"}], "explanations": {"锡": "锡是一种软的银白色金属，与“软软的金属”相符。", "木头": "语义：木头不是金属，与“金属”矛盾。", "石头": "搭配：石头一般是硬的，不说“软软的石头”，与句中“软软的”不搭。", "棉花": "语义：棉花是植物纤维，不是金属。"}, "sentence_index": 0, "correct_answer": "锡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只锡。", "explanation": "这里应该用〈块〉。锡是物质，计量时用“块”或“锭”，不用“只”。"}, {"text": "我买了一本锡，准备熔化。", "explanation": "这里应该用〈块〉。锡是块状物质，计量时用“块”或“锭”，“本”用于书册，不能用来数锡。"}, {"text": "工厂运来了一辆锡，准备熔化。", "explanation": "这里应该用〈块〉。锡是块状物质，计量时用“块”或“锭”，“辆”用于车辆，不能用来数锡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92943, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "锡", "is_correct": true, "explanation": "锡，xī（第一声），一种软软的银白色金属。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，意思是高兴。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 xī（第一声）声调不同，意思是戏剧。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，意思是座位。"}, {"text": "新", "is_correct": false, "explanation": "xīn 比 xī 多了韵尾 n，意思是新的。"}], "explanations": {"锡": "锡，xī（第一声），一种软软的银白色金属。", "喜": "xǐ（第三声）与 xī（第一声）声调不同，意思是高兴。", "戏": "xì（第四声）与 xī（第一声）声调不同，意思是戏剧。", "席": "xí（第二声）与 xī（第一声）声调不同，意思是座位。", "新": "xīn 比 xī 多了韵尾 n，意思是新的。"}, "sentence_index": null, "correct_answer": "锡"}, "level_3": {"options": [{"text": "锡", "is_correct": true, "explanation": "锡是金属，可以用来做小盒子，符合“用……做的”。"}, {"text": "云", "is_correct": false, "explanation": "语义：云不是能用来做盒子的材料。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦是抽象的，不能用来做实物。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“用……做”后面一般接材料，不接“歌”。"}], "explanations": {"锡": "锡是金属，可以用来做小盒子，符合“用……做的”。", "云": "语义：云不是能用来做盒子的材料。", "梦": "语义：梦是抽象的，不能用来做实物。", "歌": "搭配：“用……做”后面一般接材料，不接“歌”。"}, "sentence_index": 6, "correct_answer": "锡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂买了一台锡，用来焊接电路板。", "explanation": "这里应该用〈块〉。锡是块状物质，计量时用“块”或“锭”，“台”用于机器，不能用来数锡。"}, {"text": "我们买了一首锡，准备熔化。", "explanation": "这里应该用〈块〉。锡是块状物质，计量时用“块”或“锭”，“首”用于诗歌、歌曲，不能用来数锡。"}, {"text": "他搬来一座锡，准备熔化。", "explanation": "这里应该用〈锭〉或〈块〉。锡是块状物质，“座”用于山、桥、房屋等大型固定物，不能用来数锡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用纸锡包了一块巧克力。", "corrected_sentence": "我用锡纸包了一块巧克力。", "error_description": "“纸锡”的词序错误。“锡纸”指用锡做的薄片，“锡”在前，不能倒过来说“纸锡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一个锡，准备做一个小勺子。", "corrected_sentence": "他买了一块锡，准备做一个小勺子。", "error_description": "量词错误。锡是块状的物质，应说“一块锡”，不说“一个锡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
