INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种银白色柔软的金属元素，常用于镀层和制合金。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "锡是一种银白色的金属元素。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在铁片上镀了一层锡。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锡和铜可以做成青铜。", "target_word": "锡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "锡的熔点很低，容易化开。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个罐头里面有一层锡。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把锡和铅放在一起做合金。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青铜里除了铜，还有锡。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防止铁生锈，人们常在它表面镀锡。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种合金里含有百分之十的锡。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每年用很多锡来做合金。", "target_word": "锡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块锡", "label": "量词"}, {"form": "锡箔", "label": "复合"}, {"form": "錫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "金属元素，用于镀层和合金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "锡", "is_correct": true, "explanation": "锡，xī（第一声），一种软软的银白色金属元素。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，意思是高兴。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 xī（第一声）声调不同，意思是戏剧。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，意思是座位。"}, {"text": "新", "is_correct": false, "explanation": "xīn 比 xī 多了韵尾 n，意思是新的。"}], "explanations": {"锡": "锡，xī（第一声），一种软软的银白色金属元素。", "喜": "xǐ（第三声）与 xī（第一声）声调不同，意思是高兴。", "戏": "xì（第四声）与 xī（第一声）声调不同，意思是戏剧。", "席": "xí（第二声）与 xī（第一声）声调不同，意思是座位。", "新": "xīn 比 xī 多了韵尾 n，意思是新的。"}, "sentence_index": null, "correct_answer": "锡"}, "level_3": {"options": [{"text": "锡", "is_correct": true, "explanation": "锡是一种银白色的金属元素，符合句意。"}, {"text": "金", "is_correct": false, "explanation": "体貌：金是黄色的，与“银白色”不符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是金属元素。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不是金属元素。"}], "explanations": {"锡": "锡是一种银白色的金属元素，符合句意。", "金": "体貌：金是黄色的，与“银白色”不符。", "玻璃": "语义：玻璃不是金属元素。", "纸": "语义：纸不是金属元素。"}, "sentence_index": 0, "correct_answer": "锡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一台锡，准备焊接电路。", "explanation": "这里应该用〈块〉或〈锭〉。锡是块状金属，计量时不用“台”（用于机器）。"}, {"text": "这次我们买了一本锡，准备浇铸。", "explanation": "这里应该用〈块〉或〈锭〉。锡是块状金属，计量时不用“本”（用于书册）。"}, {"text": "我买了三只锡。", "explanation": "这里应该用〈块〉或〈锭〉。锡是物质，数量用“块”“锭”计，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92944, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "锡", "is_correct": true, "explanation": "锡，xī（第一声），一种软软的银白色金属元素。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，意思是练习。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，意思是清洗。"}, {"text": "系", "is_correct": false, "explanation": "xì（第四声）与 xī（第一声）声调不同，意思是系统、系上。"}, {"text": "星", "is_correct": false, "explanation": "xīng 比 xī 多了韵尾 ng，意思是星星。"}, {"text": "心", "is_correct": false, "explanation": "xīn 比 xī 多了韵尾 n，意思是心脏、心意。"}], "explanations": {"锡": "锡，xī（第一声），一种软软的银白色金属元素。", "习": "xí（第二声）与 xī（第一声）声调不同，意思是练习。", "洗": "xǐ（第三声）与 xī（第一声）声调不同，意思是清洗。", "系": "xì（第四声）与 xī（第一声）声调不同，意思是系统、系上。", "星": "xīng 比 xī 多了韵尾 ng，意思是星星。", "心": "xīn 比 xī 多了韵尾 n，意思是心脏、心意。"}, "sentence_index": null, "correct_answer": "锡"}, "level_3": {"options": [{"text": "锡", "is_correct": true, "explanation": "锡是青铜的成分之一，符合“还有”的语境。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不是金属，不能作青铜的成分。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：青铜是金属合金，“还有”后接的应是金属成分，不说“糖”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是金属成分，与“青铜”的构成相矛盾。"}], "explanations": {"锡": "锡是青铜的成分之一，符合“还有”的语境。", "水": "语义：水不是金属，不能作青铜的成分。", "糖": "搭配：青铜是金属合金，“还有”后接的应是金属成分，不说“糖”。", "石头": "语义：石头不是金属成分，与“青铜”的构成相矛盾。"}, "sentence_index": 6, "correct_answer": "锡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仓库里放着一辆锡，等着运走。", "explanation": "这里应该用〈块〉或〈锭〉。锡是块状金属，计量时不用“辆”（用于车辆）。"}, {"text": "妈妈寄来一封锡，让我做实验。", "explanation": "这里应该用〈块〉。锡是块状物质，计量时用“块”或“锭”，“封”用于信件，不能用来数锡。"}, {"text": "他搬来一架锡，准备浇铸。", "explanation": "这里应该用〈块〉或〈锭〉。锡是块状金属，计量时不用“架”（用于机器、飞机）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些铁钉表面镀了一块锡，不容易生锈。", "corrected_sentence": "这些铁钉表面镀了一层锡，不容易生锈。", "error_description": "量词错误。镀在表面的锡是一层，应说“一层锡”，不说“一块锡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一本锡放在火上熔化了。", "corrected_sentence": "他把一块锡放在火上熔化了。", "error_description": "量词错误。锡是块状金属，应说“一块锡”，“本”用于书册，不能用来数锡。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
