INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92945, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "在内是也算在里面。", "primary_collocate": null, "pronunciation": "zài nèi", "ipa": "tsaɪ˥˩ neɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们一共五个人，我也在内。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行，连老师在内，一共二十人。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租和水电费都在内吗？", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个价钱，早饭也在内。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要交作业的人里，小明也在内。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有的书，这本也在内，都要还。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的名单里，爸爸妈妈和我，一家人都在内。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些钱，路费在内吗？", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都去，你也在内。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末的假期，周六和周日都在内。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在內", "label": "繁体"}], "register": "中性", "sense_fingerprint": "也算在里面，被计算在范围之中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在内", "is_correct": true, "explanation": "在内表示算进某个范围。“我也在内”即我也被算在这五个人里。"}, {"text": "在外", "is_correct": false, "explanation": "语义：在外表示不在其中，与“一共五个人”把我算进去相矛盾。"}, {"text": "缺席", "is_correct": false, "explanation": "语义：缺席指没有到场，句子说的是把我计入总数，而不是我没到。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是书面敬语，用于说客人到场，用在“我也”这样的口语句中很突兀。"}], "explanations": {"在内": "在内表示算进某个范围。“我也在内”即我也被算在这五个人里。", "在外": "语义：在外表示不在其中，与“一共五个人”把我算进去相矛盾。", "缺席": "语义：缺席指没有到场，句子说的是把我计入总数，而不是我没到。", "莅临": "语域：莅临是书面敬语，用于说客人到场，用在“我也”这样的口语句中很突兀。"}, "sentence_index": 0, "correct_answer": "在内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天下大雨，我们都在内。", "explanation": "在内表示计入某个范围，不指所在位置。这里应说“在屋里”。"}, {"text": "他在屋里，我也在内。", "explanation": "在内表示计入某个范围，不表示所在位置。这里是把“在内”当作“在某处”来用，应改用表示位置的说法。"}, {"text": "这份工作我们一周在内就能做完。", "explanation": "在内表示计入范围，不表示时间上的限制。这里是把它当作“之内”来用，应说“一周之内”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在内", "is_correct": true, "explanation": "在内表示算进一家人的范围，爸爸妈妈和我都在这一家人里。"}, {"text": "分居", "is_correct": false, "explanation": "语义：分居指分开住，与“一家人”合在一起的意思相矛盾。"}, {"text": "离散", "is_correct": false, "explanation": "语义：离散指分散各处，与名单里一家人都在内的意思相反。"}, {"text": "分开", "is_correct": false, "explanation": "语义：分开指各走各的，与“一家人都”的意思相反。"}], "explanations": {"在内": "在内表示算进一家人的范围，爸爸妈妈和我都在这一家人里。", "分居": "语义：分居指分开住，与“一家人”合在一起的意思相矛盾。", "离散": "语义：离散指分散各处，与名单里一家人都在内的意思相反。", "分开": "语义：分开指各走各的，与“一家人都”的意思相反。"}, "sentence_index": 6, "correct_answer": "在内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天下大雨，我们一家人都在内。", "explanation": "在内表示计入范围，不指位置。这里应说“在家里”。"}, {"text": "孩子们都在内玩耍。", "explanation": "在内表示计入范围，不表示所在位置。这里把“在内”当作“在屋里”来用，应说“在屋里玩”。"}, {"text": "我们三天在内就能画完这幅画。", "explanation": "在内表示计入范围，不表示时间上的限制。这里应说“三天之内”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次聚会一共六个人，我很在内。", "corrected_sentence": "这次聚会一共六个人，我也在内。", "error_description": "错误形式：“我很在内”；正确形式：“我也在内”。“在内”是动词，不能用程度副词“很”修饰；表示“也算进去”应用副词“也”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次家庭聚会，我妈妈也在内着。", "corrected_sentence": "这次家庭聚会，我妈妈也在内。", "error_description": "“在内”后面不能加“着”。应说“我妈妈也在内”，表示我妈妈也算在里面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
