INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92946, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "包括在里面。", "primary_collocate": null, "pronunciation": "zài nèi", "ipa": "tsaɪ˥˩ neɪ˥˩", "syllable_count": 2, "sentences": [{"text": "包括我在内，大家都喜欢这个电影。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家人，包括爷爷在内，都来了。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业，写作文在内，要两个小时。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的价钱，早饭在内，一晚三百元。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人，我在内，都是北京人。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的开销，房租在内，是五千块。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有的学生，小李在内，都得参加考试。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次出游的费用，包括我的在内，一共两千块。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全校一千人，老师在内，今天都放假。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司，老板在内，只有八个人。", "target_word": "在内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在內", "label": "繁体"}], "register": "中性", "sense_fingerprint": "包括在里面，常用于列举后补充说明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在内", "is_correct": true, "explanation": "“包括我在内”中，在内是“包括”后的补充，表示连我也算上。"}, {"text": "在外", "is_correct": false, "explanation": "语义：在外表示不算在内，与“包括我”的意思相矛盾。"}, {"text": "不在", "is_correct": false, "explanation": "语义：不在表示我不在场，与“包括我”把我算进去相矛盾。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是书面敬语，用在“包括我”这样的口语句中很突兀。"}], "explanations": {"在内": "“包括我在内”中，在内是“包括”后的补充，表示连我也算上。", "在外": "语义：在外表示不算在内，与“包括我”的意思相矛盾。", "不在": "语义：不在表示我不在场，与“包括我”把我算进去相矛盾。", "莅临": "语域：莅临是书面敬语，用在“包括我”这样的口语句中很突兀。"}, "sentence_index": 0, "correct_answer": "在内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外面下大雨，我们全都在内。", "explanation": "在内表示计入某个范围，不指所在位置。这里应说“在屋里”。"}, {"text": "这两天在内，我们完成了所有工作。", "explanation": "在内表示计入范围，不表示时间限制。这里应说“这两天之内”。"}, {"text": "猫在内睡觉，狗在外叫。", "explanation": "在内表示计入范围，不表示所在位置。这里应说“在屋里”，表示在房间里面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在内", "is_correct": true, "explanation": "在内表示小李也算在所有学生里，所以都得参加考试。"}, {"text": "离开", "is_correct": false, "explanation": "语义：离开指走开，与“都得参加考试”的语境不合。"}, {"text": "放假", "is_correct": false, "explanation": "语义：放假指不上课、不上学，与“都得参加考试”相矛盾。"}, {"text": "光临", "is_correct": false, "explanation": "语域：光临是敬语，用在学生身上显得突兀，不符合口语语境。"}], "explanations": {"在内": "在内表示小李也算在所有学生里，所以都得参加考试。", "离开": "语义：离开指走开，与“都得参加考试”的语境不合。", "放假": "语义：放假指不上课、不上学，与“都得参加考试”相矛盾。", "光临": "语域：光临是敬语，用在学生身上显得突兀，不符合口语语境。"}, "sentence_index": 6, "correct_answer": "在内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外面太热了，我们都在内。", "explanation": "在内表示计入范围，不指位置。这里应说“在屋里”。"}, {"text": "他很兴奋，老板在内。", "explanation": "“在内”用于把人列入一个群体，这里只说一个人的情绪，没有群体可列，应说“老板也很兴奋”。"}, {"text": "客人们都在内吃饭。", "explanation": "在内表示计入范围，不表示所在位置。这里应说“在屋里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次聚餐，包括王老师在内着，一共八个人。", "corrected_sentence": "这次聚餐，包括王老师在内，一共八个人。", "error_description": "“在内”后面不能加“着”。应说“包括王老师在内”，“着”不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班一共三十个人，王老师很在内。", "corrected_sentence": "我们班一共三十个人，王老师也在内。", "error_description": "错误形式：“王老师很在内”；正确形式：“王老师也在内”。“在内”是动词，不能用程度副词“很”修饰；表示“也算进去”应用副词“也”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
