INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92947, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钥匙是用来开锁的小东西。", "primary_collocate": null, "pronunciation": "yào shi", "ipa": "jɑʊ˥˩ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "我的钥匙找不到了。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙放在桌子上。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁着，我没带钥匙。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给了我一把新钥匙。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把钥匙交给门口的老师。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钥匙掉在地上，发出一声响。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用钥匙打开了家门。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把钥匙太小，开不了大门。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前要看看有没有带钥匙。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把我的钥匙叼走了。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把钥匙", "label": "量词（把）"}, {"form": "钥匙串", "label": "复合"}, {"form": "鑰匙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常开锁的小东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钥匙", "is_correct": true, "explanation": "钥匙（yào shi）指开锁用的小器具，是正确答案。"}, {"text": "药师", "is_correct": false, "explanation": "药师（yào shī）指药剂师。第二音节 shī（第一声）与 shi（轻声）声调不同，意思不同。"}, {"text": "要事", "is_correct": false, "explanation": "要事（yào shì）指重要的事。第二音节 shì（第四声）与 shi（轻声）声调不同。"}, {"text": "药石", "is_correct": false, "explanation": "药石（yào shí）指药物。第二音节 shí（第二声）与 shi（轻声）声调不同，意思不同。"}], "explanations": {"钥匙": "钥匙（yào shi）指开锁用的小器具，是正确答案。", "药师": "药师（yào shī）指药剂师。第二音节 shī（第一声）与 shi（轻声）声调不同，意思不同。", "要事": "要事（yào shì）指重要的事。第二音节 shì（第四声）与 shi（轻声）声调不同。", "药石": "药石（yào shí）指药物。第二音节 shí（第二声）与 shi（轻声）声调不同，意思不同。"}, "sentence_index": null, "correct_answer": "钥匙"}, "level_3": {"options": [{"text": "钥匙", "is_correct": true, "explanation": "正确：钥匙是可以丢失、找不到的小物件，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以丢失或找不到的物件，句子不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无处不在，不能像随身物品那样“找不到”。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛长在身上，不会像随身物品那样“找不到了”。"}], "explanations": {"钥匙": "正确：钥匙是可以丢失、找不到的小物件，符合句意。", "天气": "语义：天气不是可以丢失或找不到的物件，句子不通。", "空气": "语义：空气无处不在，不能像随身物品那样“找不到”。", "眼睛": "语义：眼睛长在身上，不会像随身物品那样“找不到了”。"}, "sentence_index": 0, "correct_answer": "钥匙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿钥匙刷开了大楼的门。", "explanation": "这里应该用〈门卡〉。刷开门靠刷卡，钥匙要插进锁孔转动，不能用来刷。"}, {"text": "我买了一只钥匙。", "explanation": "这里应该用〈把〉。“只”用于动物或成对物件中的单个，钥匙是一件器具，要用“把”来数。"}, {"text": "他把钥匙按在指纹锁上，录入了自己的指纹。", "explanation": "这里应该用〈手指〉。录入指纹要把手指按在传感器上，钥匙不能用来录指纹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": true, "explanation": "正确：钥匙插进锁孔转动就能打开家门，符合句意。"}, {"text": "大门", "is_correct": false, "explanation": "语义：门是被打开的对象，不能用来打开门。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户也是被开关的对象，不是打开家门的工具。"}, {"text": "锁", "is_correct": false, "explanation": "搭配：“用锁打开门”不成立，锁本身就是被打开的对象，不能作工具。"}], "explanations": {"钥匙": "正确：钥匙插进锁孔转动就能打开家门，符合句意。", "大门": "语义：门是被打开的对象，不能用来打开门。", "窗户": "语义：窗户也是被开关的对象，不是打开家门的工具。", "锁": "搭配：“用锁打开门”不成立，锁本身就是被打开的对象，不能作工具。"}, "sentence_index": 6, "correct_answer": "钥匙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他输入了钥匙，门就开了。", "explanation": "这里应该用〈密码〉。输入的是密码，钥匙要插进锁孔转动，不能输入。"}, {"text": "我口袋里有一条钥匙。", "explanation": "量词错误：钥匙应用“把”，“条”用于细长的物件。"}, {"text": "他按了一下门口的钥匙，屋里就响起了铃声。", "explanation": "这里应该用〈门铃〉。按一下让屋里响起铃声的是门铃，钥匙是开锁的器具，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我丢了一只钥匙。", "corrected_sentence": "我丢了一把钥匙。", "error_description": "量词错误：“钥匙”应用量词“把”，写成“只”不对。正确说法是“一把钥匙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一条钥匙放进了包里。", "corrected_sentence": "他把一把钥匙放进了包里。", "error_description": "量词错误：“钥匙”应用“把”，写成“条”不对，“条”用于细长的物件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
