INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "开锁或上锁用的金属器具。", "primary_collocate": null, "pronunciation": "yào shi", "ipa": "jɑʊ˥˩ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "这把金属钥匙是铜做的。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上睡觉前，他用钥匙锁好了门。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钥匙插进锁里，却转不动。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的钥匙由经理保管。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧钥匙上有一点铁锈。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的保险箱要用两把钥匙才能打开。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙转了两圈，门就锁上了。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "配一把钥匙只要十分钟。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的钥匙不见了，我们只好打车去。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口袋里装着三把钥匙。", "target_word": "钥匙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把钥匙", "label": "量词（把）"}, {"form": "钥匙串", "label": "复合"}, {"form": "鑰匙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开锁或上锁的金属器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
