s_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": true, "explanation": "正确：转动钥匙才能锁门，符合句意。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：转动钢笔不会把门锁上，句子不通。"}, {"text": "方向盘", "is_correct": false, "explanation": "搭配：转动方向盘不能锁门，“门就锁上了”与“方向盘”的作用不相关。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：转动椅子不能使门锁上，与句中的动作和结果都不相符。"}], "explanations": {"钥匙": "正确：转动钥匙才能锁门，符合句意。", "钢笔": "语义：转动钢笔不会把门锁上，句子不通。", "方向盘": "搭配：转动方向盘不能锁门，“门就锁上了”与“方向盘”的作用不相关。", "椅子": "语义：转动椅子不能使门锁上，与句中的动作和结果都不相符。"}, "sentence_index": 6, "correct_answer": "钥匙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拉了钥匙，灯就亮了。", "explanation": "这里应该用〈开关〉。开灯要按开关，钥匙不能用来拉。"}, {"text": "他用钥匙刷开了办公室的门。", "explanation": "这里应该用〈门卡〉。刷开门要用门卡，钥匙要插进锁孔转动。"}, {"text": "他的口袋里装着三根钥匙。", "explanation": "量词错误：钥匙应用“把”，“根”用于细长的棍状物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条旧钥匙已经生锈了。", "corrected_sentence": "这把旧钥匙已经生锈了。", "error_description": "量词错误：“钥匙”应用“把”，写成“条”不对，“条”用于细长的物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的书包里装着两根钥匙。", "corrected_sentence": "他的书包里装着两把钥匙。", "error_description": "量词错误：“钥匙”应用“把”，写成“根”不对，“根”用于细长的棍状物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
