INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外汇是别的国家用的钱。", "primary_collocate": null, "pronunciation": "wài huì", "ipa": "/uai̯˥˩ xuei̯˥˩/", "syllable_count": 2, "sentences": [{"text": "去美国以前，我先换了一些外汇。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的银行可以换外汇。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你带了多少外汇出国？", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱包里有一点外汇。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外汇不能在商店直接用。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用人民币买外汇。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的外汇窗口在二楼。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去旅行时，带着外汇很方便。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过海关时，要说明带了多少外汇。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把外汇放在包里了。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外汇储备", "label": "复合"}, {"form": "外匯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别的国家用的钱，出国时要换的外币", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外汇", "is_correct": true, "explanation": "正确：“换了一些外汇”指去国外前把人民币换成外国货币，符合语境。"}, {"text": "云彩", "is_correct": false, "explanation": "语义：云彩不能被兑换，“换了一些云彩”句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能被兑换，“换了一些体重”句子不通。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不能拿来兑换，“换了一些影子”句子不通。"}], "explanations": {"外汇": "正确：“换了一些外汇”指去国外前把人民币换成外国货币，符合语境。", "云彩": "语义：云彩不能被兑换，“换了一些云彩”句子不通。", "体重": "语义：体重不能被兑换，“换了一些体重”句子不通。", "影子": "语义：影子不能拿来兑换，“换了一些影子”句子不通。"}, "sentence_index": 0, "correct_answer": "外汇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他会说很多种外汇。", "explanation": "这里应该用〈外语〉。外汇指外国的钱，会说的是外语。"}, {"text": "我在路上遇到了一个外汇。", "explanation": "这里应该用〈外国人〉。外汇指钱，不是人，遇到的人应说外国人。"}, {"text": "我每天早上喝一杯外汇。", "explanation": "这里应该用〈牛奶〉。外汇是钱，不是饮料，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外汇", "is_correct": true, "explanation": "正确：“外汇窗口”是银行办理外汇业务的窗口，符合“这家银行的……窗口”的语境。"}, {"text": "挂号", "is_correct": false, "explanation": "搭配：“挂号”是医院的业务，银行不设挂号窗口。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是医院的场所，与银行无关，句子不通。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是车站的业务，与银行的窗口不相符。"}], "explanations": {"外汇": "正确：“外汇窗口”是银行办理外汇业务的窗口，符合“这家银行的……窗口”的语境。", "挂号": "搭配：“挂号”是医院的业务，银行不设挂号窗口。", "病房": "语义：病房是医院的场所，与银行无关，句子不通。", "车票": "语义：车票是车站的业务，与银行的窗口不相符。"}, "sentence_index": 6, "correct_answer": "外汇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿着一件外汇出门了。", "explanation": "这里应该用〈外套〉。外汇是钱，不是衣服，不能说穿着外汇。"}, {"text": "我昨天吃了一盘外汇。", "explanation": "这里应该用〈饭菜〉。外汇不是食物，不能用“盘”来“吃”。"}, {"text": "他去外汇出差了。", "explanation": "这里应该用〈外地〉。外汇是钱，不是地方，出差的目的地应说外地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出国前我去银行换了一些的外汇。", "corrected_sentence": "出国前我去银行换了一些外汇。", "error_description": "助词错误：数量短语“一些”与名词“外汇”之间不用“的”，应为“一些外汇”，不能说“一些的外汇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在机场换了一只外汇。", "corrected_sentence": "他在机场换了一笔外汇。", "error_description": "量词错误：外汇这类款项应用“笔”计量，“只”不能用于外汇。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
