INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可用于国际支付的外国货币及其支付凭证。", "primary_collocate": null, "pronunciation": "wài huì", "ipa": "/uai̯˥˩ xuei̯˥˩/", "syllable_count": 2, "sentences": [{"text": "中国的外汇储备很多。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行可以帮你办理外汇业务。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司用外汇进口机器。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出口多了，国家的外汇就多了。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行工作，专门做外汇买卖。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要管理好外汇，保护经济安全。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外汇市场每天都在变化。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进口石油要用外汇支付。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家缺少外汇，买不起很多东西。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游业给国家赚来了很多外汇。", "target_word": "外汇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外汇储备", "label": "复合"}, {"form": "外汇市场", "label": "复合"}, {"form": "外匯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可用于国际支付的外国货币及支付凭证", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外汇", "is_correct": true, "explanation": "正确：“外汇”是可用于国际支付的外国货币及凭证，可以“储备”。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”不是可以积累的物资或资金，“中国的心跳储备”句子不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“储备”指可以积累的物资，空气不能作为储备，句子不通。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：情绪不是可以储存的物资，“中国的情绪储备”与句意不符。"}], "explanations": {"外汇": "正确：“外汇”是可用于国际支付的外国货币及凭证，可以“储备”。", "心跳": "语义：“心跳”不是可以积累的物资或资金，“中国的心跳储备”句子不通。", "空气": "语义：“储备”指可以积累的物资，空气不能作为储备，句子不通。", "情绪": "语义：情绪不是可以储存的物资，“中国的情绪储备”与句意不符。"}, "sentence_index": 0, "correct_answer": "外汇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外汇很好看，我想穿。", "explanation": "这里应该用〈衣服〉。外汇是货币，不是衣服，不能穿。"}, {"text": "这位同事是外汇。", "explanation": "这里应该用〈外籍〉。外汇是货币，不指人；指外国国籍的同事应说“外籍同事”。"}, {"text": "这家公司每年都在院子里种很多外汇。", "explanation": "这里应该用〈树苗〉。种是对植物的动作，外汇是货币，不能种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外汇", "is_correct": true, "explanation": "正确：“外汇市场”是指外汇买卖的市场，符合“每天都在变化”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是市场上交易的对象，“天气市场”不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是市场交易的商品，“阳光市场”句子不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“市场”一般不与“时间”组合，“时间市场”不是常用说法。"}], "explanations": {"外汇": "正确：“外汇市场”是指外汇买卖的市场，符合“每天都在变化”的语境。", "天气": "语义：天气不是市场上交易的对象，“天气市场”不通。", "阳光": "语义：阳光不是市场交易的商品，“阳光市场”句子不通。", "时间": "搭配：“市场”一般不与“时间”组合，“时间市场”不是常用说法。"}, "sentence_index": 6, "correct_answer": "外汇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "央行每年印刷大量外汇。", "explanation": "这里应该用〈人民币〉。央行印刷的是本国货币，外汇是外国货币及凭证，不能印刷。"}, {"text": "他买了一本外汇小说。", "explanation": "这里应该用〈外文〉。外汇指外国货币，不能修饰书；外国文字的书应说“外文书”。"}, {"text": "他的外汇有一米八。", "explanation": "这里应该用〈身高〉。外汇是货币，不能用米来量；说人的高度应说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天在银行换了一只外汇。", "corrected_sentence": "他昨天在银行换了一笔外汇。", "error_description": "量词错误：“外汇”应与“笔”搭配，“只”用于动物等，不能用于外汇。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂被外汇进口原料。", "corrected_sentence": "这家工厂用外汇进口原料。", "error_description": "介词错误：“外汇”是进口原料所用的支付手段，应用介词“用”引出，构成“用外汇进口原料”；“被”表示被动，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
