INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92952, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "关心并爱护。", "primary_collocate": null, "pronunciation": "guān huái", "ipa": "kwan˥ xwai˧˥", "syllable_count": 2, "sentences": [{"text": "老师很关怀每一个学生。", "target_word": "关怀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "社会应该关怀老人。", "target_word": "关怀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一直关怀着山区的孩子。", "target_word": "关怀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生不但治病，还关怀每一位病人。", "target_word": "关怀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司很关怀生病的员工。", "target_word": "关怀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "校长常常去看望并关怀贫困学生。", "target_word": "关怀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要关怀身边需要帮助的人。", "target_word": "关怀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者关怀过很多孤独的老人。", "target_word": "关怀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很关怀同事，常常问他们累不累。", "target_word": "关怀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家一直关怀着退休工人的生活。", "target_word": "关怀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关怀着", "label": "体标"}, {"form": "关怀过", "label": "体标"}, {"form": "關懷", "label": "繁体"}], "register": "书面", "sense_fingerprint": "以关心和爱护的态度对待他人，多用于上对下或对弱势群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批发", "is_correct": false, "explanation": "语义：“批发”指成批卖货，不能用来形容老师对学生的态度。"}, {"text": "关怀", "is_correct": true, "explanation": "“关怀”指关心并爱护，与老师对每个学生的态度相符，填入这里正确。"}, {"text": "运输", "is_correct": false, "explanation": "语义：“运输”针对货物，不能用来形容老师对每个学生的态度。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等，不说修建学生。"}], "explanations": {"批发": "语义：“批发”指成批卖货，不能用来形容老师对学生的态度。", "关怀": "“关怀”指关心并爱护，与老师对每个学生的态度相符，填入这里正确。", "运输": "语义：“运输”针对货物，不能用来形容老师对每个学生的态度。", "修建": "搭配：“修建”的对象是房屋、道路等，不说修建学生。"}, "sentence_index": 0, "correct_answer": "关怀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "专家们关怀这次地震的后续情况。", "explanation": "这里应该用〈关注〉。关怀的对象一般是人，“地震的后续情况”是事情，要用〈关注〉。"}, {"text": "我妈妈每天都关怀院子里的花。", "explanation": "这里应该用〈照料〉。关怀多用于对人的关爱，给花草浇水、施肥要用〈照料〉。"}, {"text": "工厂要关怀生产安全，每天都派人检查。", "explanation": "这里应该用〈监督〉。关怀指对人的关心爱护，检查生产安全要用〈监督〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装修", "is_correct": false, "explanation": "语义：“装修”针对房屋，不能用来形容对身边人的关爱。"}, {"text": "关怀", "is_correct": true, "explanation": "“关怀”指关心并爱护，与“身边需要帮助的人”相符，填入这里正确。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”指用工具量长度、重量，与对人的关爱无关。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的对象一般是物品，不说清洗需要帮助的人。"}], "explanations": {"装修": "语义：“装修”针对房屋，不能用来形容对身边人的关爱。", "关怀": "“关怀”指关心并爱护，与“身边需要帮助的人”相符，填入这里正确。", "测量": "语义：“测量”指用工具量长度、重量，与对人的关爱无关。", "清洗": "搭配：“清洗”的对象一般是物品，不说清洗需要帮助的人。"}, "sentence_index": 6, "correct_answer": "关怀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很关怀这本书，从不乱写乱画。", "explanation": "这里应该用〈爱惜〉。关怀的对象是人，珍惜物品要用〈爱惜〉。"}, {"text": "我们要关怀网络安全，不能随便泄露信息。", "explanation": "这里应该用〈维护〉。关怀针对人及其生活、冷暖，网络安全是一种制度性的事物，保障它要用〈维护〉。"}, {"text": "工人每天都关怀机器，防止出故障。", "explanation": "这里应该用〈保养〉。机器是物品，关怀多指对人的关爱，给机器做维护要用〈保养〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区干部每天都关怀了独居老人，帮他们买菜。", "corrected_sentence": "社区干部每天都关怀独居老人，帮他们买菜。", "error_description": "了用错：“每天都”表示经常发生的动作，不与表示完成的“了”搭配，应去掉“了”，说“每天都关怀独居老人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该多关怀了身边的困难家庭。", "corrected_sentence": "我们应该多关怀身边的困难家庭。", "error_description": "了用错：“应该”表示应当，不与表示完成的“了”搭配，这里应去掉“了”，说“应该多关怀身边的困难家庭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
