INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92953, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好多是特别多。", "primary_collocate": null, "pronunciation": "hǎo duō", "ipa": "xaʊ˨˩ twɔ˥", "syllable_count": 2, "sentences": [{"text": "过年的时候，街上好多人，特别热闹。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天海边好多人，找不到位子。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末商店里好多人，排队排了很久。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友好多，每天都有人找他。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天做了好多作业，累极了。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了好多好吃的，装满了冰箱。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛那天来了好多记者，门口都站满了。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的雪好多，路都看不见了。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了好多糖，牙都疼了。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我花了好多钱，只好少买东西。", "target_word": "好多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "强调数量特别多，带有惊讶或夸张的语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDE