INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92953, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好少", "is_correct": false, "explanation": "语义：“好少”说人数少，与“特别热闹”的语境相矛盾。"}, {"text": "好多", "is_correct": true, "explanation": "“好多”强调数量特别多，与“街上”和“特别热闹”相合，填入后句意通顺。"}, {"text": "好冷", "is_correct": false, "explanation": "搭配：“冷”形容温度，不修饰人的数量。"}, {"text": "好慢", "is_correct": false, "explanation": "搭配：“慢”形容速度，不修饰人的数量。"}], "explanations": {"好少": "语义：“好少”说人数少，与“特别热闹”的语境相矛盾。", "好多": "“好多”强调数量特别多，与“街上”和“特别热闹”相合，填入后句意通顺。", "好冷": "搭配：“冷”形容温度，不修饰人的数量。", "好慢": "搭配：“慢”形容速度，不修饰人的数量。"}, "sentence_index": 0, "correct_answer": "好多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车好多钱？", "explanation": "这里“好多”表示“多少”，用于问价钱，不是“特别多”的意思。"}, {"text": "我的感冒好多了。", "explanation": "这里“好多”表示“好得多”，说病情好转很多，不是数量多。"}, {"text": "这次考试他比我好多了。", "explanation": "这里“好多”表示“好得多”，说成绩高出很多，不是数量多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
