INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好酸", "is_correct": false, "explanation": "搭配：“酸”形容味道，不修饰学生的数量。"}, {"text": "好慢", "is_correct": false, "explanation": "搭配：“慢”形容速度，不修饰学生的数量。"}, {"text": "好多", "is_correct": true, "explanation": "“好多”表示数量很大，与“来了”和“学生”相合，填入后句意通顺。"}, {"text": "好热", "is_correct": false, "explanation": "搭配：“热”形容温度，不修饰学生的数量。"}], "explanations": {"好酸": "搭配：“酸”形容味道，不修饰学生的数量。", "好慢": "搭配：“慢”形容速度，不修饰学生的数量。", "好多": "“好多”表示数量很大，与“来了”和“学生”相合，填入后句意通顺。", "好热": "搭配：“热”形容温度，不修饰学生的数量。"}, "sentence_index": 6, "correct_answer": "好多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件外套好多钱？", "explanation": "这里“好多”表示“多少”，用于问价钱，不是“数量很大”的意思。"}, {"text": "睡了一觉，我好多了。", "explanation": "这里“好多”表示“好得多”，说身体状况好转，不是数量多。"}, {"text": "她的中文比去年好多了。", "explanation": "这里“好多”表示“好得多”，说能力提高很多，不是数量多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了好多了书。", "corrected_sentence": "我买了好多书。", "error_description": "“好多”后多写了一个“了”。“好多了”表示好得多，与“书”不搭；应写作“我买了好多书”。只删去多出的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们给我寄了很好多信。", "corrected_sentence": "他们给我寄了好多信。", "error_description": "错误形式：“很好多”；正确形式：“好多”。“好多”本身已表示数量很大，不能再加程度副词“很”修饰；应删去“很”，写作“寄了好多信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
