INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92955, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防范是先做好准备，不让坏事发生。", "primary_collocate": null, "pronunciation": "fáng fàn", "ipa": "faŋ˧˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "出门前关好门窗，是为了防范小偷。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天容易感冒，我们要提前防范。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很小心，早就防范着这种事发生。", "target_word": "防范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防范火灾，每层楼都放了灭火器。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要防范他，他常常说话不算数。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教孩子怎么防范陌生人。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪以后路很滑，大家要防范交通事故。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们已经防范了，还是出了问题。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑里有重要的东西，要防范病毒。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把门锁好，才能防范坏人进来。", "target_word": "防范", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防范了", "label": "体标"}, {"form": "防范着", "label": "体标"}, {"form": "防范过", "label": "体标"}, {"form": "防范措施", "label": "复合"}, {"form": "防範", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事先做好准备，不让坏事发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防范", "is_correct": true, "explanation": "防范：事先采取措施防止小偷，符合“是为了”的目的。"}, {"text": "款待", "is_correct": false, "explanation": "语义：“款待”是热情招待，与“为了防小偷”的目的相反。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”是不及物动词，后面不能直接带“小偷”作宾语。"}, {"text": "陪伴", "is_correct": false, "explanation": "语义：“陪伴”指陪着别人，与“关好门窗”的目的不合。"}], "explanations": {"防范": "防范：事先采取措施防止小偷，符合“是为了”的目的。", "款待": "语义：“款待”是热情招待，与“为了防小偷”的目的相反。", "结婚": "配价：“结婚”是不及物动词，后面不能直接带“小偷”作宾语。", "陪伴": "语义：“陪伴”指陪着别人，与“关好门窗”的目的不合。"}, "sentence_index": 0, "correct_answer": "防范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校努力防范学生的兴趣。", "explanation": "这里应该用〈培养〉。“防范”用于不利的事，培养兴趣要用“培养”。"}, {"text": "我们防范大家的帮助。", "explanation": "这里应该用〈感谢〉。“防范”不能用于感激他人的帮助，应说“感谢大家的帮助”。"}, {"text": "大家防范节日的到来。", "explanation": "这里应该用〈庆祝〉。节日是令人高兴的事，不能用“防范”，应说“庆祝节日的到来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防范", "is_correct": true, "explanation": "防范：事先采取措施，避免发生交通事故，符合“路很滑，大家要”的语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱地看，不能用于交通事故。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”用于活动、比赛，不能说“参加交通事故”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示愉快地接受好事，与交通事故这种不利之事不合。"}], "explanations": {"防范": "防范：事先采取措施，避免发生交通事故，符合“路很滑，大家要”的语境。", "欣赏": "语义：“欣赏”表示喜爱地看，不能用于交通事故。", "参加": "搭配：“参加”用于活动、比赛，不能说“参加交通事故”。", "享受": "语义：“享受”表示愉快地接受好事，与交通事故这种不利之事不合。"}, "sentence_index": 6, "correct_answer": "防范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家热情地防范新来的同学。", "explanation": "这里应该用〈欢迎〉。“防范”针对不利或危险的事，热情接待新同学要用“欢迎”。"}, {"text": "妈妈经常防范我的进步。", "explanation": "这里应该用〈夸奖〉。“防范”针对不利的事，称赞进步要用“夸奖”。"}, {"text": "工人正在防范电梯。", "explanation": "这里应该用〈修理〉。“防范”的对象是危险，维修设备要用“修理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上次我们没防范了，所以出了事。", "corrected_sentence": "上次我们没防范，所以出了事。", "error_description": "“没”后不能再带“了”。否定过去已发生的动作用“没”，但不能同时加“了”。正确形式是“上次我们没防范”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个门锁很安全，能很防范小偷。", "corrected_sentence": "这个门锁很安全，能防范小偷。", "error_description": "“防范”前多加了副词“很”。“很”不能修饰这类动作动词，应删去，正确形式是“能防范小偷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
