INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92956, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "戒备，采取措施以防止不利或危险的事情发生。", "primary_collocate": null, "pronunciation": "fáng fàn", "ipa": "faŋ˧˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "我们要防范小偷。", "target_word": "防范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "银行提醒大家要防范电信诈骗。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天要防范火灾，不能乱扔烟头。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门在外，要时时防范坏人。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察提醒市民，要防范身边的骗子。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直防范着陌生人，什么也不说。", "target_word": "防范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校教学生怎样防范地震带来的危险。", "target_word": "防范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该提前防范，不要等出事以后才后悔。", "target_word": "防范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府早就防范了这种病，所以没有大问题。", "target_word": "防范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区常下大雨，当地人很会防范洪水。", "target_word": "防范", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防范了", "label": "体标"}, {"form": "防范着", "label": "体标"}, {"form": "防范过", "label": "体标"}, {"form": "防范措施", "label": "复合"}, {"form": "防範", "label": "繁体"}], "register": "中性", "sense_fingerprint": "戒备并采取措施防止危险或不利之事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防范", "is_correct": true, "explanation": "防范：事先采取措施防止小偷，符合“我们要”的语义。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示热情接待，不能用于小偷。"}, {"text": "逃跑", "is_correct": false, "explanation": "配价：“逃跑”是不及物动词，不能带“小偷”作宾语。"}, {"text": "尊敬", "is_correct": false, "explanation": "语义：“尊敬”表示敬重，不能用于小偷。"}], "explanations": {"防范": "防范：事先采取措施防止小偷，符合“我们要”的语义。", "欢迎": "语义：“欢迎”表示热情接待，不能用于小偷。", "逃跑": "配价：“逃跑”是不及物动词，不能带“小偷”作宾语。", "尊敬": "语义：“尊敬”表示敬重，不能用于小偷。"}, "sentence_index": 0, "correct_answer": "防范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一定要防范孩子的安全。", "explanation": "这里应该用〈保护〉。“防范”针对坏人、危险等不利的事，不能用来说“防范安全”。"}, {"text": "老师每天认真防范学生的作业。", "explanation": "这里应该用〈检查〉。“防范”针对不利或危险的事，检查作业要用“检查”，不能用“防范”。"}, {"text": "我们热情防范远道而来的客人。", "explanation": "这里应该用〈欢迎〉。“防范”表示提防不利的事，不能用来表示热情接待客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防范", "is_correct": true, "explanation": "防范：事先采取措施，防止地震带来的危险，符合“教学生怎样”的语境。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示愉快地接受好事，与地震的危险不合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于场所、展览，不能用于“危险”。"}, {"text": "理睬", "is_correct": false, "explanation": "搭配：“理睬”指对人有所回应，不能用于“危险”。"}], "explanations": {"防范": "防范：事先采取措施，防止地震带来的危险，符合“教学生怎样”的语境。", "享受": "语义：“享受”表示愉快地接受好事，与地震的危险不合。", "参观": "搭配：“参观”用于场所、展览，不能用于“危险”。", "理睬": "搭配：“理睬”指对人有所回应，不能用于“危险”。"}, "sentence_index": 6, "correct_answer": "防范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校经常防范交通安全知识。", "explanation": "这里应该用〈宣传〉。“防范”针对不利的事，传播知识要用“宣传”。"}, {"text": "工人们每天防范教室。", "explanation": "这里应该用〈打扫〉。“防范”的对象是危险或坏人，不能用于打扫场所。"}, {"text": "妈妈在客厅里热情防范客人，给他们倒茶。", "explanation": "这里应该用〈招待〉。客人不是危险，热情接待客人要用“招待”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "保安们应该防范了小偷。", "corrected_sentence": "保安们应该防范小偷。", "error_description": "“防范”后多加了“了”。“应该”表示应当，与表示完成的“了”矛盾。正确形式是“应该防范小偷”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要认真防范过网络诈骗。", "corrected_sentence": "我们要认真防范网络诈骗。", "error_description": "体标错误。“过”表示曾经有过的经历，与表示应当的“要”矛盾。正确形式是“要认真防范网络诈骗”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
