INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "客人；来访的人。", "primary_collocate": null, "pronunciation": "kè", "ipa": "kʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "门口有客，你去开门吧。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客不多，只有三位。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主人让客先坐下。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对客很热情。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位客等了很久。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是从远方来的客。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客要走了，主人送到门外。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，今天来的客是谁？", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司来客，先倒茶。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客喝完茶，就和主人聊天。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "客人", "label": "复合"}], "register": "中性", "sense_fingerprint": "被主人接待的来访者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "客", "is_correct": true, "explanation": "客（kè）指被接待的来访者，是正确答案。"}, {"text": "渴", "is_correct": false, "explanation": "渴（kě，第三声）与 kè（第四声）声调不同，意思是口渴。"}, {"text": "棵", "is_correct": false, "explanation": "棵（kē，第一声）与 kè 声调不同，是量词，用于树木。"}, {"text": "壳", "is_correct": false, "explanation": "壳（ké，第二声）与 kè 声调不同，意思是外壳。"}, {"text": "各", "is_correct": false, "explanation": "各（gè）与 kè 声母不同（g 与 k），意思是各自、每个。"}], "explanations": {"客": "客（kè）指被接待的来访者，是正确答案。", "渴": "渴（kě，第三声）与 kè（第四声）声调不同，意思是口渴。", "棵": "棵（kē，第一声）与 kè 声调不同，是量词，用于树木。", "壳": "壳（ké，第二声）与 kè 声调不同，意思是外壳。", "各": "各（gè）与 kè 声母不同（g 与 k），意思是各自、每个。"}, "sentence_index": null, "correct_answer": "客"}, "level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "语义：下雨不需要去开门，与“你去开门”的情境不合。"}, {"text": "客", "is_correct": true, "explanation": "客指来访的人，“门口有客”指有人来访，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“门口有”后接的是具体的人或物，“空气”不这样搭配。"}, {"text": "火", "is_correct": false, "explanation": "语义：门口有火与“你去开门”的情境不合，而且有危险。"}], "explanations": {"雨": "语义：下雨不需要去开门，与“你去开门”的情境不合。", "客": "客指来访的人，“门口有客”指有人来访，符合句意。", "空气": "搭配：“门口有”后接的是具体的人或物，“空气”不这样搭配。", "火": "语义：门口有火与“你去开门”的情境不合，而且有危险。"}, "sentence_index": 0, "correct_answer": "客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐车去工厂当客，负责修理机器。", "explanation": "这里应该用〈当工人〉。“客”指来访的人，在工厂工作的是工人，不能说“当客”。"}, {"text": "我家的小狗是客，它一直住在我们家。", "explanation": "这里应该用〈宠物〉。“客”指来访的人，一直住在家里的小狗不是客。"}, {"text": "这间屋子的客是我，我来招待你们。", "explanation": "这里应该用〈主人〉。招待客人的是主人，“客”是被招待的人，不能说自己是客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "客", "is_correct": true, "explanation": "客（kè）指被接待的来访者，是正确答案。"}, {"text": "贺", "is_correct": false, "explanation": "贺（hè）与 kè 声母不同（h 与 k），意思是祝贺。"}, {"text": "可", "is_correct": false, "explanation": "可（kě，第三声）与 kè（第四声）声调不同，意思是“可以”。"}, {"text": "科", "is_correct": false, "explanation": "科（kē，第一声）与 kè 声调不同，意思是学科、科目。"}, {"text": "咳", "is_correct": false, "explanation": "咳（ké，第二声）与 kè（第四声）声调不同，意思是咳嗽。"}], "explanations": {"客": "客（kè）指被接待的来访者，是正确答案。", "贺": "贺（hè）与 kè 声母不同（h 与 k），意思是祝贺。", "可": "可（kě，第三声）与 kè（第四声）声调不同，意思是“可以”。", "科": "科（kē，第一声）与 kè 声调不同，意思是学科、科目。", "咳": "咳（ké，第二声）与 kè（第四声）声调不同，意思是咳嗽。"}, "sentence_index": null, "correct_answer": "客"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“要走了”，与“主人送到门外”也不合。"}, {"text": "客", "is_correct": true, "explanation": "客指来访的人，“要走了”和“主人送到门外”说的都是客人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己离开，与“要走了”的说法不合。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“要走了”的主语应是能自行离开的人或物，墙不能说要走。"}], "explanations": {"桌子": "语义：桌子不会“要走了”，与“主人送到门外”也不合。", "客": "客指来访的人，“要走了”和“主人送到门外”说的都是客人。", "石头": "语义：石头不会自己离开，与“要走了”的说法不合。", "墙": "搭配：“要走了”的主语应是能自行离开的人或物，墙不能说要走。"}, "sentence_index": 6, "correct_answer": "客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的客是我爸爸，他每天在店里卖东西。", "explanation": "这里应该用〈老板〉。在店里卖东西的是老板，不是来访的客。"}, {"text": "医院里的客正在给病人看病。", "explanation": "这里应该用〈医生〉。给病人看病的是医生，“客”指来访的人。"}, {"text": "院子里停着一辆车，车上的客装满了砖头。", "explanation": "这里应该用〈货〉。“客”指来访的人，不能指装在车上的货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末，客们陆续来了。", "corrected_sentence": "周末，客人们陆续来了。", "error_description": "错误：“客们”。“客”单用时不能直接加“们”，应说“客人们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天来了三条客，厨房都忙不过来了。", "corrected_sentence": "今天来了三位客人，厨房都忙不过来了。", "error_description": "错误：“三条客”。“条”用于细长的东西，指人应用“位”，应说“三位客人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
