INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "附带在主体上、作为主体一部分的（多指建筑、设备、部件等）。", "primary_collocate": null, "pronunciation": "fù shǔ", "ipa": "fu˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个附属房间很小，只能放杂物。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机的附属部件都放在盒子里。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主楼旁边有一个附属建筑。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电脑时，他还买了一些附属设备。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小花园是房子的附属部分。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的附属光盘在书后面的袋子里。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房旁边是一间附属的小仓库。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上画着大楼和它的附属小楼。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的附属停车场很大。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的附属抽屉可以放笔和本子。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "附属品", "label": "复合"}, {"form": "附属医院", "label": "复合"}], "register": "中性", "sense_fingerprint": "跟随主体、作为其一部分的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdadcb77-e6c4-4c9d-9376-79a977628fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。附属 fù shǔ，指跟着一个大东西、属于它的一部分。"}, {"text": "复数", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）第二个音节声调不同，意思是复数。"}, {"text": "服输", "is_correct": false, "explanation": "fú shū（第二、第一声）与 fù shǔ（第四、第三声）两个音节声调都不同，意思是认输。"}, {"text": "部属", "is_correct": false, "explanation": "bù 与 fù 声母不同（b 与 f），意思是部下。"}], "explanations": {"附属": "正确。附属 fù shǔ，指跟着一个大东西、属于它的一部分。", "复数": "shù（第四声）与 shǔ（第三声）第二个音节声调不同，意思是复数。", "服输": "fú shū（第二、第一声）与 fù shǔ（第四、第三声）两个音节声调都不同，意思是认输。", "部属": "bù 与 fù 声母不同（b 与 f），意思是部下。"}, "sentence_index": null, "correct_answer": "附属"}, "level_3": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。“附属房间”指与主体相连、属于它的小房间，与“很小”“放杂物”相合。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”与后文“很小”矛盾。"}, {"text": "豪华", "is_correct": false, "explanation": "语义：豪华的房间不会只能放杂物。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”指高而大，与后文“很小”矛盾。"}], "explanations": {"附属": "正确。“附属房间”指与主体相连、属于它的小房间，与“很小”“放杂物”相合。", "宽敞": "语义：“宽敞”与后文“很小”矛盾。", "豪华": "语义：豪华的房间不会只能放杂物。", "高大": "语义：“高大”指高而大，与后文“很小”矛盾。"}, "sentence_index": 0, "correct_answer": "附属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑还要交一笔附属费。", "explanation": "这里应该用〈附加〉。附加表示额外增加的费用；附属指属于某主体的一部分，不能用来说费用。"}, {"text": "这封邮件里有一个附属。", "explanation": "这里应该用〈附件〉。附件指随正文一同发送的文件；附属是形容词，不能单独作名词指邮件里的附加文件。"}, {"text": "他在实验中是附属的主角。", "explanation": "这里应该用〈主要〉。主要指居于首位；附属指依附于主体，与“主角”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。“附属的小仓库”指与厨房相连、属于它的小仓库，与语境相合。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，不能用来修饰仓库。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”多形容街区、市场，不用来说仓库。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”多用来形容人，不用来形容仓库。"}], "explanations": {"附属": "正确。“附属的小仓库”指与厨房相连、属于它的小仓库，与语境相合。", "勇敢": "搭配：“勇敢”形容人的品质，不能用来修饰仓库。", "繁华": "搭配：“繁华”多形容街区、市场，不用来说仓库。", "年轻": "搭配：“年轻”多用来形容人，不用来形容仓库。"}, "sentence_index": 6, "correct_answer": "附属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震之后又出现了附属灾害。", "explanation": "这里应该用〈次生〉。次生灾害指由原生灾害引起的灾害；附属不能用来说灾害。"}, {"text": "这种病的附属症状很明显。", "explanation": "这里应该用〈伴随〉。伴随症状指与主病同时出现的症状；附属强调属于主体的一部分，不这样说。"}, {"text": "这只是附属原因。", "explanation": "这里应该用〈次要〉。次要表示不是主要的；附属强调依附于某主体，不用来说原因的主次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间附属了主楼。", "corrected_sentence": "这个房间附属于主楼。", "error_description": "漏“于”：“附属”后面要用“于”引出所属的主体，应说“附属于主楼”，不能说“附属了主楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台游戏机的附属于配件都放在柜子里。", "corrected_sentence": "这台游戏机的附属配件都放在柜子里。", "error_description": "多出“于”：“附属”作定语修饰“配件”时后面不加“于”，应说“附属配件”；“附属于”只用于后面带所属主体的情况，不能直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
