INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "依附于某一主体或隶属于某一单位。", "primary_collocate": null, "pronunciation": "fù shǔ", "ipa": "fu˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在北京大学附属医院工作。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所附属中学离大学很近。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司附属于一家大企业。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿在师范大学附属小学读书。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究所附属于国家科学院。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附属学校的老师都是大学请来的。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院是大学的附属单位。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附属医院的医生经验很丰富。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的工厂附属于总公司。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的孩子都在附属幼儿园上学。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "附属品", "label": "复合"}, {"form": "附属医院", "label": "复合"}], "register": "中性", "sense_fingerprint": "隶属于某个单位或机构的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdadcb77-e6c4-4c9d-9376-79a977628fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。附属 fù shǔ，指依附于某一主体或隶属于某一单位。"}, {"text": "负数", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）第二个音节声调不同，意思是负数。"}, {"text": "服输", "is_correct": false, "explanation": "fú shū（第二、第一声）与 fù shǔ（第四、第三声）两个音节声调都不同，意思是认输。"}, {"text": "部属", "is_correct": false, "explanation": "bù 与 fù 声母不同（b 与 f），意思是部下。"}], "explanations": {"附属": "正确。附属 fù shǔ，指依附于某一主体或隶属于某一单位。", "负数": "shù（第四声）与 shǔ（第三声）第二个音节声调不同，意思是负数。", "服输": "fú shū（第二、第一声）与 fù shǔ（第四、第三声）两个音节声调都不同，意思是认输。", "部属": "bù 与 fù 声母不同（b 与 f），意思是部下。"}, "sentence_index": null, "correct_answer": "附属"}, "level_3": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。“附属医院”指隶属于大学的医院，与“北京大学”和“工作”相合。"}, {"text": "愉快", "is_correct": false, "explanation": "搭配：“愉快”形容人的心情，不用来修饰医院。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”形容天气或环境，不用来修饰医院。"}, {"text": "荒凉", "is_correct": false, "explanation": "语义：北京大学的医院不会荒凉，与语境不符。"}], "explanations": {"附属": "正确。“附属医院”指隶属于大学的医院，与“北京大学”和“工作”相合。", "愉快": "搭配：“愉快”形容人的心情，不用来修饰医院。", "寒冷": "搭配：“寒冷”形容天气或环境，不用来修饰医院。", "荒凉": "语义：北京大学的医院不会荒凉，与语境不符。"}, "sentence_index": 0, "correct_answer": "附属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是局长的附属领导。", "explanation": "这里应该用〈直属〉。直属指直接隶属于某上级，说领导要用直属；附属指依附于主体，不说领导。"}, {"text": "这套房子附属于车库。", "explanation": "这里应该用〈附有〉。附有表示带有某物；附属于指某物隶属于某主体，房子不能隶属于车库。"}, {"text": "北京是一个附属市。", "explanation": "这里应该用〈直辖〉。直辖市直接由中央管辖；附属指属于某主体，不能说“附属市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。“附属单位”指隶属于大学的单位，与“大学的”相合。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：“幸福”形容人的感受，不用来形容单位。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人的说话方式，不用来修饰单位。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：医院或单位不用“凶猛”形容，与语境不合。"}], "explanations": {"附属": "正确。“附属单位”指隶属于大学的单位，与“大学的”相合。", "幸福": "搭配：“幸福”形容人的感受，不用来形容单位。", "幽默": "搭配：“幽默”形容人的说话方式，不用来修饰单位。", "凶猛": "语义：医院或单位不用“凶猛”形容，与语境不合。"}, "sentence_index": 6, "correct_answer": "附属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很附属，穿着很舒服。", "explanation": "这里应该用〈合身〉。“穿着很舒服”说的是衣服大小合适；附属指隶属于某单位，不能形容衣服，也不能受“很”修饰。"}, {"text": "这家餐厅还收了一笔附属服务费。", "explanation": "这里应该用〈附加〉。附加表示另外增加的费用；附属不能用来说服务费。"}, {"text": "他从小就附属父母，什么事都要问他们。", "explanation": "这里应该用〈依赖〉。依赖指在生活上靠别人；附属指单位、机构隶属于另一单位，不用来说人对父母的依靠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所小医院附属一家大学。", "corrected_sentence": "这所小医院附属于一家大学。", "error_description": "漏了“于”：表示隶属关系时，“附属”后面要加“于”再接单位，应说“附属于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个实验室是那所大学的附属于单位。", "corrected_sentence": "这个实验室是那所大学的附属单位。", "error_description": "多出“于”：“附属”作定语修饰“单位”时后面不加“于”，应说“附属单位”；“附属于”要接所属的主体，不能直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92961, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92961, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "屠杀是大批地伤害并杀死人或动物。", "primary_collocate": null, "pronunciation": "tú shā", "ipa": "tʰu˧˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "士兵屠杀了很多无辜的村民。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不应该屠杀这些野生动物。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人在村里屠杀了几百人。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，军队屠杀过许多平民。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人为了皮毛，大量屠杀狐狸。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些人屠杀动物，实在太残忍。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把全村的牛羊都屠杀了。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，侵略者屠杀过无数百姓。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想屠杀所有反对的人。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们怕敌人来屠杀他们。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "屠杀了", "label": "完成体"}, {"form": "屠杀过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "动词，大批地伤害并杀死人或动物，对象可以是人也可以是动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屠杀", "is_correct": true, "explanation": "正确：“屠杀”指大批残酷地杀害，符合“大批杀害无辜的村民”的语境。"}, {"text": "包庇", "is_correct": false, "explanation": "语义：“包庇”指袒护坏人，与“无辜”的村民矛盾。"}, {"text": "收养", "is_correct": false, "explanation": "搭配：“收养”多用于孩子或弃儿，不能说收养大批成年村民。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”的前提是对方有过错，无辜的村民不需要被原谅，句子不通。"}], "explanations": {"屠杀": "正确：“屠杀”指大批残酷地杀害，符合“大批杀害无辜的村民”的语境。", "包庇": "语义：“包庇”指袒护坏人，与“无辜”的村民矛盾。", "收养": "搭配：“收养”多用于孩子或弃儿，不能说收养大批成年村民。", "原谅": "语义：“原谅”的前提是对方有过错，无辜的村民不需要被原谅，句子不通。"}, "sentence_index": 0, "correct_answer": "屠杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他屠杀了一个邻居。", "explanation": "这里应该用〈杀害〉。屠杀指大批残酷地杀人，只杀一个人应说“杀害”。"}, {"text": "法院屠杀了那名死刑犯。", "explanation": "这里应该用〈处决〉。依法执行单人死刑用“处决”，屠杀指大批残酷杀害。"}, {"text": "军队屠杀了这次示威。", "explanation": "这里应该用〈镇压〉。屠杀的对象是人，且指大批杀害，不能用于一场示威活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屠杀", "is_correct": true, "explanation": "正确：“屠杀”指大批残酷地杀害，符合“把全村的牛羊都屠杀了”的语境。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”的对象是人，不能说表扬牛羊。"}, {"text": "教育", "is_correct": false, "explanation": "搭配：“教育”的对象是人，不能用于牛羊。"}, {"text": "宠爱", "is_correct": false, "explanation": "语义：“宠爱”指特别疼爱心爱的人或宠物，与大批牛羊的语境不符。"}], "explanations": {"屠杀": "正确：“屠杀”指大批残酷地杀害，符合“把全村的牛羊都屠杀了”的语境。", "表扬": "搭配：“表扬”的对象是人，不能说表扬牛羊。", "教育": "搭配：“教育”的对象是人，不能用于牛羊。", "宠爱": "语义：“宠爱”指特别疼爱心爱的人或宠物，与大批牛羊的语境不符。"}, "sentence_index": 6, "correct_answer": "屠杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天把那只蚊子屠杀了。", "explanation": "这里应该用〈打死〉。屠杀指大批残酷地杀害，打死一只蚊子应说“打死”。"}, {"text": "警察屠杀了那个逃犯。", "explanation": "这里应该用〈击毙〉。屠杀指大批残杀，警察开枪打死单个逃犯应说“击毙”。"}, {"text": "他屠杀了一条毒蛇。", "explanation": "这里应该用〈杀死〉。屠杀指大批杀害，杀死一条毒蛇应说“杀死”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那支部队曾经屠杀着很多平民。", "corrected_sentence": "那支部队曾经屠杀过很多平民。", "error_description": "体标错误：“曾经”表示过去的经历，应用经历体“过”，“着”表示持续，不能用于此处，应为“屠杀过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那伙人把整个村子的人都屠杀地了。", "corrected_sentence": "那伙人把整个村子的人都屠杀了。", "error_description": "助词错误：动词“屠杀”后多出了“地”，“地”只用于动词前作状语，应去掉，为“都屠杀了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
