INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92962, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92962, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大批残酷地杀害。", "primary_collocate": null, "pronunciation": "tú shā", "ipa": "tʰu˧˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "敌人残酷地屠杀了那里的居民。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们残酷地屠杀着无辜的人。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家曾屠杀过很多少数民族。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侵略军进城后，开始屠杀百姓。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了士兵屠杀妇女和孩子的事。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些人冷酷地屠杀了整个村子的人。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们屠杀俘虏，违反了战争的规则。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人哭着说，敌人屠杀了他全家。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凶手无情地屠杀了所有的家人。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能原谅屠杀儿童的人。", "target_word": "屠杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "屠杀了", "label": "完成体"}, {"form": "屠杀着", "label": "持续体"}, {"form": "屠杀过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "动词，残酷无情地大批杀害，多用于战争、侵略和暴行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屠杀", "is_correct": true, "explanation": "正确：“屠杀”指残酷地大批杀害，符合“残酷地……居民”的语境。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“残酷地”与“感谢”的温和含义相矛盾，句子不通。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“残酷地”与“照顾”的关怀含义相矛盾，句子不通。"}, {"text": "收养", "is_correct": false, "explanation": "搭配：“收养”多用于孩子或弃儿，不能说收养大批成年居民。"}], "explanations": {"屠杀": "正确：“屠杀”指残酷地大批杀害，符合“残酷地……居民”的语境。", "感谢": "语义：“残酷地”与“感谢”的温和含义相矛盾，句子不通。", "照顾": "语义：“残酷地”与“照顾”的关怀含义相矛盾，句子不通。", "收养": "搭配：“收养”多用于孩子或弃儿，不能说收养大批成年居民。"}, "sentence_index": 0, "correct_answer": "屠杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那群强盗屠杀了一个路人。", "explanation": "这里应该用〈杀害〉。屠杀指大批残酷地杀害，只杀一个路人应说“杀害”。"}, {"text": "他把那封信屠杀了。", "explanation": "这里应该用〈撕毁〉。屠杀的对象是生命，信件不能被屠杀，应说“撕毁”。"}, {"text": "政府屠杀了那次暴动。", "explanation": "这里应该用〈镇压〉。屠杀的对象是人，且指大批杀害，不能用于一次暴动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屠杀", "is_correct": true, "explanation": "正确：“屠杀”指残酷地大批杀害，符合“屠杀俘虏”的语境。"}, {"text": "释放", "is_correct": false, "explanation": "语义：释放俘虏本身并不违反战争规则，与“违反了战争的规则”矛盾。"}, {"text": "优待", "is_correct": false, "explanation": "语义：优待俘虏符合战争规则，与“违反了战争的规则”矛盾。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”一般不用于俘虏这类对象，句子搭配不通。"}], "explanations": {"屠杀": "正确：“屠杀”指残酷地大批杀害，符合“屠杀俘虏”的语境。", "释放": "语义：释放俘虏本身并不违反战争规则，与“违反了战争的规则”矛盾。", "优待": "语义：优待俘虏符合战争规则，与“违反了战争的规则”矛盾。", "赞美": "搭配：“赞美”一般不用于俘虏这类对象，句子搭配不通。"}, "sentence_index": 6, "correct_answer": "屠杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的粗心屠杀了朋友的感情。", "explanation": "这里应该用〈伤害〉。屠杀只用于残害生命，不能用于感情。"}, {"text": "士兵屠杀了那个逃兵。", "explanation": "这里应该用〈处决〉。屠杀指大批残杀，对单个逃兵执行死刑应说“处决”。"}, {"text": "我昨天把那只苍蝇屠杀了。", "explanation": "这里应该用〈拍死〉。屠杀指大批残酷杀害，拍死一只苍蝇应说“拍死”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那次战争中，敌人曾经屠杀着很多平民。", "corrected_sentence": "那次战争中，敌人曾经屠杀过很多平民。", "error_description": "体标错误：“曾经”表示过去的经历，应用经历体“过”，“着”表示持续，不能用于此处，应为“屠杀过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那支军队残酷得屠杀了全村的人。", "corrected_sentence": "那支军队残酷地屠杀了全村的人。", "error_description": "助词错误：修饰动词的状语应用“地”，不能用“得”，应为“残酷地屠杀”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
