INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92965, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "平时是平常的日子，不是特别的日子。", "primary_collocate": null, "pronunciation": "píng shí", "ipa": "pʰiŋ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "平时我很忙，周末才休息。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时我们吃得很简单，过年才做大菜。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时他穿得很普通，今天却穿了西装。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店平时人很少，节日人才多。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时妈妈做饭，今天爸爸做了。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时学校八点上课，考试那天九点。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我平时不喝咖啡，只在生日喝一杯。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时路上车不多，下雨天就堵车了。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷平时早上六点起床，今天睡晚了。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们平时很安静，今天特别高兴。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "平时：与节日、考试等特别日子相对的平常日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平时", "is_correct": true, "explanation": "正确：平时指平常的日子，与“周末才休息”描述的日常安排相符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是特定的一天，不表示平常的日子，与“我很忙”这一日常状况不符。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能用作时间状语，“很我很忙”不成立。"}, {"text": "却", "is_correct": false, "explanation": "语法：“却”是转折副词，须位于主语之后，“却我很忙”不成立。"}], "explanations": {"平时": "正确：平时指平常的日子，与“周末才休息”描述的日常安排相符。", "生日": "语义：生日是特定的一天，不表示平常的日子，与“我很忙”这一日常状况不符。", "很": "语法：“很”是程度副词，不能用作时间状语，“很我很忙”不成立。", "却": "语法：“却”是转折副词，须位于主语之后，“却我很忙”不成立。"}, "sentence_index": 0, "correct_answer": "平时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震那天是平时的一天，大家都很平静。", "explanation": "这里误用了〈平时〉。平时指平常的日子，与地震这类特殊事件相对，地震那天不是平时的一天，不能这样说。"}, {"text": "这场期末考试是平时的一次小测验，没什么要紧的。", "explanation": "这里误用了〈平时〉。平时指平常的日子，与期末考试这类特殊场合相对，不能说期末考试是“平时的小测验”。"}, {"text": "我的生日平时过得很快乐。", "explanation": "这里误用了〈平时〉：“平时”指平常的日子，生日是特别的日子，不能说生日“平时”过得怎样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平时", "is_correct": true, "explanation": "正确：平时表示日常的习惯，与“只在生日喝一杯”的特殊情况形成对照。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来不喝”与后文“只在生日喝一杯”自相矛盾，不能填入。"}, {"text": "桌子", "is_correct": false, "explanation": "语法：“桌子”是普通名词，不能作状语修饰“不喝咖啡”，“我桌子不喝咖啡”不成立。"}, {"text": "吃饭", "is_correct": false, "explanation": "语法：“吃饭”是动词短语，不能作时间状语，句子不通。"}], "explanations": {"平时": "正确：平时表示日常的习惯，与“只在生日喝一杯”的特殊情况形成对照。", "从来": "语义：“从来不喝”与后文“只在生日喝一杯”自相矛盾，不能填入。", "桌子": "语法：“桌子”是普通名词，不能作状语修饰“不喝咖啡”，“我桌子不喝咖啡”不成立。", "吃饭": "语法：“吃饭”是动词短语，不能作时间状语，句子不通。"}, "sentence_index": 6, "correct_answer": "平时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场婚礼是平时的一次聚会，很热闹。", "explanation": "这里误用了〈平时〉：婚礼是特别的场合，不是平常的日子，不能说它是“平时的一次聚会”。"}, {"text": "这场大地震是平时发生的，人们都很惊讶。", "explanation": "这里误用了〈平时〉。平时指平常的日子，与大地震这类特殊事件相对，不能说地震是“平时发生”的。"}, {"text": "今天是平时，我们要过大年。", "explanation": "这里误用了〈平时〉的“平常的日子”义来说今天，但句中要过大年，大年是特殊节日，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "平时地饭菜很简单。", "corrected_sentence": "平时的饭菜很简单。", "error_description": "错误：“平时”修饰名词“饭菜”时要用“的”，不能用“地”。正确：平时的饭菜很简单。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "平时的训练很平时。", "corrected_sentence": "平时的训练很辛苦。", "error_description": "错误：“平时”是时间名词，不能作谓语，不能说“很平时”。正确：平时的训练很辛苦。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
