INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92966, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "平常；一般的时候。", "primary_collocate": null, "pronunciation": "píng shí", "ipa": "pʰiŋ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "你平时几点睡觉？", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我平时骑自行车去上班。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她平时说话很轻。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时多锻炼，身体才会好。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时喜欢看书，不爱玩游戏。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你平时都吃什么早饭？", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我平时在家做饭，很少出去吃。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈平时很少生气。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时没事的时候，我常常听音乐。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时对人很客气。", "target_word": "平时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "平时：一般情况下、通常的时候，常用来说习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平时", "is_correct": true, "explanation": "正确：平时表示一般情况下的习惯，用来问平常的作息时间。"}, {"text": "吃饭", "is_correct": false, "explanation": "语法：“吃饭”是动词短语，不能作时间状语，“你吃饭几点睡觉”不成立。"}, {"text": "终于", "is_correct": false, "explanation": "语法：“终于”是副词，不能放在“几点睡觉”之前作时间状语，句子不通。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能修饰“几点睡觉”，句子不通。"}], "explanations": {"平时": "正确：平时表示一般情况下的习惯，用来问平常的作息时间。", "吃饭": "语法：“吃饭”是动词短语，不能作时间状语，“你吃饭几点睡觉”不成立。", "终于": "语法：“终于”是副词，不能放在“几点睡觉”之前作时间状语，句子不通。", "很": "语法：“很”是程度副词，不能修饰“几点睡觉”，句子不通。"}, "sentence_index": 0, "correct_answer": "平时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他平时哭了起来，大家都很吃惊。", "explanation": "这里应该用〈突然〉。平时表示一般的习惯，不能用来描述某一次突然发生的动作。"}, {"text": "这次比赛我平时拿了冠军。", "explanation": "这里不该用〈平时〉。平时说的是一般情况下的习惯，不能用来说明这一次比赛的结果。"}, {"text": "他平时第一次考了第一名，大家都很惊讶。", "explanation": "这里误用了〈平时〉的“经常”义：“第一次”是一次性的事，不能用表示经常情况的“平时”来修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平时", "is_correct": true, "explanation": "正确：平时表示一般的习惯，与“很少出去吃”的日常情况相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语法：“厨房”是名词，不能放在“在家做饭”之前作状语，“我厨房在家做饭”不成立。"}, {"text": "便宜", "is_correct": false, "explanation": "语法：“便宜”是形容词，不能修饰动词“做饭”，“我便宜在家做饭”不成立。"}, {"text": "而且", "is_correct": false, "explanation": "语法：“而且”是连词，用于连接分句或并列成分，不能作时间状语，“我而且在家做饭”不成立。"}], "explanations": {"平时": "正确：平时表示一般的习惯，与“很少出去吃”的日常情况相符。", "厨房": "语法：“厨房”是名词，不能放在“在家做饭”之前作状语，“我厨房在家做饭”不成立。", "便宜": "语法：“便宜”是形容词，不能修饰动词“做饭”，“我便宜在家做饭”不成立。", "而且": "语法：“而且”是连词，用于连接分句或并列成分，不能作时间状语，“我而且在家做饭”不成立。"}, "sentence_index": 6, "correct_answer": "平时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车平时要开了。", "explanation": "这里应该用〈马上〉。平时指一般的习惯，不能用来说即将发生的事。"}, {"text": "这次他平时赢了一大笔钱，大家都很羡慕。", "explanation": "这里误用了〈平时〉的“经常”义：“这次”指一次性的事件，不能用“平时”来说明。"}, {"text": "电影平时就要开始了，快进去吧。", "explanation": "这里应该用〈马上〉。平时指一般情况下的习惯，不能用来说眼前即将发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我平时地喜欢喝茶。", "corrected_sentence": "我平时喜欢喝茶。", "error_description": "错误：“平时”作状语修饰动词时，后面不能加“地”，应说“我平时喜欢喝茶”。正确：我平时喜欢喝茶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我平时的不太喝酒。", "corrected_sentence": "我平时不太喝酒。", "error_description": "错误：“平时”作状语修饰动词或副词时，后面不能加“的”，应说“我平时不太喝酒”。正确：我平时不太喝酒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
