INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92967, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电影院是大家坐在里面看电影的地方。", "primary_collocate": null, "pronunciation": "diàn yǐng yuàn", "ipa": "tjɛn˥˩ iŋ˨˩˦ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "我们周末去电影院看电影。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院里很黑，大家都坐着看。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家电影院的座位很舒服。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院在超市的旁边。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院里不能大声说话。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电影院门口等我。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在电影院遇到了老同学。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院里的人很多，我们没有买到票。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢坐在电影院的前面还是后面？", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带孩子去电影院看动画片。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "大家坐着看电影的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电影院", "is_correct": true, "explanation": "正确。“去……看电影”需要放映电影的场所，应填“电影院”。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不放映电影，“去医院看电影”不合理。"}, {"text": "公交站", "is_correct": false, "explanation": "语义：公交站不放映电影，“去公交站看电影”不合理。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“去……看电影”通常搭配放映场所，“厨房”不搭配。"}], "explanations": {"电影院": "正确。“去……看电影”需要放映电影的场所，应填“电影院”。", "医院": "语义：医院不放映电影，“去医院看电影”不合理。", "公交站": "语义：公交站不放映电影，“去公交站看电影”不合理。", "厨房": "搭配：“去……看电影”通常搭配放映场所，“厨房”不搭配。"}, "sentence_index": 0, "correct_answer": "电影院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去电影院上课。", "explanation": "这里应该用〈教室〉。上课要去教室，电影院是放映电影的地方。"}, {"text": "我们去电影院打篮球。", "explanation": "这里应该用〈体育馆〉。打篮球要去体育馆，电影院是放电影的地方。"}, {"text": "我们去电影院买菜。", "explanation": "这里应该用〈超市〉。买菜要去超市，电影院不卖菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影院", "is_correct": true, "explanation": "正确。“我昨天在……遇到了老同学”需要人能到的场所，应填“电影院”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：人不能在冰箱里遇到老同学，句子读不通。"}, {"text": "墨水瓶", "is_correct": false, "explanation": "语义：墨水瓶太小，人不能在里面遇到老同学。"}, {"text": "字典", "is_correct": false, "explanation": "搭配：“在……遇到”指人能到的地点，“字典”不搭配。"}], "explanations": {"电影院": "正确。“我昨天在……遇到了老同学”需要人能到的场所，应填“电影院”。", "冰箱": "语义：人不能在冰箱里遇到老同学，句子读不通。", "墨水瓶": "语义：墨水瓶太小，人不能在里面遇到老同学。", "字典": "搭配：“在……遇到”指人能到的地点，“字典”不搭配。"}, "sentence_index": 6, "correct_answer": "电影院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去电影院踢球。", "explanation": "这里应该用〈球场〉。踢球要在球场，电影院只放电影。"}, {"text": "我们去电影院游泳。", "explanation": "这里应该用〈游泳馆〉。游泳要去游泳馆，电影院不能游泳。"}, {"text": "我们去电影院借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，电影院不借书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本电影院离我家很近。", "corrected_sentence": "这家电影院离我家很近。", "error_description": "错误：量词“本”。正确：量词“家”。电影院是场所，常用量词“家”（也可说“座”）；“本”用于书。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上周电影院门口见到了朋友。", "corrected_sentence": "他上周在电影院门口见到了朋友。", "error_description": "错误：缺少介词“在”。正确：“在电影院门口”。表示地点的介词“在”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
