INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92968, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "放映电影供观众观看的场所。", "primary_collocate": null, "pronunciation": "diàn yǐng yuàn", "ipa": "tjɛn˥˩ iŋ˨˩˦ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "这座城市新开了一家电影院。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家电影院每天放五场电影。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院的大屏幕又大又清楚。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近没有电影院，要坐车去。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院的票比网上的贵一点。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院今天下午不开门。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家电影院正在放一部新电影。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院里的声音很好听。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电影院工作，每天看很多电影。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们到电影院的时候，电影已经开始了。", "target_word": "电影院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "放映电影给观众看的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电影院", "is_correct": true, "explanation": "正确。句子说新开了一家放映电影的场所，应填“电影院”。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：“老虎”是动物，不能说“新开了一家老虎”。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不能作为新开的场所。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“新开”搭配店铺或场所，“空气”不搭配。"}], "explanations": {"电影院": "正确。句子说新开了一家放映电影的场所，应填“电影院”。", "老虎": "语义：“老虎”是动物，不能说“新开了一家老虎”。", "春天": "语义：“春天”是季节，不能作为新开的场所。", "空气": "搭配：“新开”搭配店铺或场所，“空气”不搭配。"}, "sentence_index": 0, "correct_answer": "电影院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去电影院看病。", "explanation": "这里应该用〈医院〉。看病要去医院，电影院是放映电影的地方。"}, {"text": "我们去电影院喝茶。", "explanation": "这里应该用〈茶馆〉。喝茶要去茶馆，电影院是放映电影的地方。"}, {"text": "我们去电影院寄信。", "explanation": "这里应该用〈邮局〉。寄信要去邮局，电影院是放映电影的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影院", "is_correct": true, "explanation": "正确。“听说那家……正在放一部新电影”需要放映电影的场所，应填“电影院”。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不放映电影，“那家医院正在放一部新电影”不合理。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不放映电影，“银行正在放一部新电影”不合理。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：“放一部新电影”通常搭配放映场所，“书店”不搭配。"}], "explanations": {"电影院": "正确。“听说那家……正在放一部新电影”需要放映电影的场所，应填“电影院”。", "医院": "语义：医院不放映电影，“那家医院正在放一部新电影”不合理。", "银行": "语义：银行不放映电影，“银行正在放一部新电影”不合理。", "书店": "搭配：“放一部新电影”通常搭配放映场所，“书店”不搭配。"}, "sentence_index": 6, "correct_answer": "电影院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去电影院看展览。", "explanation": "这里应该用〈博物馆〉。看展览要去博物馆，电影院不办展览。"}, {"text": "我们去电影院打针。", "explanation": "这里应该用〈医院〉。打针要去医院，电影院是放映电影的地方。"}, {"text": "我们去电影院修车。", "explanation": "这里应该用〈修车厂〉。修车要去修车厂，电影院是放映电影的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇前年新开了一部电影院。", "corrected_sentence": "这个小镇前年新开了一家电影院。", "error_description": "错误：“一部电影院”。正确：“一家电影院”。“部”用于电影、书等，不用于场所；电影院常用量词“家”或“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去了过那家电影院。", "corrected_sentence": "我们去过那家电影院。", "error_description": "错误：“去了过”，“了”和“过”不能一起用在动词后面。正确：“去过”。表示曾经有过这种经历，用“动词＋过”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
