INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92969, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年成是这一年庄稼长得好不好。", "primary_collocate": null, "pronunciation": "nián cheng", "ipa": "njɛn˧˥ ʈʂʰəŋ", "syllable_count": 2, "sentences": [{"text": "今年年成好，农民都很高兴。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年年成不好，粮食很少。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老农说，年成好不好要看老天爷。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年年成差，村里很多人吃不饱。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年成好的时候，家家都有多余的粮食。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水够多，今年的年成一定不错。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到坏年成，农民只好少吃一点儿。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的地不多，年成好坏直接关系到全家的生活。", "target_word": "年成", "complexity_tier": "T3", "furigana": "nián cheng", "sentence_source": "generated"}, {"text": "今年是个好年成，玉米长得特别好。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为年成不好，村里的粮价涨了。", "target_word": "年成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "通用", "sense_fingerprint": "名词：一年里庄稼长得好不好，常说年成好、年成不好、好年成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37389423-afce-42fb-8c84-9ff544ce5cc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92969, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年成", "is_correct": true, "explanation": "正确：「年成」指一年的收成，与「今年……好，农民都很高兴」相符。"}, {"text": "年假", "is_correct": false, "explanation": "语义：「年假」指假期，与农民因收成而高兴的语境不合。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：「年纪」指人的岁数，不能说“年纪好”。"}, {"text": "年代", "is_correct": false, "explanation": "语义：「年代」指时代，与句中收成好坏的语境不符。"}], "explanations": {"年成": "正确：「年成」指一年的收成，与「今年……好，农民都很高兴」相符。", "年假": "语义：「年假」指假期，与农民因收成而高兴的语境不合。", "年纪": "搭配：「年纪」指人的岁数，不能说“年纪好”。", "年代": "语义：「年代」指时代，与句中收成好坏的语境不符。"}, "sentence_index": 0, "correct_answer": "年成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的年成很大了，还在工作。", "explanation": "这里应该用〈年纪〉。「年纪」指人的岁数；「年成」只指一年庄稼的收成，不能用来说人的年龄。"}, {"text": "这家饭店的年成很好，客人特别多。", "explanation": "这里应该用〈生意〉。「生意」指买卖经营的情况；「年成」只指一年庄稼的收成，不能用来说饭店的经营。"}, {"text": "他这次考试的年成很好，老师很高兴。", "explanation": "这里应该用〈成绩〉。「成绩」指学习或考试的结果；「年成」只指庄稼的收成，不能用来说考试情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年成", "is_correct": true, "explanation": "正确：「年成」指一年的收成，与「遇到坏年成，农民只好少吃」相符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」指人的岁数，不能说“遇到坏年龄”。"}, {"text": "年底", "is_correct": false, "explanation": "语义：「年底」指一年的末尾，与收成不好导致少吃的语境不合。"}, {"text": "年假", "is_correct": false, "explanation": "语义：「年假」指假期，与收成不好的语境毫无关系。"}], "explanations": {"年成": "正确：「年成」指一年的收成，与「遇到坏年成，农民只好少吃」相符。", "年龄": "搭配：「年龄」指人的岁数，不能说“遇到坏年龄”。", "年底": "语义：「年底」指一年的末尾，与收成不好导致少吃的语境不合。", "年假": "语义：「年假」指假期，与收成不好的语境毫无关系。"}, "sentence_index": 6, "correct_answer": "年成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的年成很好，我们去公园玩吧。", "explanation": "这里应该用〈天气〉。「天气」指一天的晴雨冷热；「年成」只指一年庄稼的收成，不能用来说今天的天气。"}, {"text": "这篇文章的年成很好，大家都喜欢读。", "explanation": "这里应该用〈质量〉。「质量」指事物的好坏；「年成」只指一年庄稼的收成，不能用来评价文章。"}, {"text": "他去年的年成很高，所以买了房子。", "explanation": "这里应该用〈收入〉。「年成」指庄稼的收成，说个人的收入要用「收入」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年是只坏年成，村里的粮食很少。", "corrected_sentence": "去年是个坏年成，村里的粮食很少。", "error_description": "量词「只」多用于动物，「年成」的量词应用「个」。这里用错了量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年雨水多，年成了好，大家都很高兴。", "corrected_sentence": "今年雨水多，年成好了，大家都很高兴。", "error_description": "表示状态变化的「了」应放在形容词「好」之后。这里「了」被放在「年成」后面，位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
