INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92971, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "食用是可以拿来吃。", "primary_collocate": null, "pronunciation": "shí yòng", "ipa": "ʂɻ̩˧˥ yŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种蘑菇有毒，不可以食用。", "target_word": "食用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛奶打开以后，请在三天内食用。", "target_word": "食用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些水果洗干净就可以食用。", "target_word": "食用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包过了日期，就不要再食用了。", "target_word": "食用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药不是食品，千万不要食用。", "target_word": "食用", "complexity_tier": "T3", "furigana": "yào bú shì shí pǐn, qiān wàn bú yào shí yòng.", "sentence_source": "generated"}, {"text": "这种花很漂亮，也可以食用。", "target_word": "食用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野生的果子，没有专家说明，最好不要食用。", "target_word": "食用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼要煮熟了再食用，这样才安全。", "target_word": "食用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她以前食用过这种草，味道有点苦。", "target_word": "食用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包装上写着：开袋后请尽快食用。", "target_word": "食用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "食用了", "label": "体标"}, {"form": "食用过", "label": "体标"}, {"form": "食用油", "label": "复合"}, {"form": "食用盐", "label": "复合"}, {"form": "食用菌", "label": "复合"}], "register": "书面", "sense_fingerprint": "可以拿来吃、当作食物吃下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "食用", "is_correct": true, "explanation": "食用：指可以拿来吃，这是正确答案。"}, {"text": "使用", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是使用，不是可以吃。"}, {"text": "试用", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是试着用。"}, {"text": "施用", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是施加使用，多指施肥。"}], "explanations": {"食用": "食用：指可以拿来吃，这是正确答案。", "使用": "shǐ（第三声）与 shí（第二声）声调不同，意思是使用，不是可以吃。", "试用": "shì（第四声）与 shí（第二声）声调不同，意思是试着用。", "施用": "shī（第一声）与 shí（第二声）声调不同，意思是施加使用，多指施肥。"}, "sentence_index": null, "correct_answer": "食用"}, "level_3": {"options": [{"text": "食用", "is_correct": true, "explanation": "食用：表示可以拿来吃，与“有毒，不可以”的句意相符。"}, {"text": "浏览", "is_correct": false, "explanation": "搭配：“浏览”一般用于网页、书报，不能用于蘑菇。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”表示长大，与“有毒，不可以”的意思不合。"}, {"text": "关闭", "is_correct": false, "explanation": "搭配：“关闭”用于门窗、网页等，不能用于蘑菇。"}], "explanations": {"食用": "食用：表示可以拿来吃，与“有毒，不可以”的句意相符。", "浏览": "搭配：“浏览”一般用于网页、书报，不能用于蘑菇。", "生长": "语义：“生长”表示长大，与“有毒，不可以”的意思不合。", "关闭": "搭配：“关闭”用于门窗、网页等，不能用于蘑菇。"}, "sentence_index": 0, "correct_answer": "食用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饮料可以直接食用。", "explanation": "这里应该用〈饮用〉。饮料要说饮用，“食用”指当作食物吃。"}, {"text": "病人要按时食用药物。", "explanation": "这里应该用〈服用〉。药物要说服用，“食用”只用于食物。"}, {"text": "大家在湖边食用美丽的风景。", "explanation": "这里应该用〈享受〉。风景不能吃，“食用”只用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食用", "is_correct": true, "explanation": "食用：表示可以拿来吃，符合“最好不要”后面的语境。"}, {"text": "穿戴", "is_correct": false, "explanation": "搭配：“穿戴”用于衣帽、饰品，不能用于果子。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，与“没有专家说明，最好不要”的劝告不合。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于文章、言论，不能用于果子。"}], "explanations": {"食用": "食用：表示可以拿来吃，符合“最好不要”后面的语境。", "穿戴": "搭配：“穿戴”用于衣帽、饰品，不能用于果子。", "夸奖": "语义：“夸奖”是称赞，与“没有专家说明，最好不要”的劝告不合。", "发表": "搭配：“发表”用于文章、言论，不能用于果子。"}, "sentence_index": 6, "correct_answer": "食用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷年轻时经常食用烟。", "explanation": "这里应该用〈吸烟〉。烟要说“吸烟”，“食用”不能用于烟草。"}, {"text": "植物通过根部食用营养。", "explanation": "这里应该用〈吸收〉。植物通过根部吸收养分，“食用”指人吃东西。"}, {"text": "他把硬币食用了下去。", "explanation": "这里应该用〈吞〉。硬币不是食物，不能说食用，应说“吞下去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种菜叶没有农药，可以很食用。", "corrected_sentence": "这种菜叶没有农药，可以食用。", "error_description": "“食用”前多加了副词“很”。这类动词前不能加“很”，应删去，正确形式是“可以食用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开袋后请尽快食用了这种酸奶。", "corrected_sentence": "开袋后请尽快食用这种酸奶。", "error_description": "“食用”后多加了助词“了”。祈使句“请……”表示要求，不能用“了”，应删去，正确形式是“请尽快食用这种酸奶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
