INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92972, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "action", "definition": "食用是可供人作为食物吃的（多作定语或表语）。", "primary_collocate": null, "pronunciation": "shí yòng", "ipa": "ʂɻ̩˧˥ yŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这瓶油是食用的，妈妈买来做菜。", "target_word": "食用", "complexity_tier": "T3", "furigana": "zhè píng yóu shì shí yòng de, mā ma mǎi lái zuò cài.", "sentence_source": "generated"}, {"text": "做菜用的盐必须是食用的，不能用工业盐。", "target_word": "食用", "complexity_tier": "T3", "furigana": "zuò cài yòng de yán bì xū shì shí yòng de, bù néng yòng gōng yè yán.", "sentence_source": "generated"}, {"text": "这种蘑菇很常见，也是食用的。", "target_word": "食用", "complexity_tier": "T3", "furigana": "zhè zhǒng mó gu hěn cháng jiàn, yě shì shí yòng de.", "sentence_source": "generated"}, {"text": "这家工厂生产的油是食用的，卖到很多城市。", "target_word": "食用", "complexity_tier": "T3", "furigana": "zhè jiā gōng chǎng shēng chǎn de yóu shì shí yòng de, mài dào hěn duō chéng shì.", "sentence_source": "generated"}, {"text": "这种红色的东西不是食用的，不能放进菜里。", "target_word": "食用", "complexity_tier": "T3", "furigana": "zhè zhǒng hóng sè de dōng xi bú shì shí yòng de, bù néng fàng jìn cài lǐ.", "sentence_source": "generated"}, {"text": "这些花是食用的，可以放在沙拉里。", "target_word": "食用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里的盐有很多种，有些是食用的。", "target_word": "食用", "complexity_tier": "T3", "furigana": "chāo shì lǐ de yán yǒu hěn duō zhǒng, yǒu xiē shì shí yòng de.", "sentence_source": "generated"}, {"text": "油用完了，我们去买一瓶，要买食用的。", "target_word": "食用", "complexity_tier": "T3", "furigana": "yóu yòng wán le, wǒ men qù mǎi yì píng, yào mǎi shí yòng de.", "sentence_source": "generated"}, {"text": "这种植物的叶子是食用的，味道很好。", "target_word": "食用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种菌是食用的，含有很多营养，对身体很好。", "target_word": "食用", "complexity_tier": "T3", "furigana": "zhè zhǒng jūn shì shí yòng de, hán yǒu hěn duō yíng yǎng, duì shēn tǐ hěn hǎo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "食用油", "label": "复合"}, {"form": "食用盐", "label": "复合"}, {"form": "食用菌", "label": "复合"}], "register": "书面", "sense_fingerprint": "可供人作食物吃的（食用油、食用盐、是食用的）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "食用", "is_correct": true, "explanation": "食用：指可以拿来吃，这是正确答案。"}, {"text": "使用", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是使用，不是可以吃。"}, {"text": "试用", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是试着用。"}, {"text": "施用", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是施加使用，多指施肥。"}], "explanations": {"食用": "食用：指可以拿来吃，这是正确答案。", "使用": "shǐ（第三声）与 shí（第二声）声调不同，意思是使用，不是可以吃。", "试用": "shì（第四声）与 shí（第二声）声调不同，意思是试着用。", "施用": "shī（第一声）与 shí（第二声）声调不同，意思是施加使用，多指施肥。"}, "sentence_index": null, "correct_answer": "食用"}, "level_3": {"options": [{"text": "食用", "is_correct": true, "explanation": "食用：表示可以拿来吃，与“买来做菜”相符。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”表示白白用掉，与“买来做菜”的意思不合。"}, {"text": "喝下", "is_correct": false, "explanation": "搭配：“喝下”一般说喝的东西，油不说“喝下”，与做菜的语境不合。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：油点燃后不能用来做菜，与句意不合。"}], "explanations": {"食用": "食用：表示可以拿来吃，与“买来做菜”相符。", "浪费": "语义：“浪费”表示白白用掉，与“买来做菜”的意思不合。", "喝下": "搭配：“喝下”一般说喝的东西，油不说“喝下”，与做菜的语境不合。", "点燃": "语义：油点燃后不能用来做菜，与句意不合。"}, "sentence_index": 0, "correct_answer": "食用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂生产的水是食用的，卖到很多城市。", "explanation": "这里应该用〈饮用〉。水要说“饮用的”，“食用的”只用于能吃的东西。"}, {"text": "这种药片是食用的，饭后吃两片。", "explanation": "这里应该用〈口服〉。药片要说“是口服的”，“食用的”只用于食品。"}, {"text": "这台仪器是食用的，只能在实验室里用。", "explanation": "这里应该用〈实验用〉。仪器是实验用的，不是食品，不能说“食用的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食用", "is_correct": true, "explanation": "食用：表示可以拿来吃，与“超市里的盐”的语境相符。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”表示毁掉，超市里的盐不会是销毁的，与句意不合。"}, {"text": "吃过", "is_correct": false, "explanation": "语义：“吃过”表示已经被吃掉，超市卖的盐不会是吃过的。"}, {"text": "演出", "is_correct": false, "explanation": "搭配：“演出”用于节目、戏剧，不能用来说盐。"}], "explanations": {"食用": "食用：表示可以拿来吃，与“超市里的盐”的语境相符。", "销毁": "语义：“销毁”表示毁掉，超市里的盐不会是销毁的，与句意不合。", "吃过": "语义：“吃过”表示已经被吃掉，超市卖的盐不会是吃过的。", "演出": "搭配：“演出”用于节目、戏剧，不能用来说盐。"}, "sentence_index": 6, "correct_answer": "食用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种洗衣液是食用的，放在水池旁边。", "explanation": "这里应该用〈洗衣用〉。洗衣液是洗衣用的，不能说“食用的”。"}, {"text": "这些木材是食用的，放在厨房里。", "explanation": "这里应该用〈烧火用〉。木材是烧火用的，不能说“食用的”。"}, {"text": "这种塑料花是食用的，放在桌子上看。", "explanation": "这里应该用〈装饰用〉。塑料花是装饰用的，不能吃，不能说“食用的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种豆子食用的，但要煮熟。", "corrected_sentence": "这种豆子是食用的，但要煮熟。", "error_description": "“是……的”结构漏掉了“是”。应为“这种豆子是食用的”，“食用的”不能直接作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种海带是食用了，味道很好。", "corrected_sentence": "这种海带是食用的，味道很好。", "error_description": "“食用”作谓语时后面应加“的”，不能用“了”。正确形式是“是食用的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92973, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自愿", "is_correct": true, "explanation": "自愿：出于本人意愿去做事，与“强迫”意思相反。"}, {"text": "允许", "is_correct": false, "explanation": "允许：准许他人做某事，与“强迫”不构成反义关系。"}, {"text": "帮助", "is_correct": false, "explanation": "帮助：给予别人支持或便利，与“强迫”不构成反义关系。"}, {"text": "鼓励", "is_correct": false, "explanation": "鼓励：促使别人增加信心或努力，与“强迫”不构成反义关系。"}], "correct_answer": "自愿", "explanations": {"自愿": "自愿：出于本人意愿去做事，与“强迫”意思相反。", "允许": "允许：准许他人做某事，与“强迫”不构成反义关系。", "帮助": "帮助：给予别人支持或便利，与“强迫”不构成反义关系。", "鼓励": "鼓励：促使别人增加信心或努力，与“强迫”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92973, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自愿", "is_correct": true, "explanation": "自愿：出于本人意愿去做事，与“强迫”意思相反。"}, {"text": "陪伴", "is_correct": false, "explanation": "陪伴：与人同在、相随，与“强迫”不构成反义关系。"}, {"text": "赞美", "is_correct": false, "explanation": "赞美：称赞他人的优点或成绩，与“强迫”不构成反义关系。"}, {"text": "提醒", "is_correct": false, "explanation": "提醒：让别人注意某事，与“强迫”不构成反义关系。"}], "correct_answer": "自愿", "explanations": {"自愿": "自愿：出于本人意愿去做事，与“强迫”意思相反。", "陪伴": "陪伴：与人同在、相随，与“强迫”不构成反义关系。", "赞美": "赞美：称赞他人的优点或成绩，与“强迫”不构成反义关系。", "提醒": "提醒：让别人注意某事，与“强迫”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92973, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "强迫是用力气让别人一定要做。", "primary_collocate": null, "pronunciation": "qiǎng pò", "ipa": "tɕʰiɑŋ˨˩˦ pʰwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "没有人可以强迫你做不喜欢的事。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他强迫孩子每天写两个小时作业。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人强迫他把钱交出来。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板强迫大家周末来加班。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想强迫你，你自己决定吧。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们强迫小王在合同上签字。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从来不强迫我学钢琴。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人强迫我喝了很多酒。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要强迫别人听你的。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他强迫自己早上六点起床。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强迫了", "label": "完成体"}, {"form": "强迫过", "label": "经历体"}, {"form": "強迫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不顾别人愿不愿意，硬让别人去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强迫", "is_correct": true, "explanation": "强迫：用力气让别人一定要做，与“没有人可以”和“做不喜欢的事”相合。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”是乐在其中，与“不喜欢的事”矛盾。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示乐意接受，不能用来指对方不喜欢的事。"}, {"text": "体谅", "is_correct": false, "explanation": "配价：“体谅”的对象是人或处境，不能直接带“你做不喜欢的事”这样的小句。"}], "explanations": {"强迫": "强迫：用力气让别人一定要做，与“没有人可以”和“做不喜欢的事”相合。", "享受": "语义：“享受”是乐在其中，与“不喜欢的事”矛盾。", "欢迎": "语义：“欢迎”表示乐意接受，不能用来指对方不喜欢的事。", "体谅": "配价：“体谅”的对象是人或处境，不能直接带“你做不喜欢的事”这样的小句。"}, "sentence_index": 0, "correct_answer": "强迫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他强迫她高兴，所以她笑了。", "explanation": "这里误把“强迫”当成了〈让〉的使役义（使人产生某种情绪）。强迫的对象必须是能被迫去做动作的人，不能用来强迫别人高兴。"}, {"text": "她终于强迫了痛苦。", "explanation": "这里误把“强迫”当成了〈摆脱〉的意思（设法离开痛苦）。强迫的对象必须是能被迫去做事的人，不能施加于“痛苦”。"}, {"text": "法院强迫执行了判决。", "explanation": "这里误把“强迫”当成了〈强制〉的意思（依法强行执行）。“强制执行”是固定说法，强迫指让人违背意愿去做，不能用来修饰“执行判决”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强迫", "is_correct": true, "explanation": "强迫：用力气让别人一定要做，与“妈妈从来不”和“我学钢琴”的语境相合。"}, {"text": "拆除", "is_correct": false, "explanation": "配价：“拆除”的对象是建筑或设施，不能用于“学钢琴”，句子不通。"}, {"text": "粘贴", "is_correct": false, "explanation": "配价：“粘贴”的对象是纸张、图片等物品，不能接“我学钢琴”这样的小句，句子不通。"}, {"text": "检阅", "is_correct": false, "explanation": "语域：“检阅”是正式书面语，指检查队伍或成果，用于家庭口语中不合适。"}], "explanations": {"强迫": "强迫：用力气让别人一定要做，与“妈妈从来不”和“我学钢琴”的语境相合。", "拆除": "配价：“拆除”的对象是建筑或设施，不能用于“学钢琴”，句子不通。", "粘贴": "配价：“粘贴”的对象是纸张、图片等物品，不能接“我学钢琴”这样的小句，句子不通。", "检阅": "语域：“检阅”是正式书面语，指检查队伍或成果，用于家庭口语中不合适。"}, "sentence_index": 6, "correct_answer": "强迫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师强迫学生乐意回答问题。", "explanation": "这里误把“强迫”当成了〈鼓励〉的意思（使人愿意去做）。强迫指违背对方意愿，与“乐意”的心甘情愿相矛盾。"}, {"text": "他强迫我会游泳。", "explanation": "这里误把“强迫”当成了〈学会〉的意思（让人掌握某种能力）。强迫只能要求对方去做具体动作，不能强迫别人“会”某种能力；应说“强迫我学会游泳”。"}, {"text": "他和对方强迫商量了一下。", "explanation": "这里误把“强迫”当成了〈商量〉的意思（彼此平等协商）。强迫指违背对方意愿，与平等协商相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天强迫了我练习钢琴。", "corrected_sentence": "妈妈每天强迫我练习钢琴。", "error_description": "“了”错误：“每天”表示习惯性的动作，不能与表示完成的“了”连用，“强迫了”只能用于一次性的已完成事件，应去掉“了”，说“妈妈每天强迫我练习钢琴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板明天强迫过我们开会。", "corrected_sentence": "老板明天强迫我们开会。", "error_description": "“过”错误：“强迫过”表示已经经历，不能和“明天”这样的将来时间词连用，应去掉“过”，说“老板明天强迫我们开会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92974, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自愿", "is_correct": true, "explanation": "自愿：出于本人意愿去做事，与“强迫”意思相反。"}, {"text": "批评", "is_correct": false, "explanation": "批评：指出别人的错误或不足，与“强迫”不构成反义关系。"}, {"text": "赞扬", "is_correct": false, "explanation": "赞扬：肯定并称赞别人，与“强迫”不构成反义关系。"}, {"text": "尊重", "is_correct": false, "explanation": "尊重：重视并顾及他人的想法，与“强迫”不构成反义关系。"}], "correct_answer": "自愿", "explanations": {"自愿": "自愿：出于本人意愿去做事，与“强迫”意思相反。", "批评": "批评：指出别人的错误或不足，与“强迫”不构成反义关系。", "赞扬": "赞扬：肯定并称赞别人，与“强迫”不构成反义关系。", "尊重": "尊重：重视并顾及他人的想法，与“强迫”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92974, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自愿", "is_correct": true, "explanation": "自愿：出于本人意愿去做事，与“强迫”意思相反。"}, {"text": "劝告", "is_correct": false, "explanation": "劝告：用言语规劝别人，与“强迫”不构成反义关系。"}, {"text": "拒绝", "is_correct": false, "explanation": "拒绝：不接受别人的要求或提议，与“强迫”不构成反义关系。"}, {"text": "邀请", "is_correct": false, "explanation": "邀请：请对方来参加或做某事，与“强迫”不构成反义关系。"}], "correct_answer": "自愿", "explanations": {"自愿": "自愿：出于本人意愿去做事，与“强迫”意思相反。", "劝告": "劝告：用言语规劝别人，与“强迫”不构成反义关系。", "拒绝": "拒绝：不接受别人的要求或提议，与“强迫”不构成反义关系。", "邀请": "邀请：请对方来参加或做某事，与“强迫”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用强力或权势使别人服从。", "primary_collocate": null, "pronunciation": "qiǎng pò", "ipa": "tɕʰiɑŋ˨˩˦ pʰwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "公司强迫员工接受新的规定。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个官员强迫农民搬出了村子。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠权力强迫别人听他的。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不应该强迫学生买这本书。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王强迫百姓交很多税。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们强迫工人接受很低的工资。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司强迫小商店低价卖货。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许任何人强迫别人结婚。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理强迫我们签了这份合同。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想强迫对方同意自己的条件。", "target_word": "强迫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强迫了", "label": "完成体"}, {"form": "强迫过", "label": "经历体"}, {"form": "強迫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "凭权力、地位或势力迫使别人服从", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强迫", "is_correct": true, "explanation": "强迫：凭权力或势力迫使别人服从，与“公司”和“员工接受规定”相合。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”是躲开，公司不会去逃避员工接受规定，句子不通。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指思念过去的人或事，与“接受新的规定”的现在行为不搭。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指记不住，与“公司要求员工接受规定”的意思不合。"}], "explanations": {"强迫": "强迫：凭权力或势力迫使别人服从，与“公司”和“员工接受规定”相合。", "逃避": "语义：“逃避”是躲开，公司不会去逃避员工接受规定，句子不通。", "怀念": "语义：“怀念”指思念过去的人或事，与“接受新的规定”的现在行为不搭。", "忘记": "语义：“忘记”指记不住，与“公司要求员工接受规定”的意思不合。"}, "sentence_index": 0, "correct_answer": "强迫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司强迫员工的意见。", "explanation": "这里误把“强迫”当成了〈征求〉的意思（询问对方的想法）。强迫的对象须是能被迫做事的人，不能施加于“意见”。"}, {"text": "他和对方强迫商量了一下。", "explanation": "这里误把“强迫”当成了〈商量〉的意思（彼此平等协商）。强迫指违背对方意愿，与平等协商相矛盾。"}, {"text": "警方采取了强迫措施。", "explanation": "这里误把“强迫”当成了〈强制〉的意思（依法强行实施）。“强制措施”是固定说法，强迫指让人服从，不能修饰“措施”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强迫", "is_correct": true, "explanation": "强迫：凭实力或势力迫使别人服从，与“大公司”和“小商店低价卖货”相合。"}, {"text": "粘贴", "is_correct": false, "explanation": "配价：“粘贴”的对象是纸张、图片等物品，不能接“小商店低价卖货”这样的小句，句子不通。"}, {"text": "哀悼", "is_correct": false, "explanation": "语义：“哀悼”是悼念逝者，与“小商店低价卖货”毫无关联，句子不通。"}, {"text": "拆除", "is_correct": false, "explanation": "配价：“拆除”的对象是建筑或设施，不能接“小商店低价卖货”这样的小句，句子不通。"}], "explanations": {"强迫": "强迫：凭实力或势力迫使别人服从，与“大公司”和“小商店低价卖货”相合。", "粘贴": "配价：“粘贴”的对象是纸张、图片等物品，不能接“小商店低价卖货”这样的小句，句子不通。", "哀悼": "语义：“哀悼”是悼念逝者，与“小商店低价卖货”毫无关联，句子不通。", "拆除": "配价：“拆除”的对象是建筑或设施，不能接“小商店低价卖货”这样的小句，句子不通。"}, "sentence_index": 6, "correct_answer": "强迫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他强迫对方乐意签字。", "explanation": "这里误把“强迫”当成了〈鼓励〉的意思（使对方愿意去做）。强迫指依靠力量违背对方意愿，与“乐意”相矛盾。"}, {"text": "他强迫对方会说三种语言。", "explanation": "这里误把“强迫”当成了〈学会〉的意思（让人掌握某种能力）。强迫只能要求对方去做具体动作，不能强迫对方“会”某种能力；应说“强迫对方学会说三种语言”。"}, {"text": "他用权势强迫对方自愿同意。", "explanation": "这里误把“强迫”当成了〈引导〉的意思（使对方主动愿意去做）。强迫依靠权势违背对方意愿，与“自愿”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厂长每周强迫了工人加班。", "corrected_sentence": "厂长每周强迫工人加班。", "error_description": "“了”错误：“每周”表示习惯性的周期动作，不能与表示完成的“了”连用，应去掉“了”，说“厂长每周强迫工人加班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大公司明天强迫了很多小店低价卖货。", "corrected_sentence": "大公司明天强迫很多小店低价卖货。", "error_description": "“了”错误：“了”直接加在“强迫”后，表示已经完成，但句中“明天”是将来时间词，二者矛盾，应去掉“了”，说“大公司明天强迫很多小店低价卖货”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
