INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不加以（后接双音节动词，表示不对其作某种处理）。", "primary_collocate": null, "pronunciation": "bù jiā", "ipa": "pu˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "他不加证实就把消息发了出去。", "target_word": "不加", "complexity_tier": "T3", "furigana": "tā bù jiā zhèngshí jiù bǎ xiāoxi fā le chūqù", "sentence_source": "generated"}, {"text": "不要不加选择地相信网上的消息。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不加掩饰地说出了想法。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生不加区别，一视同仁。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能不加考虑就做决定。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不加解释就走了。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话他不加修饰地写了下来。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要不加分析地接受别人的意见。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不加思考就回答了问题。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件事，大家不加评论。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "后接双音节动词，表示不对其作某种处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c571f81-6489-4741-8a61-f863fc462a95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确：不加（bù jiā），意思是不做某种处理。"}, {"text": "不嫁", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是不出嫁。"}, {"text": "不假", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是不是假的、真实的。"}, {"text": "补假", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补休的假期。"}], "explanations": {"不加": "正确：不加（bù jiā），意思是不做某种处理。", "不嫁": "jià（第四声）与 jiā（第一声）声调不同，意思是不出嫁。", "不假": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是不是假的、真实的。", "补假": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补休的假期。"}, "sentence_index": null, "correct_answer": "不加"}, "level_3": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确。“不加证实”表示不经过核实就把消息发出去。"}, {"text": "不唱", "is_correct": false, "explanation": "语义：“唱”不能与“证实”搭配，句子不通。"}, {"text": "不吃", "is_correct": false, "explanation": "搭配：“吃”指进食，不能用于“证实”这种行为。"}, {"text": "不喝", "is_correct": false, "explanation": "搭配：“喝”针对饮品，“喝证实”不成立。"}], "explanations": {"不加": "正确。“不加证实”表示不经过核实就把消息发出去。", "不唱": "语义：“唱”不能与“证实”搭配，句子不通。", "不吃": "搭配：“吃”指进食，不能用于“证实”这种行为。", "不喝": "搭配：“喝”针对饮品，“喝证实”不成立。"}, "sentence_index": 0, "correct_answer": "不加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不加朋友的意见，一意孤行。", "explanation": "这里应该用〈不采纳〉。“不加”表示不做某种处理，后接动词；“意见”是名词，不能直接放在“不加”后面。"}, {"text": "他不加后果就冲了出去。", "explanation": "这里应该用〈不顾〉。“不加”后要接动词，表示不做某种处理；“后果”是名词，要说“不顾后果”。"}, {"text": "他不加时间地工作。", "explanation": "这里应该用〈不计〉。“不加”后要接动词，“时间”是名词，要说“不计时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确：不加（bù jiā），意思是不做某种处理。"}, {"text": "补加", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，补加意思是后来再加上。"}, {"text": "补价", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补偿的差价。"}, {"text": "布甲", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，布甲指用布做的护甲。"}], "explanations": {"不加": "正确：不加（bù jiā），意思是不做某种处理。", "补加": "bǔ（第三声）与 bù（第四声）声调不同，补加意思是后来再加上。", "补价": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补偿的差价。", "布甲": "jiǎ（第三声）与 jiā（第一声）声调不同，布甲指用布做的护甲。"}, "sentence_index": null, "correct_answer": "不加"}, "level_3": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确。“不加修饰”表示不经过修饰就写下来。"}, {"text": "不穿", "is_correct": false, "explanation": "语义：“穿”指穿戴衣物，“修饰”不能穿，句子不通。"}, {"text": "不擦", "is_correct": false, "explanation": "搭配：“擦”针对可以擦掉的东西，“擦修饰”不能说。"}, {"text": "不剪", "is_correct": false, "explanation": "搭配：“剪”针对可以剪断的东西，“修饰”不能剪。"}], "explanations": {"不加": "正确。“不加修饰”表示不经过修饰就写下来。", "不穿": "语义：“穿”指穿戴衣物，“修饰”不能穿，句子不通。", "不擦": "搭配：“擦”针对可以擦掉的东西，“擦修饰”不能说。", "不剪": "搭配：“剪”针对可以剪断的东西，“修饰”不能剪。"}, "sentence_index": 6, "correct_answer": "不加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不加允许就进了办公室。", "explanation": "这里应该用〈不经〉。“不加”后接表示处理的动词（如“考虑、分析”），“允许”不能与“不加”搭配，固定说法是“不经允许”。"}, {"text": "老师不加学生的感受，一味批评。", "explanation": "这里应该用〈不理〉。“不加”表示不做某种处理，后接动词，不能接“学生的感受”。"}, {"text": "他对谁都不加彼此。", "explanation": "这里应该用〈不分〉。“不加”后要接动词，不能接“彼此”，要说“不分彼此”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不加了审查就把文件交了上去。", "corrected_sentence": "他不加审查就把文件交了上去。", "error_description": "“了”的位置错误。“不加”后接动词“审查”时不能带“了”，应说“不加审查”；“不加了审查”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不加核实过就把数据交了上去。", "corrected_sentence": "他不加核实就把数据交了上去。", "error_description": "“过”用错。“不加”后接动词“核实”时不能再带“过”，应说“他不加核实就把数据交了上去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
