INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92977, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "后话是以后才说的话。", "primary_collocate": null, "pronunciation": "hòu huà", "ipa": "xoʊ˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "先把钱借给他，后话等他回来再说。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这事的后话，等有结果再说吧。", "target_word": "后话", "complexity_tier": "T3", "furigana": "Zhè shì de hòuhuà, děng yǒu jiéguǒ zài shuō ba.", "sentence_source": "generated"}, {"text": "我们先看比赛，后话明天再聊。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说完前面的事，才开始讲后话。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后话是什么，他一直没有告诉我。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的前因她讲了，后话她没提。", "target_word": "后话", "complexity_tier": "T3", "furigana": "Zhè jiàn shì de qiányīn tā jiǎng le, hòuhuà tā méi tí.", "sentence_source": "generated"}, {"text": "你先听我讲，后话我慢慢告诉你。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只说了开头，后话留给明天。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天先定价钱，后话等老板来了再说。", "target_word": "后话", "complexity_tier": "T3", "furigana": "Jīntiān xiān dìng jiàqián, hòuhuà děng lǎobǎn lái le zài shuō.", "sentence_source": "generated"}, {"text": "这些是开头，后话我明天再讲。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "后话：名词，留到以后才说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后话", "is_correct": true, "explanation": "后话指留到以后才说的话，与“等他回来再说”相符。"}, {"text": "后悔", "is_correct": false, "explanation": "词性：“后悔”是动词，不能作“等他回来再说”的话题。"}, {"text": "后退", "is_correct": false, "explanation": "词性：“后退”是动词，指向后移动，不能作这里的话题。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”是动作，句子要的是留到以后才说的内容。"}], "explanations": {"后话": "后话指留到以后才说的话，与“等他回来再说”相符。", "后悔": "词性：“后悔”是动词，不能作“等他回来再说”的话题。", "后退": "词性：“后退”是动词，指向后移动，不能作这里的话题。", "离开": "语义：“离开”是动作，句子要的是留到以后才说的内容。"}, "sentence_index": 0, "correct_answer": "后话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把父亲留下的后话都处理完了。", "explanation": "这里应该用〈后事〉。后事指死后或以后要办的事，可以说“处理后事”；后话指以后才说的话，不能这样用。"}, {"text": "他总在背后说后话。", "explanation": "这里应该用〈闲话〉。后话指留到以后才说的话，背后议论别人要说闲话。"}, {"text": "他们换了一个后话。", "explanation": "这里应该用〈话题〉。后话指留到以后才说的话，换的是谈论的内容，应说话题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后话", "is_correct": true, "explanation": "后话指留到以后才说的话，与“你先听我讲”后的承接吻合。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”不能“告诉你”，与句中要说的内容不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不能“告诉你”，与句中要说的内容不符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“告诉”后接的应是话语或事情，不能接“面包”。"}], "explanations": {"后话": "后话指留到以后才说的话，与“你先听我讲”后的承接吻合。", "椅子": "语义：“椅子”不能“告诉你”，与句中要说的内容不符。", "桌子": "语义：“桌子”不能“告诉你”，与句中要说的内容不符。", "面包": "搭配：“告诉”后接的应是话语或事情，不能接“面包”。"}, "sentence_index": 6, "correct_answer": "后话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对我说了后话，我很相信他。", "explanation": "这里应该用〈实话〉。后话指留到以后才说的话，不指真实的话。"}, {"text": "这首歌的后话很好听。", "explanation": "这里应该用〈歌词〉。后话不指歌词，歌好听应说歌词好听。"}, {"text": "他讲了一个后话，大家都笑了。", "explanation": "这里应该用〈笑话〉。后话指留到以后才说的话，能让人笑的应说笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的一张后话，我们以后再讲。", "corrected_sentence": "这件事的后话，我们以后再讲。", "error_description": "量词错误：“后话”前多加了“一张”。“张”用于纸、桌子等平面的东西，不能修饰“后话”；应直接说“这件事的后话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们先谈钱，一本后话以后再谈。", "corrected_sentence": "我们先谈钱，后话以后再谈。", "error_description": "量词错误：“后话”前多加了“一本”。“本”用于书籍，不能修饰“后话”；“后话”前直接说“后话以后再谈”，不加量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
