INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以后再说的话，后面的事情。", "primary_collocate": null, "pronunciation": "hòu huà", "ipa": "xoʊ˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "他后来成了大老板，那是后话。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是后话，我们先说现在的事。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把眼前的事做好，后话以后再说。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚以后的事，都是后话了。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次考试他没过，后话就不说了。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先去买票，后话到车站再想。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划能不能成功，是后话。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先搬到北京，后话等工作找到了再说。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在先别操心后话，好好学习。", "target_word": "后话", "complexity_tier": "T3", "furigana": "Xiànzài xiān bié cāoxīn hòuhuà, hǎohǎo xuéxí.", "sentence_source": "generated"}, {"text": "他后来去了国外，这些都是后话。", "target_word": "后话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "后话：名词，以后才会发生或才谈的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后话", "is_correct": true, "explanation": "后话指后面发生的事，与“后来成了大老板”的时间顺序相符。"}, {"text": "开场白", "is_correct": false, "explanation": "语义：“开场白”指开头的话，与“后来”的时间顺序相反。"}, {"text": "词汇", "is_correct": false, "explanation": "搭配：“词汇”不能指一件事，不能作“那是”的所指。"}, {"text": "前情", "is_correct": false, "explanation": "语义：“前情”指以前发生的事，与“后来”相反。"}], "explanations": {"后话": "后话指后面发生的事，与“后来成了大老板”的时间顺序相符。", "开场白": "语义：“开场白”指开头的话，与“后来”的时间顺序相反。", "词汇": "搭配：“词汇”不能指一件事，不能作“那是”的所指。", "前情": "语义：“前情”指以前发生的事，与“后来”相反。"}, "sentence_index": 0, "correct_answer": "后话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他办完了父亲的后话。", "explanation": "这里应该用〈后事〉。后事指死后或以后要办的事，可以说“办后事”；后话不能用“办”。"}, {"text": "这件事的后话已经贴在墙上了。", "explanation": "这里应该用〈通知〉。后话指以后才说的事，不能贴在墙上；能贴出来的应是通知。"}, {"text": "他把后话放进了抽屉。", "explanation": "这里应该用〈文件〉。后话是要说的话，不能放进抽屉；能放进抽屉的应是文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后话", "is_correct": true, "explanation": "后话指以后才说的话，与“这个计划能不能成功”的说明相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与计划能否成功无关，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与计划能否成功无关，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不能用来说明计划是否成功。"}], "explanations": {"后话": "后话指以后才说的话，与“这个计划能不能成功”的说明相符。", "颜色": "语义：“颜色”与计划能否成功无关，句意不通。", "天气": "语义：“天气”与计划能否成功无关，句意不通。", "桌子": "搭配：“桌子”不能用来说明计划是否成功。"}, "sentence_index": 6, "correct_answer": "后话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他爷爷去世了，家里正在办后话。", "explanation": "这里应该用〈后事〉。人去世后要办的是后事；后话指以后才说的事，不能“办”。"}, {"text": "他把故事的后话扔进了垃圾桶。", "explanation": "这里应该用〈结局〉。后话指以后才说的话，不能扔进垃圾桶；故事的结尾才是结局。"}, {"text": "他在背后说了很多别人的后话。", "explanation": "这里应该用〈闲话〉。背后议论别人是说闲话；后话指以后才谈的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他后来去了北京，那是一本后话。", "corrected_sentence": "他后来去了北京，那是后话。", "error_description": "量词错误：“后话”不用量词，直接说“那是后话”；“本”用于书籍，不能修饰“后话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先去了北京，一把后话等他回来再说。", "corrected_sentence": "他先去了北京，后话等他回来再说。", "error_description": "量词错误：“后话”前多加了“一把”。“把”用于刀、椅子等东西，不能修饰“后话”；应直接说“后话等他回来再说”，不加量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
