INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92979, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得知是听别人说，才知道这件事。", "primary_collocate": null, "pronunciation": "dé zhī", "ipa": "/tɤ˧˥ ʈʂɻ̩˥/", "syllable_count": 2, "sentences": [{"text": "我听朋友说，才得知他生病了。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从邻居那里得知我考上了大学。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从同事口中得知公司要搬家。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是昨天才得知这件事的。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从朋友的话里得知了真相。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从同学那儿得知小王没来的原因。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从别人那里得知，他已经回国了。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听邻居说起，我才得知她搬走了。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从哥哥口中得知了这个好消息。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从朋友那里得知这家店明天关门。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "得知了", "label": "体标"}], "register": "正式", "sense_fingerprint": "听别人说才知道某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得知", "is_correct": true, "explanation": "“得知”表示听别人说才知道，与句中“听朋友说”一致，可以填入。"}, {"text": "猜到", "is_correct": false, "explanation": "语义：“猜到”指凭推测想出，与句中“听朋友说”的信息来源相矛盾。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”靠亲眼所见获得信息，与“听朋友说”相矛盾。"}, {"text": "打听", "is_correct": false, "explanation": "配价：“打听”的宾语是要询问的内容，不能直接接“他生病了”这样的陈述。"}], "explanations": {"得知": "“得知”表示听别人说才知道，与句中“听朋友说”一致，可以填入。", "猜到": "语义：“猜到”指凭推测想出，与句中“听朋友说”的信息来源相矛盾。", "看见": "语义：“看见”靠亲眼所见获得信息，与“听朋友说”相矛盾。", "打听": "配价：“打听”的宾语是要询问的内容，不能直接接“他生病了”这样的陈述。"}, "sentence_index": 0, "correct_answer": "得知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在街上得知了他的身影。", "explanation": "这里应该用〈看见〉。得知指通过消息或别人告知而知道事情，亲眼看到人要用看见，不能用得知。"}, {"text": "我得知了他寄来的信。", "explanation": "这里应该用〈收到〉。得知的对象是消息或事情，“信”是实物，应说收到他寄来的信。"}, {"text": "这道菜很咸，我一尝就得知了它的咸味。", "explanation": "这里应该用〈尝到〉。得知用于获悉消息，不能用于味觉感受，尝到咸味才符合语境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得知", "is_correct": true, "explanation": "“得知”表示从别人那里获悉，与“从别人那里”一致，可以填入。"}, {"text": "发现", "is_correct": false, "explanation": "语义：“发现”指自己察觉，与“从别人那里”相矛盾。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”靠亲眼所见，与“从别人那里”相矛盾。"}, {"text": "收到", "is_correct": false, "explanation": "配价：“收到”需要宾语（消息、信件），这里没有可接的对象，句子不完整。"}], "explanations": {"得知": "“得知”表示从别人那里获悉，与“从别人那里”一致，可以填入。", "发现": "语义：“发现”指自己察觉，与“从别人那里”相矛盾。", "看见": "语义：“看见”靠亲眼所见，与“从别人那里”相矛盾。", "收到": "配价：“收到”需要宾语（消息、信件），这里没有可接的对象，句子不完整。"}, "sentence_index": 6, "correct_answer": "得知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家正在得知这个问题。", "explanation": "这里应该用〈研究〉。得知是一次性获悉消息，不能与“正在”搭配描述正在进行的探究。"}, {"text": "我们认真得知了这件事。", "explanation": "这里应该用〈思考〉。得知表示被动获悉，不能用“认真”修饰，主动钻研要用思考。"}, {"text": "请你得知大家这个结果。", "explanation": "这里应该用〈通知〉。得知是自己获悉，不能用于要求别人把消息告诉大家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从老师那里得知到这次考试的时间。", "corrected_sentence": "我从老师那里得知了这次考试的时间。", "error_description": "“得知”后面不能再加补语“到”。正确说法是“得知了”，“了”表示完成；加“到”与“得知”重复，不符合母语者的习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从同事那里得知着这件事。", "corrected_sentence": "我从同事那里得知了这件事。", "error_description": "“得知”表示瞬间完成的获悉，不能与表示持续的“着”搭配；应说“得知了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
