INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92980, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到消息而知道。", "primary_collocate": null, "pronunciation": "dé zhī", "ipa": "/tɤ˧˥ ʈʂɻ̩˥/", "syllable_count": 2, "sentences": [{"text": "收到短信，我得知考试时间改了。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了新闻，大家得知比赛取消了。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接到电话，他得知奶奶住院了。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从报纸上得知天气会变冷。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得知自己通过了考试，她高兴极了。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得知妈妈要来，我马上打扫房间。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上得知这里有新工作。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得知火车晚点，大家只好在车站等着。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得知孩子平安到家，妈妈放心了。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发了通知，我们才得知要放假。", "target_word": "得知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "得知了", "label": "体标"}], "register": "正式", "sense_fingerprint": "收到消息、通知或新闻后知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得知", "is_correct": true, "explanation": "“得知”表示通过收到的消息而知道，与“收到短信”一致，可以填入。"}, {"text": "离开", "is_correct": false, "explanation": "配价：“离开”的宾语是地方或人，不能接“考试时间改了”这样的陈述。"}, {"text": "打听", "is_correct": false, "explanation": "配价：“打听”需要询问的对象，后面不能直接接“考试时间改了”这样的已发生陈述。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示不再记得，与收到短信后才知道的情况相矛盾。"}], "explanations": {"得知": "“得知”表示通过收到的消息而知道，与“收到短信”一致，可以填入。", "离开": "配价：“离开”的宾语是地方或人，不能接“考试时间改了”这样的陈述。", "打听": "配价：“打听”需要询问的对象，后面不能直接接“考试时间改了”这样的已发生陈述。", "忘记": "语义：“忘记”表示不再记得，与收到短信后才知道的情况相矛盾。"}, "sentence_index": 0, "correct_answer": "得知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在抽屉里得知了钥匙。", "explanation": "这里应该用〈发现〉。得知指通过消息知道事情，在抽屉里找到实物要用发现。"}, {"text": "屋里暖气很足，我得知了身上的暖意。", "explanation": "这里应该用〈感到〉。得知指获悉消息，“身上的暖意”是身体的感受，要用感到，不能用得知。"}, {"text": "我在走廊得知了脚步声。", "explanation": "这里应该用〈听到〉。得知表示通过消息获悉，不能用于耳朵听见的声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得知", "is_correct": true, "explanation": "“得知”表示在网上获悉消息，与“在网上”一致，可以填入。"}, {"text": "证明", "is_correct": false, "explanation": "语义：“证明”指用证据说明真实，句中是获知消息，不是论证，意思不符。"}, {"text": "保存", "is_correct": false, "explanation": "搭配：“保存”的宾语应是文件、资料等具体对象，不能接“这里有新工作”这样的陈述。"}, {"text": "失去", "is_correct": false, "explanation": "配价：“失去”的宾语应是具体事物，不能接“这里有新工作”这样的陈述。"}], "explanations": {"得知": "“得知”表示在网上获悉消息，与“在网上”一致，可以填入。", "证明": "语义：“证明”指用证据说明真实，句中是获知消息，不是论证，意思不符。", "保存": "搭配：“保存”的宾语应是文件、资料等具体对象，不能接“这里有新工作”这样的陈述。", "失去": "配价：“失去”的宾语应是具体事物，不能接“这里有新工作”这样的陈述。"}, "sentence_index": 6, "correct_answer": "得知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在得知明天的比赛。", "explanation": "这里应该用〈准备〉。得知是一次性获悉，不能用于“正在”进行的过程。"}, {"text": "我仔细得知了作业。", "explanation": "这里应该用〈检查〉。得知是被动获悉，不能用“仔细”修饰，也不能以作业为对象。"}, {"text": "请你得知大家这个消息。", "explanation": "这里应该用〈告诉〉。得知是自己获悉消息，不能用于请别人把消息传给大家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从电话里得知到奶奶的病情。", "corrected_sentence": "我从电话里得知了奶奶的病情。", "error_description": "“得知”后面不能再加补语“到”。正确说法是“得知了”，“了”表示完成；加“到”与“得知”重复，不符合母语者的习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在网上得知着这家店的地址。", "corrected_sentence": "我在网上得知了这家店的地址。", "error_description": "“得知”表示瞬间完成的获悉，不能与表示持续的“着”搭配；应说“得知了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
