INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人的内心、精神和思想感情。", "primary_collocate": null, "pronunciation": "xīn líng", "ipa": "ɕin˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她的心灵很美。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很关心学生的心灵健康。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书可以让人的心灵更丰富。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争给孩子的心灵留下了伤痛。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个心灵很纯洁的人。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家写出了普通人的心灵世界。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐可以安慰人的心灵。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心灵受过很大的伤害。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要多读书，让心灵更干净。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影让很多人的心灵得到了安慰。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心灵深处", "label": "复合"}, {"form": "心靈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人的内心、精神和思想感情的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c651e1d1-7d7e-4bf6-8590-9fbd5db22afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心灵", "is_correct": true, "explanation": "心灵指人的内心和精神，可以用“美”来形容，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“美”不用来形容体重。"}, {"text": "血压", "is_correct": false, "explanation": "语义：血压是生理指标，没有美丑之分。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：成绩多说“好”，不说“美”。"}], "explanations": {"心灵": "心灵指人的内心和精神，可以用“美”来形容，符合句意。", "体重": "搭配：“美”不用来形容体重。", "血压": "语义：血压是生理指标，没有美丑之分。", "成绩": "搭配：成绩多说“好”，不说“美”。"}, "sentence_index": 0, "correct_answer": "心灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃得太多让他的心灵长胖了。", "explanation": "这里应该用〈身体〉。长胖指身体，心灵指内心和精神，不能说长胖。"}, {"text": "理发师剪短了她的心灵。", "explanation": "这里应该用〈头发〉。被剪短的是头发，心灵不能被剪。"}, {"text": "他用心灵咬碎了饼干。", "explanation": "这里应该用〈牙齿〉。咬东西要用牙齿，心灵是内心，不能用来咬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心灵", "is_correct": true, "explanation": "心灵指人的内心和思想感情，音乐可以安慰它，符合句意。"}, {"text": "肚子", "is_correct": false, "explanation": "语义：肚子没有感情，不需要音乐的安慰。"}, {"text": "脚趾", "is_correct": false, "explanation": "语义：脚趾没有感受，不会因音乐得到安慰。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“安慰”的对象是人或情绪，不说安慰眼泪。"}], "explanations": {"心灵": "心灵指人的内心和思想感情，音乐可以安慰它，符合句意。", "肚子": "语义：肚子没有感情，不需要音乐的安慰。", "脚趾": "语义：脚趾没有感受，不会因音乐得到安慰。", "眼泪": "搭配：“安慰”的对象是人或情绪，不说安慰眼泪。"}, "sentence_index": 6, "correct_answer": "心灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生切除了他的心灵。", "explanation": "这里应该用〈肾〉。切除的是器官，心灵是内心和精神，不能被切除。"}, {"text": "他把心灵剪短了。", "explanation": "这里应该用〈指甲〉。剪的是指甲，心灵不能被剪短。"}, {"text": "他给手机换了心灵。", "explanation": "这里应该用〈电池〉。换的是电池，心灵是人的内心，不能用于手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人的心灵们很宁静。", "corrected_sentence": "这位老人的心灵很宁静。", "error_description": "错误形式是在“心灵”后加“们”，正确形式是“心灵”不加“们”。“心灵”不能通过加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一把善良的心灵。", "corrected_sentence": "这是一颗善良的心灵。", "error_description": "错误形式是量词“把”，正确形式是“颗”。“把”用于有柄的器具，心灵应用“颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92983, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "爱", "is_correct": true, "explanation": "正确：「爱」与「恨」是反义词，表示喜爱。"}, {"text": "洗", "is_correct": false, "explanation": "与「恨」没有反义关系，「洗」指用水去除污物。"}, {"text": "跑", "is_correct": false, "explanation": "与「恨」没有反义关系，「跑」指快速移动。"}, {"text": "画", "is_correct": false, "explanation": "与「恨」没有反义关系，「画」指用线条或颜色描绘。"}], "correct_answer": "爱", "explanations": {"爱": "正确：「爱」与「恨」是反义词，表示喜爱。", "洗": "与「恨」没有反义关系，「洗」指用水去除污物。", "跑": "与「恨」没有反义关系，「跑」指快速移动。", "画": "与「恨」没有反义关系，「画」指用线条或颜色描绘。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92983, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "爱", "is_correct": true, "explanation": "正确：「爱」与「恨」是反义词，表示喜爱。"}, {"text": "吃", "is_correct": false, "explanation": "与「恨」没有反义关系，「吃」指进食。"}, {"text": "写", "is_correct": false, "explanation": "与「恨」没有反义关系，「写」指书写文字。"}, {"text": "唱", "is_correct": false, "explanation": "与「恨」没有反义关系，「唱」指发出歌声。"}], "correct_answer": "爱", "explanations": {"爱": "正确：「爱」与「恨」是反义词，表示喜爱。", "吃": "与「恨」没有反义关系，「吃」指进食。", "写": "与「恨」没有反义关系，「写」指书写文字。", "唱": "与「恨」没有反义关系，「唱」指发出歌声。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92983, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恨是特别生气，非常不喜欢某个人。", "primary_collocate": null, "pronunciation": "hèn", "ipa": "xən˥˩", "syllable_count": 1, "sentences": [{"text": "我恨他。", "target_word": "恨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她恨她的哥哥。", "target_word": "恨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他恨那个骗他的人。", "target_word": "恨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我真的很恨这个人。", "target_word": "恨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他恨了妹妹一个星期。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明恨他的同学，因为同学拿走了他的书。", "target_word": "恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么这么恨我？", "target_word": "恨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她从来没有恨过别人。", "target_word": "恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想恨任何人。", "target_word": "恨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他恨着那个人，不想和他说话。", "target_word": "恨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恨过", "label": "体标"}, {"form": "恨着", "label": "体标"}, {"form": "仇恨", "label": "复合"}], "register": "中性", "sense_fingerprint": "恨：特别生气，非常不喜欢某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92983, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恨", "is_correct": true, "explanation": "正确：「恨」hèn，表示特别生气、非常不喜欢某个人。"}, {"text": "很", "is_correct": false, "explanation": "hěn（第三声）与 hèn（第四声）声调不同，意思是很。"}, {"text": "汉", "is_correct": false, "explanation": "hàn 与 hèn 韵母不同（an 与 en），意思是汉族或汉字。"}, {"text": "痕", "is_correct": false, "explanation": "hén（第二声）与 hèn（第四声）声调不同，意思是痕迹。"}], "explanations": {"恨": "正确：「恨」hèn，表示特别生气、非常不喜欢某个人。", "很": "hěn（第三声）与 hèn（第四声）声调不同，意思是很。", "汉": "hàn 与 hèn 韵母不同（an 与 en），意思是汉族或汉字。", "痕": "hén（第二声）与 hèn（第四声）声调不同，意思是痕迹。"}, "sentence_index": null, "correct_answer": "恨"}, "level_3": {"options": [{"text": "恨", "is_correct": true, "explanation": "正确：「恨」表示非常不喜欢某个人，与「我」「他」的句子相符。"}, {"text": "哭", "is_correct": false, "explanation": "配价：「哭」是不及物动词，后面不能直接带人作宾语，「我哭他」不成立。"}, {"text": "坐", "is_correct": false, "explanation": "配价：「坐」不能直接带人作宾语，「我坐他」不成立。"}, {"text": "伸", "is_correct": false, "explanation": "搭配：「伸」要与手、腰、腿等搭配，不能说「伸他」。"}], "explanations": {"恨": "正确：「恨」表示非常不喜欢某个人，与「我」「他」的句子相符。", "哭": "配价：「哭」是不及物动词，后面不能直接带人作宾语，「我哭他」不成立。", "坐": "配价：「坐」不能直接带人作宾语，「我坐他」不成立。", "伸": "搭配：「伸」要与手、腰、腿等搭配，不能说「伸他」。"}, "sentence_index": 0, "correct_answer": "恨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我真的很恨这位热心的邻居，他总是帮我修电脑。", "explanation": "这里应该用〈感激〉。「恨」指特别生气、非常不喜欢某个人；对帮过自己的人应说「感激」。"}, {"text": "我很恨这个新来的同学，他很快就成了我的好朋友。", "explanation": "这里应该用〈喜欢〉。「恨」指特别生气、非常不喜欢某个人；对刚认识就成为好朋友的同学应说「喜欢」。"}, {"text": "我恨这位画家，他的作品太美了。", "explanation": "这里应该用〈欣赏〉。「恨」指特别生气、非常不喜欢某个人；对美的作品应说「欣赏」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92983, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恨", "is_correct": true, "explanation": "正确：「恨」hèn，表示特别生气、非常不喜欢某个人。"}, {"text": "狠", "is_correct": false, "explanation": "hěn（第三声）与 hèn（第四声）声调不同，意思是凶狠。"}, {"text": "汗", "is_correct": false, "explanation": "hàn 与 hèn 韵母不同（an 与 en），意思是汗水。"}, {"text": "痕", "is_correct": false, "explanation": "hén（第二声）与 hèn（第四声）声调不同，意思是痕迹。"}], "explanations": {"恨": "正确：「恨」hèn，表示特别生气、非常不喜欢某个人。", "狠": "hěn（第三声）与 hèn（第四声）声调不同，意思是凶狠。", "汗": "hàn 与 hèn 韵母不同（an 与 en），意思是汗水。", "痕": "hén（第二声）与 hèn（第四声）声调不同，意思是痕迹。"}, "sentence_index": null, "correct_answer": "恨"}, "level_3": {"options": [{"text": "恨", "is_correct": true, "explanation": "正确：「恨」表示非常不喜欢某个人，与「你为什么这么……我」相符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：「咳嗽」是不及物动词，不能直接带「我」作宾语。"}, {"text": "走", "is_correct": false, "explanation": "配价：「走」不能直接带人作宾语，「你为什么这么走我」不成立。"}, {"text": "投", "is_correct": false, "explanation": "搭配：「投」要接「投降」「投资」等，不能与「这么」和「我」搭配成句。"}], "explanations": {"恨": "正确：「恨」表示非常不喜欢某个人，与「你为什么这么……我」相符。", "咳嗽": "配价：「咳嗽」是不及物动词，不能直接带「我」作宾语。", "走": "配价：「走」不能直接带人作宾语，「你为什么这么走我」不成立。", "投": "搭配：「投」要接「投降」「投资」等，不能与「这么」和「我」搭配成句。"}, "sentence_index": 6, "correct_answer": "恨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很恨这位老师，他讲课讲得太好了。", "explanation": "这里应该用〈敬佩〉。「恨」指特别生气、非常不喜欢某个人；老师讲得好应说「敬佩」。"}, {"text": "我很恨我的哥哥，他每次回家都给我带礼物。", "explanation": "这里应该用〈喜欢〉。「恨」指特别生气、非常不喜欢某个人；哥哥每次带礼物应说「喜欢」或「亲近」。"}, {"text": "妈妈恨他的饭菜太咸。", "explanation": "这里应该用〈嫌〉。「恨」指特别生气、非常不喜欢某个人，饭菜咸只是口味问题，应说「嫌」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从来没恨了他。", "corrected_sentence": "我从来没恨过他。", "error_description": "错误：「从来没……」表示经历过的动作要用「过」，不用「了」，应说「从来没恨过他」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你为什么这恨他？", "corrected_sentence": "你为什么这么恨他？", "error_description": "错误：「这」不能单独修饰动词「恨」，应说「这么」。「这么恨他」中「这么」是状语，要放在「恨」前面，应说「你为什么这么恨他」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92984, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "爱", "is_correct": true, "explanation": "正确：「爱」与「恨」是反义词，表示喜爱、深厚的感情。"}, {"text": "吃", "is_correct": false, "explanation": "与「恨」没有反义关系，「吃」指进食。"}, {"text": "写", "is_correct": false, "explanation": "与「恨」没有反义关系，「写」指书写文字。"}, {"text": "唱", "is_correct": false, "explanation": "与「恨」没有反义关系，「唱」指发出歌声。"}], "correct_answer": "爱", "explanations": {"爱": "正确：「爱」与「恨」是反义词，表示喜爱、深厚的感情。", "吃": "与「恨」没有反义关系，「吃」指进食。", "写": "与「恨」没有反义关系，「写」指书写文字。", "唱": "与「恨」没有反义关系，「唱」指发出歌声。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
