INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92984, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仇视；对人或事物强烈不满。", "primary_collocate": null, "pronunciation": "hèn", "ipa": "xən˥˩", "syllable_count": 1, "sentences": [{"text": "他恨那些伤害过孩子的人。", "target_word": "恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我恨这种不公平的制度。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很恨欺骗自己的朋友。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不恨他，只是不想再见他。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民们都恨这个贪官。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他恨那个偷了他钱的人。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人恨战争，因为战争带来痛苦。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她恨了他很多年。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人恨着那场大火，一直不愿提起。", "target_word": "恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我恨这种总是迟到的习惯。", "target_word": "恨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "恨过", "label": "体标"}, {"form": "恨着", "label": "体标"}, {"form": "仇恨", "label": "复合"}], "register": "中性", "sense_fingerprint": "恨：仇视某人，或对某事物强烈不满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恨", "is_correct": true, "explanation": "正确：「恨」hèn，表示仇视或强烈不满。"}, {"text": "很", "is_correct": false, "explanation": "hěn（第三声）与 hèn（第四声）声调不同，意思是很。"}, {"text": "汉", "is_correct": false, "explanation": "hàn 与 hèn 韵母不同（an 与 en），意思是汉族或汉字。"}, {"text": "痕", "is_correct": false, "explanation": "hén（第二声）与 hèn（第四声）声调不同，意思是痕迹。"}], "explanations": {"恨": "正确：「恨」hèn，表示仇视或强烈不满。", "很": "hěn（第三声）与 hèn（第四声）声调不同，意思是很。", "汉": "hàn 与 hèn 韵母不同（an 与 en），意思是汉族或汉字。", "痕": "hén（第二声）与 hèn（第四声）声调不同，意思是痕迹。"}, "sentence_index": null, "correct_answer": "恨"}, "level_3": {"options": [{"text": "恨", "is_correct": true, "explanation": "正确：「恨」表示仇视，与「伤害过孩子的人」的语境相符。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：「感谢」表示感激，与「伤害过孩子的人」的语境相反，句意荒谬。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」表示赞赏，与伤害孩子的人不合。"}, {"text": "生气", "is_correct": false, "explanation": "配价：「生气」不能直接带人作宾语，应说「对……生气」或「生……的气」。"}], "explanations": {"恨": "正确：「恨」表示仇视，与「伤害过孩子的人」的语境相符。", "感谢": "语义：「感谢」表示感激，与「伤害过孩子的人」的语境相反，句意荒谬。", "欣赏": "语义：「欣赏」表示赞赏，与伤害孩子的人不合。", "生气": "配价：「生气」不能直接带人作宾语，应说「对……生气」或「生……的气」。"}, "sentence_index": 0, "correct_answer": "恨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很恨老师，因为老师每天都帮我补习功课。", "explanation": "这里应该用〈感激〉。「恨」表示仇视或强烈不满，对帮过自己的人不能用；这里表示感谢，应说「感激」。"}, {"text": "我很恨这次旅行，风景美得让人感动。", "explanation": "这里应该用〈喜爱〉。「恨」表示仇视或强烈不满，风景让人感动时应说「喜爱」。"}, {"text": "他很恨这位新来的同事，还把自己的工作都教给他。", "explanation": "这里应该用〈欣赏〉。「恨」表示仇视，同事教他工作说明是关心或欣赏，应说「欣赏」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92984, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恨", "is_correct": true, "explanation": "正确：「恨」hèn，表示仇视或强烈不满。"}, {"text": "狠", "is_correct": false, "explanation": "hěn（第三声）与 hèn（第四声）声调不同，意思是凶狠。"}, {"text": "汗", "is_correct": false, "explanation": "hàn 与 hèn 韵母不同（an 与 en），意思是汗水。"}, {"text": "痕", "is_correct": false, "explanation": "hén（第二声）与 hèn（第四声）声调不同，意思是痕迹。"}], "explanations": {"恨": "正确：「恨」hèn，表示仇视或强烈不满。", "狠": "hěn（第三声）与 hèn（第四声）声调不同，意思是凶狠。", "汗": "hàn 与 hèn 韵母不同（an 与 en），意思是汗水。", "痕": "hén（第二声）与 hèn（第四声）声调不同，意思是痕迹。"}, "sentence_index": null, "correct_answer": "恨"}, "level_3": {"options": [{"text": "恨", "is_correct": true, "explanation": "正确：「恨」表示仇视，与「因为战争带来痛苦」的理由相符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：「赞美」表示称赞，与「因为战争带来痛苦」的理由相矛盾。"}, {"text": "得罪", "is_correct": false, "explanation": "搭配：「得罪」的对象一般是人，不能说「得罪战争」。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：「喜欢」表示喜爱，与后半句「战争带来痛苦」的因果关系相矛盾。"}], "explanations": {"恨": "正确：「恨」表示仇视，与「因为战争带来痛苦」的理由相符。", "赞美": "语义：「赞美」表示称赞，与「因为战争带来痛苦」的理由相矛盾。", "得罪": "搭配：「得罪」的对象一般是人，不能说「得罪战争」。", "喜欢": "语义：「喜欢」表示喜爱，与后半句「战争带来痛苦」的因果关系相矛盾。"}, "sentence_index": 6, "correct_answer": "恨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈很恨我的成绩，每次都夸我。", "explanation": "这里应该用〈满意〉。「恨」表示仇视或强烈不满，妈妈夸奖时应说「满意」。"}, {"text": "老板很恨我的新方案，马上就批准了。", "explanation": "这里应该用〈赞赏〉。「恨」表示仇视或强烈不满，老板马上批准时应说「赞赏」。"}, {"text": "奶奶恨这个孙子，每次都把好吃的留给他。", "explanation": "这里应该用〈疼爱〉。「恨」表示仇视，对孙子应说「疼爱」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他恨咬牙切齿。", "corrected_sentence": "他恨得咬牙切齿。", "error_description": "错误：补语前漏掉了「得」。「恨得……」表示程度，应说「恨得咬牙切齿」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经恨了我，但后来不恨了。", "corrected_sentence": "他曾经恨过我，但后来不恨了。", "error_description": "错误：表示曾经经历过的动作要用「过」，不用「了」。「曾经恨了」应改为「曾经恨过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
