INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92985, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "成对是两个两个放在一起。", "primary_collocate": null, "pronunciation": "chéng duì", "ipa": "tʂʰɤŋ˧˥ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "筷子总是成对放。", "target_word": "成对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两只鸟成对飞来飞去。", "target_word": "成对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上的花瓶成对摆着。", "target_word": "成对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的鞋子成对放在架子上。", "target_word": "成对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些灯成对挂在门口。", "target_word": "成对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把手套成对放进盒子里。", "target_word": "成对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟总是成对出现。", "target_word": "成对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友送了我一些成对的杯子。", "target_word": "成对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架上的小狗娃娃成对坐着。", "target_word": "成对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们成对走进教室。", "target_word": "成对", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "成对了", "label": "体标"}, {"form": "成双成对", "label": "成语"}], "register": "中性", "sense_fingerprint": "成对：两个两个放在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成对", "is_correct": true, "explanation": "成对指两两放在一起，与“总是……放”的摆放方式相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：筷子不能唱，“唱放”讲不通。"}, {"text": "跑", "is_correct": false, "explanation": "语义：筷子不会跑，“跑放”不能表示摆放。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”不能修饰“放”，两者不构成搭配。"}], "explanations": {"成对": "成对指两两放在一起，与“总是……放”的摆放方式相符。", "唱": "语义：筷子不能唱，“唱放”讲不通。", "跑": "语义：筷子不会跑，“跑放”不能表示摆放。", "修": "搭配：“修”不能修饰“放”，两者不构成搭配。"}, "sentence_index": 0, "correct_answer": "成对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞成对放在架子上。", "explanation": "“成对”要两件配成一对，“这把伞”只是一件，不能说成对。"}, {"text": "我的书包和牙刷成对放在架子上。", "explanation": "“成对”指两件同类、能配成一对的东西，“书包”和“牙刷”不是一对，不能说成对放。"}, {"text": "这个苹果成对放在架子上。", "explanation": "“成对”需要两件以上配成一对，一个苹果不能说成对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成对", "is_correct": true, "explanation": "成对表示两两一起出现，与“总是……出现”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：鸟不会“吃出现”，句子无法表达出现的意思。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪，“煮出现”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“出现”搭配。"}], "explanations": {"成对": "成对表示两两一起出现，与“总是……出现”相合。", "吃": "语义：鸟不会“吃出现”，句子无法表达出现的意思。", "煮": "语义：煮是烹饪，“煮出现”不成立。", "洗": "搭配：“洗”不能与“出现”搭配。"}, "sentence_index": 6, "correct_answer": "成对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一个小朋友成对走进教室。", "explanation": "“成对”需要两个以上配成一对，“一个小朋友”不能成对。"}, {"text": "一张桌子成对搬进了教室。", "explanation": "“成对”要两件配成一对，“一张桌子”只是一件，不能说成对搬进教室。"}, {"text": "明天的晚会成对开始了。", "explanation": "“成对”只用于两件物品或两人配成一对，不能用于“晚会”这类活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "碗筷总是很成对放。", "corrected_sentence": "碗筷总是成对放。", "error_description": "错误：「很」是程度副词，不能修饰动词「成对」，应删去「很」，说「总是成对放」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些蝴蝶总是很成对飞。", "corrected_sentence": "那些蝴蝶总是成对飞。", "error_description": "错误：「很」是程度副词，不能修饰动词「成对」，应删去「很」，说「总是成对飞」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
