INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "配成一对；两个合成一组。", "primary_collocate": null, "pronunciation": "chéng duì", "ipa": "tʂʰɤŋ˧˥ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这些鞋要成对卖。", "target_word": "成对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手套都是成对的。", "target_word": "成对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让学生成对练习说话。", "target_word": "成对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这些袜子成对放好。", "target_word": "成对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些杯子是成对买的。", "target_word": "成对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们先成对，然后再开始游戏。", "target_word": "成对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两只袜子已经成对了。", "target_word": "成对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们成对站好，开始跳舞。", "target_word": "成对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "店里的耳环都要成对出售。", "target_word": "成对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们成对做实验。", "target_word": "成对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成对了", "label": "体标"}, {"form": "成双成对", "label": "成语"}], "register": "中性", "sense_fingerprint": "成对：把两个配成一对、合成一组", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成对", "is_correct": true, "explanation": "成对指两只配成一对，这里说这些鞋要成双出售，正好相合。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去灰尘或污渍，“要擦卖”讲不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”与“卖”之间没有搭配关系，不能说修卖。"}, {"text": "染", "is_correct": false, "explanation": "语义：染是给物体上色，“要染卖”不成立。"}], "explanations": {"成对": "成对指两只配成一对，这里说这些鞋要成双出售，正好相合。", "擦": "语义：擦是抹去灰尘或污渍，“要擦卖”讲不通。", "修": "搭配：“修”与“卖”之间没有搭配关系，不能说修卖。", "染": "语义：染是给物体上色，“要染卖”不成立。"}, "sentence_index": 0, "correct_answer": "成对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个钟成对挂在墙上。", "explanation": "“成对”要两件配成一对，“这个钟”只是一件，不能说成对。"}, {"text": "我的手机和电脑成对买回来了。", "explanation": "“成对”指两件同类、能配成一对的东西，“手机”和“电脑”不是一对，不能说成对买。"}, {"text": "他一个人成对走进教室。", "explanation": "“成对”需要两件或两人配成一对，“一个人”无法成对，这里不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成对", "is_correct": true, "explanation": "成对用于两只配成一对的东西，这里说两只袜子已经成对了。"}, {"text": "吃", "is_correct": false, "explanation": "语义：袜子不能吃，“已经吃了”与句子的主语不合。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”不与“袜子”搭配，不能说读袜子。"}, {"text": "唱", "is_correct": false, "explanation": "语义：袜子不能唱歌，“已经唱了”讲不通。"}], "explanations": {"成对": "成对用于两只配成一对的东西，这里说两只袜子已经成对了。", "吃": "语义：袜子不能吃，“已经吃了”与句子的主语不合。", "读": "搭配：“读”不与“袜子”搭配，不能说读袜子。", "唱": "语义：袜子不能唱歌，“已经唱了”讲不通。"}, "sentence_index": 6, "correct_answer": "成对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室里只有一个学生，他成对做实验。", "explanation": "“成对”需要两个以上配成一对，只有一个学生时不能说成对做实验。"}, {"text": "这一本书是成对装的。", "explanation": "这里应该用〈单独〉。一本书只是一件，不能成对装。"}, {"text": "明天的会议成对开始了。", "explanation": "“成对”只用于两件物品或两人配成一对，不能用于“会议”这类活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两只鸟很成对飞走了。", "corrected_sentence": "这两只鸟成对飞走了。", "error_description": "错误：「很」是程度副词，不能修饰动词「成对」，应删去「很」，说「成对飞走了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些袜子很成对了。", "corrected_sentence": "这些袜子已经成对了。", "error_description": "错误：「很」是程度副词，不能修饰「成对」这样表示动作结果的动词，应改为「已经」，说「已经成对了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
