INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92988, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按次序摆放，使成行列。", "primary_collocate": null, "pronunciation": "pái", "ipa": "pʰai˧˥", "syllable_count": 1, "sentences": [{"text": "请按高矮把同学排好。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片按时间排好了。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把名字按顺序排在黑板上。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书按大小排成一行。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些字母按顺序排一下。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把椅子排整齐吧。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把玩具车按颜色排好。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员正在把水果按大小排好。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把卡片按号码排好。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把座位按次序排得很整齐。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排了", "label": "完成体"}, {"form": "排着", "label": "持续体"}, {"form": "排过", "label": "经历体"}, {"form": "排好", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "按顺序、大小等次序摆放，使成行列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c651e1d1-7d7e-4bf6-8590-9fbd5db22afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92988, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排", "is_correct": true, "explanation": "排 pái（第二声）是正确答案，意思是按次序摆放。"}, {"text": "爬", "is_correct": false, "explanation": "爬 pá 与 pái 韵母不同（a 与 ai），意思是爬行。"}, {"text": "白", "is_correct": false, "explanation": "白 bái 与 pái 声母不同（b 与 p），意思是白色。"}, {"text": "台", "is_correct": false, "explanation": "台 tái 与 pái 声母不同（t 与 p），意思是台子。"}, {"text": "拍", "is_correct": false, "explanation": "拍 pāi（第一声）与 pái（第二声）声调不同，意思是拍打。"}], "explanations": {"排": "排 pái（第二声）是正确答案，意思是按次序摆放。", "爬": "爬 pá 与 pái 韵母不同（a 与 ai），意思是爬行。", "白": "白 bái 与 pái 声母不同（b 与 p），意思是白色。", "台": "台 tái 与 pái 声母不同（t 与 p），意思是台子。", "拍": "拍 pāi（第一声）与 pái（第二声）声调不同，意思是拍打。"}, "sentence_index": null, "correct_answer": "排"}, "level_3": {"options": [{"text": "排", "is_correct": true, "explanation": "排好是按次序摆整齐，“排好同学”符合句意。"}, {"text": "叫", "is_correct": false, "explanation": "语义：“叫好”指喝彩，不能指按高矮整理同学。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗的对象多为物品，不说洗同学。"}, {"text": "吹", "is_correct": false, "explanation": "语义：吹指用气流推动，与排列同学无关。"}], "explanations": {"排": "排好是按次序摆整齐，“排好同学”符合句意。", "叫": "语义：“叫好”指喝彩，不能指按高矮整理同学。", "洗": "搭配：洗的对象多为物品，不说洗同学。", "吹": "语义：吹指用气流推动，与排列同学无关。"}, "sentence_index": 0, "correct_answer": "排"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把衣服排得很干净。", "explanation": "这里应该用〈洗〉。排表示按次序摆放，不表示清洗使衣服干净。"}, {"text": "他把牛奶排进了杯子里。", "explanation": "这里应该用〈倒〉。排指按次序摆放人或东西，液体不能这样排列。"}, {"text": "他把孩子排得很高兴。", "explanation": "这里应该用〈逗〉。排表示按次序摆放，不能使人高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92988, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "排", "is_correct": true, "explanation": "排 pái（第二声）是正确答案，意思是按次序摆放。"}, {"text": "拍", "is_correct": false, "explanation": "拍 pāi（第一声）与 pái（第二声）声调不同，意思是拍打。"}, {"text": "盘", "is_correct": false, "explanation": "盘 pán 与 pái 韵母不同（an 与 ai），意思是盘子。"}, {"text": "派", "is_correct": false, "explanation": "派 pài（第四声）与 pái（第二声）声调不同，意思是派遣。"}, {"text": "赔", "is_correct": false, "explanation": "赔 péi 与 pái 韵母不同（ei 与 ai），意思是赔偿。"}], "explanations": {"排": "排 pái（第二声）是正确答案，意思是按次序摆放。", "拍": "拍 pāi（第一声）与 pái（第二声）声调不同，意思是拍打。", "盘": "盘 pán 与 pái 韵母不同（an 与 ai），意思是盘子。", "派": "派 pài（第四声）与 pái（第二声）声调不同，意思是派遣。", "赔": "赔 péi 与 pái 韵母不同（ei 与 ai），意思是赔偿。"}, "sentence_index": null, "correct_answer": "排"}, "level_3": {"options": [{"text": "排", "is_correct": true, "explanation": "排是按次序摆放，“排好玩具车”符合句意。"}, {"text": "写", "is_correct": false, "explanation": "语义：写指书写文字，不能用于摆放玩具车。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：煮的对象是食物，不说煮玩具车。"}, {"text": "砍", "is_correct": false, "explanation": "语义：砍指用刀斩断，与按颜色摆放玩具车无关。"}], "explanations": {"排": "排是按次序摆放，“排好玩具车”符合句意。", "写": "语义：写指书写文字，不能用于摆放玩具车。", "煮": "搭配：煮的对象是食物，不说煮玩具车。", "砍": "语义：砍指用刀斩断，与按颜色摆放玩具车无关。"}, "sentence_index": 6, "correct_answer": "排"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把教室排得很干净。", "explanation": "这里应该用〈擦〉。排表示按次序摆放，不能表示清洁。"}, {"text": "他把栏杆排得很白。", "explanation": "这里应该用〈刷〉。排不表示涂刷或使变白。"}, {"text": "他把桌椅排得很结实。", "explanation": "这里应该用〈修〉。排不表示修理使牢固。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
