INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员把水果排很整齐。", "corrected_sentence": "店员把水果排得很整齐。", "error_description": "错误形式是“排很整齐”，正确形式是“排得很整齐”。描述结果的补语前要用“得”连接，漏掉“得”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
