INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92989, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摸是用手轻轻碰一碰。", "primary_collocate": null, "pronunciation": "mō", "ipa": "mwo˥", "syllable_count": 1, "sentences": [{"text": "小狗很乖，你可以摸它。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别摸火，很烫！", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子伸手摸了摸桌子。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻摸着小猫的头。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙是湿的，你摸一下。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我摸过这只兔子，毛很软。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的东西，请不要乱摸。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摸了一下我的手，很凉。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你摸一摸这块布，很软。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈摸了摸孩子的额头，有点热。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摸了", "label": "完成体"}, {"form": "摸着", "label": "持续体"}, {"form": "摸过", "label": "经历体"}, {"form": "摸摸", "label": "重叠"}], "register": "口语", "sense_fingerprint": "摸：用手轻轻碰一下某个东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors =