INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92989, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摸", "is_correct": true, "explanation": "正确：摸 mō（第一声）是用手轻轻碰一碰的动作。"}, {"text": "模", "is_correct": false, "explanation": "模 mó（第二声）与 mō 声调不同，意思是模型，不是用手碰。"}, {"text": "磨", "is_correct": false, "explanation": "磨 mó（第二声）与 mō 声调不同，意思是打磨、研磨。"}, {"text": "抹", "is_correct": false, "explanation": "抹 mǒ（第三声）与 mō 声调不同，意思是涂抹、擦掉。"}, {"text": "墨", "is_correct": false, "explanation": "墨 mò（第四声）与 mō 声调不同，意思是墨水。"}], "explanations": {"摸": "正确：摸 mō（第一声）是用手轻轻碰一碰的动作。", "模": "模 mó（第二声）与 mō 声调不同，意思是模型，不是用手碰。", "磨": "磨 mó（第二声）与 mō 声调不同，意思是打磨、研磨。", "抹": "抹 mǒ（第三声）与 mō 声调不同，意思是涂抹、擦掉。", "墨": "墨 mò（第四声）与 mō 声调不同，意思是墨水。"}, "sentence_index": null, "correct_answer": "摸"}, "level_3": {"options": [{"text": "摸", "is_correct": true, "explanation": "正确：摸表示用手轻轻碰，适合用在小狗身上，与“你可以”的许可语气相符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”多用于花果，不用于小狗。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧会造成伤害，与“小狗很乖”这种温和的互动相反。"}, {"text": "熄", "is_correct": false, "explanation": "搭配：“熄”多用于火、灯，不能用于小狗。"}], "explanations": {"摸": "正确：摸表示用手轻轻碰，适合用在小狗身上，与“你可以”的许可语气相符。", "摘": "搭配：“摘”多用于花果，不用于小狗。", "烧": "语义：烧会造成伤害，与“小狗很乖”这种温和的互动相反。", "熄": "搭配：“熄”多用于火、灯，不能用于小狗。"}, "sentence_index": 0, "correct_answer": "摸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小猫摸了我一下，手上留下了一道血印。", "explanation": "这里应该用〈挠〉。摸只是轻触，不会划出血印；猫爪挠破皮肤要说〈挠〉。"}, {"text": "他用力摸住我的手，不让我走。", "explanation": "这里应该用〈抓〉。摸只是轻碰，不表示用力握住。"}, {"text": "他用手摸断了那根树枝，大家都很惊讶。", "explanation": "这里应该用〈掰〉。摸只是轻碰，不能表示把树枝弄断；徒手折断要说〈掰〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =