INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92989, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "摸", "is_correct": true, "explanation": "正确：摸 mō（第一声）是用手轻轻碰一碰的动作。"}, {"text": "魔", "is_correct": false, "explanation": "魔 mó（第二声）与 mō 声调不同，意思是魔鬼、魔法。"}, {"text": "默", "is_correct": false, "explanation": "默 mò（第四声）与 mō 声调不同，意思是不说话、沉默。"}, {"text": "莫", "is_correct": false, "explanation": "莫 mò（第四声）与 mō 声调不同，常用于书面语，意思是不要、没有人。"}, {"text": "抹", "is_correct": false, "explanation": "抹 mǒ（第三声）与 mō 声调不同，意思是擦掉、涂抹。"}], "explanations": {"摸": "正确：摸 mō（第一声）是用手轻轻碰一碰的动作。", "魔": "魔 mó（第二声）与 mō 声调不同，意思是魔鬼、魔法。", "默": "默 mò（第四声）与 mō 声调不同，意思是不说话、沉默。", "莫": "莫 mò（第四声）与 mō 声调不同，常用于书面语，意思是不要、没有人。", "抹": "抹 mǒ（第三声）与 mō 声调不同，意思是擦掉、涂抹。"}, "sentence_index": null, "correct_answer": "摸"}, "level_3": {"options": [{"text": "摸", "is_correct": true, "explanation": "正确：摸表示用手轻碰，与“请不要乱”的限制搭配，指不要随便用手碰。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”用于书籍、文字，不能用于商店里的东西。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲，不能用于一般的东西，句子不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加工食物的动作，与“商店里的东西”的泛指不符。"}], "explanations": {"摸": "正确：摸表示用手轻碰，与“请不要乱”的限制搭配，指不要随便用手碰。", "读": "语义：“读”用于书籍、文字，不能用于商店里的东西。", "唱": "搭配：“唱”用于歌曲，不能用于一般的东西，句子不通。", "煮": "语义：煮是加工食物的动作，与“商店里的东西”的泛指不符。"}, "sentence_index": 6, "correct_answer": "摸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摸开了瓶盖，喝了一口水。", "explanation": "这里应该用〈拧〉。摸只是轻碰，不能表示拧开瓶盖。"}, {"text": "他用力把老人摸倒在地上。", "explanation": "这里应该用〈推〉。摸只是轻碰，不能表示用力把人弄倒；使人倒下要说〈推〉。"}, {"text": "他摸了我一拳。", "explanation": "这里应该用〈打〉。摸是轻碰，不能表示用拳头打人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_ver