INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他轻轻着摸那只猫的背。", "corrected_sentence": "他轻轻摸着那只猫的背。", "error_description": "错误：持续体“着”应紧跟在动词“摸”之后，说“摸着”，不能放在“摸”之前。正确：他轻轻摸着那只猫的背。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
