INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92990, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手轻轻接触或抚动。", "primary_collocate": null, "pronunciation": "mō", "ipa": "mwo˥", "syllable_count": 1, "sentences": [{"text": "奶奶笑着摸孩子的头。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摸着胡子，慢慢地想。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩摸着娃娃的头发。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫喜欢人摸它的背。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人摸着我的脸说：“长大了。”", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不停地摸自己的头发。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这匹马很温顺，让我摸它的脖子。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗躺下来，让我摸它的肚子。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈轻轻摸着我的背，我慢慢睡着了。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常摸着那只旧手表，想起爷爷。", "target_word": "摸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摸了", "label": "完成体"}, {"form": "摸着", "label": "持续体"}, {"form": "摸过", "label": "经历体"}, {"form": "摸摸", "label": "重叠"}], "register": "口语", "sense_fingerprint": "摸：用手轻轻抚摸，带有亲近、爱护的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va