INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摸", "is_correct": true, "explanation": "正确：摸 mō（第一声）是用手轻轻抚动的动作，带有亲近的意味。"}, {"text": "模", "is_correct": false, "explanation": "模 mó（第二声）与 mō 声调不同，意思是模型，不是抚摸。"}, {"text": "磨", "is_correct": false, "explanation": "磨 mó（第二声）与 mō 声调不同，意思是打磨、研磨。"}, {"text": "抹", "is_correct": false, "explanation": "抹 mǒ（第三声）与 mō 声调不同，意思是涂抹、擦掉。"}, {"text": "墨", "is_correct": false, "explanation": "墨 mò（第四声）与 mō 声调不同，意思是墨水。"}], "explanations": {"摸": "正确：摸 mō（第一声）是用手轻轻抚动的动作，带有亲近的意味。", "模": "模 mó（第二声）与 mō 声调不同，意思是模型，不是抚摸。", "磨": "磨 mó（第二声）与 mō 声调不同，意思是打磨、研磨。", "抹": "抹 mǒ（第三声）与 mō 声调不同，意思是涂抹、擦掉。", "墨": "墨 mò（第四声）与 mō 声调不同，意思是墨水。"}, "sentence_index": null, "correct_answer": "摸"}, "level_3": {"options": [{"text": "摸", "is_correct": true, "explanation": "正确：摸表示轻柔的抚动，与“笑着”的亲昵场景相符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”多用于花果，不能用于人的头。"}, {"text": "砍", "is_correct": false, "explanation": "语义：砍是暴力的动作，与“笑着”的亲昵氛围冲突。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是把东西分开，用在人的头上不通，也与“笑着”的亲昵场景不符。"}], "explanations": {"摸": "正确：摸表示轻柔的抚动，与“笑着”的亲昵场景相符。", "摘": "搭配：“摘”多用于花果，不能用于人的头。", "砍": "语义：砍是暴力的动作，与“笑着”的亲昵氛围冲突。", "切": "语义：切是把东西分开，用在人的头上不通，也与“笑着”的亲昵场景不符。"}, "sentence_index": 0, "correct_answer": "摸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生用刀摸开了他的伤口。", "explanation": "这里应该用〈切〉。摸只是轻触，不能表示用刀切开伤口。"}, {"text": "他摸了我的胳膊一下，疼得我叫了起来。", "explanation": "这里应该用〈掐〉。摸只是轻触，不会让人疼得叫起来；掐捏才会使人疼痛。"}, {"text": "他用石头摸碎了玻璃，屋里的人都吓了一跳。", "explanation": "这里应该用〈砸〉。摸只是轻触，不能把玻璃摸碎；用石头打碎玻璃要说〈砸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "摸", "is_correct": true, "explanation": "正确：摸 mō（第一声）是用手轻轻抚动的动作。"}, {"text": "膜", "is_correct": false, "explanation": "膜 mó（第二声）与 mō 声调不同，意思是薄膜。"}, {"text": "默", "is_correct": false, "explanation": "默 mò（第四声）与 mō 声调不同，意思是沉默。"}, {"text": "莫", "is_correct": false, "explanation": "莫 mò（第四声）与 mō 声调不同，常用于书面语。"}, {"text": "魔", "is_correct": false, "explanation": "魔 mó（第二声）与 mō 声调不同，意思是魔鬼、魔法。"}], "explanations": {"摸": "正确：摸 mō（第一声）是用手轻轻抚动的动作。", "膜": "膜 mó（第二声）与 mō 声调不同，意思是薄膜。", "默": "默 mò（第四声）与 mō 声调不同，意思是沉默。", "莫": "莫 mò（第四声）与 mō 声调不同，常用于书面语。", "魔": "魔 mó（第二声）与 mō 声调不同，意思是魔鬼、魔法。"}, "sentence_index": null, "correct_answer": "摸"}, "level_3": {"options": [{"text": "摸", "is_correct": true, "explanation": "正确：摸表示轻轻地用手碰，与“温顺”的马和“让我”的许可相符。"}, {"text": "打", "is_correct": false, "explanation": "语义：打是击打，与“温顺”的马冲突。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是伤人的动作，与“很温顺”的描述矛盾。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是伤人的动作，与“很温顺”的马不相符。"}], "explanations": {"摸": "正确：摸表示轻轻地用手碰，与“温顺”的马和“让我”的许可相符。", "打": "语义：打是击打，与“温顺”的马冲突。", "踢": "语义：踢是伤人的动作，与“很温顺”的描述矛盾。", "咬": "语义：咬是伤人的动作，与“很温顺”的马不相符。"}, "sentence_index": 6, "correct_answer": "摸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摸破了那只气球，孩子们哭了起来。", "explanation": "这里应该用〈扎〉。摸只是轻触，不能把气球摸破；扎破气球要说〈扎〉。"}, {"text": "他一脚摸开了那扇门，走了出去。", "explanation": "这里应该用〈踢〉。摸只是轻碰，不能表示用脚踢开门。"}, {"text": "他用拳头摸了那只小狗一下，小狗疼得叫了起来。", "explanation": "这里应该用〈打〉。摸只是轻碰，不能表示用拳头打狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶轻轻摸了着我的手。", "corrected_sentence": "奶奶轻轻摸着我的手。", "error_description": "错误：持续体“着”前不能加“了”，应说“摸着”。正确：奶奶轻轻摸着我的手。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他摸地很轻。", "corrected_sentence": "他摸得很轻。", "error_description": "错误：“摸”后面带状态补语时要用“得”，不能用“地”。正确：他摸得很轻。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
