INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "历史上遗留下来的具有价值的物品。", "primary_collocate": null, "pronunciation": "wén wù", "ipa": "wən˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "这件文物是三千年前留下来的。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多珍贵的文物。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在地下发现了一件文物。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要好好保护国家的文物。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些文物是从一座老墓里挖出来的。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别碰这件文物，它很贵重。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家里的文物送给了博物馆。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批文物下个月会去外国展览。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人偷走了博物馆的一件文物。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察找回了丢失的文物。", "target_word": "文物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "文物古迹", "label": "复合"}, {"form": "出土文物", "label": "复合"}], "register": "中性", "sense_fingerprint": "文物：历史上留下来、有价值的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459873f2-15f3-4c94-997f-d7fd10d4860f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "文物", "is_correct": true, "explanation": "“文物”指历史上遗留下来的具有价值的物品，即本词条。"}, {"text": "万物", "is_correct": false, "explanation": "wàn 与 wén 韵母不同（an/en），意思是一切事物。"}, {"text": "文武", "is_correct": false, "explanation": "wǔ 与 wù 声调不同（第三声与第四声），意思是文官和武官。"}, {"text": "玩物", "is_correct": false, "explanation": "wán 与 wén 韵母不同（an/en），意思是供玩赏的东西。"}], "explanations": {"文物": "“文物”指历史上遗留下来的具有价值的物品，即本词条。", "万物": "wàn 与 wén 韵母不同（an/en），意思是一切事物。", "文武": "wǔ 与 wù 声调不同（第三声与第四声），意思是文官和武官。", "玩物": "wán 与 wén 韵母不同（an/en），意思是供玩赏的东西。"}, "sentence_index": null, "correct_answer": "文物"}, "level_3": {"options": [{"text": "文物", "is_correct": true, "explanation": "“文物”指历史上留下来的有价值的物品，与“三千年前留下来的”相符。"}, {"text": "电视", "is_correct": false, "explanation": "语义：三千年前没有电视，与“三千年前留下来的”矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：三千年前没有手机，与“三千年前留下来的”矛盾。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜会腐烂，不可能留存三千年，与“留下来的”矛盾。"}], "explanations": {"文物": "“文物”指历史上留下来的有价值的物品，与“三千年前留下来的”相符。", "电视": "语义：三千年前没有电视，与“三千年前留下来的”矛盾。", "手机": "语义：三千年前没有手机，与“三千年前留下来的”矛盾。", "蔬菜": "语义：蔬菜会腐烂，不可能留存三千年，与“留下来的”矛盾。"}, "sentence_index": 0, "correct_answer": "文物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件文物是我昨天刚织好的毛衣。", "explanation": "“文物”指历史上遗留下来的器物，刚织好的衣服不能称为文物；这里应该用〈衣服〉。"}, {"text": "这家超市卖的都是最新款的文物。", "explanation": "“文物”指历史上留下来的器物，最新款的商品不能叫文物；这里应该用〈商品〉。"}, {"text": "我今天午饭吃的是一件文物。", "explanation": "“文物”指有历史价值的器物，食物不能用它来指称；这里应该用〈饭菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文物", "is_correct": true, "explanation": "“文物”指历史上留下来的有价值的物品，与“他把家里的……送给了博物馆”的语境相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是废弃无用之物，博物馆不会收藏，与“送给了博物馆”矛盾。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不能送进博物馆展示，与“送给了博物馆”的语境矛盾。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物是活的动物，不能送给博物馆收藏，与语境矛盾。"}], "explanations": {"文物": "“文物”指历史上留下来的有价值的物品，与“他把家里的……送给了博物馆”的语境相符。", "垃圾": "语义：垃圾是废弃无用之物，博物馆不会收藏，与“送给了博物馆”矛盾。", "食物": "语义：食物不能送进博物馆展示，与“送给了博物馆”的语境矛盾。", "宠物": "语义：宠物是活的动物，不能送给博物馆收藏，与语境矛盾。"}, "sentence_index": 6, "correct_answer": "文物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个文物是我们小区里新种的花。", "explanation": "“文物”指历史上遗留下来的器物，新种的花不属于这一类，不能用它指植物。"}, {"text": "我们班的文物都很活泼，每天都在讲笑话。", "explanation": "“文物”只指器物，不能用来指人；这里应该用〈同学〉。"}, {"text": "展览厅里的文物都是上个月才做好的。", "explanation": "“文物”指很久以前留下来的器物，刚做好的东西不能称为文物；这里应该用〈新产品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首文物是唐朝留下来的。", "corrected_sentence": "这件文物是唐朝留下来的。", "error_description": "“首”用于诗、歌曲等，不用于器物；正确的说法是“这件文物是唐朝留下来的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批文物们明年会去外国展览。", "corrected_sentence": "这批文物明年会去外国展览。", "error_description": "“文物”是无生命的器物，不能加复数后缀“们”（“们”只用于人）。正确的说法是“这批文物明年会去外国展览”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
