INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92995, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "曰是古书里用的字，意思是说。", "primary_collocate": null, "pronunciation": "yuē", "ipa": "ɥœ˧˥", "syllable_count": 1, "sentences": [{"text": "孔子曰：“三人行，必有我师。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "子曰：“学而时习之，不亦说乎？”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "颜回曰：“回虽不敏，请事斯语矣。”", "target_word": "曰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孔子曰：“温故而知新，可以为师矣。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孟子曰：“人皆可以为尧舜。”", "target_word": "曰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "子路曰：“闻斯行诸？”", "target_word": "曰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老子曰：“千里之行，始于足下。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上写着：“荀子曰，学不可以已。”", "target_word": "曰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "韩愈曰：“师者，所以传道受业解惑也。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "曾子曰：“吾日三省吾身。”", "target_word": "曰", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "子曰", "label": "复合"}], "register": "文言", "sense_fingerprint": "古书里引出某人的话，相当于“说”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "曰", "is_correct": true, "explanation": "曰（yuē）：古书里引出说的话，相当于“说”。"}, {"text": "月", "is_correct": false, "explanation": "yuè（第四声）与 yuē（第二声）声调不同，意思是月亮。"}, {"text": "越", "is_correct": false, "explanation": "yuè（第四声）与 yuē（第二声）声调不同，意思是超过、越过。"}, {"text": "缺", "is_correct": false, "explanation": "quē 与 yuē 声母不同（q 与 y），意思是缺少。"}], "explanations": {"曰": "曰（yuē）：古书里引出说的话，相当于“说”。", "月": "yuè（第四声）与 yuē（第二声）声调不同，意思是月亮。", "越": "yuè（第四声）与 yuē（第二声）声调不同，意思是超过、越过。", "缺": "quē 与 yuē 声母不同（q 与 y），意思是缺少。"}, "sentence_index": null, "correct_answer": "曰"}, "level_3": {"options": [{"text": "曰", "is_correct": true, "explanation": "曰：古书里引出孔子的话，相当于“说”，是这里唯一合适的词。"}, {"text": "问", "is_correct": false, "explanation": "语义：“问”引出的是提问，而这里引的是陈述句“三人行，必有我师”。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能用来引出一段话作为内容，不能说“哭：……”。"}, {"text": "看", "is_correct": false, "explanation": "配价：“看”需要具体的宾语，不能直接引出一段话。"}], "explanations": {"曰": "曰：古书里引出孔子的话，相当于“说”，是这里唯一合适的词。", "问": "语义：“问”引出的是提问，而这里引的是陈述句“三人行，必有我师”。", "哭": "搭配：“哭”不能用来引出一段话作为内容，不能说“哭：……”。", "看": "配价：“看”需要具体的宾语，不能直接引出一段话。"}, "sentence_index": 0, "correct_answer": "曰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在台上曰一首歌，声音很好听。", "explanation": "这里应该用〈唱〉。曰只表示说，不能用来指唱歌。"}, {"text": "他每天早上曰单词。", "explanation": "这里应该用〈背〉。曰只表示“说”，不能用来指背单词。"}, {"text": "他用毛笔曰一首诗。", "explanation": "这里应该用〈写〉。曰只表示说，不能指用毛笔写诗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92995, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "曰", "is_correct": true, "explanation": "曰（yuē）：古书里引出说的话，相当于“说”。"}, {"text": "悦", "is_correct": false, "explanation": "yuè（第四声）与 yuē（第二声）声调不同，意思是高兴、喜悦。"}, {"text": "阅", "is_correct": false, "explanation": "yuè（第四声）与 yuē（第二声）声调不同，意思是阅读、看。"}, {"text": "靴", "is_correct": false, "explanation": "xuē 与 yuē 声母不同（x 与 y），意思是靴子。"}], "explanations": {"曰": "曰（yuē）：古书里引出说的话，相当于“说”。", "悦": "yuè（第四声）与 yuē（第二声）声调不同，意思是高兴、喜悦。", "阅": "yuè（第四声）与 yuē（第二声）声调不同，意思是阅读、看。", "靴": "xuē 与 yuē 声母不同（x 与 y），意思是靴子。"}, "sentence_index": null, "correct_answer": "曰"}, "level_3": {"options": [{"text": "曰", "is_correct": true, "explanation": "曰：古书里引出老子的话，相当于“说”，是这里唯一合适的词。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要食物作宾语，不能直接引出一段话。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”是不及物的动作，不能用来引出说话的内容。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：“摇”表示晃动，不能与直接引语搭配，说“摇：……”不通。"}], "explanations": {"曰": "曰：古书里引出老子的话，相当于“说”，是这里唯一合适的词。", "吃": "配价：“吃”需要食物作宾语，不能直接引出一段话。", "跑": "搭配：“跑”是不及物的动作，不能用来引出说话的内容。", "摇": "搭配：“摇”表示晃动，不能与直接引语搭配，说“摇：……”不通。"}, "sentence_index": 6, "correct_answer": "曰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他举手曰老师一个问题。", "explanation": "这里应该用〈问〉。曰只能引出所说的话，不能带“老师”和“一个问题”作双宾语。"}, {"text": "我每天晚上曰课文给妈妈听。", "explanation": "这里应该用〈念〉。曰只能引出所说的话，不能指朗读课文。"}, {"text": "他每天早上曰一杯牛奶。", "explanation": "这里应该用〈喝〉。曰只表示说，不能用来指喝东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墨子曰了：“兼相爱，交相利。”", "corrected_sentence": "墨子曰：“兼相爱，交相利。”", "error_description": "“曰”后面不能加“了”。错误形式：曰了；正确形式：曰。“曰”引出说话的内容，不带动态助词，直接写“墨子曰：”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "荀子说曰：“不积跬步，无以至千里。”", "corrected_sentence": "荀子曰：“不积跬步，无以至千里。”", "error_description": "“曰”前面不能再加“说”。错误形式：说曰；正确形式：曰。“曰”本身就是“说”，不能与“说”叠用，直接写“荀子曰：”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
