INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92996, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "文言中的“说”。", "primary_collocate": null, "pronunciation": "yuē", "ipa": "ɥœ˧˥", "syllable_count": 1, "sentences": [{"text": "子曰：“有朋自远方来，不亦乐乎？”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孔子曰：“己所不欲，勿施于人。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孟子曰：“老吾老，以及人之老。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "荀子曰：“青，取之于蓝，而青于蓝。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "曾子曰：“士不可以不弘毅。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他读古书，读到“王曰”两个字，就知道是王说的话。", "target_word": "曰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诸葛亮曰：“非淡泊无以明志。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司马迁曰：“人固有一死。”", "target_word": "曰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孟子曰：“得道者多助，失道者寡助。”", "target_word": "曰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师写在黑板上：“子曰：温故而知新。”", "target_word": "曰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "子曰", "label": "复合"}], "register": "文言", "sense_fingerprint": "文言文里表示“说”的动词，后接所说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
