INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92997, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不好意思是怕别人笑，觉得难为情。", "primary_collocate": null, "pronunciation": "bù hǎo yì si", "ipa": "pu˥˩ xɑʊ˨˩˦ i˥˩ sɿ", "syllable_count": 4, "sentences": [{"text": "她第一次上台，觉得很不好意思。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不好意思地低下了头。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都夸我，我有点不好意思。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩很不好意思，躲在妈妈后面。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不好意思开口向朋友借钱。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说错了话，他脸红了，很不好意思。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不好意思说自己不会唱歌。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这么多人面前跳舞，我真不好意思。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟不好意思地笑了笑。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我穿着旧衣服去，有点不好意思。", "target_word": "不好意思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "因怕被人笑而觉得难为情、害羞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92997, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不好意思", "is_correct": true, "explanation": "正确：“不好意思”表示因怕被笑而难为情，与“第一次上台”的语境相符。"}, {"text": "熟练", "is_correct": false, "explanation": "语义：“熟练”需要多次练习才能达到，与“第一次上台”矛盾。"}, {"text": "老练", "is_correct": false, "explanation": "语义：“老练”指经验丰富，与“第一次上台”矛盾。"}, {"text": "隐蔽", "is_correct": false, "explanation": "搭配：“隐蔽”说的是地点或行动，不用来描述人的感觉。"}], "explanations": {"不好意思": "正确：“不好意思”表示因怕被笑而难为情，与“第一次上台”的语境相符。", "熟练": "语义：“熟练”需要多次练习才能达到，与“第一次上台”矛盾。", "老练": "语义：“老练”指经验丰富，与“第一次上台”矛盾。", "隐蔽": "搭配：“隐蔽”说的是地点或行动，不用来描述人的感觉。"}, "sentence_index": 0, "correct_answer": "不好意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他发烧了，很不好意思。", "explanation": "这里应该用〈难受〉。不好意思表示怕被笑而难为情，发烧时的身体不适要用难受。"}, {"text": "她的小猫走丢了，心里很不好意思。", "explanation": "这里应该用〈难过〉。不好意思表示因怕被笑而难为情，猫走丢后的伤心要用难过。"}, {"text": "他被人冤枉，很不好意思。", "explanation": "这里应该用〈生气〉。不好意思表示难为情，被冤枉后的愤怒要用生气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不好意思", "is_correct": true, "explanation": "正确：“不好意思”表示难为情，与“说自己不会唱歌”的羞怯语气相符。"}, {"text": "自信", "is_correct": false, "explanation": "语义：“自信”与“说自己不会唱歌”的谦逊语气不协调。"}, {"text": "自豪", "is_correct": false, "explanation": "语义：“自豪”表示以某事为荣，与“不会唱歌”的羞怯语境不符。"}, {"text": "满意", "is_correct": false, "explanation": "配价：“满意”后面要接“对……”引出对象或加“地”，这里直接用在“说”前不通。"}], "explanations": {"不好意思": "正确：“不好意思”表示难为情，与“说自己不会唱歌”的羞怯语气相符。", "自信": "语义：“自信”与“说自己不会唱歌”的谦逊语气不协调。", "自豪": "语义：“自豪”表示以某事为荣，与“不会唱歌”的羞怯语境不符。", "满意": "配价：“满意”后面要接“对……”引出对象或加“地”，这里直接用在“说”前不通。"}, "sentence_index": 6, "correct_answer": "不好意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "深夜里听见敲门声，他很不好意思。", "explanation": "这里应该用〈恐惧〉。不好意思表示难为情，害怕时要用恐惧。"}, {"text": "我看到那堆垃圾，很不好意思。", "explanation": "这里应该用〈厌恶〉。不好意思表示难为情，对脏东西的反感要用厌恶。"}, {"text": "他的牙疼得厉害，很不好意思。", "explanation": "这里应该用〈疼〉。不好意思表示怕被笑而难为情，身体的疼痛要用疼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不好意思的把信递给老师。", "corrected_sentence": "她不好意思地把信递给老师。", "error_description": "错误：“不好意思的把信递给老师”。正确：“不好意思地把信递给老师”。修饰动词“递”的状语要用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忘记带伞，淋湿了，有点不好意思过。", "corrected_sentence": "他忘记带伞，淋湿了，有点不好意思。", "error_description": "错误：“有点不好意思过”。正确：“有点不好意思”。这里说的是他当时的感觉，“有点不好意思”表示当前的状态，不能加表示经历的“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
