INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92998, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用作客套话，表示歉意。", "primary_collocate": null, "pronunciation": "bù hǎo yì si", "ipa": "pu˥˩ xɑʊ˨˩˦ i˥˩ sɿ", "syllable_count": 4, "sentences": [{"text": "不好意思，我来晚了。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好意思，请问去地铁站怎么走？", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好意思，借过一下。", "target_word": "不好意思", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不好意思，这个座位有人吗？", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "真不好意思，让你等了这么久。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好意思，我听不清楚，请再说一遍。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好意思，麻烦你帮我拿一下。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好意思，我拿错了你的伞。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好意思，我打错电话了。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好意思，今天我不能去参加你的聚会了。", "target_word": "不好意思", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "客套话，打扰或做错事时表示歉意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不好意思", "is_correct": true, "explanation": "正确：“不好意思”用作客套话，表示迟到的歉意，与句意相符。"}, {"text": "荣幸", "is_correct": false, "explanation": "语义：“荣幸”表示受到恩惠的感激，不用于说明自己迟到。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示愉快，与为迟到道歉的语境不符。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多形容表演或内容，不用来说明自己迟到。"}], "explanations": {"不好意思": "正确：“不好意思”用作客套话，表示迟到的歉意，与句意相符。", "荣幸": "语义：“荣幸”表示受到恩惠的感激，不用于说明自己迟到。", "高兴": "语义：“高兴”表示愉快，与为迟到道歉的语境不符。", "精彩": "搭配：“精彩”多形容表演或内容，不用来说明自己迟到。"}, "sentence_index": 0, "correct_answer": "不好意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情很不好意思，不想说话。", "explanation": "这里应该用〈郁闷〉。不好意思表示致歉，心里不痛快要用郁闷。"}, {"text": "不好意思你帮我拿行李。", "explanation": "这里应该用〈谢谢〉。不好意思用于道歉，表示感谢要用谢谢。"}, {"text": "不好意思你毕业了！", "explanation": "这里应该用〈恭喜〉。不好意思用于道歉，祝贺别人要用恭喜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不好意思", "is_correct": true, "explanation": "正确：“不好意思”用作客套话，引出请求，与句意相符。"}, {"text": "不耐烦", "is_correct": false, "explanation": "语域：“不耐烦”带有不满的情绪，与礼貌请求的语气不符。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语域：“粗鲁”是不礼貌的评价，与请人帮忙的礼貌语境冲突。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”形容态度冷淡，与请求别人帮忙的语境不协调。"}], "explanations": {"不好意思": "正确：“不好意思”用作客套话，引出请求，与句意相符。", "不耐烦": "语域：“不耐烦”带有不满的情绪，与礼貌请求的语气不符。", "粗鲁": "语域：“粗鲁”是不礼貌的评价，与请人帮忙的礼貌语境冲突。", "冷漠": "语义：“冷漠”形容态度冷淡，与请求别人帮忙的语境不协调。"}, "sentence_index": 6, "correct_answer": "不好意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不好意思你来我家做客。", "explanation": "这里应该用〈欢迎〉。不好意思用于道歉，迎接客人要用欢迎。"}, {"text": "下课了，同学们对老师说：“老师，不好意思！”", "explanation": "这里应该用〈再见〉。不好意思用于道歉，下课离开时向老师道别要用再见。"}, {"text": "不好意思生日快乐！", "explanation": "这里应该用〈祝〉。不好意思用于道歉，祝福别人要用祝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "真不好意思过，我的车坏在路上了。", "corrected_sentence": "真不好意思，我的车坏在路上了。", "error_description": "错误：“真不好意思过”。正确：“真不好意思”。“过”表示经历，只用在动词后，客套话“不好意思”后不加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不好意思的，请问能帮我看一下行李吗？", "corrected_sentence": "不好意思，请问能帮我看一下行李吗？", "error_description": "“不好意思”用作客套话时后面直接接句子，不能加“的”。说成“不好意思的”不通，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
