INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92999, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "此后是从这件事以后。", "primary_collocate": null, "pronunciation": "cǐ hòu", "ipa": "tsʰɨ˨˩˦ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他去了北京，此后再也没回来。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那年她生了一场病，此后身体一直不好。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们吵了一架，此后很少说话。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在那里学过画画，此后一直很喜欢。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说了他一次，此后他再也没迟到。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大学毕业后找到工作，此后很少回家。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次考试他很努力，此后成绩越来越好。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们见了一面，此后没有联系。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗丢了，此后孩子总是不高兴。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她搬到了国外，此后我们只能写信。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "此后：从前面说的这件事以后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此后", "is_correct": true, "explanation": "此后指从这件事以后，与“去了北京”之后的时间相符。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“回来”要求人或物返回，“饭店再也没回来”不能这样搭配。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是机构，不能作为“再也没回来”的主语。"}, {"text": "中国", "is_correct": false, "explanation": "语义：国家不能像人一样“回来”，句子不通。"}], "explanations": {"此后": "此后指从这件事以后，与“去了北京”之后的时间相符。", "饭店": "搭配：“回来”要求人或物返回，“饭店再也没回来”不能这样搭配。", "学校": "语义：学校是机构，不能作为“再也没回来”的主语。", "中国": "语义：国家不能像人一样“回来”，句子不通。"}, "sentence_index": 0, "correct_answer": "此后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他离开北京之前，此后一直住在上海。", "explanation": "这里应该用〈此前〉。“此后”指之后，与“离开北京之前”的时间方向相反。"}, {"text": "他站在门此后，没有进来。", "explanation": "这里应该用〈后面〉。「此后」只指时间上的之后，不能表示空间上的后面。"}, {"text": "此后我们正在吃饭。", "explanation": "这里应该用〈此时〉。“正在”指当下进行，与“此后”指之后的时间不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此后", "is_correct": true, "explanation": "此后指那次考试以后，与“成绩越来越好”的时间关系相符。"}, {"text": "高山", "is_correct": false, "explanation": "语义：高山不能有“成绩”，主语不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能有“成绩”，句子不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子不能与“成绩越来越好”搭配。"}], "explanations": {"此后": "此后指那次考试以后，与“成绩越来越好”的时间关系相符。", "高山": "语义：高山不能有“成绩”，主语不合。", "冰箱": "语义：冰箱不能有“成绩”，句子不通。", "桌子": "搭配：桌子不能与“成绩越来越好”搭配。"}, "sentence_index": 6, "correct_answer": "此后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他躲在桌子此后，没有出来。", "explanation": "“此后”只指时间上的之后，不能表示空间上的后面，这里应该用〈后面〉。"}, {"text": "她搬走之前，此后我们只能写信。", "explanation": "这里应该用〈此前〉。“搬走之前”与“此后”的时间方向相反。"}, {"text": "此后我们正在上课。", "explanation": "这里应该用〈此时〉。“正在”指当下进行，与“此后”指之后的时间不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她生了孩子，此后了很少出门。", "corrected_sentence": "她生了孩子，此后很少出门。", "error_description": "“此后”是名词，后面不能直接加“了”；错误形式在“此后”后多出了“了”，应说“此后很少出门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
