INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从这时以后。", "primary_collocate": null, "pronunciation": "cǐ hòu", "ipa": "tsʰɨ˨˩˦ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "今年夏天他搬家了，此后我很少见到他。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十岁那年离开家，此后一直住在外地。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一九九〇年他结婚了，此后过着安静的生活。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议到五点结束，此后大家可以自由活动。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九月一日学校开学，此后我每天早起。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年冬天她戒了烟，此后再没抽过。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司三月成立，此后发展很快。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛晚上八点结束，此后街上安静了。", "target_word": "此后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业那天哭了，此后很少哭。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨在中午停了，此后天气一直很好。", "target_word": "此后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "此后：从前面提到的这个时间点以后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此后", "is_correct": true, "explanation": "此后指今年夏天搬家以后，与“很少见到他”相符。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：“饭店”是地点名词，不能表示搬家以后的时间，句子不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，不能表示时间先后，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能“见到他”，句子不通。"}], "explanations": {"此后": "此后指今年夏天搬家以后，与“很少见到他”相符。", "饭店": "语义：“饭店”是地点名词，不能表示搬家以后的时间，句子不通。", "桌子": "语义：“桌子”是物品，不能表示时间先后，句子不通。", "冰箱": "语义：冰箱不能“见到他”，句子不通。"}, "sentence_index": 0, "correct_answer": "此后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书放在桌子此后。", "explanation": "这里应该用〈后面〉。「此后」只指时间上的之后，不能表示空间上的后面。"}, {"text": "会议五点结束，此后大家正在自由活动。", "explanation": "这里应该用〈此时〉。“正在”指当下进行，与“此后”指之后的时间不符。"}, {"text": "会议到五点结束之前，此后大家可以自由活动。", "explanation": "这里应该用〈此前〉。“结束之前”与“此后”的时间方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此后", "is_correct": true, "explanation": "此后指公司成立之后，与“发展很快”相符。"}, {"text": "高山", "is_correct": false, "explanation": "语义：高山不会“发展”，主语不合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会“发展”，句子不通。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：河流不能与“发展很快”搭配。"}], "explanations": {"此后": "此后指公司成立之后，与“发展很快”相符。", "高山": "语义：高山不会“发展”，主语不合。", "窗户": "语义：窗户不会“发展”，句子不通。", "河流": "搭配：河流不能与“发展很快”搭配。"}, "sentence_index": 6, "correct_answer": "此后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她坐在门此后，一直没说话。", "explanation": "“此后”只指时间上的之后，不能表示空间上的后面，这里应该用〈后面〉。"}, {"text": "雨停之前，此后天气一直很好。", "explanation": "这里应该用〈此前〉。“雨停之前”与“此后”的时间方向相反。"}, {"text": "此后我们正在吃午饭。", "explanation": "这里应该用〈此时〉。“正在”指当下进行，与“此后”指之后的时间不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我大学毕业了，此后了就没联系过他。", "corrected_sentence": "我大学毕业了，此后就没联系过他。", "error_description": "“此后”是名词，后面不能加“了”；错误形式在“此后”后多出了“了”，应说“此后就没联系过他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她结婚了，此后的很少跟朋友见面。", "corrected_sentence": "她结婚了，此后很少跟朋友见面。", "error_description": "“此后”是名词，后面不能加“的”来修饰副词“很少”；错误形式多出了“的”，应说“此后很少跟朋友见面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
