INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93001, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不禁是忍不住，自己就做了。", "primary_collocate": null, "pronunciation": "bù jīn", "ipa": "pu˥˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "蛋糕太香了，我不禁多吃了一块。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到音乐，他不禁跟着唱了起来。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看见雪，不禁叫了起来。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到别人跳舞，她不禁也动了起来。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影太好笑了，大家不禁拍起手来。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那只小猫，我不禁摸了摸它。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲得太好了，我不禁拍了拍手。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闻到面包的香味，我不禁停下了脚步。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着窗外的雨，她不禁叹了口气。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个笑话，大家不禁都笑了。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "忍不住，没有打算却自己做出了某个动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8173b1b7-e271-40b8-a04e-530729132fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93001, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不禁", "is_correct": true, "explanation": "正确答案：不禁（bù jīn）。"}, {"text": "不仅", "is_correct": false, "explanation": "jǐn（第三声）与 jīn（第一声）声调不同，意思是不但。"}, {"text": "不尽", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是没有止境。"}, {"text": "不精", "is_correct": false, "explanation": "jīng 与 jīn 韵尾不同（ng 与 n），意思是不精细。"}], "explanations": {"不禁": "正确答案：不禁（bù jīn）。", "不仅": "jǐn（第三声）与 jīn（第一声）声调不同，意思是不但。", "不尽": "jìn（第四声）与 jīn（第一声）声调不同，意思是没有止境。", "不精": "jīng 与 jīn 韵尾不同（ng 与 n），意思是不精细。"}, "sentence_index": null, "correct_answer": "不禁"}, "level_3": {"options": [{"text": "不禁", "is_correct": true, "explanation": "正确答案：不禁，指没有打算却忍不住做出了动作。"}, {"text": "千万", "is_correct": false, "explanation": "语法：“千万”多用于祈使或否定句，不能接已完成的“多吃了一块”。"}, {"text": "从来", "is_correct": false, "explanation": "语法：“从来”表示一向如此，不能用于一次性的已完成动作。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示进行中，不能与“了”及已完成的动作同用。"}], "explanations": {"不禁": "正确答案：不禁，指没有打算却忍不住做出了动作。", "千万": "语法：“千万”多用于祈使或否定句，不能接已完成的“多吃了一块”。", "从来": "语法：“从来”表示一向如此，不能用于一次性的已完成动作。", "正在": "语法：“正在”表示进行中，不能与“了”及已完成的动作同用。"}, "sentence_index": 0, "correct_answer": "不禁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做事粗心，不禁要出错。", "explanation": "这里应该用〈免不了〉。免不了表示必然会发生，不禁表示没有打算却做出的动作，不能表示必然。"}, {"text": "他明天不禁会来。", "explanation": "这里应该用〈可能〉。可能表示推测，不禁表示没有打算却做出的动作，不能用于推测将来。"}, {"text": "他不禁考了第一名。", "explanation": "这里应该用〈竟然〉。竟然表示出乎意料，不禁表示没有打算却做出的动作，考试成绩不能这样做出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93001, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不禁", "is_correct": true, "explanation": "正确答案：不禁（bù jīn）。"}, {"text": "不尽", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是没有止境。"}, {"text": "步进", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是一步步向前推进。"}, {"text": "不经", "is_correct": false, "explanation": "jīng 与 jīn 韵尾不同（ng 与 n），意思是不经过、不合常理。"}], "explanations": {"不禁": "正确答案：不禁（bù jīn）。", "不尽": "jìn（第四声）与 jīn（第一声）声调不同，意思是没有止境。", "步进": "jìn（第四声）与 jīn（第一声）声调不同，意思是一步步向前推进。", "不经": "jīng 与 jīn 韵尾不同（ng 与 n），意思是不经过、不合常理。"}, "sentence_index": null, "correct_answer": "不禁"}, "level_3": {"options": [{"text": "不禁", "is_correct": true, "explanation": "正确答案：不禁，指没有打算却忍不住做出了动作。"}, {"text": "没有", "is_correct": false, "explanation": "语法：“没有”否定已发生的动作，与“拍了拍手”的肯定叙述矛盾。"}, {"text": "差点", "is_correct": false, "explanation": "语法：“差点”表示几乎发生但实际未发生，与已完成的“拍了拍手”矛盾。"}, {"text": "不必", "is_correct": false, "explanation": "语法：“不必”表示没有必要，不能与已完成的“拍了拍手”同用。"}], "explanations": {"不禁": "正确答案：不禁，指没有打算却忍不住做出了动作。", "没有": "语法：“没有”否定已发生的动作，与“拍了拍手”的肯定叙述矛盾。", "差点": "语法：“差点”表示几乎发生但实际未发生，与已完成的“拍了拍手”矛盾。", "不必": "语法：“不必”表示没有必要，不能与已完成的“拍了拍手”同用。"}, "sentence_index": 6, "correct_answer": "不禁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请大家不禁安静。", "explanation": "这里应该用〈保持〉。“请大家保持安静”是礼貌的要求，不禁表示没有打算却忍不住做出的动作，不能用于请求。"}, {"text": "下雨天没有公交车，我不禁打了车。", "explanation": "这里应该用〈只好〉。只好表示迫于无奈只能如此，不禁表示没有打算却忍不住做出的动作，与“没有公交车”的被迫选择不符。"}, {"text": "为了健康，他不禁戒了烟。", "explanation": "这里应该用〈决定〉。戒烟是经过打算的行为，决定表示有意做出选择，不禁表示没有打算却忍不住做出的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看到好吃的，很不禁咽了一下口水。", "corrected_sentence": "他看到好吃的，不禁咽了一下口水。", "error_description": "程度副词错误：“不禁”是副词，不能被“很”修饰，应去掉“很”，即“他看到好吃的，不禁咽了一下口水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看见老朋友，我忍不住不禁伸手拥抱了他。", "corrected_sentence": "看见老朋友，我不禁伸手拥抱了他。", "error_description": "重复：“忍不住”与“不禁”意思相同，不能叠用，应只用“我不禁伸手拥抱了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
