INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使人死亡，致人于死。", "primary_collocate": null, "pronunciation": "shā hài", "ipa": "ʂa˥ xai˥˩", "syllable_count": 2, "sentences": [{"text": "昨天夜里，有人杀害了这家的主人。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他杀害过人，要坐很多年牢。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了抢钱，他杀害了出租车司机。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏人杀害了两个孩子的妈妈。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有杀害那个女人，是警察弄错了。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察找到了杀害老板的刀。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杀害别人的人，一定会受到处罚。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想杀害自己的对手，但是没有成功。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院说他杀害了朋友，是有罪的。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位记者在国外遇到了坏人，他们杀害了他。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀害了", "label": "完成体"}, {"form": "杀害过", "label": "经历体"}, {"form": "杀害者", "label": "复合"}, {"form": "殺害", "label": "繁体"}], "register": "书面", "sense_fingerprint": "使人死亡，致人于死，多用于案件和新闻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c651e1d1-7d7e-4bf6-8590-9fbd5db22afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杀害", "is_correct": true, "explanation": "正确：杀害指使人死亡，与“昨天夜里”的案件语境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫的对象是房间、地面，不能是“这家的主人”。"}, {"text": "训练", "is_correct": false, "explanation": "搭配：训练多用于动物或学员，不说“训练主人”。"}, {"text": "驯服", "is_correct": false, "explanation": "语义：驯服的对象是动物，不用于人。"}], "explanations": {"杀害": "正确：杀害指使人死亡，与“昨天夜里”的案件语境相符。", "打扫": "搭配：打扫的对象是房间、地面，不能是“这家的主人”。", "训练": "搭配：训练多用于动物或学员，不说“训练主人”。", "驯服": "语义：驯服的对象是动物，不用于人。"}, "sentence_index": 0, "correct_answer": "杀害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熬夜会杀害你的身体。", "explanation": "这里应该用〈伤害〉。伤害可用于身体，杀害只用于人的死亡。"}, {"text": "渔民每天杀害一块咸鱼当午饭。", "explanation": "这里应该用〈切〉。杀害的对象须是有生命的个体，咸鱼已不是活物。"}, {"text": "台风杀害了很多房子。", "explanation": "这里应该用〈摧毁〉。摧毁可用于房屋，杀害只用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杀害", "is_correct": true, "explanation": "正确：杀害指致人于死，“杀害别人的人，一定会受到处罚”符合语境。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：帮助别人的人不会受到处罚，与句子语境矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是施惠的人，“感谢别人的人受到处罚”搭配不当。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：夸奖别人的人不会受到处罚，与句子语境矛盾。"}], "explanations": {"杀害": "正确：杀害指致人于死，“杀害别人的人，一定会受到处罚”符合语境。", "帮助": "语义：帮助别人的人不会受到处罚，与句子语境矛盾。", "感谢": "搭配：“感谢”的对象是施惠的人，“感谢别人的人受到处罚”搭配不当。", "夸奖": "语义：夸奖别人的人不会受到处罚，与句子语境矛盾。"}, "sentence_index": 6, "correct_answer": "杀害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他杀害了一栋老房子。", "explanation": "这里应该用〈拆〉。拆用于房屋，杀害只用于把人弄死。"}, {"text": "这个病毒杀害了我的电脑。", "explanation": "这里应该用〈破坏〉。破坏可用于电脑，杀害只用于把人弄死。"}, {"text": "这部电影杀害了很多观众。", "explanation": "这里应该用〈感动〉。感动指使人情绪触动，杀害是把人弄死。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "凶手杀害死了一名女护士。", "corrected_sentence": "凶手杀害了一名女护士。", "error_description": "错误：“杀害死”，“杀害”已含“死”的意思，又加补语“死”，重复。正确是“杀害了一名女护士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这名护士被了凶手杀害了。", "corrected_sentence": "这名护士被凶手杀害了。", "error_description": "错误：“被”与施事“凶手”之间多出“了”，被字句应为“被＋施事＋杀害”。正确形式是“这名护士被凶手杀害了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93006, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "美", "is_correct": true, "explanation": "“美”与“丑”相对，是反义词，本义项词典明确列出。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有污垢，与“丑”没有反义关系；它的反义词是“脏”。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“丑”不构成反义关系。"}, {"text": "快", "is_correct": false, "explanation": "“快”指速度，与“丑”没有反义关系。"}], "correct_answer": "美", "explanations": {"美": "“美”与“丑”相对，是反义词，本义项词典明确列出。", "干净": "“干净”指没有污垢，与“丑”没有反义关系；它的反义词是“脏”。", "安静": "“安静”形容声音或环境，与“丑”不构成反义关系。", "快": "“快”指速度，与“丑”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93006, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "美", "is_correct": true, "explanation": "“美”与“丑”相对，是反义词。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”指重量，与“丑”没有反义关系。"}, {"text": "热", "is_correct": false, "explanation": "“热”指温度，与“丑”没有反义关系。"}, {"text": "饱", "is_correct": false, "explanation": "“饱”指吃得满足，与“丑”没有反义关系。"}], "correct_answer": "美", "explanations": {"美": "“美”与“丑”相对，是反义词。", "轻": "“轻”指重量，与“丑”没有反义关系。", "热": "“热”指温度，与“丑”没有反义关系。", "饱": "“饱”指吃得满足，与“丑”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93006, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "相貌或样子难看，与美相对。", "primary_collocate": null, "pronunciation": "chǒu", "ipa": "tʂʰou˨˩˦", "syllable_count": 1, "sentences": [{"text": "故事里的女巫长得很丑。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美的东西让人开心，丑的东西让人不舒服。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长得不丑，就是不爱笑。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸭子小时候很丑，长大后很漂亮。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不应该说别人丑。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥又黑又旧，在美丽的河边显得很丑。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人觉得美，有的人觉得丑。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论美还是丑，他都喜欢这只小狗。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画是美是丑，每个人想法不同。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个玩具的样子很丑，孩子却很喜欢。", "target_word": "丑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丑陋", "label": "复合"}, {"form": "丑八怪", "label": "复合"}], "register": "口语", "sense_fingerprint": "相貌或样子难看，与美相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丑", "is_correct": true, "explanation": "丑（chǒu，第三声）意思是相貌或样子难看，与美相对，是本题的正确答案。"}, {"text": "臭", "is_correct": false, "explanation": "chòu（第四声）与 chǒu 声调不同，意思是气味难闻。"}, {"text": "愁", "is_correct": false, "explanation": "chóu（第二声）与 chǒu 声调不同，意思是发愁。"}, {"text": "抽", "is_correct": false, "explanation": "chōu（第一声）与 chǒu 声调不同，意思是抽出、抽取。"}, {"text": "手", "is_correct": false, "explanation": "shǒu（第三声）与 chǒu 声母不同（sh 与 ch），声调相同，意思是手。"}], "explanations": {"丑": "丑（chǒu，第三声）意思是相貌或样子难看，与美相对，是本题的正确答案。", "臭": "chòu（第四声）与 chǒu 声调不同，意思是气味难闻。", "愁": "chóu（第二声）与 chǒu 声调不同，意思是发愁。", "抽": "chōu（第一声）与 chǒu 声调不同，意思是抽出、抽取。", "手": "shǒu（第三声）与 chǒu 声母不同（sh 与 ch），声调相同，意思是手。"}, "sentence_index": null, "correct_answer": "丑"}, "level_3": {"options": [{"text": "丑", "is_correct": true, "explanation": "正确：“丑”说女巫的相貌难看，与“长得很”及故事语境相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说的是头脑，“长得”只说外貌，与句意不符。"}, {"text": "勤劳", "is_correct": false, "explanation": "语义：“勤劳”说的是做事的态度，不能用来描述长相。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“长得”后面只接外貌类形容词，“幽默”说的是性格。"}], "explanations": {"丑": "正确：“丑”说女巫的相貌难看，与“长得很”及故事语境相符。", "聪明": "语义：“聪明”说的是头脑，“长得”只说外貌，与句意不符。", "勤劳": "语义：“勤劳”说的是做事的态度，不能用来描述长相。", "幽默": "搭配：“长得”后面只接外貌类形容词，“幽默”说的是性格。"}, "sentence_index": 0, "correct_answer": "丑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生气时，声音很丑。", "explanation": "这里应该用〈难听〉。丑指相貌或样子难看，形容声音时要用难听。"}, {"text": "这道菜的味道很丑，我没吃几口。", "explanation": "这里应该用〈难吃〉。丑指样子不好看，形容味道时要用难吃。"}, {"text": "这间屋子的气味很丑，我开了窗户。", "explanation": "这里应该用〈难闻〉。丑指样子不好看，形容气味时要用难闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93006, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "丑", "is_correct": true, "explanation": "丑（chǒu，第三声）意思是相貌或样子难看，是本题的正确答案。"}, {"text": "吵", "is_correct": false, "explanation": "chǎo（第三声）与 chǒu 韵母不同（ao 与 ou），声调相同，意思是吵闹。"}, {"text": "臭", "is_correct": false, "explanation": "chòu（第四声）与 chǒu 声调不同，意思是气味难闻。"}, {"text": "绸", "is_correct": false, "explanation": "chóu（第二声）与 chǒu 声调不同，意思是丝绸。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 chǒu 声母不同（zh 与 ch），声调相同，意思是手臂的关节。"}], "explanations": {"丑": "丑（chǒu，第三声）意思是相貌或样子难看，是本题的正确答案。", "吵": "chǎo（第三声）与 chǒu 韵母不同（ao 与 ou），声调相同，意思是吵闹。", "臭": "chòu（第四声）与 chǒu 声调不同，意思是气味难闻。", "绸": "chóu（第二声）与 chǒu 声调不同，意思是丝绸。", "肘": "zhǒu（第三声）与 chǒu 声母不同（zh 与 ch），声调相同，意思是手臂的关节。"}, "sentence_index": null, "correct_answer": "丑"}, "level_3": {"options": [{"text": "丑", "is_correct": true, "explanation": "正确：“丑”指觉得样子难看，与前面“觉得美”形成对比，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说的是味觉，不是审美判断。"}, {"text": "响", "is_correct": false, "explanation": "搭配：“响”说的是声音，不与“觉得”后面的审美判断搭配。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说的是高度，不能用来表示审美判断。"}], "explanations": {"丑": "正确：“丑”指觉得样子难看，与前面“觉得美”形成对比，符合句意。", "甜": "语义：“甜”说的是味觉，不是审美判断。", "响": "搭配：“响”说的是声音，不与“觉得”后面的审美判断搭配。", "高": "语义：“高”说的是高度，不能用来表示审美判断。"}, "sentence_index": 6, "correct_answer": "丑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的天气很丑，我们只好待在酒店。", "explanation": "这里应该用〈糟糕〉。丑只用来说人或物的样子难看，不用来形容天气的好坏。"}, {"text": "这台电脑的价格很丑，我买不起。", "explanation": "这里应该用〈贵〉。丑指样子难看，说价格高要用贵。"}, {"text": "他这个月的收入很丑，房租都快付不起了。", "explanation": "这里应该用〈少〉。丑指样子难看，说收入数额不多要用少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个老头长很丑，但是心地很善良。", "corrected_sentence": "那个老头长得很丑，但是心地很善良。", "error_description": "“长得”是“长”后面接程度补语的固定格式。错误形式是“长很丑”，漏掉了“得”，正确形式是“长得很丑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件毛衣丑太了，但我妈妈很喜欢。", "corrected_sentence": "这件毛衣太丑了，但我妈妈很喜欢。", "error_description": "“太”是程度副词，要放在形容词“丑”前面。错误形式是“丑太了”，正确形式是“太丑了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
