INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93009, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没想到是事情和你以前想的不一样。", "primary_collocate": null, "pronunciation": "méi xiǎng dào", "ipa": "mei˧˥ ɕjɑŋ˨˩ tɑu˥˩", "syllable_count": 3, "sentences": [{"text": "我以为这道菜很辣，没想到一点也不辣。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他是老师，没想到他是医生。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店看起来很小，没想到里面很大。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以前以为学中文很难，没想到很有意思。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看上去很年轻，没想到已经五十岁了。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们以为天会下雨，没想到今天是大晴天。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前我觉得北京很冷，没想到夏天这么热。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他不喜欢运动，没想到他每天跑步。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家说他很懒，没想到他工作非常努力。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他会生气，没想到他笑着说没关系。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有想到", "label": "完整形式"}], "register": "口语", "sense_fingerprint": "没想到：事实与先前的想法不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93009, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没想到", "is_correct": true, "explanation": "没想到：事情和想法不同，与“以为这道菜很辣”的预期相呼应，后半句“一点也不辣”即是结果。"}, {"text": "纠正", "is_correct": false, "explanation": "语义：“纠正”的对象是错误或说法，不能接“一点也不辣”这样的结果，句子不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的宾语是要求或邀请，不能与“一点也不辣”搭配。"}, {"text": "拆除", "is_correct": false, "explanation": "配价：“拆除”的对象是建筑或设施，不能接“一点也不辣”这样的小句，句子不通。"}], "explanations": {"没想到": "没想到：事情和想法不同，与“以为这道菜很辣”的预期相呼应，后半句“一点也不辣”即是结果。", "纠正": "语义：“纠正”的对象是错误或说法，不能接“一点也不辣”这样的结果，句子不通。", "拒绝": "搭配：“拒绝”的宾语是要求或邀请，不能与“一点也不辣”搭配。", "拆除": "配价：“拆除”的对象是建筑或设施，不能接“一点也不辣”这样的小句，句子不通。"}, "sentence_index": 0, "correct_answer": "没想到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一加一没想到等于二。", "explanation": "语义：“一加一等于二”是人人皆知的常识，没有出乎意料之处，“没想到”的意外义不能用于常识。"}, {"text": "这件事我早就料到了，没想到。", "explanation": "这里误把“没想到”当成了〈预料之中〉的意思。“早就料到了”说明事先已预料，与“没想到”的意外义矛盾。"}, {"text": "我每天都没想到上班。", "explanation": "语义：“每天都”说明这是习惯，没有出乎意料之处，不能用“没想到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没想到", "is_correct": true, "explanation": "没想到：事情和想法不同，与“以前觉得北京很冷”相呼应，后半句说夏天很热。"}, {"text": "同意", "is_correct": false, "explanation": "搭配：“同意”后面接的是人或意见，不能接“夏天这么热”这样的事实。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指去看地方或展览，不能用来指“夏天这么热”。"}, {"text": "戒掉", "is_correct": false, "explanation": "语义：“戒掉”指改掉习惯，与“夏天这么热”这样的天气描述不相干，句子不通。"}], "explanations": {"没想到": "没想到：事情和想法不同，与“以前觉得北京很冷”相呼应，后半句说夏天很热。", "同意": "搭配：“同意”后面接的是人或意见，不能接“夏天这么热”这样的事实。", "参观": "语义：“参观”指去看地方或展览，不能用来指“夏天这么热”。", "戒掉": "语义：“戒掉”指改掉习惯，与“夏天这么热”这样的天气描述不相干，句子不通。"}, "sentence_index": 6, "correct_answer": "没想到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一直觉得他很聪明，没想到他很聪明。", "explanation": "这里误把“没想到”当成了〈强调〉的意思（加强语气）。“没想到”表示事实与想法不同，前后两个判断相同，没有出乎意料之处。"}, {"text": "这是我早就知道的事，没想到。", "explanation": "语义：“早就知道”说明事先已知，没有出乎意料之处，“没想到”的意外义不能用于此。"}, {"text": "这事我早就计划好了，没想到。", "explanation": "语义：“早就计划好了”说明事先已安排，没有出乎意料之处，与“没想到”的意外义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以为他会迟到，没想到的他提前到了。", "corrected_sentence": "我以为他会迟到，没想到他提前到了。", "error_description": "“的”多出：“没想到”后面不能加“的”，应直接接小句，说“没想到他提前到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以为他会晚到，没想到了他早就到了。", "corrected_sentence": "我以为他会晚到，没想到他早就到了。", "error_description": "“了”错误：“了”加在“没想到”后面，破坏了这个表示意外的固定说法，应去掉“了”，说“没想到他早就到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
