INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93010, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情出乎意料。", "primary_collocate": null, "pronunciation": "méi xiǎng dào", "ipa": "mei˧˥ ɕjɑŋ˨˩ tɑu˥˩", "syllable_count": 3, "sentences": [{"text": "没想到会在这里遇到你！", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真没想到，你已经会做饭了。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没想到今天的考试这么容易。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我真没想到他会来参加我的生日会。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没想到你也喜欢这个歌手！", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没想到他一个人走了二十公里。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没想到雨下得这么大，我们只好回家。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都没想到，他会得第一名。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没想到这么小的孩子也会说三种语言。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没想到他把我的名字记住了。", "target_word": "没想到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有想到", "label": "完整形式"}], "register": "口语", "sense_fingerprint": "没想到：表达意外、吃惊的语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没想到", "is_correct": true, "explanation": "没想到：表示事情出乎意料，与“在这里遇到你”的惊讶语气相合。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”的宾语是希望或机会，不能接“在这里遇到你”这样的事件。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指去看地方或展览，“参观会在这里遇到你”语义不通。"}, {"text": "催促", "is_correct": false, "explanation": "语义：“催促”是叫别人快做某事，与“遇到你”的意外语气不合。"}], "explanations": {"没想到": "没想到：表示事情出乎意料，与“在这里遇到你”的惊讶语气相合。", "放弃": "搭配：“放弃”的宾语是希望或机会，不能接“在这里遇到你”这样的事件。", "参观": "语义：“参观”指去看地方或展览，“参观会在这里遇到你”语义不通。", "催促": "语义：“催促”是叫别人快做某事，与“遇到你”的意外语气不合。"}, "sentence_index": 0, "correct_answer": "没想到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早就猜到他会来，真没想到他来了。", "explanation": "语义：说话人“早就猜到”他会来，说明事情在预料之中，与“没想到”的意外义矛盾。"}, {"text": "真没想到，太阳每天从东边升起。", "explanation": "语义：“太阳每天从东边升起”是常识，没有出乎意料之处，不能用“没想到”。"}, {"text": "这件事我一直都在预料之中，真没想到。", "explanation": "语义：“一直都在预料之中”说明事先已预料，与“真没想到”的意外义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没想到", "is_correct": true, "explanation": "没想到：表示事情出乎意料，与“雨下得这么大”的意外语气相合，后半句说明只好回家。"}, {"text": "佩服", "is_correct": false, "explanation": "搭配：“佩服”的对象是人或本领，不能直接接“雨下得这么大”。"}, {"text": "研究", "is_correct": false, "explanation": "语义：“研究”是对问题或对象进行探讨，“研究雨下得这么大”语义不通。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”的对象是商品，“购买雨下得这么大”语义不通。"}], "explanations": {"没想到": "没想到：表示事情出乎意料，与“雨下得这么大”的意外语气相合，后半句说明只好回家。", "佩服": "搭配：“佩服”的对象是人或本领，不能直接接“雨下得这么大”。", "研究": "语义：“研究”是对问题或对象进行探讨，“研究雨下得这么大”语义不通。", "购买": "语义：“购买”的对象是商品，“购买雨下得这么大”语义不通。"}, "sentence_index": 6, "correct_answer": "没想到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我每天都会做的事，真没想到。", "explanation": "语义：这是每天都会做的事，早已习惯，不会出乎意料，不能用“没想到”。"}, {"text": "这是早就约好的事，真没想到。", "explanation": "语义：“早就约好”说明事先已有安排，没有出乎意料之处，不能用“没想到”。"}, {"text": "二加二等于四，真没想到。", "explanation": "语义：二加二等于四是常识，没有出乎意料之处，不能用“没想到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "真没想到了这么快就做完了！", "corrected_sentence": "真没想到这么快就做完了！", "error_description": "“了”多出：“没想到”是固定说法，后面不能加“了”，应说“真没想到这么快就做完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
