INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93011, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "中等是不太好，也不太差，在中间。", "primary_collocate": null, "pronunciation": "zhōng děng", "ipa": "ʈʂʊŋ˥ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的个子中等，不高也不矮。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜味道中等，不好也不坏。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的唱歌水平中等，不太好也不太差。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的质量中等，不算好也不算差。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她中等身材，穿什么都合适。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试我考得中等，没进前十。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李跑步的速度中等，不快也不慢。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的大小中等，住两个人正好。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗面的价钱中等，不贵也不便宜。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画技中等，不高也不低。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中等身材", "label": "复合"}, {"form": "中等个子", "label": "复合"}], "register": "中性", "sense_fingerprint": "不太好也不太差，大小、高低、好坏都在中间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8173b1b7-e271-40b8-a04e-530729132fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93011, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中等", "is_correct": true, "explanation": "正确。“中等”表示个子不高不矮，与后半句“不高也不矮”相呼应。"}, {"text": "高", "is_correct": false, "explanation": "语义：后半句是“不高也不矮”，填“高”则前后矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”说容貌或事物的美，不用来说个子。"}, {"text": "紧张", "is_correct": false, "explanation": "搭配：“紧张”说心理状态，不能用来形容个子。"}], "explanations": {"中等": "正确。“中等”表示个子不高不矮，与后半句“不高也不矮”相呼应。", "高": "语义：后半句是“不高也不矮”，填“高”则前后矛盾。", "漂亮": "搭配：“漂亮”说容貌或事物的美，不用来说个子。", "紧张": "搭配：“紧张”说心理状态，不能用来形容个子。"}, "sentence_index": 0, "correct_answer": "中等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的味道中等得让人赞不绝口。", "explanation": "这里应该用〈好〉。“中等”表示不好不坏、居中，不能用来形容味道好到让人赞不绝口，与“赞不绝口”相矛盾。"}, {"text": "妈妈看到孩子受伤，心里非常中等。", "explanation": "这里应该用〈悲伤〉。“中等”说程度，不用来形容心情。"}, {"text": "这次旅行的体验中等，我们玩得尽兴极了。", "explanation": "这里应该用〈精彩〉。“中等”表示居中，与“玩得尽兴极了”的程度相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中等", "is_correct": true, "explanation": "正确。“中等”表示速度不快不慢，与后半句“不快也不慢”相呼应。"}, {"text": "快", "is_correct": false, "explanation": "语义：后半句是“不快也不慢”，填“快”则前后矛盾。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”说环境或声音，不用来说跑步的速度。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“清晰”说声音或画面，不用来形容速度。"}], "explanations": {"中等": "正确。“中等”表示速度不快不慢，与后半句“不快也不慢”相呼应。", "快": "语义：后半句是“不快也不慢”，填“快”则前后矛盾。", "安静": "搭配：“安静”说环境或声音，不用来说跑步的速度。", "清晰": "搭配：“清晰”说声音或画面，不用来形容速度。"}, "sentence_index": 6, "correct_answer": "中等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的画技中等，简直无可挑剔。", "explanation": "这里应该用〈完美〉。“中等”表示不好不坏、居中，与“无可挑剔”相矛盾。"}, {"text": "这家饭馆的菜味道中等，是全城最好吃的。", "explanation": "这里应该用〈好〉。“中等”表示居中，与“全城最好吃”相矛盾。"}, {"text": "这家店的服务中等，是全市最好的一家。", "explanation": "这里应该用〈好〉。“中等”表示居中，与“全市最好”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这碗饭的分量中等过，正好吃饱。", "corrected_sentence": "这碗饭的分量中等，正好吃饱。", "error_description": "“中等”是表示状态的形容词，后面不能加“过”（“过”表示经历过某种动作）。应为“分量中等，正好吃饱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盘菜的味道算中等地，还可以吃。", "corrected_sentence": "这盘菜的味道算中等，还可以吃。", "error_description": "“中等”作谓语时不加“地”；“地”用在状语后修饰动词。应为“算中等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
