INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "等级、程度处于中间的。", "primary_collocate": null, "pronunciation": "zhōng děng", "ipa": "ʈʂʊŋ˥ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次考试，他的成绩是中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的发展水平属于中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国是中等收入国家。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的价格是中等水平。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的学校质量处于中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平只有中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批苹果的质量是中等的。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队这学期的排名属于中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的收入在全市算中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布的等级是中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中等教育", "label": "复合"}, {"form": "中等收入", "label": "复合"}], "register": "中性", "sense_fingerprint": "水平、等级、质量等在上等和下等之间，处于中间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8173b1b7-e271-40b8-a04e-530729132fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中等", "is_correct": true, "explanation": "正确。“中等”表示成绩处于中间的等级，与“成绩”搭配。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的头脑，不能说成绩聪明。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容身材或外形，与成绩的等级无关。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指没有污垢、整洁，与成绩的好坏无关。"}], "explanations": {"中等": "正确。“中等”表示成绩处于中间的等级，与“成绩”搭配。", "聪明": "搭配：“聪明”形容人的头脑，不能说成绩聪明。", "高大": "语义：“高大”形容身材或外形，与成绩的等级无关。", "干净": "语义：“干净”指没有污垢、整洁，与成绩的好坏无关。"}, "sentence_index": 0, "correct_answer": "中等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐在教室的中等位置，离黑板不远也不近。", "explanation": "这里应该用〈中间〉。“中等”说等级、程度，不能用来指座位在教室里的位置。"}, {"text": "这次比赛的成绩中等，我们以全场最高分夺冠。", "explanation": "这里应该用〈优秀〉。“中等”表示居中，与“全场最高分”相矛盾。"}, {"text": "这家饭馆的菜价中等，却是全城最贵的。", "explanation": "这里应该用〈高〉。“中等”表示居中，与“全城最贵”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中等", "is_correct": true, "explanation": "正确。“中等”说质量的等级，与“这批苹果的质量”搭配。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”说温度或态度，不能用来说苹果的质量等级。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄，苹果没有年龄，不能说质量年轻。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能用来形容苹果的质量。"}], "explanations": {"中等": "正确。“中等”说质量的等级，与“这批苹果的质量”搭配。", "冰冷": "语义：“冰冷”说温度或态度，不能用来说苹果的质量等级。", "年轻": "语义：“年轻”说年龄，苹果没有年龄，不能说质量年轻。", "热情": "搭配：“热情”形容人的态度，不能用来形容苹果的质量。"}, "sentence_index": 6, "correct_answer": "中等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的水平中等，却被评为全校第一。", "explanation": "这里应该用〈优秀〉。“中等”表示居中，与“全校第一”相矛盾。"}, {"text": "这份工作的待遇中等，却是公司里最高的一档。", "explanation": "这里应该用〈高〉。“中等”表示居中，与“最高的一档”相矛盾。"}, {"text": "听到这个消息，她心里很中等。", "explanation": "这里应该用〈悲伤〉。“中等”用于等级、程度，不能用来形容人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服的质量是中等得。", "corrected_sentence": "这件衣服的质量是中等的。", "error_description": "“的”误写为“得”。“中等”作表语，其后的结构助词应为“的”，应说“是中等的”；“得”接在动词或形容词后补充程度或结果，不能接在“中等”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的规模属于中等地。", "corrected_sentence": "这家公司的规模属于中等。", "error_description": "“中等”作谓语（属于…）时不加“地”；“地”用在状语后修饰动词。应为“属于中等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93013, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "正确：「死」与「活着」是反义词，指没有生命。"}, {"text": "睡觉", "is_correct": false, "explanation": "与「活着」没有反义关系，「睡觉」指躺下休息。"}, {"text": "旅行", "is_correct": false, "explanation": "与「活着」没有反义关系，「旅行」指到外地游览。"}, {"text": "唱歌", "is_correct": false, "explanation": "与「活着」没有反义关系，「唱歌」指发出歌声。"}], "correct_answer": "死", "explanations": {"死": "正确：「死」与「活着」是反义词，指没有生命。", "睡觉": "与「活着」没有反义关系，「睡觉」指躺下休息。", "旅行": "与「活着」没有反义关系，「旅行」指到外地游览。", "唱歌": "与「活着」没有反义关系，「唱歌」指发出歌声。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93013, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "正确：「死」与「活着」是反义词，指没有生命。"}, {"text": "吃饭", "is_correct": false, "explanation": "与「活着」没有反义关系，「吃饭」指进食。"}, {"text": "跑步", "is_correct": false, "explanation": "与「活着」没有反义关系，「跑步」指快速地跑。"}, {"text": "写字", "is_correct": false, "explanation": "与「活着」没有反义关系，「写字」指用笔写出文字。"}], "correct_answer": "死", "explanations": {"死": "正确：「死」与「活着」是反义词，指没有生命。", "吃饭": "与「活着」没有反义关系，「吃饭」指进食。", "跑步": "与「活着」没有反义关系，「跑步」指快速地跑。", "写字": "与「活着」没有反义关系，「写字」指用笔写出文字。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93013, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "活着是还有生命，没有死。", "primary_collocate": null, "pronunciation": "huó zhe", "ipa": "xuo˧˥ tʂə", "syllable_count": 2, "sentences": [{"text": "他还活着，大家都很高兴。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，那个人还活着。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，他们找到了三个活着的人。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷活着的时候，常常带我去公园。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要活着，就有希望。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条鱼还活着，你快放回水里。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他还活着，我马上去看他。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他活着回到了家。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人知道他是死了还是活着。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树已经死了，那棵还活着。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "活着：动词，还有生命，没有死", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活着", "is_correct": true, "explanation": "正确：「活着」指还有生命，与「还」和「大家都很高兴」相符。"}, {"text": "去世", "is_correct": false, "explanation": "语义：「去世」指死亡，与「还」表示仍在世的意思相矛盾，也与大家都很高兴不合。"}, {"text": "死去", "is_correct": false, "explanation": "语义：「死去」表示已经死亡，与「还」连用时句意自相矛盾。"}, {"text": "长眠", "is_correct": false, "explanation": "语义：「长眠」是死去的委婉说法，与「还」表示仍在世相矛盾。"}], "explanations": {"活着": "正确：「活着」指还有生命，与「还」和「大家都很高兴」相符。", "去世": "语义：「去世」指死亡，与「还」表示仍在世的意思相矛盾，也与大家都很高兴不合。", "死去": "语义：「死去」表示已经死亡，与「还」连用时句意自相矛盾。", "长眠": "语义：「长眠」是死去的委婉说法，与「还」表示仍在世相矛盾。"}, "sentence_index": 0, "correct_answer": "活着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题一直活着，没有解决。", "explanation": "这里应该用〈存在〉。「活着」只用于有生命的人或动物，问题不能说活着。"}, {"text": "他每天在公园活着，身体很好。", "explanation": "这里应该用〈活动〉。「活着」说明还有生命，不指做运动。"}, {"text": "他的身体活着呢，每天都去跑步。", "explanation": "这里应该用〈好〉。「身体好着呢」说身体状况好；「活着」只说还有生命，不能用来说身体的状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活着", "is_correct": true, "explanation": "正确：「活着」指还有生命，与「还」及「我马上去看他」相符。"}, {"text": "病逝", "is_correct": false, "explanation": "语域：「病逝」是讣告式的书面说法，口语里不说「听说他还病逝」，且表示死亡，与「还」矛盾。"}, {"text": "咽气", "is_correct": false, "explanation": "语义：「咽气」指断气，表示已经死去，与「还」所表示的仍在世相矛盾。"}, {"text": "归天", "is_correct": false, "explanation": "语域：「归天」是口语委婉说法，指已经去世，与「还」和「我马上去看他」的语境不合。"}], "explanations": {"活着": "正确：「活着」指还有生命，与「还」及「我马上去看他」相符。", "病逝": "语域：「病逝」是讣告式的书面说法，口语里不说「听说他还病逝」，且表示死亡，与「还」矛盾。", "咽气": "语义：「咽气」指断气，表示已经死去，与「还」所表示的仍在世相矛盾。", "归天": "语域：「归天」是口语委婉说法，指已经去世，与「还」和「我马上去看他」的语境不合。"}, "sentence_index": 6, "correct_answer": "活着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他年轻时在国外工作，活着以后大家都很难过。", "explanation": "这里应该用〈过世〉。「活着」表示还活着，不能用于死后的「以后」。"}, {"text": "他每天活着一本书，读得很快。", "explanation": "这里应该用〈读〉。「活着」是不及物动词，不能带宾语。"}, {"text": "他把钥匙活着了，找了很久。", "explanation": "这里应该用〈弄丢〉。「活着」只表示有生命，不能用于钥匙，也不能放在「把」字句里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小鸟掉进河里以后，居然很活着。", "corrected_sentence": "这只小鸟掉进河里以后，居然还活着。", "error_description": "错误：「很」是程度副词，不能修饰动词「活着」，应删去「很」，说「居然还活着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地震以后，他们在废墟下找到了一个活着孩子。", "corrected_sentence": "地震以后，他们在废墟下找到了一个活着的孩子。", "error_description": "错误：「活着」修饰名词时漏掉了「的」。动词短语作定语要加「的」，应说「活着的孩子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
