INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93014, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "正确：「死」与「活着」是反义词，指没有生命。"}, {"text": "吃饭", "is_correct": false, "explanation": "与「活着」没有反义关系，「吃饭」指进食。"}, {"text": "读书", "is_correct": false, "explanation": "与「活着」没有反义关系，「读书」指阅读学习。"}, {"text": "洗澡", "is_correct": false, "explanation": "与「活着」没有反义关系，「洗澡」指清洗身体。"}], "correct_answer": "死", "explanations": {"死": "正确：「死」与「活着」是反义词，指没有生命。", "吃饭": "与「活着」没有反义关系，「吃饭」指进食。", "读书": "与「活着」没有反义关系，「读书」指阅读学习。", "洗澡": "与「活着」没有反义关系，「洗澡」指清洗身体。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93014, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有生命，生存着。", "primary_collocate": null, "pronunciation": "huó zhe", "ipa": "xuo˧˥ tʂə", "syllable_count": 2, "sentences": [{"text": "他活着只是为了家人。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们活着，就要好好过每一天。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人为了钱活着。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人活着，过得很不容易。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在沙漠里活着很难。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为孩子活着，什么苦都不怕。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多年，他靠捡垃圾活着。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在山里活着，没有电也没有水。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活着不容易，你要好好照顾自己。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想只是活着，他还想做自己喜欢的事。", "target_word": "活着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "活着：动词，生存、过日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活着", "is_correct": true, "explanation": "正确：「活着」表示生存、过日子，与「只是为了家人」的目的相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：「生病」不能表示为了家人的目的，「他生病只是为了家人」句意不通。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：「发呆」不能表示为了家人的目的，「他发呆只是为了家人」句意不通。"}, {"text": "做梦", "is_correct": false, "explanation": "语义：「做梦」不能表达「为了家人」的目的，句子意思不通。"}], "explanations": {"活着": "正确：「活着」表示生存、过日子，与「只是为了家人」的目的相符。", "生病": "语义：「生病」不能表示为了家人的目的，「他生病只是为了家人」句意不通。", "发呆": "语义：「发呆」不能表示为了家人的目的，「他发呆只是为了家人」句意不通。", "做梦": "语义：「做梦」不能表达「为了家人」的目的，句子意思不通。"}, "sentence_index": 0, "correct_answer": "活着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在操场上活着，玩得很开心。", "explanation": "这里应该用〈玩〉。「活着」只表示生存，不表示玩耍、活动。"}, {"text": "我每天早上活着一碗粥。", "explanation": "这里应该用〈喝〉。「活着」是不及物动词，不能带宾语。"}, {"text": "他的心情活着呢，一直在唱歌。", "explanation": "这里应该用〈好〉。「心情好着呢」说情绪好；「活着」只表示还有生命，不能用来说心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活着", "is_correct": true, "explanation": "正确：「活着」表示靠某种方式生存，与「靠捡垃圾」相符。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：「靠捡垃圾」后面要接谋生的方式，「结婚」不能与之搭配。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：「靠捡垃圾跳舞」句意不通，跳舞不是谋生的方式。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：「靠捡垃圾洗澡」句意不通，洗澡不是谋生的方式。"}], "explanations": {"活着": "正确：「活着」表示靠某种方式生存，与「靠捡垃圾」相符。", "结婚": "搭配：「靠捡垃圾」后面要接谋生的方式，「结婚」不能与之搭配。", "跳舞": "语义：「靠捡垃圾跳舞」句意不通，跳舞不是谋生的方式。", "洗澡": "语义：「靠捡垃圾洗澡」句意不通，洗澡不是谋生的方式。"}, "sentence_index": 6, "correct_answer": "活着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上活着一个电话。", "explanation": "这里应该用〈打〉。「活着」是不及物动词，不能带宾语。"}, {"text": "他活着以后，家人很伤心。", "explanation": "这里应该用〈离世〉。「活着」不能用于死亡之后的「以后」。"}, {"text": "他每天早上去河边活着，跑步锻炼。", "explanation": "这里应该用〈锻炼〉。「活着」只表示生存，不表示做运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他靠卖菜很活着，日子很苦。", "corrected_sentence": "他靠卖菜活着，日子很苦。", "error_description": "错误：「很」是程度副词，不能修饰动词「活着」，应删去「很」，说「靠卖菜活着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，她靠做手工很活着。", "corrected_sentence": "这些年，她靠做手工活着。", "error_description": "错误：「很」是程度副词，不能修饰动词「活着」，应删去「很」，说「靠做手工活着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
