INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用仪器或工具量出物体的大小、长短等。", "primary_collocate": null, "pronunciation": "cè liáng", "ipa": "tsʰɤ˥˩ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "工程师用仪器测量这座山有多高。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用激光仪器测量两座楼之间的距离。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用专门的工具测量了这块石头的大小。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用仪器测量这条路有多长。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用显微镜测量细胞的大小。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用游标卡尺测量小球有多大。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术员正在用仪器测量这根钢管的长度。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师用工具测量过这条河有多宽。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员把仪器放在桥上，测量桥的长度。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以精确测量零件的大小。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "测量了", "label": "体标（了）"}, {"form": "测量过", "label": "体标（过）"}, {"form": "测量员", "label": "复合词"}, {"form": "测量仪", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用仪器工具量出物体大小长短", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3db2a8-898c-4672-8b0b-0fbffde2e471') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "测量", "is_correct": true, "explanation": "正确：“测量”指用仪器量出高度，与“用仪器”和“有多高”相符。"}, {"text": "称重", "is_correct": false, "explanation": "搭配：“称重”只用于称轻重，不能称山“有多高”。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”指构思规划，与用仪器量高度无关。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造房屋或道路，山不能被修建，也不是量高度。"}], "explanations": {"测量": "正确：“测量”指用仪器量出高度，与“用仪器”和“有多高”相符。", "称重": "搭配：“称重”只用于称轻重，不能称山“有多高”。", "设计": "语义：“设计”指构思规划，与用仪器量高度无关。", "修建": "语义：“修建”指建造房屋或道路，山不能被修建，也不是量高度。"}, "sentence_index": 0, "correct_answer": "测量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工作人员测量了全市的人口数量。", "explanation": "这里应该用〈统计〉。测量指用工具量取长短大小，人口数量要用统计。"}, {"text": "财务人员测量了这笔工程的成本。", "explanation": "这里应该用〈核算〉。测量用于可以量出的长短、大小，工程成本要用核算。"}, {"text": "气象员测量了去年下雨的天数。", "explanation": "这里应该用〈记录〉。测量用于量取长短、大小等，下雨的天数要用记录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "测量", "is_correct": true, "explanation": "正确：“测量”指用仪器量出长度，与“用仪器”和“这根钢管的长度”相符。"}, {"text": "焊接", "is_correct": false, "explanation": "语义：“焊接”是把金属连接起来，与量长度无关。"}, {"text": "弯曲", "is_correct": false, "explanation": "语义：“弯曲”是改变形状，不是测量长度。"}, {"text": "称", "is_correct": false, "explanation": "搭配：“称”只用于称重量，不能称“长度”。"}], "explanations": {"测量": "正确：“测量”指用仪器量出长度，与“用仪器”和“这根钢管的长度”相符。", "焊接": "语义：“焊接”是把金属连接起来，与量长度无关。", "弯曲": "语义：“弯曲”是改变形状，不是测量长度。", "称": "搭配：“称”只用于称重量，不能称“长度”。"}, "sentence_index": 6, "correct_answer": "测量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计测量了今年的利润。", "explanation": "这里应该用〈计算〉。测量指用工具量出长短、大小等，利润要用计算。"}, {"text": "专家测量了这座古城的历史价值。", "explanation": "这里应该用〈评估〉。测量用于可以量出的实物，历史价值要用评估。"}, {"text": "我们测量了这套房子的价格。", "explanation": "这里应该用〈估计〉。测量得出的是确定的数据，价格的推断要用估计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位工程师用仪器测量了过这条河的宽度。", "corrected_sentence": "这位工程师用仪器测量过这条河的宽度。", "error_description": "错误在“测量”后的体标。“测量过”已用“过”表示经历，不能再加“了”，应说“测量过”，不能说“测量了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员用激光测量了出这块玻璃的厚度。", "corrected_sentence": "研究人员用激光测量出了这块玻璃的厚度。", "error_description": "补语“出”应紧跟在“测量”后面，说“测量出了”，不能说“测量了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
