INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "集中进行有价证券或大宗商品买卖的场所。", "primary_collocate": null, "pronunciation": "jiāo yì suǒ", "ipa": "tɕiɑʊ˥ i˥˩ suɔ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这家公司的股票在上海证券交易所上市。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在交易所工作，每天都看股票价格。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交易所九点半开市，投资者开始买股票。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家交易所主要买卖石油和黄金。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的股票今天在交易所挂牌了。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交易所规定，股票每天最多涨百分之十。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他通过交易所买了一些公司的股票。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交易所下午三点收市，价格不再变化。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上很多大城市都有证券交易所。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，交易所今天的成交量很大。", "target_word": "交易所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "证券交易所", "label": "复合"}], "register": "正式", "sense_fingerprint": "集中买卖股票、债券或大宗商品的正规市场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交易所", "is_correct": true, "explanation": "正确：指集中买卖股票的正规市场，“在……上市”符合句意。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是股票买卖的场所，“上市”说不通。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是买卖蔬菜等日常食品的地方，股票不能在菜市场上市。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是股票上市的地方，与句中的“股票”不相关。"}], "explanations": {"交易所": "正确：指集中买卖股票的正规市场，“在……上市”符合句意。", "医院": "语义：医院不是股票买卖的场所，“上市”说不通。", "菜市场": "语义：菜市场是买卖蔬菜等日常食品的地方，股票不能在菜市场上市。", "学校": "语义：学校不是股票上市的地方，与句中的“股票”不相关。"}, "sentence_index": 0, "correct_answer": "交易所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每次都去交易所存钱。", "explanation": "这里应该用〈银行〉。存钱要去银行，交易所是买卖股票或商品的正规市场。"}, {"text": "我家门口新开了一根交易所。", "explanation": "这里应该用〈家〉。“根”用于细长的棍状物，交易所是机构，应用量词“家”。"}, {"text": "他每周六都在证券交易所打篮球。", "explanation": "这里应该用〈体育馆〉。打篮球要去体育馆，证券交易所是集中买卖证券或大宗商品的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交易所", "is_correct": true, "explanation": "正确：指买卖股票的正规市场，“通过交易所买股票”符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是买卖股票的场所，与“公司的股票”不相关。"}, {"text": "理发店", "is_correct": false, "explanation": "搭配：理发店不卖股票，“通过理发店买股票”搭配不当。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园是参观动物的地方，不能用来买股票。"}], "explanations": {"交易所": "正确：指买卖股票的正规市场，“通过交易所买股票”符合句意。", "厨房": "语义：厨房不是买卖股票的场所，与“公司的股票”不相关。", "理发店": "搭配：理发店不卖股票，“通过理发店买股票”搭配不当。", "动物园": "语义：动物园是参观动物的地方，不能用来买股票。"}, "sentence_index": 6, "correct_answer": "交易所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们中午去交易所吃饭。", "explanation": "这里应该用〈饭馆〉。吃饭要去饭馆，交易所是买卖股票或商品的正规市场。"}, {"text": "她下班后去交易所寄包裹。", "explanation": "这里应该用〈快递站〉。寄包裹要去快递站或邮局，交易所不办这类业务。"}, {"text": "我们楼下新开了一条交易所。", "explanation": "量词错误：交易所作为机构应用“家”，“条”用于细长的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一只证券交易所工作。", "corrected_sentence": "他在一家证券交易所工作。", "error_description": "量词错误：“证券交易所”应用量词“家”，写成“只”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去了一把证券交易所参观。", "corrected_sentence": "他去了一家证券交易所参观。", "error_description": "量词错误：“证券交易所”应用量词“家”，写成“把”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "正确。「平静」与「激动」构成反义，指心情没有起伏。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：「寒冷」形容温度，与「激动」的情绪没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：「坚硬」形容质地，与「激动」没有任何反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "无关：「整齐」形容排列或状态，与「激动」不构成反义。"}], "correct_answer": "平静", "explanations": {"平静": "正确。「平静」与「激动」构成反义，指心情没有起伏。", "寒冷": "无关：「寒冷」形容温度，与「激动」的情绪没有反义关系。", "坚硬": "无关：「坚硬」形容质地，与「激动」没有任何反义关系。", "整齐": "无关：「整齐」形容排列或状态，与「激动」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
