INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "激动是心里特别高兴，心跳得很快。", "primary_collocate": null, "pronunciation": "jī dòng", "ipa": "tɕi˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "听到好消息，他激动得一晚上没睡着。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天就要见到妈妈了，我心跳得很快，特别激动。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次坐飞机，孩子激动极了。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿到录取通知书，激动得哭了。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛马上开始，大家都很激动。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他激动地对我说：“我们赢了！”", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在演唱会门口，我激动得手都在发抖。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天要见偶像，从早上就很激动。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我太激动了，一个字也说不出来。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看着手里的新手机，弟弟高兴又激动。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "激动了", "label": "体标"}, {"form": "激动人心", "label": "复合"}, {"form": "激動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到特别高兴的事，心跳加快，兴奋得难以平静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2534af2a-1516-45ed-a22b-20f025827a87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激动", "is_correct": true, "explanation": "正确。「激动」表示因好消息而心情强烈起伏，兴奋得睡不着。"}, {"text": "伤心", "is_correct": false, "explanation": "语义：「伤心」表示悲痛，与「听到好消息」的语境相反。"}, {"text": "平静", "is_correct": false, "explanation": "语义：「平静」指心情没有起伏，与因好消息而失眠的情形不符。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：「安静」多形容环境或状态，不能用来描述因消息而失眠的心情。"}], "explanations": {"激动": "正确。「激动」表示因好消息而心情强烈起伏，兴奋得睡不着。", "伤心": "语义：「伤心」表示悲痛，与「听到好消息」的语境相反。", "平静": "语义：「平静」指心情没有起伏，与因好消息而失眠的情形不符。", "安静": "搭配：「安静」多形容环境或状态，不能用来描述因消息而失眠的心情。"}, "sentence_index": 0, "correct_answer": "激动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在考场上激动地答完了所有的题，心情却很平静。", "explanation": "这里应该用「冷静」。「激动」指心里兴奋、高兴，与「心情却很平静」矛盾。"}, {"text": "妈妈看着菜单，激动得一口也不吃，只是平静地坐着。", "explanation": "这里应该用「镇定」。「激动」表示心里高兴、兴奋，与「平静地坐着」矛盾。"}, {"text": "他睡了一整天觉，醒来后非常激动，一点精神也没有。", "explanation": "这里应该用「疲倦」。「激动」指兴奋、心跳加快，与「一点精神也没有」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激动", "is_correct": true, "explanation": "正确。「激动」表示兴奋得手都在发抖。"}, {"text": "镇定", "is_correct": false, "explanation": "语义：「镇定」表示沉着不慌，与「手都在发抖」矛盾。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：「轻松」表示心情放松，与「手都在发抖」不合。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：「热情」形容待人的态度，不能用来描述手发抖这样的身体状态。"}], "explanations": {"激动": "正确。「激动」表示兴奋得手都在发抖。", "镇定": "语义：「镇定」表示沉着不慌，与「手都在发抖」矛盾。", "轻松": "语义：「轻松」表示心情放松，与「手都在发抖」不合。", "热情": "搭配：「热情」形容待人的态度，不能用来描述手发抖这样的身体状态。"}, "sentence_index": 6, "correct_answer": "激动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听了一节很无聊的课，激动得打起了哈欠。", "explanation": "这里应该用「困」。「激动」指兴奋高兴，与无聊、打哈欠矛盾。"}, {"text": "他拿到奖学金后，激动地说：“我一点也不高兴。”", "explanation": "这里应该用「沮丧」。「激动」指兴奋高兴，与「一点也不高兴」矛盾。"}, {"text": "今天和平常一样，没什么特别的事，他激动得睡不着。", "explanation": "这里应该用「平静」。「激动」需要有让人特别高兴的事，与「没什么特别的事」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈见到我们，很激动得哭了。", "corrected_sentence": "妈妈见到我们，激动得哭了。", "error_description": "错误在于「激动得哭了」前加了「很」。带「得」补语的「激动」前不能再用「很」，正确说法是「激动得哭了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他激动跑出了教室。", "corrected_sentence": "他激动地跑出了教室。", "error_description": "错误在于状语「激动」后漏掉了「地」。形容词作状语后要加「地」，正确说法是「他激动地跑出了教室」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "正确。「平静」与「激动」构成反义，指情绪不起波澜。"}, {"text": "松软", "is_correct": false, "explanation": "无关：「松软」形容质地，与「激动」没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "无关：「清脆」形容声音，与「激动」不构成反义。"}, {"text": "狭小", "is_correct": false, "explanation": "无关：「狭小」形容空间，与「激动」没有反义关系。"}], "correct_answer": "平静", "explanations": {"平静": "正确。「平静」与「激动」构成反义，指情绪不起波澜。", "松软": "无关：「松软」形容质地，与「激动」没有反义关系。", "清脆": "无关：「清脆」形容声音，与「激动」不构成反义。", "狭小": "无关：「狭小」形容空间，与「激动」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "正确。「平静」与「激动」构成反义，指情绪不起波澜。"}, {"text": "粗糙", "is_correct": false, "explanation": "无关：「粗糙」形容表面质感，与「激动」没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：「明亮」形容光线，与「激动」不构成反义。"}, {"text": "狭窄", "is_correct": false, "explanation": "无关：「狭窄」形容空间，与「激动」没有反义关系。"}], "correct_answer": "平静", "explanations": {"平静": "正确。「平静」与「激动」构成反义，指情绪不起波澜。", "粗糙": "无关：「粗糙」形容表面质感，与「激动」没有反义关系。", "明亮": "无关：「明亮」形容光线，与「激动」不构成反义。", "狭窄": "无关：「狭窄」形容空间，与「激动」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "感情强烈冲动，不能平静。", "primary_collocate": null, "pronunciation": "jī dòng", "ipa": "tɕi˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你先别激动，坐下来慢慢说。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一听这话就激动起来，声音越来越大。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说病人不能太激动，要保持平静。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他情绪很激动，一边说一边拍桌子。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了那些话，她激动得脸都红了，大声争吵。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一激动就说错话。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家情绪太激动，会议只好先停下来。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他越说越激动，最后站了起来。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她激动的样子，让大家都有点害怕。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别让孩子太激动，不然他晚上睡不着。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "激动了", "label": "体标"}, {"form": "激動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "情绪强烈波动，一时无法冷静下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2534af2a-1516-45ed-a22b-20f025827a87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激动", "is_correct": true, "explanation": "正确。「别激动」指别情绪过于强烈，需要冷静下来。"}, {"text": "热情", "is_correct": false, "explanation": "语义：「热情」形容待人态度，与「先别……慢慢说」的冷静语境不合。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：「别」后不能接「安静」这类状态形容词来劝人控制情绪。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：「寒冷」形容温度，不能用来劝人控制情绪。"}], "explanations": {"激动": "正确。「别激动」指别情绪过于强烈，需要冷静下来。", "热情": "语义：「热情」形容待人态度，与「先别……慢慢说」的冷静语境不合。", "安静": "搭配：「别」后不能接「安静」这类状态形容词来劝人控制情绪。", "寒冷": "搭配：「寒冷」形容温度，不能用来劝人控制情绪。"}, "sentence_index": 0, "correct_answer": "激动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和别人吵架时很激动，说话却轻声细语、不慌不忙。", "explanation": "这里应该用「冷静」。「激动」指情绪强烈、不能平静，与「轻声细语、不慌不忙」矛盾。"}, {"text": "他听完我的话，激动得一句话都没说，情绪却非常冷静。", "explanation": "「激动」表示情绪强烈，与「情绪却非常冷静」矛盾。"}, {"text": "听到敲门声，他激动地站在门口，情绪却非常平静。", "explanation": "「激动」表示情绪强烈，与「情绪却非常平静」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激动", "is_correct": true, "explanation": "正确。「情绪太激动」指情绪强烈、难以平静，导致会议无法继续。"}, {"text": "亲切", "is_correct": false, "explanation": "搭配：「亲切」形容态度，不能用来修饰「情绪」。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：「清晰」形容思路或声音，不能用来形容情绪。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：若情绪冷静，会议就没有停下来的必要，与语境的因果关系不合。"}], "explanations": {"激动": "正确。「情绪太激动」指情绪强烈、难以平静，导致会议无法继续。", "亲切": "搭配：「亲切」形容态度，不能用来修饰「情绪」。", "清晰": "搭配：「清晰」形容思路或声音，不能用来形容情绪。", "冷静": "语义：若情绪冷静，会议就没有停下来的必要，与语境的因果关系不合。"}, "sentence_index": 6, "correct_answer": "激动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师很激动，心里却一点波澜也没有，继续慢慢地讲课。", "explanation": "「激动」指情绪强烈，与「心里却一点波澜也没有」矛盾。"}, {"text": "他很激动地坐着，显得特别镇定。", "explanation": "这里应该用「镇定」。「激动」指情绪强烈、不能平静，与「显得特别镇定」矛盾。"}, {"text": "这次没赢，大家都很激动，情绪却很平静。", "explanation": "「激动」指情绪强烈，与「情绪却很平静」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你太激动的了，先喝口水吧。", "corrected_sentence": "你太激动了，先喝口水吧。", "error_description": "错误在于形容词「激动」后多加了「的」。「激动」作谓语后直接接「了」，不能加「的」，正确说法是「你太激动了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很太激动了，连话都说不清楚。", "corrected_sentence": "他太激动了，连话都说不清楚。", "error_description": "错误在于多加了「很」。「很」与「太」不能同时修饰同一个形容词，正确说法是「他太激动了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
