INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93025, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无数是多得数也数不过来。", "primary_collocate": null, "pronunciation": "wú shù", "ipa": "u˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "夜里，天上有无数星星。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有无数的沙子。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的公园里开着无数的花。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河里有无数小鱼。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上有无数只蚂蚁。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，街上有无数人。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海里有无数我们不认识的鱼。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有无数本书。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有无数高大的树。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里有无数高楼。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無數", "label": "繁体"}, {"form": "无数次", "label": "复合词"}], "register": "中性", "sense_fingerprint": "无数：具体事物多得数不过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93025, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无数", "is_correct": true, "explanation": "正确：无数 wú shù，表示数量极多、数不过来。"}, {"text": "武术", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术。"}, {"text": "无处", "is_correct": false, "explanation": "chù（第四声）与 shù（第四声）声母不同（ch 与 sh），意思是没有地方。"}, {"text": "无事", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是没有事情。"}, {"text": "无助", "is_correct": false, "explanation": "zhù（第四声）与 shù（第四声）声母不同（zh 与 sh），意思是没有依靠。"}], "explanations": {"无数": "正确：无数 wú shù，表示数量极多、数不过来。", "武术": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术。", "无处": "chù（第四声）与 shù（第四声）声母不同（ch 与 sh），意思是没有地方。", "无事": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是没有事情。", "无助": "zhù（第四声）与 shù（第四声）声母不同（zh 与 sh），意思是没有依靠。"}, "sentence_index": null, "correct_answer": "无数"}, "level_3": {"options": [{"text": "无数", "is_correct": true, "explanation": "正确：“天上有无数星星”中，“无数”修饰星星，表示数量极多。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：「清澈」形容水或眼睛，不能修饰天上的星星。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：「漆黑」形容颜色或光线，句中要说的是星星的数量多。"}, {"text": "憨厚", "is_correct": false, "explanation": "语义：「憨厚」形容人的品性，不能用来形容天上的星星。"}], "explanations": {"无数": "正确：“天上有无数星星”中，“无数”修饰星星，表示数量极多。", "清澈": "搭配：「清澈」形容水或眼睛，不能修饰天上的星星。", "漆黑": "语义：「漆黑」形容颜色或光线，句中要说的是星星的数量多。", "憨厚": "语义：「憨厚」形容人的品性，不能用来形容天上的星星。"}, "sentence_index": 0, "correct_answer": "无数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喝了无数水。", "explanation": "这里应该用〈很多〉。无数只修饰能一个个数的人或事物，水不能数，应说“喝了很多水”。"}, {"text": "工厂排放了无数废气。", "explanation": "这里应该用〈大量〉。废气是不可数的，应说“排放了大量废气”，“无数”不能修饰它。"}, {"text": "我买了无数牛奶。", "explanation": "这里应该用〈一些〉。牛奶是不可数的，应说“买了一些牛奶”，“无数”只用于能数的人或事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无数", "is_correct": true, "explanation": "正确：“大海里有无数我们不认识的鱼”中，“无数”表示鱼的数量极多。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：「悲伤」是情绪，不能用来说鱼的数量。"}, {"text": "乐观", "is_correct": false, "explanation": "语义：「乐观」形容人的态度，不能修饰鱼。"}, {"text": "年迈", "is_correct": false, "explanation": "搭配：「年迈」只用于形容人的年龄，不能与“鱼”这样的对象搭配。"}], "explanations": {"无数": "正确：“大海里有无数我们不认识的鱼”中，“无数”表示鱼的数量极多。", "悲伤": "语义：「悲伤」是情绪，不能用来说鱼的数量。", "乐观": "语义：「乐观」形容人的态度，不能修饰鱼。", "年迈": "搭配：「年迈」只用于形容人的年龄，不能与“鱼”这样的对象搭配。"}, "sentence_index": 6, "correct_answer": "无数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里有无数油。", "explanation": "这里应该用〈少量〉。油是不可数的，应说“有少量油”，“无数”只能修饰可以一个个数的人或事物。"}, {"text": "饭桌上有无数汤。", "explanation": "这里应该用〈一碗〉。汤要用“碗”来计量，“无数”不能修饰不可数的东西。"}, {"text": "他的脸上有无数汗。", "explanation": "这里应该用〈几滴〉。汗是不可数的，要用“滴”来计量，不能说“无数汗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "田野里开着无数只野花。", "corrected_sentence": "田野里开着无数朵野花。", "error_description": "错误在“野花”的量词。花一般用“朵”计量，“只”多用于动物等；应为「无数朵野花」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
