INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93026, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数不清，形容极多。", "primary_collocate": null, "pronunciation": "wú shù", "ipa": "u˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "为了这次比赛，他练习了无数次。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年，他帮助过无数的人。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈为我们做了无数顿饭。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里有无数的话想对你说。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无数个夜晚，她都在灯下看书。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我想了无数遍，还是不明白。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教过无数学生。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一路上看到了无数新鲜的东西。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对你说过无数次谢谢了。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生中会遇到无数个选择。", "target_word": "无数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無數", "label": "繁体"}, {"form": "无数次", "label": "复合词"}], "register": "中性", "sense_fingerprint": "无数：夸张地形容次数、人数极多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93026, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无数", "is_correct": true, "explanation": "正确：无数 wú shù，表示次数或人数极多。"}, {"text": "武术", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术。"}, {"text": "无处", "is_correct": false, "explanation": "chù（第四声）与 shù（第四声）声母不同（ch 与 sh），意思是没有地方。"}, {"text": "无事", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是没有事情。"}, {"text": "无助", "is_correct": false, "explanation": "zhù（第四声）与 shù（第四声）声母不同（zh 与 sh），意思是没有依靠。"}], "explanations": {"无数": "正确：无数 wú shù，表示次数或人数极多。", "武术": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术。", "无处": "chù（第四声）与 shù（第四声）声母不同（ch 与 sh），意思是没有地方。", "无事": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是没有事情。", "无助": "zhù（第四声）与 shù（第四声）声母不同（zh 与 sh），意思是没有依靠。"}, "sentence_index": null, "correct_answer": "无数"}, "level_3": {"options": [{"text": "无数", "is_correct": true, "explanation": "正确：“练习了无数次”中，“无数”修饰“次”，表示次数极多。"}, {"text": "简短", "is_correct": false, "explanation": "搭配：「简短」形容时间或言辞，不能修饰次数。"}, {"text": "清晰", "is_correct": false, "explanation": "语义：「清晰」形容事物清楚的程度，句中要说的是次数多。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容体格或外形，不能修饰练习的次数。"}], "explanations": {"无数": "正确：“练习了无数次”中，“无数”修饰“次”，表示次数极多。", "简短": "搭配：「简短」形容时间或言辞，不能修饰次数。", "清晰": "语义：「清晰」形容事物清楚的程度，句中要说的是次数多。", "高大": "体貌：「高大」形容体格或外形，不能修饰练习的次数。"}, "sentence_index": 0, "correct_answer": "无数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出生了无数次。", "explanation": "这里应该用〈一次〉。出生只能发生一次，“无数次”只能用于可以反复发生的事。"}, {"text": "我的毕业典礼举行了无数次。", "explanation": "这里应该用〈一次〉。毕业典礼只举行一次，“无数次”说的是反复多次，不能用于这种只发生一次的事。"}, {"text": "我们的婚礼办了无数次。", "explanation": "这里应该用〈一次〉。婚礼一般只办一次，“无数次”说的是反复多次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无数", "is_correct": true, "explanation": "正确：“这位老师教过无数学生”中，“无数”表示学生的人数极多。"}, {"text": "悠久", "is_correct": false, "explanation": "语义：「悠久」形容历史或传统的长久，不能修饰学生的人数。"}, {"text": "漫长", "is_correct": false, "explanation": "搭配：「漫长」形容时间或路程，不能修饰学生。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：「雪白」形容颜色，不能说明学生的数量。"}], "explanations": {"无数": "正确：“这位老师教过无数学生”中，“无数”表示学生的人数极多。", "悠久": "语义：「悠久」形容历史或传统的长久，不能修饰学生的人数。", "漫长": "搭配：「漫长」形容时间或路程，不能修饰学生。", "雪白": "语义：「雪白」形容颜色，不能说明学生的数量。"}, "sentence_index": 6, "correct_answer": "无数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的工资发了无数次。", "explanation": "这里应该用〈一次〉。这个月的工资只发一次，“无数次”说的是反复多次，不能用于固定只发生一次的事。"}, {"text": "这台电脑买了无数次。", "explanation": "这里应该用〈一次〉。同一台电脑只买一次，“无数次”说的是多次重复。"}, {"text": "他大学毕业了无数次。", "explanation": "这里应该用〈一次〉。大学毕业通常只有一次，“无数次”不能用于这种只发生一次的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他参加过无数遍比赛。", "corrected_sentence": "他参加过无数次比赛。", "error_description": "错误在“无数”后的量词。表示次数应用“次”，“遍”指从头到尾的一遍，不用于比赛；应为「参加过无数次比赛」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听过这首歌无数首。", "corrected_sentence": "我听过这首歌无数遍。", "error_description": "错误在“无数”后的量词。“首”计量歌曲，计算听歌的次数应用“遍”；正确为「听过这首歌无数遍」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
