INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "布置是把东西摆好，让一个地方变好看。", "primary_collocate": null, "pronunciation": "bù zhì", "ipa": "pu˥˩ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我们把教室布置得很漂亮。", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在客厅里布置了一棵圣诞树。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生日那天，朋友们把房间布置成了粉色。", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新家刚搬好，我想先布置一下卧室。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里布置着很多孩子画的画。", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用花和灯把婚礼现场布置得很浪漫。", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间咖啡店布置得很温馨，我很喜欢。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年前，我们一家人一起布置客厅。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书桌放在窗边，你看我这样布置书房好不好？", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爱花，把阳台布置成了小花园。", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "布置了", "label": "体标：了"}, {"form": "布置着", "label": "体标：着"}, {"form": "布置过", "label": "体标：过"}, {"form": "布置布置", "label": "重叠"}], "register": "中性", "sense_fingerprint": "布置：摆放装饰，使场所整齐好看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd75ca80b-1f26-4b15-81d3-10584f1de521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93027, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "布置", "is_correct": true, "explanation": "正确答案。“布置”读作 bù zhì，意思是把东西摆好、装饰场所，使其好看。"}, {"text": "不止", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，“不止”意思是不仅、不只。"}, {"text": "不知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，“不知”意思是不知道。"}, {"text": "不值", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，“不值”意思是不值得。"}, {"text": "木质", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），“木质”意思是木材的质地。"}], "explanations": {"布置": "正确答案。“布置”读作 bù zhì，意思是把东西摆好、装饰场所，使其好看。", "不止": "zhǐ（第三声）与 zhì（第四声）声调不同，“不止”意思是不仅、不只。", "不知": "zhī（第一声）与 zhì（第四声）声调不同，“不知”意思是不知道。", "不值": "zhí（第二声）与 zhì（第四声）声调不同，“不值”意思是不值得。", "木质": "mù 与 bù 声母不同（m 与 b），“木质”意思是木材的质地。"}, "sentence_index": null, "correct_answer": "布置"}, "level_3": {"options": [{"text": "布置", "is_correct": true, "explanation": "正确答案。“布置”指把教室摆设装饰好，与“布置得很漂亮”相符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指挪动东西，不能说“把教室搬得很漂亮”，与“漂亮”的美化结果不合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与“把教室……得很漂亮”的美化意思相冲突。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”一般搭配坑、洞、土等对象，不搭配“教室”。"}], "explanations": {"布置": "正确答案。“布置”指把教室摆设装饰好，与“布置得很漂亮”相符。", "搬": "语义：“搬”指挪动东西，不能说“把教室搬得很漂亮”，与“漂亮”的美化结果不合。", "扔": "语义：“扔”指丢弃，与“把教室……得很漂亮”的美化意思相冲突。", "挖": "搭配：“挖”一般搭配坑、洞、土等对象，不搭配“教室”。"}, "sentence_index": 0, "correct_answer": "布置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台坏掉的冰箱，我已经布置好了。", "explanation": "这里应该用〈修理〉。“布置”指摆放、装饰房间或场地，修理机器要用“修理”，不能用“布置”。"}, {"text": "这位设计师为公司布置了一个新标志。", "explanation": "这里应该用〈设计〉。“布置”指摆放、装饰场地，设计标志要用“设计”，不能用“布置”。"}, {"text": "他把自己布置得很帅。", "explanation": "这里应该用〈打扮〉。“布置”用于房间、场地，不能用来指人的装扮和外貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93027, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "布置", "is_correct": true, "explanation": "正确答案。“布置”读作 bù zhì，意思是把东西摆好、装饰场所，使其好看。"}, {"text": "复制", "is_correct": false, "explanation": "fù（第四声）与 bù（第四声）声母不同（f 与 b），“复制”意思是照原样做出一份。"}, {"text": "录制", "is_correct": false, "explanation": "lù 与 bù 声母不同（l 与 b），“录制”意思是把声音、图像记录下来。"}, {"text": "不是", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），“不是”表示否定。"}], "explanations": {"布置": "正确答案。“布置”读作 bù zhì，意思是把东西摆好、装饰场所，使其好看。", "复制": "fù（第四声）与 bù（第四声）声母不同（f 与 b），“复制”意思是照原样做出一份。", "录制": "lù 与 bù 声母不同（l 与 b），“录制”意思是把声音、图像记录下来。", "不是": "shì 与 zhì 声母不同（sh 与 zh），“不是”表示否定。"}, "sentence_index": null, "correct_answer": "布置"}, "level_3": {"options": [{"text": "布置", "is_correct": true, "explanation": "正确答案。“布置得很温馨”指把咖啡店装饰得有温暖的氛围。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除、拆开，与“温馨”的氛围完全相反。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：“吵”形容声音嘈杂，不用来描述店铺的温馨氛围。"}, {"text": "锁", "is_correct": false, "explanation": "语义：“锁”指上锁、关闭，与“温馨”的氛围不相容。"}], "explanations": {"布置": "正确答案。“布置得很温馨”指把咖啡店装饰得有温暖的氛围。", "拆": "语义：“拆”指拆除、拆开，与“温馨”的氛围完全相反。", "吵": "搭配：“吵”形容声音嘈杂，不用来描述店铺的温馨氛围。", "锁": "语义：“锁”指上锁、关闭，与“温馨”的氛围不相容。"}, "sentence_index": 6, "correct_answer": "布置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把衣服布置得很干净。", "explanation": "这里应该用〈洗〉。“布置”指摆放、装饰，清洗衣服要用“洗”，不能用“布置”。"}, {"text": "他布置了一首新歌。", "explanation": "这里应该用〈写〉。“布置”指摆放、装饰房间或场地，创作歌曲要用“写”，不能用“布置”。"}, {"text": "她把破袜子布置好了。", "explanation": "这里应该用〈缝〉。“布置”指装饰摆放，修补衣物要用“缝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把客厅布置很漂亮。", "corrected_sentence": "我把客厅布置得很漂亮。", "error_description": "“布置”后的结果补语要用“得”连接，应说“布置得很漂亮”。漏掉“得”，直接说“布置很漂亮”，是不地道的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把客厅布置了好。", "corrected_sentence": "妈妈把客厅布置好了。", "error_description": "结果补语“好”应紧跟动词，“了”放在句末。应说“布置好了”，不能说“布置了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
