INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对工作、任务作出安排和部署。", "primary_collocate": null, "pronunciation": "bù zhì", "ipa": "pu˥˩ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师布置了很多作业。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理今天上午给我们布置了新任务。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末老师没有布置作业，我可以出去玩。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时，领导布置了下个月的工作。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师刚布置完作业，同学们就开始写了。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长先把比赛的任务布置给每个人。", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在会上布置了明年的工作。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一回到公司，就开始布置今天的工作。", "target_word": "布置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给孩子布置了一个小任务：每天浇花。", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周老师布置过一篇作文，你写完了吗？", "target_word": "布置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "布置了", "label": "体标：了"}, {"form": "布置过", "label": "体标：过"}, {"form": "布置布置", "label": "重叠"}], "register": "中性", "sense_fingerprint": "布置：对工作、任务、作业作出安排和部署", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd75ca80b-1f26-4b15-81d3-10584f1de521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93028, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "布置", "is_correct": true, "explanation": "正确答案。“布置”读作 bù zhì，这里指对工作、任务作出安排。"}, {"text": "不止", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，“不止”意思是不仅、不只。"}, {"text": "不值", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，“不值”意思是不值得。"}, {"text": "木质", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），“木质”意思是木材的质地。"}], "explanations": {"布置": "正确答案。“布置”读作 bù zhì，这里指对工作、任务作出安排。", "不止": "zhǐ（第三声）与 zhì（第四声）声调不同，“不止”意思是不仅、不只。", "不值": "zhí（第二声）与 zhì（第四声）声调不同，“不值”意思是不值得。", "木质": "mù 与 bù 声母不同（m 与 b），“木质”意思是木材的质地。"}, "sentence_index": null, "correct_answer": "布置"}, "level_3": {"options": [{"text": "布置", "is_correct": true, "explanation": "正确答案。“布置了很多作业”指老师给学生分派作业。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指演唱，与“很多作业”无关，句子说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般搭配衣物、碗碟，不搭配“作业”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”搭配食物一类对象，不搭配“作业”。"}], "explanations": {"布置": "正确答案。“布置了很多作业”指老师给学生分派作业。", "唱": "语义：“唱”指演唱，与“很多作业”无关，句子说不通。", "洗": "搭配：“洗”一般搭配衣物、碗碟，不搭配“作业”。", "吃": "搭配：“吃”搭配食物一类对象，不搭配“作业”。"}, "sentence_index": 0, "correct_answer": "布置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校把这笔助学金布置给了三个新生。", "explanation": "这里应该用〈发放〉。“布置”用于安排工作、任务，钱款、助学金要用“发放”，不能用“布置”。"}, {"text": "邮递员把信件布置到了家里。", "explanation": "这里应该用〈送〉。“布置”用于安排工作、任务，寄送信件要用“送”，不能用“布置”。"}, {"text": "他把碗布置干净了。", "explanation": "这里应该用〈洗〉。“布置”指安排或装饰，洗碗要用“洗”，不能用“布置”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93028, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "布置", "is_correct": true, "explanation": "正确答案。“布置”读作 bù zhì，这里指对工作、任务作出安排。"}, {"text": "复制", "is_correct": false, "explanation": "fù（第四声）与 bù（第四声）声母不同（f 与 b），“复制”意思是照原样做出一份。"}, {"text": "录制", "is_correct": false, "explanation": "lù 与 bù 声母不同（l 与 b），“录制”意思是把声音、图像记录下来。"}, {"text": "不是", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），“不是”表示否定。"}], "explanations": {"布置": "正确答案。“布置”读作 bù zhì，这里指对工作、任务作出安排。", "复制": "fù（第四声）与 bù（第四声）声母不同（f 与 b），“复制”意思是照原样做出一份。", "录制": "lù 与 bù 声母不同（l 与 b），“录制”意思是把声音、图像记录下来。", "不是": "shì 与 zhì 声母不同（sh 与 zh），“不是”表示否定。"}, "sentence_index": null, "correct_answer": "布置"}, "level_3": {"options": [{"text": "布置", "is_correct": true, "explanation": "正确答案。“布置了明年的工作”指在会上对明年的工作作出安排。"}, {"text": "总结", "is_correct": false, "explanation": "语义：“总结”指回顾已经做过的事，与“明年的工作”尚未开始相冲突。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”指终止，与“明年的工作”的时间方向不合。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”一般搭配房屋、包装等对象，不搭配“工作”。"}], "explanations": {"布置": "正确答案。“布置了明年的工作”指在会上对明年的工作作出安排。", "总结": "语义：“总结”指回顾已经做过的事，与“明年的工作”尚未开始相冲突。", "结束": "语义：“结束”指终止，与“明年的工作”的时间方向不合。", "拆": "搭配：“拆”一般搭配房屋、包装等对象，不搭配“工作”。"}, "sentence_index": 6, "correct_answer": "布置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府布置了一部新法律。", "explanation": "这里应该用〈颁布〉。“布置”用于安排工作、任务，法律、法规要用“颁布”。"}, {"text": "公司布置了三千块奖金。", "explanation": "这里应该用〈发放〉。“布置”指安排工作、任务，钱款、奖金要用“发放”。"}, {"text": "老师布置了一张奖状。", "explanation": "这里应该用〈颁发〉。“布置”不用于颁发证书、奖状，这类东西要用“颁发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理下午给大家了布置新任务。", "corrected_sentence": "经理下午给大家布置新任务。", "error_description": "“了”放在动词“布置”之前是错误的位置。应去掉“布置”前的“了”，说“给大家布置新任务”。若要表示动作完成，“了”应放在动词之后，如“布置了新任务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月班长布置了过一次大扫除。", "corrected_sentence": "上个月班长布置过一次大扫除。", "error_description": "“了”和“过”不能同时用在同一个动词后。表示曾经做过，应说“布置过”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
