INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "烟是东西烧起来，往上飘的灰白色的气。", "primary_collocate": null, "pronunciation": "yān", "ipa": "jɛn˥", "syllable_count": 1, "sentences": [{"text": "烟从屋顶上慢慢冒出来。", "target_word": "烟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "着火了，房间里到处都是烟。", "target_word": "烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟往上飘，越飘越高。", "target_word": "烟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他烧了一堆树叶，烟特别大。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟太多了，我看不清前面的路。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户开着，烟都飘出去了。", "target_word": "烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烤肉的时候，烟熏得我直流眼泪。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处有一缕烟升到了天上。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用湿毛巾捂住鼻子，怕吸进烟。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火小了，烟也慢慢少了。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}, {"form": "缕", "label": "量词"}, {"form": "团", "label": "量词"}, {"form": "煙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西燃烧时往上飘的灰白色气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df81c267-6b39-4d12-95ab-3643a04c33bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93029, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烟", "is_correct": true, "explanation": "烟：东西燃烧时往上飘的灰白色的气，本词的正确形式。"}, {"text": "盐", "is_correct": false, "explanation": "yán（第二声）与 yān（第一声）声调不同，意思是盐。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn（第三声）与 yān（第一声）声调不同，意思是眼睛。"}, {"text": "严", "is_correct": false, "explanation": "yán（第二声）与 yān（第一声）声调不同，意思是严格。"}, {"text": "验", "is_correct": false, "explanation": "yàn（第四声）与 yān（第一声）声调不同，意思是检验。"}], "explanations": {"烟": "烟：东西燃烧时往上飘的灰白色的气，本词的正确形式。", "盐": "yán（第二声）与 yān（第一声）声调不同，意思是盐。", "眼": "yǎn（第三声）与 yān（第一声）声调不同，意思是眼睛。", "严": "yán（第二声）与 yān（第一声）声调不同，意思是严格。", "验": "yàn（第四声）与 yān（第一声）声调不同，意思是检验。"}, "sentence_index": null, "correct_answer": "烟"}, "level_3": {"options": [{"text": "烟", "is_correct": true, "explanation": "烟：从屋顶上冒出来的东西，符合句意。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不会从屋顶上慢慢冒出来，与句中的场景不合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“冒出”多用于烟、气、水，不说冒出石头。"}, {"text": "字", "is_correct": false, "explanation": "语义：字不能从屋顶上慢慢冒出来，与句中的场景不合。"}], "explanations": {"烟": "烟：从屋顶上冒出来的东西，符合句意。", "钱": "语义：钱不会从屋顶上慢慢冒出来，与句中的场景不合。", "石头": "搭配：“冒出”多用于烟、气、水，不说冒出石头。", "字": "语义：字不能从屋顶上慢慢冒出来，与句中的场景不合。"}, "sentence_index": 0, "correct_answer": "烟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他烧了一堆树叶，冒出一只烟。", "explanation": "这里应该用〈股〉。“只”不能用来数烟，烟要用“股”来数。"}, {"text": "天空飘着一张烟。", "explanation": "这里应该用〈缕〉。“张”用于平面的东西，烟不能用它来数。"}, {"text": "他烧了一堆树叶，升起一颗烟。", "explanation": "这里应该用〈股〉或〈缕〉。“颗”用于粒状的东西，烟不能用它来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93029, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "烟", "is_correct": true, "explanation": "烟：东西燃烧时往上飘的灰白色的气，本词的正确形式。"}, {"text": "演", "is_correct": false, "explanation": "yǎn（第三声）与 yān（第一声）声调不同，意思是表演。"}, {"text": "艳", "is_correct": false, "explanation": "yàn（第四声）与 yān（第一声）声调不同，意思是鲜艳。"}, {"text": "言", "is_correct": false, "explanation": "yán（第二声）与 yān（第一声）声调不同，意思是言语。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yān（第一声）声调不同，意思是宴会。"}], "explanations": {"烟": "烟：东西燃烧时往上飘的灰白色的气，本词的正确形式。", "演": "yǎn（第三声）与 yān（第一声）声调不同，意思是表演。", "艳": "yàn（第四声）与 yān（第一声）声调不同，意思是鲜艳。", "言": "yán（第二声）与 yān（第一声）声调不同，意思是言语。", "宴": "yàn（第四声）与 yān（第一声）声调不同，意思是宴会。"}, "sentence_index": null, "correct_answer": "烟"}, "level_3": {"options": [{"text": "烟", "is_correct": true, "explanation": "烟：烤肉时熏人的东西，符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不会熏得人直流眼泪，与句中的场景不合。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能熏人，与“烤肉的时候”的场景不合。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“熏”的对象是烟或气味，不能说手熏人。"}], "explanations": {"烟": "烟：烤肉时熏人的东西，符合句意。", "蛋糕": "语义：蛋糕不会熏得人直流眼泪，与句中的场景不合。", "书": "语义：书不能熏人，与“烤肉的时候”的场景不合。", "手": "搭配：“熏”的对象是烟或气味，不能说手熏人。"}, "sentence_index": 6, "correct_answer": "烟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把烟掐灭了，转身出了门。", "explanation": "这里的“烟”指香烟，是另一个义项，与“东西烧起来往上飘的灰白色的气”的意思不同。"}, {"text": "他家门前种了一大片烟，准备卖给收购站。", "explanation": "这里的“烟”指烟草，是另一个义项，与“东西燃烧时往上飘的气”的意思不同。"}, {"text": "窗玻璃上结满了烟，看不清外面。", "explanation": "这里应该用〈雾气〉。“结”多用于雾气、霜等，烟不能附着在玻璃上结成一层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋顶上冒出一个烟。", "corrected_sentence": "屋顶上冒出一股烟。", "error_description": "“烟”飘起来时应用“股”来数，“个”不能用于烟；应说“冒出一股烟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里飘着一烟，很呛人。", "corrected_sentence": "屋里飘着一股烟，很呛人。", "error_description": "“一烟”缺少量词，应说“一股烟”；烟要用适当的量词来数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
