INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物质燃烧时产生的气体；也指香烟。", "primary_collocate": null, "pronunciation": "yān", "ipa": "jɛn˥", "syllable_count": 1, "sentences": [{"text": "他一天抽一包烟。", "target_word": "烟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸为了健康，一支烟也不抽了。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里都是烟，我一直咳嗽。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里冒出了很多烟。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿出一支烟，用打火机点着了。", "target_word": "烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有一缕烟慢慢飘向天空。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说抽烟对肺不好。", "target_word": "烟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火灭了，可是还有烟从屋顶上冒出来。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在中国，买烟的人必须满十八岁。", "target_word": "烟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把烟扔在地上，用脚踩灭了。", "target_word": "烟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "缕", "label": "量词"}, {"form": "煙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "燃烧产生的气体，也指香烟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df81c267-6b39-4d12-95ab-3643a04c33bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93030, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烟", "is_correct": true, "explanation": "烟：物质燃烧时产生的气体，也指香烟，本词的正确形式。"}, {"text": "盐", "is_correct": false, "explanation": "yán（第二声）与 yān（第一声）声调不同，意思是盐。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn（第三声）与 yān（第一声）声调不同，意思是眼睛。"}, {"text": "严", "is_correct": false, "explanation": "yán（第二声）与 yān（第一声）声调不同，意思是严格。"}, {"text": "验", "is_correct": false, "explanation": "yàn（第四声）与 yān（第一声）声调不同，意思是检验。"}], "explanations": {"烟": "烟：物质燃烧时产生的气体，也指香烟，本词的正确形式。", "盐": "yán（第二声）与 yān（第一声）声调不同，意思是盐。", "眼": "yǎn（第三声）与 yān（第一声）声调不同，意思是眼睛。", "严": "yán（第二声）与 yān（第一声）声调不同，意思是严格。", "验": "yàn（第四声）与 yān（第一声）声调不同，意思是检验。"}, "sentence_index": null, "correct_answer": "烟"}, "level_3": {"options": [{"text": "烟", "is_correct": true, "explanation": "烟：“抽一包”所搭配的对象，符合句意。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：“抽”的对象是烟，不说“抽糖”。"}, {"text": "酒", "is_correct": false, "explanation": "搭配：“抽”不能和“酒”搭配，酒要说“喝”。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不能被抽，与“抽”的动作和句中的语境不合。"}], "explanations": {"烟": "烟：“抽一包”所搭配的对象，符合句意。", "糖": "搭配：“抽”的对象是烟，不说“抽糖”。", "酒": "搭配：“抽”不能和“酒”搭配，酒要说“喝”。", "钱": "语义：钱不能被抽，与“抽”的动作和句中的语境不合。"}, "sentence_index": 0, "correct_answer": "烟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只烟。", "explanation": "这里应该用〈包〉或〈支〉。“只”不能用来数烟。"}, {"text": "山上飘着一支烟。", "explanation": "这里应该用〈缕〉。“支”用于香烟，飘在空中的烟要用“缕”。"}, {"text": "屋里有一块烟。", "explanation": "这里应该用〈缕〉或〈团〉。“块”用于块状的东西，烟不能这样数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93030, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "烟", "is_correct": true, "explanation": "烟：物质燃烧时产生的气体，也指香烟，本词的正确形式。"}, {"text": "演", "is_correct": false, "explanation": "yǎn（第三声）与 yān（第一声）声调不同，意思是表演。"}, {"text": "艳", "is_correct": false, "explanation": "yàn（第四声）与 yān（第一声）声调不同，意思是鲜艳。"}, {"text": "言", "is_correct": false, "explanation": "yán（第二声）与 yān（第一声）声调不同，意思是言语。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yān（第一声）声调不同，意思是宴会。"}], "explanations": {"烟": "烟：物质燃烧时产生的气体，也指香烟，本词的正确形式。", "演": "yǎn（第三声）与 yān（第一声）声调不同，意思是表演。", "艳": "yàn（第四声）与 yān（第一声）声调不同，意思是鲜艳。", "言": "yán（第二声）与 yān（第一声）声调不同，意思是言语。", "宴": "yàn（第四声）与 yān（第一声）声调不同，意思是宴会。"}, "sentence_index": null, "correct_answer": "烟"}, "level_3": {"options": [{"text": "烟", "is_correct": true, "explanation": "烟：“抽”所搭配的对象，符合句意。"}, {"text": "药", "is_correct": false, "explanation": "搭配：“抽”一般跟“烟”搭配，不说“抽药”。"}, {"text": "茶", "is_correct": false, "explanation": "搭配：“抽”不能和“茶”搭配，茶要说“喝”或“泡”。"}, {"text": "水", "is_correct": false, "explanation": "语义：“抽水”指用机器把水抽出来，与“对肺不好”没有关系，句意不通。"}], "explanations": {"烟": "烟：“抽”所搭配的对象，符合句意。", "药": "搭配：“抽”一般跟“烟”搭配，不说“抽药”。", "茶": "搭配：“抽”不能和“茶”搭配，茶要说“喝”或“泡”。", "水": "语义：“抽水”指用机器把水抽出来，与“对肺不好”没有关系，句意不通。"}, "sentence_index": 6, "correct_answer": "烟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节日的夜空里绽放着美丽的烟。", "explanation": "这里应该用〈烟花〉。“烟”指燃烧产生的气体，不能“绽放”，绽放的是烟花。"}, {"text": "我们村今年种了很多烟，收成特别好。", "explanation": "这里的“烟”指烟草这种作物，是另一个义项，与“燃烧产生的气体、香烟”的意思不同。"}, {"text": "玻璃上结了一层烟。", "explanation": "这里应该用〈雾气〉。“结”多用于雾气、霜等，烟不能附着在玻璃上结成一层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt