INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天买了三个烟。", "corrected_sentence": "他昨天买了三包烟。", "error_description": "“烟”可用“包”“支”“根”等量词来数，“个”不能用于烟；应说“三包烟”，“三个烟”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家里放着两烟，都是给客人的。", "corrected_sentence": "他家里放着两包烟，都是给客人的。", "error_description": "“两烟”缺少量词，应说“两包烟”；烟要用适当的量词来数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
