INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "位图是用很多小小的点拼成的图片。", "primary_collocate": null, "pronunciation": "wèi tú", "ipa": "weɪ˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "位图是很多小点拼成的图片。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一张位图。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把位图放大，就能看到小点。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张位图的颜色很多，也很好看。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，位图里的小点是方的。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的小图片很多是位图。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在电脑上打开一张位图。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "位图的小点越多，图片越清楚。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花的照片是一张位图，放大以后能看到小点。", "target_word": "位图", "complexity_tier": "T3", "furigana": "zhè duǒ huā de zhào piàn shì yì zhāng wèi tú, fàng dà yǐ hòu néng kàn dào xiǎo diǎn", "sentence_source": "generated"}, {"text": "这幅位图上有一只小猫。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位圖", "label": "繁体"}], "register": "专业", "sense_fingerprint": "用很多小点拼成的图片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "位图", "is_correct": true, "explanation": "语义：位图由很多小点拼成，与“是很多小点拼成的图片”相合。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文字作品，不是由小点拼成的图片。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是粮食，不是图片，句子说不通。"}, {"text": "剪纸", "is_correct": false, "explanation": "搭配：剪纸是用剪刀剪出来的，不说“由小点拼成”。"}], "explanations": {"位图": "语义：位图由很多小点拼成，与“是很多小点拼成的图片”相合。", "诗歌": "语义：诗歌是文字作品，不是由小点拼成的图片。", "大米": "语义：大米是粮食，不是图片，句子说不通。", "剪纸": "搭配：剪纸是用剪刀剪出来的，不说“由小点拼成”。"}, "sentence_index": 0, "correct_answer": "位图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张位图无论放大多少倍，线条都不会模糊。", "explanation": "这里应该用〈矢量图〉。位图由小点组成，放大很多倍就会模糊；无论怎么放大都清楚，是矢量图的特点。"}, {"text": "妈妈用一张位图记下了我们每个人的生日。", "explanation": "这里应该用〈表格〉。位图指由小点拼成的图片，不能用来记录生日这类信息。"}, {"text": "妈妈在墙上挂了一只位图。", "explanation": "这里应该用〈幅〉或〈张〉。位图是图片，“只”用于动物或成对的东西，量词用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位图", "is_correct": true, "explanation": "语义：电脑上可以打开图片，“位图”是图片，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：不能在电脑上打开桌子，句子说不通。"}, {"text": "床", "is_correct": false, "explanation": "语义：不能在电脑上打开床，与“电脑上”的情境不符。"}, {"text": "木板", "is_correct": false, "explanation": "搭配：“打开”通常接文件或窗口，不接木板。"}], "explanations": {"位图": "语义：电脑上可以打开图片，“位图”是图片，符合句意。", "桌子": "语义：不能在电脑上打开桌子，句子说不通。", "床": "语义：不能在电脑上打开床，与“电脑上”的情境不符。", "木板": "搭配：“打开”通常接文件或窗口，不接木板。"}, "sentence_index": 6, "correct_answer": "位图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只位图上有一只小猫。", "explanation": "这里应该用〈幅〉。“只”用于动物，不能用来数位图；位图是图片，应用“幅”或“张”。"}, {"text": "这幅位图上有一只小猫，放大一千倍也不会模糊。", "explanation": "这里应该用〈矢量图〉。位图由小点组成，放大很多倍会出现方块；放大多少倍都清楚是矢量图的特点。"}, {"text": "这幅位图的笔触很粗，很有力量。", "explanation": "这里应该用〈油画〉。位图是点阵图像，没有笔触，“笔触很粗”是油画的特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在屏幕上看了两只位图。", "corrected_sentence": "妹妹在屏幕上看了两张位图。", "error_description": "错误：量词“只”。“位图”是图片，应用量词“张”；应说“两张位图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟在电脑上打开了一本位图，图上有很多小点。", "corrected_sentence": "弟弟在电脑上打开了一张位图，图上有很多小点。", "error_description": "错误：量词“本”。“位图”是图片，应用量词“张”；应说“一张位图”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
