INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由像素点阵构成的图像，也称点阵图。", "primary_collocate": null, "pronunciation": "wèi tú", "ipa": "weɪ˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "位图放大以后，会看到很多小方块。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张位图是用电脑画出来的。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "位图的每个小点都有一种颜色。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片一般是位图，不是矢量图。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "位图太大，所以发邮件很慢。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把图片存成了位图。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以打开位图和矢量图。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师用位图做网页上的小图片。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "位图越大，占的空间越多。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画位图时，要先选好点的大小。", "target_word": "位图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位圖", "label": "繁体"}], "register": "专业", "sense_fingerprint": "由像素点阵构成的图像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "位图", "is_correct": true, "explanation": "语义：位图由像素点阵构成，放大后会显出小方块，与句意相合。"}, {"text": "矢量图", "is_correct": false, "explanation": "语义：矢量图由曲线构成，放大后仍然清楚，不会出现小方块。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“放大”用于图像或字号，不说“放大饼干”。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是声音，放大后不会看到方块。"}], "explanations": {"位图": "语义：位图由像素点阵构成，放大后会显出小方块，与句意相合。", "矢量图": "语义：矢量图由曲线构成，放大后仍然清楚，不会出现小方块。", "饼干": "搭配：“放大”用于图像或字号，不说“放大饼干”。", "音乐": "语义：音乐是声音，放大后不会看到方块。"}, "sentence_index": 0, "correct_answer": "位图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张位图放大以后，线条依然很平滑。", "explanation": "这里应该用〈矢量图〉。位图放大后会出现小方块，线条平滑是矢量图的特点。"}, {"text": "设计师用位图画了一条精确的路径，可以无限缩放而不失真。", "explanation": "这里应该用〈矢量图〉。位图由像素点组成，放大会失真；能无限缩放、保持清晰是矢量图的特点。"}, {"text": "我把一只位图发给了朋友。", "explanation": "这里应该用〈张〉或〈幅〉。位图是图片，量词用“张”“幅”，“只”用于动物或成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位图", "is_correct": true, "explanation": "语义：这个软件能打开位图文件，与“矢量图”并列，符合句意。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：软件打开的是文件，不能打开饺子，“打开饺子和矢量图”说不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：软件打开的是文件，不能打开蛋糕，“打开蛋糕和矢量图”与句意不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：软件不能打开冰箱，“打开冰箱和矢量图”与句意不符。"}], "explanations": {"位图": "语义：这个软件能打开位图文件，与“矢量图”并列，符合句意。", "饺子": "语义：软件打开的是文件，不能打开饺子，“打开饺子和矢量图”说不通。", "蛋糕": "语义：软件打开的是文件，不能打开蛋糕，“打开蛋糕和矢量图”与句意不符。", "冰箱": "语义：软件不能打开冰箱，“打开冰箱和矢量图”与句意不符。"}, "sentence_index": 6, "correct_answer": "位图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每一个位图都有一种颜色。", "explanation": "这里应该用〈像素〉。位图指整幅点阵图像，单个小点才是像素，不能说“每一个位图”。"}, {"text": "我把位图放进耳机里听了一遍。", "explanation": "这里应该用〈音乐〉。位图是图像，只能看，不能听。"}, {"text": "我用位图写了一封信寄给奶奶。", "explanation": "这里应该用〈信纸〉。位图是由像素构成的图像，不是用来写信的纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只位图的分辨率很低，放大后很模糊。", "corrected_sentence": "这张位图的分辨率很低，放大后很模糊。", "error_description": "错误：量词“只”。“位图”是图片，应用量词“张”（或“幅”）；应说“这张位图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张位图得边缘有很多锯齿。", "corrected_sentence": "这张位图的边缘有很多锯齿。", "error_description": "错误：“的”误写为“得”。“位图的边缘”中“的”表示修饰关系，应写“的”；“得”用于动词或形容词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
