INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93033, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皇家是国王和他家里的人。", "primary_collocate": null, "pronunciation": "huáng jiā", "ipa": "xwɑŋ˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "皇家的孩子也要每天上学。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的大房子是皇家的。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁进了皇家，生活变了很多。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是皇家的一员，大家都认识他。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，很多人想看看皇家的人。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的皇家很受人们喜欢。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇家的车队今天要出门，路上有很多警察。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王子长大后，要为皇家做事。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里在说皇家的故事。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇家的生活和我们的不一样。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "皇家花园", "label": "复合"}, {"form": "皇家成员", "label": "复合"}], "register": "中性", "sense_fingerprint": "国王和他的家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93033, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇家", "is_correct": true, "explanation": "语义：“皇家”指国王和他家里的人，与“孩子也要每天上学”相合。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，没有孩子，“咖啡的孩子”说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能有孩子，“汽车的孩子”无法成立。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”不能拥有孩子，“石头的孩子”不是常见的说法。"}], "explanations": {"皇家": "语义：“皇家”指国王和他家里的人，与“孩子也要每天上学”相合。", "咖啡": "语义：咖啡是饮料，没有孩子，“咖啡的孩子”说不通。", "汽车": "语义：汽车是交通工具，不能有孩子，“汽车的孩子”无法成立。", "石头": "搭配：“石头”不能拥有孩子，“石头的孩子”不是常见的说法。"}, "sentence_index": 0, "correct_answer": "皇家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个皇家是个小女孩，她很可爱。", "explanation": "这里应该用〈公主〉。“皇家”指整个家族，不能说它“是个小女孩”；指一个人应说“公主”。"}, {"text": "我们去皇家参观了一天，看了很多宝贝。", "explanation": "这里应该用〈王宫〉。“皇家”指国王和他家里的人，不指建筑，不能作“参观”的地点。"}, {"text": "宫里来了一位皇家，大家都在欢迎。", "explanation": "这里应该用〈皇室成员〉。“皇家”是集体名词，指整个家族，不能用量词“位”数成一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇家", "is_correct": true, "explanation": "语义：“皇家”指国王的家人，句中“要出门，路上有很多警察”正说明他们的身份。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，没有车队，“白菜的车队”说不通。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是书，没有车队，也不需要警察护送。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，没有车队，“河流的车队”说不通。"}], "explanations": {"皇家": "语义：“皇家”指国王的家人，句中“要出门，路上有很多警察”正说明他们的身份。", "白菜": "语义：白菜是蔬菜，没有车队，“白菜的车队”说不通。", "字典": "语义：字典是书，没有车队，也不需要警察护送。", "河流": "语义：河流是自然景物，没有车队，“河流的车队”说不通。"}, "sentence_index": 6, "correct_answer": "皇家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "皇家是一只可爱的小猫，我每天都喂它。", "explanation": "这里应该用〈猫〉。“皇家”指帝王的家族，不能指一只动物。"}, {"text": "我叔叔是皇家，他每天都去钓鱼。", "explanation": "这里应该用〈皇亲〉。“皇家”指整个家族，不能直接充当“是”的表语来指称一个人；指个人应说“皇亲”。"}, {"text": "我在超市买了一斤皇家。", "explanation": "这里应该用〈水果〉等商品。“皇家”指国王和他的家人，不能买卖、论斤称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "皇家得房子在山上，又大又漂亮。", "corrected_sentence": "皇家的房子在山上，又大又漂亮。", "error_description": "错误：“皇家”后的“的”误写为“得”。“皇家的房子”中“的”表示领属关系，应写“的”；“得”用于动词或形容词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "皇家得生活很安静，没有太多人来打扰。", "corrected_sentence": "皇家的生活很安静，没有太多人来打扰。", "error_description": "错误：“皇家”后的“的”误写为“得”。“皇家的生活”中“的”表示修饰关系，应写“的”；“得”用于动词或形容词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
