INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93034, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "属于帝王家族的，如皇家花园、皇家卫队。", "primary_collocate": null, "pronunciation": "huáng jiā", "ipa": "xwɑŋ˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "我们在皇家花园里走了一圈。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一座皇家宫殿，游客很多。", "target_word": "皇家", "complexity_tier": "T3", "furigana": "zhè shì yí zuò huáng jiā gōng diàn, yóu kè hěn duō", "sentence_source": "generated"}, {"text": "皇家图书馆里有很多老书。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在皇家医院工作了二十年。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇家乐团今晚在城里演出。", "target_word": "皇家", "complexity_tier": "T3", "furigana": "huáng jiā yuè tuán jīn wǎn zài chéng lǐ yǎn chū", "sentence_source": "generated"}, {"text": "皇家卫队每天早上站在门口。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路只供皇家车队使用，以前平民不能走。", "target_word": "皇家", "complexity_tier": "T3", "furigana": "zhè tiáo lù zhǐ gōng huáng jiā chē duì shǐ yòng, yǐ qián píng mín bù néng zǒu", "sentence_source": "generated"}, {"text": "皇家酒店的房间又大又漂亮。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去皇家歌剧院听音乐会。", "target_word": "皇家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是一座皇家园林，已经有两百年了。", "target_word": "皇家", "complexity_tier": "T3", "furigana": "nà shì yí zuò huáng jiā yuán lín, yǐ jīng yǒu liǎng bǎi nián le", "sentence_source": "generated"}], "morphological_forms": [{"form": "皇家花园", "label": "复合"}, {"form": "皇家学院", "label": "复合"}], "register": "中性", "sense_fingerprint": "属于帝王家族的，如皇家花园、皇家卫队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇家", "is_correct": true, "explanation": "语义：“皇家花园”指帝王家族的花园，与“走了一圈”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以走进去的花园，“冰箱花园”说不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，没有可以走进去的花园，“钢笔花园”说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车花园”不是常见说法，而且汽车不适合用来“走一圈”。"}], "explanations": {"皇家": "语义：“皇家花园”指帝王家族的花园，与“走了一圈”相合。", "冰箱": "语义：冰箱是家电，不是可以走进去的花园，“冰箱花园”说不通。", "钢笔": "语义：钢笔是书写工具，没有可以走进去的花园，“钢笔花园”说不通。", "汽车": "搭配：“汽车花园”不是常见说法，而且汽车不适合用来“走一圈”。"}, "sentence_index": 0, "correct_answer": "皇家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "皇家，请您坐下，我们都在等您。", "explanation": "这里应该用〈陛下〉。“皇家”指家族，不能直接用来称呼某一位君主。"}, {"text": "我每天骑车经过皇家，路边有很多树。", "explanation": "这里应该用〈王宫〉。“皇家”只用在名词前表示“属于帝王家族的”，不能单独指地点。"}, {"text": "我们学校来了一位皇家，大家都很高兴。", "explanation": "这里应该用〈皇室成员〉。“皇家”在此义项中只修饰名词，不能单独指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇家", "is_correct": true, "explanation": "语义：“皇家”指帝王家族，与“只供……使用，以前平民不能走”相合。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“车队”指一队车辆，不说“椅子车队”。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“使用”一般用于人或物品，不说“花朵使用道路”。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不能使用道路，句中“平民不能走”也无法对应。"}], "explanations": {"皇家": "语义：“皇家”指帝王家族，与“只供……使用，以前平民不能走”相合。", "椅子": "搭配：“车队”指一队车辆，不说“椅子车队”。", "花朵": "搭配：“使用”一般用于人或物品，不说“花朵使用道路”。", "地震": "语义：地震是自然灾害，不能使用道路，句中“平民不能走”也无法对应。"}, "sentence_index": 6, "correct_answer": "皇家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的邻居是皇家，他每天都很忙。", "explanation": "这里应该用〈王子〉。“皇家”指整个家族，不能直接充当“是”的表语来指称一个人；指个人应说“王子”。"}, {"text": "那是一座皇家，已经有两百年了。", "explanation": "这里应该用〈王府〉或〈园林〉。“皇家”指家族，不指建筑，不能单独作“一座”的中心词。"}, {"text": "我家门口的皇家已经有两百年了。", "explanation": "这里应该用〈园林〉。“皇家”指帝王家族，不能用来称呼建筑或地点；修饰园林时要说“皇家园林”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座很皇家花园里有很多老树。", "corrected_sentence": "这座皇家花园里有很多老树。", "error_description": "错误：“皇家”前加了“很”。“皇家”作定语修饰“花园”，不能受程度副词修饰；应说“这座皇家花园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很皇家图书馆的书很老，已经有上百年了。", "corrected_sentence": "皇家图书馆的书很老，已经有上百年了。", "error_description": "错误：“皇家”前多加了“很”。“皇家”作定语修饰名词，不能直接受程度副词“很”修饰；应说“皇家图书馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护指使人免受伤害，与“侵害”意思相反，是反义词。"}, {"text": "观看", "is_correct": false, "explanation": "观看指用眼睛看，与“侵害”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加指加入某项活动，与“侵害”没有反义关系。"}, {"text": "同意", "is_correct": false, "explanation": "同意指赞成或接受，与“侵害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确。保护指使人免受伤害，与“侵害”意思相反，是反义词。", "观看": "观看指用眼睛看，与“侵害”没有反义关系。", "参加": "参加指加入某项活动，与“侵害”没有反义关系。", "同意": "同意指赞成或接受，与“侵害”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护指使人免受伤害，与“侵害”意思相反，是反义词。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使损坏的东西恢复原样，与“侵害”没有反义关系。"}, {"text": "计划", "is_correct": false, "explanation": "计划指事先安排，与“侵害”没有反义关系。"}, {"text": "协商", "is_correct": false, "explanation": "协商指共同商量，与“侵害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确。保护指使人免受伤害，与“侵害”意思相反，是反义词。", "修理": "修理指使损坏的东西恢复原样，与“侵害”没有反义关系。", "计划": "计划指事先安排，与“侵害”没有反义关系。", "协商": "协商指共同商量，与“侵害”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "侵害是做坏事，让别人受伤或吃亏。", "primary_collocate": null, "pronunciation": "qīn hài", "ipa": "tɕʰin˥ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "有些人专门侵害弱小的人。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能侵害别人，也要保护自己。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常侵害邻居家的孩子，大家都不喜欢他。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些坏人侵害过很多儿童。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉孩子，不能侵害别人。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人侵害了一个小女孩，被警察抓走了。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了赚钱，侵害了很多人。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种坏事会侵害普通人的身体健康。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意推倒路人，侵害了别人的人身安全。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了侵害老人的坏人。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵害了", "label": "体标"}, {"form": "侵害过", "label": "体标"}], "register": "书面", "sense_fingerprint": "做坏事让别人受伤或吃亏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdadcb77-e6c4-4c9d-9376-79a977628fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵害", "is_correct": true, "explanation": "正确。“有些人专门侵害弱小的人”指做坏事使弱小者受伤或吃亏，与语境相合。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”指交换意见，与“专门……弱小的人”的加害义不符。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”的对象是建筑或设施，不能用于弱小的人。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”针对书刊或作品，不用于人。"}], "explanations": {"侵害": "正确。“有些人专门侵害弱小的人”指做坏事使弱小者受伤或吃亏，与语境相合。", "讨论": "语义：“讨论”指交换意见，与“专门……弱小的人”的加害义不符。", "修建": "语义：“修建”的对象是建筑或设施，不能用于弱小的人。", "出版": "搭配：“出版”针对书刊或作品，不用于人。"}, "sentence_index": 0, "correct_answer": "侵害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话侵害了我的感情。", "explanation": "这里应该用〈伤害〉。侵害指做坏事让人受伤或吃亏；说感情受损要用伤害。"}, {"text": "这件事侵害了班级的和谐。", "explanation": "这里应该用〈破坏〉。和谐要用破坏，不说“侵害和谐”。"}, {"text": "这场灾难侵害了他们的希望。", "explanation": "这里应该用〈摧毁〉。希望要用摧毁，侵害不这样搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵害", "is_correct": true, "explanation": "正确。“他为了赚钱，侵害了很多人”指他为赚钱做坏事使人吃亏，与语境相合。"}, {"text": "捐", "is_correct": false, "explanation": "搭配：“捐”的对象是钱物，不能说“捐人”。"}, {"text": "宽慰", "is_correct": false, "explanation": "语义：“宽慰”是安慰，与“为了赚钱”的动机不符。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是建筑或设施，不能说“修建了很多人”。"}], "explanations": {"侵害": "正确。“他为了赚钱，侵害了很多人”指他为赚钱做坏事使人吃亏，与语境相合。", "捐": "搭配：“捐”的对象是钱物，不能说“捐人”。", "宽慰": "语义：“宽慰”是安慰，与“为了赚钱”的动机不符。", "修建": "搭配：“修建”的对象是建筑或设施，不能说“修建了很多人”。"}, "sentence_index": 6, "correct_answer": "侵害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种天气侵害了我们的睡眠。", "explanation": "这里应该用〈影响〉。侵害指做坏事使人受伤或吃亏；睡眠要用影响，不说“侵害睡眠”。"}, {"text": "这种批评侵害了大家的积极性。", "explanation": "这里应该用〈打击〉。积极性是精神状态，要用打击；侵害不这样搭配。"}, {"text": "这种制度侵害了年轻人的创造力。", "explanation": "这里应该用〈扼杀〉。创造力要用扼杀，侵害不这样搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几个孩子被他过侵害了。", "corrected_sentence": "几个孩子被他侵害了。", "error_description": "多余的“过”：“过”不能放在动词前，应去掉，说“被他侵害了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们被他侵害了过。", "corrected_sentence": "孩子们被他侵害过。", "error_description": "体标重复：“侵害”后不能同时用“了”和“过”，应只用“过”，说“孩子们被他侵害过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护指维护他人的权益，与“侵害”意思相反，是反义词。"}, {"text": "观看", "is_correct": false, "explanation": "观看指用眼睛看，与“侵害”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加指加入某项活动，与“侵害”没有反义关系。"}, {"text": "同意", "is_correct": false, "explanation": "同意指赞成或接受，与“侵害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确。保护指维护他人的权益，与“侵害”意思相反，是反义词。", "观看": "观看指用眼睛看，与“侵害”没有反义关系。", "参加": "参加指加入某项活动，与“侵害”没有反义关系。", "同意": "同意指赞成或接受，与“侵害”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护指维护他人的权益，与“侵害”意思相反，是反义词。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使损坏的东西恢复原样，与“侵害”没有反义关系。"}, {"text": "计划", "is_correct": false, "explanation": "计划指事先安排，与“侵害”没有反义关系。"}, {"text": "协商", "is_correct": false, "explanation": "协商指共同商量，与“侵害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确。保护指维护他人的权益，与“侵害”意思相反，是反义词。", "修理": "修理指使损坏的东西恢复原样，与“侵害”没有反义关系。", "计划": "计划指事先安排，与“侵害”没有反义关系。", "协商": "协商指共同商量，与“侵害”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "非法侵入并损害他人的权益或利益。", "primary_collocate": null, "pronunciation": "qīn hài", "ipa": "tɕʰin˥ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司侵害了顾客的权益。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许任何人侵害他人的权利。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站公开她的照片，侵害了她的隐私。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章侵害了他的名誉。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂侵害工人的利益，法院罚了它的钱。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有同意就用别人的画，这是侵害版权。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不给加班费，侵害了员工的权益。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法侵害了消费者的权利。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人侵害你的权利，你可以找律师。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院认为他的行为侵害了公司的利益。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵害了", "label": "体标"}, {"form": "侵害过", "label": "体标"}], "register": "书面", "sense_fingerprint": "非法损害他人的权利或利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdadcb77-e6c4-4c9d-9376-79a977628fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵害", "is_correct": true, "explanation": "正确。“侵害顾客的权益”指非法损害他人的权益，与语境相合。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是人或作品，不能用于“权益”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：公司不能“享受”顾客的权益，与语境不符。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是事物或作品，不能用于“权益”。"}], "explanations": {"侵害": "正确。“侵害顾客的权益”指非法损害他人的权益，与语境相合。", "赞美": "搭配：“赞美”的对象是人或作品，不能用于“权益”。", "享受": "语义：公司不能“享受”顾客的权益，与语境不符。", "欣赏": "搭配：“欣赏”的对象是事物或作品，不能用于“权益”。"}, "sentence_index": 0, "correct_answer": "侵害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友侵害了我的感情。", "explanation": "这里应该用〈伤害〉。侵害多指对权益、利益的侵犯；感情要用伤害。"}, {"text": "这件小事侵害了我们的友谊。", "explanation": "这里应该用〈破坏〉。侵害针对他人的权益或利益；友谊要用破坏。"}, {"text": "这阵噪音侵害了我的心情。", "explanation": "这里应该用〈影响〉。侵害针对他人的权益或利益；心情要用影响，不说“侵害心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵害", "is_correct": true, "explanation": "正确。“老板不给加班费，侵害了员工的权益”指老板非法损害员工的权益，与语境相合。"}, {"text": "珍惜", "is_correct": false, "explanation": "语义：不给加班费的老板不会“珍惜”员工的权益，与语境矛盾。"}, {"text": "捍卫", "is_correct": false, "explanation": "语义：“捍卫”是保卫，与不给加班费的做法矛盾。"}, {"text": "资助", "is_correct": false, "explanation": "搭配：“资助”针对人或项目的经济支持，不用来说权益。"}], "explanations": {"侵害": "正确。“老板不给加班费，侵害了员工的权益”指老板非法损害员工的权益，与语境相合。", "珍惜": "语义：不给加班费的老板不会“珍惜”员工的权益，与语境矛盾。", "捍卫": "语义：“捍卫”是保卫，与不给加班费的做法矛盾。", "资助": "搭配：“资助”针对人或项目的经济支持，不用来说权益。"}, "sentence_index": 6, "correct_answer": "侵害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些车辆侵害了交通。", "explanation": "这里应该用〈妨碍〉。侵害针对他人的权益；交通要用妨碍。"}, {"text": "这次失败侵害了他的信心。", "explanation": "这里应该用〈打击〉。侵害多指对权益或利益的侵犯；信心要用打击。"}, {"text": "这场大雨侵害了我们的旅行计划。", "explanation": "这里应该用〈打乱〉。侵害指非法损害权益；计划要用打乱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商场侵害了过顾客的权益。", "corrected_sentence": "这家商场侵害过顾客的权益。", "error_description": "体标重复：“侵害”后只用“过”，不能再加“了”，应说“侵害过顾客的权益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消费者的利益被这些商家过侵害了。", "corrected_sentence": "消费者的利益被这些商家侵害了。", "error_description": "多余的“过”：“过”不能放在动词前，应去掉，说“被这些商家侵害了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
