INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼前是现在这个时候，指当前、目前。", "primary_collocate": null, "pronunciation": "yǎn qián", "ipa": "jɛn˨˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "眼前最重要的是把身体养好。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼前的困难很大，但我们不怕。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只想着眼前的快乐。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先解决眼前的问题，以后再说。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼前的情况还不清楚，我们先等等消息。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼前的生活比以前好多了。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼前的任务很重，大家都很忙。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼前的工作很多，我们先别出去玩。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼前的钱不多，我们先别买车。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只想眼前，要看得远一点。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "眼前：现在这个时候，当前、目前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3db2a8-898c-4672-8b0b-0fbffde2e471') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼前", "is_correct": true, "explanation": "「眼前」指现在这个时候，作主语表示当前最要紧的事，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：「手机」是物品，与“把身体养好”无关，句意不通。"}, {"text": "历史", "is_correct": false, "explanation": "语义：「历史」指过去的事实，不表示当前，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」是钱数，与“把身体养好”无关，句意不通。"}], "explanations": {"眼前": "「眼前」指现在这个时候，作主语表示当前最要紧的事，符合句意。", "手机": "语义：「手机」是物品，与“把身体养好”无关，句意不通。", "历史": "语义：「历史」指过去的事实，不表示当前，句意不通。", "价格": "语义：「价格」是钱数，与“把身体养好”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "眼前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的眼前一直不太好，要常去看医生。", "explanation": "这里说的是视力，但眼前只指当前，不指视力本身。"}, {"text": "他闭上了眼前，不想再看这个世界。", "explanation": "这里说的是眼睛，但闭上的是眼睛，眼前不指眼睛本身，不能作“闭”的对象。"}, {"text": "他眼前去过北京。", "explanation": "这里应该用〈以前〉。眼前指现在，不能用来说过去的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼前", "is_correct": true, "explanation": "「眼前」指现在这个时候，作定语修饰“任务”，符合句意。"}, {"text": "收入", "is_correct": false, "explanation": "语义：「收入」指钱财，不表示时间，“收入的任务很重”不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：「名字」不表示时间，“名字的任务很重”不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」是数字概念，不表示时间，“年龄的任务很重”不通。"}], "explanations": {"眼前": "「眼前」指现在这个时候，作定语修饰“任务”，符合句意。", "收入": "语义：「收入」指钱财，不表示时间，“收入的任务很重”不通。", "名字": "语义：「名字」不表示时间，“名字的任务很重”不通。", "年龄": "语义：「年龄」是数字概念，不表示时间，“年龄的任务很重”不通。"}, "sentence_index": 6, "correct_answer": "眼前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼前很温柔，大家都喜欢他。", "explanation": "这里说的是眼神，但眼前不表示眼神或目光，只指当前。"}, {"text": "我们上个月眼前见过面。", "explanation": "这里应删去〈眼前〉，改为「上个月见过面」。眼前指当前，不能指“上个月”这段过去的时间。"}, {"text": "他揉了揉眼前。", "explanation": "这里说的是揉眼睛，但眼前不指眼睛，揉的是眼睛，不是眼前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "眼前地问题很大，我们要解决。", "corrected_sentence": "眼前的问题很大，我们要解决。", "error_description": "修饰名词「问题」要用「的」，「地」用于动词或形容词前，不能用于名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事眼前的不急，可以慢慢来。", "corrected_sentence": "这件事眼前不急，可以慢慢来。", "error_description": "「眼前」作状语修饰“不急”时，后面不加「的」，应说「眼前不急」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
