INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93039, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信息管理是把知道的消息收好，要用时能找到。", "primary_collocate": null, "pronunciation": "xìn xī guǎn lǐ", "ipa": "ɕin⁵¹ ɕi⁵⁵ kwan²¹⁴ li²¹⁴", "syllable_count": 4, "sentences": [{"text": "公司请了专家教大家做信息管理。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的信息管理能让我们很快找到资料。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的电脑里文件很乱，需要学一学信息管理。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息管理做得好，找东西就不会花很多时间。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门信息管理课教我们怎么整理资料。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的信息管理很好，要什么文件都找得到。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办公室每周都做一次信息管理。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有信息管理，旧文件很容易丢。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用手机软件做信息管理。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，信息管理从分类开始。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信息管理系统", "label": "复合词"}], "register": "中性", "sense_fingerprint": "日常说法：把消息和资料收好、整理好，需要时能很快找到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息管理", "is_correct": true, "explanation": "正确：“做信息管理”是常见搭配，指整理和查找资料的工作。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“做天气”不成立，天气不是人能做的事情。"}, {"text": "梦", "is_correct": false, "explanation": "搭配：“做梦”不能被“教”，“教大家做梦”不成立。"}, {"text": "鬼脸", "is_correct": false, "explanation": "语义：“做鬼脸”是面部动作，不是专家可以教给员工的工作内容。"}], "explanations": {"信息管理": "正确：“做信息管理”是常见搭配，指整理和查找资料的工作。", "天气": "搭配：“做天气”不成立，天气不是人能做的事情。", "梦": "搭配：“做梦”不能被“教”，“教大家做梦”不成立。", "鬼脸": "语义：“做鬼脸”是面部动作，不是专家可以教给员工的工作内容。"}, "sentence_index": 0, "correct_answer": "信息管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气冷了，我出门前穿上了一件信息管理。", "explanation": "这里应该用〈外套〉。信息管理是整理资料的工作，不是衣服；能穿的是〈外套〉。"}, {"text": "他的电脑坏了，他打电话找信息管理来修理。", "explanation": "这里应该用〈技术支持〉。信息管理是整理和查找资料的工作，不负责修理设备。"}, {"text": "他的早饭是信息管理和一杯牛奶。", "explanation": "这里应该用〈面包〉。信息管理是整理资料的工作，不是食物；早饭应吃〈面包〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息管理", "is_correct": true, "explanation": "正确：“做一次信息管理”指定期整理归档文件，符合办公室的工作。"}, {"text": "面膜", "is_correct": false, "explanation": "语义：面膜是美容用品，学校办公室不做这类事。"}, {"text": "美甲", "is_correct": false, "explanation": "语义：美甲是美容服务，与办公室的工作无关。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：发型属于外形，不是办公室定期要做的工作。"}], "explanations": {"信息管理": "正确：“做一次信息管理”指定期整理归档文件，符合办公室的工作。", "面膜": "语义：面膜是美容用品，学校办公室不做这类事。", "美甲": "语义：美甲是美容服务，与办公室的工作无关。", "发型": "体貌：发型属于外形，不是办公室定期要做的工作。"}, "sentence_index": 6, "correct_answer": "信息管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学了一台信息管理，主要是学怎么整理资料。", "explanation": "这里应该用〈门〉。作为课程，信息管理用量词“门”；“台”用于机器、电器等。"}, {"text": "他完成了一块信息管理，老板很满意。", "explanation": "这里应该用〈项〉。信息管理作为工作任务，量词用“项”；“块”用于块状、片状的东西。"}, {"text": "公司设计了一根信息管理，效果很好。", "explanation": "这里应该用〈套〉。信息管理指一整套方法或制度，量词用“套”；“根”用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要把信息管理。", "corrected_sentence": "我们需要把信息管理做好。", "error_description": "“把”字句缺少动词：只说“把信息管理”不完整，应为“把信息管理做好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的信息管理做很细致。", "corrected_sentence": "他的信息管理做得很细致。", "error_description": "漏了“得”：补语前要用“得”连接，应为“做得很细致”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
