INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对信息的收集、存储、处理和利用进行组织与控制的活动。", "primary_collocate": null, "pronunciation": "xìn xī guǎn lǐ", "ipa": "ɕin⁵¹ ɕi⁵⁵ kwan²¹⁴ li²¹⁴", "syllable_count": 4, "sentences": [{"text": "信息管理包括收集、存储、处理和利用。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院正在加强患者资料的信息管理。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习信息管理专业。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业的信息管理水平直接影响工作效率。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息管理需要对数据进行组织和控制。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的信息管理已经全部数字化了。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司设立了专门的部门负责信息管理。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做好信息管理，可以降低企业的成本。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府部门要重视信息管理的安全问题。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息管理离不开合适的软件和制度。", "target_word": "信息管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信息管理系统", "label": "复合词"}], "register": "书面", "sense_fingerprint": "术语：对信息的收集、存储、处理、利用进行组织和控制的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息管理", "is_correct": true, "explanation": "正确：作主语，指对信息的收集、存储、处理和利用进行组织与控制的活动。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不包括收集、存储和利用这些活动。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指外形，与收集和存储信息无关。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是菜谱，不指收集、存储这类活动。"}], "explanations": {"信息管理": "正确：作主语，指对信息的收集、存储、处理和利用进行组织与控制的活动。", "天气": "语义：天气不包括收集、存储和利用这些活动。", "身材": "体貌：身材指外形，与收集和存储信息无关。", "食谱": "语义：食谱是菜谱，不指收集、存储这类活动。"}, "sentence_index": 0, "correct_answer": "信息管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很注重信息管理，每天都穿名牌。", "explanation": "这里应该用〈形象管理〉。信息管理指对资料的收集、存储和利用；注重穿着打扮要用〈形象管理〉。"}, {"text": "电脑出了问题，可以找信息管理来修理。", "explanation": "这里应该用〈技术支持〉。信息管理是组织和控制信息的工作，不负责修理设备。"}, {"text": "这个学期我们学了信息管理，学会了怎么安排作息。", "explanation": "这里应该用〈时间管理〉。信息管理指对信息的收集、存储和利用；安排作息属于〈时间管理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息管理", "is_correct": true, "explanation": "正确：“负责信息管理”指负责管理信息的工作，是常见说法。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：部门不负责宇宙，句意荒谬。"}, {"text": "梦想", "is_correct": false, "explanation": "搭配：“负责”一般搭配工作、事务，不搭配“梦想”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“负责体重”不是常见说法，与部门的职能不符。"}], "explanations": {"信息管理": "正确：“负责信息管理”指负责管理信息的工作，是常见说法。", "宇宙": "语义：部门不负责宇宙，句意荒谬。", "梦想": "搭配：“负责”一般搭配工作、事务，不搭配“梦想”。", "体重": "搭配：“负责体重”不是常见说法，与部门的职能不符。"}, "sentence_index": 6, "correct_answer": "信息管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司引进了一只信息管理，效果很好。", "explanation": "这里应该用〈套〉。信息管理指一整套方法或制度，量词用“套”；“只”用于动物或成对物品中的一个。"}, {"text": "他们设计了一张信息管理，计划很清楚。", "explanation": "这里应该用〈项〉。信息管理作为工作任务，量词用“项”；“张”用于平面的东西。"}, {"text": "他完成了一辆信息管理，老板很满意。", "explanation": "这里应该用〈项〉。“辆”只用于车辆，不能修饰工作任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府正在把信息管理。", "corrected_sentence": "政府正在加强信息管理。", "error_description": "“把”字句缺少动词：只说“把信息管理”不完整，应改为“加强信息管理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的信息管理做很规范。", "corrected_sentence": "这家公司的信息管理做得很规范。", "error_description": "漏了“得”：补语前要用“得”连接，应为“做得很规范”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
