INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93041, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "祝是说好话，希望你好。", "primary_collocate": null, "pronunciation": "zhù", "ipa": "ʈʂu˥˩", "syllable_count": 1, "sentences": [{"text": "我给朋友发短信，祝他生日快乐。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着祝我考试顺利。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走的时候，大家都祝他一路平安。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想祝奶奶身体健康。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话里祝我新年快乐。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一起祝老师节日快乐。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经祝过她生日快乐了。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起杯子，祝大家身体健康。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去看他的时候，替我祝他早日好起来。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都来祝我们新婚幸福。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "祝愿", "label": "复合词"}, {"form": "祝福", "label": "复合词"}, {"form": "祝过", "label": "体标"}], "register": "中性", "sense_fingerprint": "祝：对某人说吉祥话，盼他过得好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93041, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "祝", "is_correct": true, "explanation": "正确：祝 zhù（第四声），表示说美好的愿望。"}, {"text": "煮", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是煮（饭）。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhù（第四声）声调不同，意思是猪。"}, {"text": "处", "is_correct": false, "explanation": "chù（第四声）与 zhù（第四声）声母不同（ch 与 zh），意思是地方、处所。"}, {"text": "这", "is_correct": false, "explanation": "zhè（第四声）与 zhù（第四声）韵母不同（e 与 u），意思是这个。"}], "explanations": {"祝": "正确：祝 zhù（第四声），表示说美好的愿望。", "煮": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是煮（饭）。", "竹": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。", "猪": "zhū（第一声）与 zhù（第四声）声调不同，意思是猪。", "处": "chù（第四声）与 zhù（第四声）声母不同（ch 与 zh），意思是地方、处所。", "这": "zhè（第四声）与 zhù（第四声）韵母不同（e 与 u），意思是这个。"}, "sentence_index": null, "correct_answer": "祝"}, "level_3": {"options": [{"text": "祝", "is_correct": true, "explanation": "正确：“祝他生日快乐”是对朋友说的祝愿。"}, {"text": "夸", "is_correct": false, "explanation": "语义：「夸」表示称赞，句子要表达的是祝愿。"}, {"text": "催", "is_correct": false, "explanation": "语义：「催」表示催促，不能用来表达生日的祝福。"}, {"text": "陪", "is_correct": false, "explanation": "搭配：「陪」要接陪伴的对象，不能与“生日快乐”搭配。"}], "explanations": {"祝": "正确：“祝他生日快乐”是对朋友说的祝愿。", "夸": "语义：「夸」表示称赞，句子要表达的是祝愿。", "催": "语义：「催」表示催促，不能用来表达生日的祝福。", "陪": "搭配：「陪」要接陪伴的对象，不能与“生日快乐”搭配。"}, "sentence_index": 0, "correct_answer": "祝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家祝他的毕业。", "explanation": "这里应该用〈庆祝〉。祝表示说祝愿的话，不能用来指一件喜事；应说“大家庆祝他的毕业”。"}, {"text": "我祝你的礼物。", "explanation": "这里应该用〈感谢〉。祝不能用来回应别人的礼物；表示谢意应说“我感谢你的礼物”。"}, {"text": "我祝你明天去哪里。", "explanation": "这里应该用〈问〉。祝不能用来询问对方的安排；应说“我问你明天去哪里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93041, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "祝", "is_correct": true, "explanation": "正确：祝 zhù（第四声），表示说美好的愿望。"}, {"text": "主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是主人。"}, {"text": "烛", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是蜡烛。"}, {"text": "珠", "is_correct": false, "explanation": "zhū（第一声）与 zhù（第四声）声调不同，意思是珠子。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 zhù（第四声）声母不同（sh 与 zh），意思是树。"}, {"text": "数", "is_correct": false, "explanation": "shù（第四声）与 zhù（第四声）声母不同（sh 与 zh），意思是数目。"}], "explanations": {"祝": "正确：祝 zhù（第四声），表示说美好的愿望。", "主": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是主人。", "烛": "zhú（第二声）与 zhù（第四声）声调不同，意思是蜡烛。", "珠": "zhū（第一声）与 zhù（第四声）声调不同，意思是珠子。", "树": "shù（第四声）与 zhù（第四声）声母不同（sh 与 zh），意思是树。", "数": "shù（第四声）与 zhù（第四声）声母不同（sh 与 zh），意思是数目。"}, "sentence_index": null, "correct_answer": "祝"}, "level_3": {"options": [{"text": "祝", "is_correct": true, "explanation": "正确：“我已经祝过她生日快乐了”中，“祝过”是说过的祝愿。"}, {"text": "问", "is_correct": false, "explanation": "搭配：「问」后面不接“生日快乐”，问的对象是问题或近况。"}, {"text": "谢", "is_correct": false, "explanation": "语义：「谢」表示感谢，句子说的是祝愿，不是感谢。"}, {"text": "赞", "is_correct": false, "explanation": "语义：「赞」表示称赞，不能用来表示生日的祝福。"}], "explanations": {"祝": "正确：“我已经祝过她生日快乐了”中，“祝过”是说过的祝愿。", "问": "搭配：「问」后面不接“生日快乐”，问的对象是问题或近况。", "谢": "语义：「谢」表示感谢，句子说的是祝愿，不是感谢。", "赞": "语义：「赞」表示称赞，不能用来表示生日的祝福。"}, "sentence_index": 6, "correct_answer": "祝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我祝他一个秘密。", "explanation": "这里应该用〈告诉〉。祝不能带“秘密”这样的信息作宾语；传达信息应说“我告诉他一个秘密”。"}, {"text": "我祝了他的建议。", "explanation": "这里应该用〈接受〉。祝不能用来回应建议；采纳建议应说“我接受了他的建议”。"}, {"text": "他祝了我的计划。", "explanation": "这里应该用〈同意〉。祝不能用来表示对计划的态度；应说“他同意了我的计划”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我祝了你春节快乐。", "corrected_sentence": "我祝你春节快乐。", "error_description": "错误在“了”：“祝”在这里表示当下说出的祝愿，句中“了”多余，应直接说“我祝你春节快乐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我祝得你一切顺利。", "corrected_sentence": "我祝你一切顺利。", "error_description": "错误在“祝”后面加了补语标记“得”。“祝”不能这样带补语，应直接说「我祝你一切顺利」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
