INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93042, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示良好的愿望。", "primary_collocate": null, "pronunciation": "zhù", "ipa": "ʈʂu˥˩", "syllable_count": 1, "sentences": [{"text": "祝你生日快乐！", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝大家新年快乐，身体健康。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天你要考试，祝你好运！", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你一路平安，到了给我打电话。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你们永远幸福！", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你工作顺利，早日升职。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节到了，祝您全家幸福。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你早日好起来！", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝老师身体健康，工作愉快。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你旅途愉快，玩得开心。", "target_word": "祝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "祝愿", "label": "复合词"}, {"form": "祝福", "label": "复合词"}], "register": "中性", "sense_fingerprint": "祝：用于祝福语，表达美好愿望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93042, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "祝", "is_correct": true, "explanation": "正确：祝 zhù（第四声），表示说美好的愿望。"}, {"text": "煮", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是煮（饭）。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhù（第四声）声调不同，意思是猪。"}, {"text": "处", "is_correct": false, "explanation": "chù（第四声）与 zhù（第四声）声母不同（ch 与 zh），意思是地方、处所。"}, {"text": "这", "is_correct": false, "explanation": "zhè（第四声）与 zhù（第四声）韵母不同（e 与 u），意思是这个。"}], "explanations": {"祝": "正确：祝 zhù（第四声），表示说美好的愿望。", "煮": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是煮（饭）。", "竹": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。", "猪": "zhū（第一声）与 zhù（第四声）声调不同，意思是猪。", "处": "chù（第四声）与 zhù（第四声）声母不同（ch 与 zh），意思是地方、处所。", "这": "zhè（第四声）与 zhù（第四声）韵母不同（e 与 u），意思是这个。"}, "sentence_index": null, "correct_answer": "祝"}, "level_3": {"options": [{"text": "祝", "is_correct": true, "explanation": "正确：“祝你……”是说祝愿的固定说法，用于生日祝福。"}, {"text": "问", "is_correct": false, "explanation": "搭配：「问」后面接的是问题或近况，不能接“生日快乐”这样的祝愿内容。"}, {"text": "谢", "is_correct": false, "explanation": "语义：「谢」表示感谢，句子说的是祝愿，不是感谢。"}, {"text": "赞", "is_correct": false, "explanation": "语义：「赞」表示称赞，不能用来表示生日的祝福。"}], "explanations": {"祝": "正确：“祝你……”是说祝愿的固定说法，用于生日祝福。", "问": "搭配：「问」后面接的是问题或近况，不能接“生日快乐”这样的祝愿内容。", "谢": "语义：「谢」表示感谢，句子说的是祝愿，不是感谢。", "赞": "语义：「赞」表示称赞，不能用来表示生日的祝福。"}, "sentence_index": 0, "correct_answer": "祝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们祝她的生日。", "explanation": "这里应该用〈庆祝〉。祝是对人说美好的愿望，不能用来指一件活动；为生日举行的活动要说“庆祝她的生日”。"}, {"text": "我祝你帮我买杯水。", "explanation": "这里应该用〈希望〉。祝只用于美好的祝愿，不能用来提出请求或期待对方做事；应说“我希望你帮我买杯水”。"}, {"text": "我们祝老师的指导。", "explanation": "这里应该用〈感谢〉。祝是对人说祝愿，不能用于表示对别人帮助的谢意；应说“我们感谢老师的指导”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93042, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "祝", "is_correct": true, "explanation": "正确：祝 zhù（第四声），表示说美好的愿望。"}, {"text": "主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是主人。"}, {"text": "烛", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是蜡烛。"}, {"text": "珠", "is_correct": false, "explanation": "zhū（第一声）与 zhù（第四声）声调不同，意思是珠子。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 zhù（第四声）声母不同（sh 与 zh），意思是树。"}, {"text": "数", "is_correct": false, "explanation": "shù（第四声）与 zhù（第四声）声母不同（sh 与 zh），意思是数目。"}], "explanations": {"祝": "正确：祝 zhù（第四声），表示说美好的愿望。", "主": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是主人。", "烛": "zhú（第二声）与 zhù（第四声）声调不同，意思是蜡烛。", "珠": "zhū（第一声）与 zhù（第四声）声调不同，意思是珠子。", "树": "shù（第四声）与 zhù（第四声）声母不同（sh 与 zh），意思是树。", "数": "shù（第四声）与 zhù（第四声）声母不同（sh 与 zh），意思是数目。"}, "sentence_index": null, "correct_answer": "祝"}, "level_3": {"options": [{"text": "祝", "is_correct": true, "explanation": "正确：“祝您全家幸福”是春节时说的祝愿。"}, {"text": "陪", "is_correct": false, "explanation": "搭配：「陪」表示陪伴，不能与“全家幸福”这样的状态搭配。"}, {"text": "催", "is_correct": false, "explanation": "语义：「催」表示催促，不能用来表示对全家的祝愿。"}, {"text": "请", "is_correct": false, "explanation": "语义：「请」表示请求或邀请，句中说的是祝愿，不是请人做事。"}], "explanations": {"祝": "正确：“祝您全家幸福”是春节时说的祝愿。", "陪": "搭配：「陪」表示陪伴，不能与“全家幸福”这样的状态搭配。", "催": "语义：「催」表示催促，不能用来表示对全家的祝愿。", "请": "语义：「请」表示请求或邀请，句中说的是祝愿，不是请人做事。"}, "sentence_index": 6, "correct_answer": "祝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我祝你去了哪里。", "explanation": "这里应该用〈问〉。祝表示美好的愿望，不能用来询问对方的去向；应说“我问你去了哪里”。"}, {"text": "我祝你一件事。", "explanation": "这里应该用〈告诉〉。祝不能带一件具体的事作宾语，要传达事情时应说“我告诉你一件事”。"}, {"text": "我祝了她的问题。", "explanation": "这里应该用〈回答〉。祝用于说祝愿，不能用来处理问题；应说“我回答了她的问题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祝了你一路顺利。", "corrected_sentence": "祝你一路顺利。", "error_description": "错误在“祝”后面加了“了”。「祝」表示对未来的美好愿望，说的时候事情还没有发生，不能加“了”；应为「祝你一路顺利」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祝着你们天天开心。", "corrected_sentence": "祝你们天天开心。", "error_description": "错误在“祝”后面加了“着”。「着」表示动作的持续，而“祝”是一次性的祝愿，不能说“祝着”；应为「祝你们天天开心」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93043, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "做得到", "is_correct": true, "explanation": "“做得到”与“做不到”互为反义，表示有能力完成。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是休闲活动，与“做不到”的能力义没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "“洗澡”是日常行为，与“做不到”在此义项上没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”是技能活动，与“做不到”在此义项上没有反义关系。"}], "correct_answer": "做得到", "explanations": {"做得到": "“做得到”与“做不到”互为反义，表示有能力完成。", "散步": "“散步”是休闲活动，与“做不到”的能力义没有反义关系。", "洗澡": "“洗澡”是日常行为，与“做不到”在此义项上没有反义关系。", "唱歌": "“唱歌”是技能活动，与“做不到”在此义项上没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
