INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93043, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做不到是想做，可是不能做成。", "primary_collocate": null, "pronunciation": "zuò bú dào", "ipa": "tsuɔ˥˩ pu˧˥ tɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "我很想早起，可是总是做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说起来容易，真的做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他答应过每天跑步，但是做不到。", "target_word": "做不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想原谅他，可是怎么也做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你让我不生气，我做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想少吃一点，可是看到蛋糕就做不到了。", "target_word": "做不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道应该早睡，但是我做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想忘记他，可是我做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想让大家都满意，真的做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想戒烟，却总是做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做得到", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "有愿望想做，但实际无法做成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做不到", "is_correct": true, "explanation": "“做不到”表示有愿望却无法实现，与“很想早起，可是”的转折呼应。"}, {"text": "唱得好", "is_correct": false, "explanation": "语义：“唱得好”说的是唱歌的水平，与“很想早起”的愿望没有关系。"}, {"text": "做得快", "is_correct": false, "explanation": "搭配：“做得快”说的是动作速度，不能接在“很想早起，可是总是”之后表示愿望落空。"}, {"text": "说得对", "is_correct": false, "explanation": "语义：“说得对”指言论正确，与“总是”所表示的愿望落空语境不符。"}], "explanations": {"做不到": "“做不到”表示有愿望却无法实现，与“很想早起，可是”的转折呼应。", "唱得好": "语义：“唱得好”说的是唱歌的水平，与“很想早起”的愿望没有关系。", "做得快": "搭配：“做得快”说的是动作速度，不能接在“很想早起，可是总是”之后表示愿望落空。", "说得对": "语义：“说得对”指言论正确，与“总是”所表示的愿望落空语境不符。"}, "sentence_index": 0, "correct_answer": "做不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一点也不想去，所以做不到去。", "explanation": "这里应该用〈不去〉。做不到表示想做却没能做成，不能表示不愿意去。"}, {"text": "在教室里，我们做不到大声说话。", "explanation": "这里应该用〈不许〉。做不到表示想做却没能做成，不能用来表示禁止。"}, {"text": "我很想回家，可是我决定做不到。", "explanation": "这里应该用〈决定不做〉。做不到表示想做却没能做成，不能表示主动决定不做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做不到", "is_correct": true, "explanation": "“做不到”表示有愿望却无法实现，与“知道应该早睡，但是”的转折呼应。"}, {"text": "吃得饱", "is_correct": false, "explanation": "语义：“吃得饱”说的是吃饭的状态，与“知道应该早睡”的转折无关。"}, {"text": "跑得快", "is_correct": false, "explanation": "搭配：“跑得快”说的是动作速度，不能接在“知道应该早睡，但是我”之后。"}, {"text": "写得好", "is_correct": false, "explanation": "语义：“写得好”说的是写字的水平，与“应该早睡”的愿望和转折不衔接。"}], "explanations": {"做不到": "“做不到”表示有愿望却无法实现，与“知道应该早睡，但是”的转折呼应。", "吃得饱": "语义：“吃得饱”说的是吃饭的状态，与“知道应该早睡”的转折无关。", "跑得快": "搭配：“跑得快”说的是动作速度，不能接在“知道应该早睡，但是我”之后。", "写得好": "语义：“写得好”说的是写字的水平，与“应该早睡”的愿望和转折不衔接。"}, "sentence_index": 6, "correct_answer": "做不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题太简单了，我们谁都做不到。", "explanation": "这里应该用〈做得到〉。做不到表示想做却没能做成，与“太简单”相矛盾。"}, {"text": "妈妈不让我玩手机，所以我做不到玩。", "explanation": "这里应该用〈不能〉。做不到表示自己想做却做不成，被别人禁止要用不能。"}, {"text": "这场比赛我们赢了，因为我们做不到。", "explanation": "这里应该用〈做得到〉。做不到表示没能做成，与“赢了”的结果相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很想减肥，可是总是做不到过。", "corrected_sentence": "我很想减肥，可是总是做不到。", "error_description": "错误：“做不到过”。正确：“做不到”。“过”表示经历，不能加在可能补语“做不到”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直想改掉熬夜的习惯，可是总是很做不到。", "corrected_sentence": "我一直想改掉熬夜的习惯，可是总是做不到。", "error_description": "错误：“总是很做不到”。正确：“总是做不到”。“很”是程度副词，不能修饰动词或可能补语“做不到”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93044, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "做得到", "is_correct": true, "explanation": "“做得到”与“做不到”互为反义，表示能力或条件允许完成。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是运动动作，与“能否完成某事”之间没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是生活行为，与“做不到”的能力义没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”是技能活动，与“做不到”在此义项上没有反义关系。"}], "correct_answer": "做得到", "explanations": {"做得到": "“做得到”与“做不到”互为反义，表示能力或条件允许完成。", "跑步": "“跑步”是运动动作，与“能否完成某事”之间没有反义关系。", "睡觉": "“睡觉”是生活行为，与“做不到”的能力义没有反义关系。", "唱歌": "“唱歌”是技能活动，与“做不到”在此义项上没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93044, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "做得到", "is_correct": true, "explanation": "“做得到”与“做不到”互为反义，表示能力或条件允许完成。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”是日常行为，与“能否完成某事”之间没有反义关系。"}, {"text": "看书", "is_correct": false, "explanation": "“看书”是阅读活动，与“做不到”在此义项上没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”是书写活动，与“做不到”在此义项上没有反义关系。"}], "correct_answer": "做得到", "explanations": {"做得到": "“做得到”与“做不到”互为反义，表示能力或条件允许完成。", "吃饭": "“吃饭”是日常行为，与“能否完成某事”之间没有反义关系。", "看书": "“看书”是阅读活动，与“做不到”在此义项上没有反义关系。", "写字": "“写字”是书写活动，与“做不到”在此义项上没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有能力或条件完成；办不到。", "primary_collocate": null, "pronunciation": "zuò bú dào", "ipa": "tsuɔ˥˩ pu˧˥ tɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "这件事太难了，我一个人做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我现在没有钱，这件事我做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一天看完三本书，谁也做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "条件太差了，这个要求我们做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有老师帮忙，我做不到这么好。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人搬走这张大桌子，我做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三天做完这些，我们真的做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有电脑，这件事我做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个速度太快，普通人做不到。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师一个人做不到，需要大家帮忙。", "target_word": "做不到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做得到", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "因能力或条件不够而无法完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做不到", "is_correct": true, "explanation": "“做不到”表示能力或条件不够而无法完成，与“太难了”的语境一致。"}, {"text": "做得好", "is_correct": false, "explanation": "语义：“做得好”说事情办得好，与“这件事太难了”的前句冲突。"}, {"text": "跑得快", "is_correct": false, "explanation": "搭配：“跑得快”说的是动作速度，不能用来说这件事能否完成。"}, {"text": "吃饱", "is_correct": false, "explanation": "语义：“吃饱”与“这件事”的完成无关，句子语义不通。"}], "explanations": {"做不到": "“做不到”表示能力或条件不够而无法完成，与“太难了”的语境一致。", "做得好": "语义：“做得好”说事情办得好，与“这件事太难了”的前句冲突。", "跑得快": "搭配：“跑得快”说的是动作速度，不能用来说这件事能否完成。", "吃饱": "语义：“吃饱”与“这件事”的完成无关，句子语义不通。"}, "sentence_index": 0, "correct_answer": "做不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告我很快就做不到，很轻松。", "explanation": "这里应该用〈做完了〉。做不到表示无法完成，与“很快”“很轻松”表示的完成结果相矛盾。"}, {"text": "这个蛋糕很好吃，他一口就做不到了。", "explanation": "这里应该用〈吃完〉。做不到表示没能完成，不能用来说一口就吃完了。"}, {"text": "这道题很简单，我一分钟就做不到了。", "explanation": "这里应该用〈做完〉。做不到表示没有能力完成，与“很简单”“一分钟就……了”的完成结果相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做不到", "is_correct": true, "explanation": "“做不到”表示能力或条件不够而无法完成，与“三天做完这些”的难度一致。"}, {"text": "睡得香", "is_correct": false, "explanation": "语义：“睡得香”说的是睡眠状态，与“三天做完这些”的任务毫无关联。"}, {"text": "唱得好", "is_correct": false, "explanation": "搭配：“唱得好”说的是唱歌的水平，不能用来表示“三天做完这些”的结果。"}, {"text": "说得快", "is_correct": false, "explanation": "搭配：“说得快”说的是言语速度，不能与“做完这些”的能力判断搭配。"}], "explanations": {"做不到": "“做不到”表示能力或条件不够而无法完成，与“三天做完这些”的难度一致。", "睡得香": "语义：“睡得香”说的是睡眠状态，与“三天做完这些”的任务毫无关联。", "唱得好": "搭配：“唱得好”说的是唱歌的水平，不能用来表示“三天做完这些”的结果。", "说得快": "搭配：“说得快”说的是言语速度，不能与“做完这些”的能力判断搭配。"}, "sentence_index": 6, "correct_answer": "做不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道难题他很快就做不到，马上写完了。", "explanation": "这里应该用〈写完〉。做不到表示没能完成，与“马上写完了”的完成结果相矛盾。"}, {"text": "那些箱子我们一起做不到，却都已经搬完了。", "explanation": "这里应该用〈搬完〉。做不到表示没能完成，与“已经搬完了”相矛盾。"}, {"text": "这台电脑他修了一整天，结果修好了，做不到。", "explanation": "这里应该用〈修好〉。做不到表示没能完成，与“结果修好了”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么多的作业，我今天很做不到。", "corrected_sentence": "这么多的作业，我今天做不到。", "error_description": "错误：“我今天很做不到”。正确：“我今天做不到”。“很”是程度副词，不能修饰动词或可能补语“做不到”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项任务太重了，我们两个人把做不到。", "corrected_sentence": "这项任务太重了，我们两个人做不到。", "error_description": "错误：“我们两个人把做不到”。正确：“我们两个人做不到”。“把”字句要求“把”后带处置的宾语，“把”不能直接放在可能补语“做不到”之前，应删去“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
