INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93045, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "竞选是好几个人比一比，看谁能被大家选上。", "primary_collocate": null, "pronunciation": "jìng xuǎn", "ipa": "tɕiŋ˥˩ ɕɥæn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们班有三个人竞选班长。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李想竞选学生会主席。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去年竞选过班长，可是没选上。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好几个同学都来竞选组长。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不竞选班长呢？", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她竞选了体育委员，大家都支持她。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想当队长的人可以来竞选。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小张都竞选队长，最后小王赢了。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想试试，明年竞选学习委员。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人竞选同一个职位。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "竞选了", "label": "完成体"}, {"form": "竞选过", "label": "经历体"}, {"form": "竞选人", "label": "复合词"}, {"form": "競選", "label": "繁体"}], "register": "中性", "sense_fingerprint": "几个人比一比，争取被大家选上（班长、组长等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞选", "is_correct": true, "explanation": "正确：竞选指争取被选上，与“三个人”“班长”相符。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”带的是活动、比赛等宾语，不能说“举办班长”。"}, {"text": "打破", "is_correct": false, "explanation": "语义：“打破”的对象是纪录、规定，与“班长”这一职位不合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与选班长无关，句子读不通。"}], "explanations": {"竞选": "正确：竞选指争取被选上，与“三个人”“班长”相符。", "举办": "搭配：“举办”带的是活动、比赛等宾语，不能说“举办班长”。", "打破": "语义：“打破”的对象是纪录、规定，与“班长”这一职位不合。", "散步": "语义：“散步”与选班长无关，句子读不通。"}, "sentence_index": 0, "correct_answer": "竞选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班在运动会上参加了接力竞选。", "explanation": "这里应该用〈竞赛〉。竞选指为当选某个职位而争取选票，比赛名次要用竞赛。"}, {"text": "两家公司在市场上竞选。", "explanation": "这里应该用〈竞争〉。竞选只用于争取职位或选票，市场上的对手较量要用竞争。"}, {"text": "他去公司竞选工程师。", "explanation": "这里应该用〈应聘〉。竞选针对由选民选出的职位，公司招人要用应聘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞选", "is_correct": true, "explanation": "正确：竞选指争取被选上，与“想当队长的人”相符。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：“辞职”是离开现任职务，与“想当队长”的意愿相反。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”必须带活动、比赛等宾语，句末缺宾语。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”是放弃抵抗，与“想当队长”的语境不相容。"}], "explanations": {"竞选": "正确：竞选指争取被选上，与“想当队长的人”相符。", "辞职": "语义：“辞职”是离开现任职务，与“想当队长”的意愿相反。", "举办": "配价：“举办”必须带活动、比赛等宾语，句末缺宾语。", "投降": "语义：“投降”是放弃抵抗，与“想当队长”的语境不相容。"}, "sentence_index": 6, "correct_answer": "竞选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校每年竞选优秀学生。", "explanation": "这里应该用〈选拔〉。竞选是候选人争取选票，学校挑选优秀学生要用选拔。"}, {"text": "公司在网上竞选志愿者。", "explanation": "这里应该用〈招募〉。竞选是候选人争取选票，公司征集志愿者要用招募。"}, {"text": "两队在决赛中争相竞选冠军。", "explanation": "这里应该用〈争夺〉。竞选限于争取职务和选票，决赛中争冠要用争夺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他竞选过班长过。", "corrected_sentence": "他竞选过班长。", "error_description": "错误形式：“竞选过班长过”；正确形式：“竞选过班长”。“过”只能出现一次，紧跟动词“竞选”表示经历，宾语后多出的“过”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他竞选上了班长上了。", "corrected_sentence": "他竞选上了班长。", "error_description": "错误形式：“竞选上了班长上了”；正确形式：“竞选上了班长”。结果补语“上了”只能出现一次，紧跟动词“竞选”，宾语后多出的“上了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
