INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93046, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了当选某个职位而进行活动，争取选票。", "primary_collocate": null, "pronunciation": "jìng xuǎn", "ipa": "tɕiŋ˥˩ ɕɥæn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他决定明年竞选市长。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人第三次竞选总统了。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了竞选议员，每天走访居民。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在街上发传单，帮候选人竞选。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竞选市长的人要先介绍自己的想法。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他竞选过两次州长，都没成功。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了竞选，他到很多城市演讲。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了一年时间竞选国会议员。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边工作，一边竞选村长。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生准备竞选区长，到处争取选票。", "target_word": "竞选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "竞选了", "label": "完成体"}, {"form": "竞选过", "label": "经历体"}, {"form": "竞选人", "label": "复合词"}, {"form": "竞选活动", "label": "复合词"}, {"form": "競選", "label": "繁体"}], "register": "正式", "sense_fingerprint": "为当选市长、总统等职位而开展活动、争取选票", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞选", "is_correct": true, "explanation": "正确：竞选指为当选而争取选票，与“明年”“市长”相符。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”带活动、比赛等宾语，不能说“举办市长”。"}, {"text": "辞职", "is_correct": false, "explanation": "配价：“辞职”是不及物动词，不能带“市长”作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与当选市长无关，句子读不通。"}], "explanations": {"竞选": "正确：竞选指为当选而争取选票，与“明年”“市长”相符。", "举办": "搭配：“举办”带活动、比赛等宾语，不能说“举办市长”。", "辞职": "配价：“辞职”是不及物动词，不能带“市长”作宾语。", "散步": "语义：“散步”与当选市长无关，句子读不通。"}, "sentence_index": 0, "correct_answer": "竞选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家餐厅在街上竞选顾客。", "explanation": "这里应该用〈竞争〉。竞选只用于争取职位或选票，餐厅争抢顾客要用竞争。"}, {"text": "学校每年竞选出优秀学生。", "explanation": "这里应该用〈选拔〉。竞选是候选人争取选票，学校挑选学生要用选拔。"}, {"text": "他去公司竞选会计。", "explanation": "这里应该用〈应聘〉。竞选针对由选民选出的职位，求职录用要用应聘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞选", "is_correct": true, "explanation": "正确：竞选指为当选而争取选票，与“演讲”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“到很多城市演讲”矛盾，句子读不通。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”与演讲拉票的目的相反，句子读不通。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”须带活动、比赛等宾语，这里缺少宾语。"}], "explanations": {"竞选": "正确：竞选指为当选而争取选票，与“演讲”的语境相符。", "睡觉": "语义：“睡觉”与“到很多城市演讲”矛盾，句子读不通。", "投降": "语义：“投降”与演讲拉票的目的相反，句子读不通。", "举办": "配价：“举办”须带活动、比赛等宾语，这里缺少宾语。"}, "sentence_index": 6, "correct_answer": "竞选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动员们在赛场上竞选金牌。", "explanation": "这里应该用〈角逐〉。竞选用于争取职位和选票，赛场上争夺金牌要用角逐。"}, {"text": "工厂在网上竞选工人。", "explanation": "这里应该用〈招聘〉。竞选针对由选民选出的职位，工厂招收工人要用招聘。"}, {"text": "两队在决赛中竞选冠军。", "explanation": "这里应该用〈争夺〉。竞选限于争取职务和选票，决赛中争冠要用争夺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她竞选过市长过。", "corrected_sentence": "她竞选过市长。", "error_description": "错误形式：“竞选过市长过”；正确形式：“竞选过市长”。“过”只能出现一次，紧跟动词“竞选”表示经历，宾语后多出的“过”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王先生竞选上了区长上了。", "corrected_sentence": "王先生竞选上了区长。", "error_description": "错误形式：“竞选上了区长上了”；正确形式：“竞选上了区长”。结果补语“上了”只能出现一次，紧跟动词“竞选”，宾语后多出的“上了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
