INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93047, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做派是一个人做事和走路说话的样子。", "primary_collocate": null, "pronunciation": "zuò pài", "ipa": "tsuo˥˩ pʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她的做派很大方，走路说话都很自然。", "target_word": "做派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做派一看就是个读书人。", "target_word": "做派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥走路说话的做派，越来越像爸爸。", "target_word": "做派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩做派老成，不像七岁的孩子。", "target_word": "做派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生的做派很斯文，说话总是慢慢的。", "target_word": "做派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢她做事干净利落的做派。", "target_word": "做派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走路说话的做派，让人想起他的老师。", "target_word": "做派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同事做派很低调，从不大声说话。", "target_word": "做派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老太太的做派很讲究，吃饭走路都有规矩。", "target_word": "做派", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "他的做派变了，现在走路说话都很稳重。", "target_word": "做派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种做派", "label": "量词：种"}, {"form": "一副做派", "label": "量词：副"}], "register": "中性", "sense_fingerprint": "做派：一个人做事、走路、说话的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd75ca80b-1f26-4b15-81d3-10584f1de521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做派", "is_correct": true, "explanation": "正确答案。“她的做派很大方”指她做事说话的样子大方得体。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不能用“大方”来形容。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，与人的举止无关。"}, {"text": "发音", "is_correct": false, "explanation": "搭配：“发音”指读音，一般不用“大方”来形容。"}], "explanations": {"做派": "正确答案。“她的做派很大方”指她做事说话的样子大方得体。", "体重": "语义：“体重”指身体的重量，不能用“大方”来形容。", "面积": "语义：“面积”指平面的大小，与人的举止无关。", "发音": "搭配：“发音”指读音，一般不用“大方”来形容。"}, "sentence_index": 0, "correct_answer": "做派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的做派很好听。", "explanation": "这里应该用〈声音〉。“做派”指人做事和走路说话的样子，声音好听要用“声音”，不能用“做派”。"}, {"text": "这朵花有一种鲜艳的做派。", "explanation": "这里应该用〈颜色〉。“做派”指人做事和走路说话的样子，花的鲜艳程度要用“颜色”，不能用“做派”。"}, {"text": "这条路的做派很平坦。", "explanation": "这里应该用〈路况〉。“做派”指人做事和走路说话的样子，路面平坦与否要用“路况”，不能用“做派”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做派", "is_correct": true, "explanation": "正确答案。“他走路说话的做派”指他走路、说话时的样子。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与走路说话的样子无关。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指长短，不能用来形容走路说话。"}, {"text": "字", "is_correct": false, "explanation": "搭配：“字”指文字，不能用来描述走路说话的样子。"}], "explanations": {"做派": "正确答案。“他走路说话的做派”指他走路、说话时的样子。", "颜色": "语义：“颜色”指色彩，与走路说话的样子无关。", "长度": "语义：“长度”指长短，不能用来形容走路说话。", "字": "搭配：“字”指文字，不能用来描述走路说话的样子。"}, "sentence_index": 6, "correct_answer": "做派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的做派很鲜。", "explanation": "这里应该用〈味道〉。“做派”指人做事和走路说话的样子，汤的鲜美与否要用“味道”，不能用“做派”。"}, {"text": "这家餐馆的做派很清淡。", "explanation": "这里应该用〈口味〉。“做派”指人的行为举止，饭菜的咸淡要用“口味”。"}, {"text": "这块石头的做派很坚硬。", "explanation": "这里应该用〈质地〉。“做派”指人做事和走路说话的样子，石头的硬度要用“质地”，不能用“做派”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她大方得做派让人印象很深。", "corrected_sentence": "她大方的做派让人印象很深。", "error_description": "修饰名词“做派”的形容词要用“的”，不用“得”。“得”用于动词或形容词之后作补语，“大方得做派”不成立，应说“大方的做派”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种的做派我看多了。", "corrected_sentence": "这种做派我看多了。", "error_description": "“这种”是指示代词加量词，修饰名词时不加“的”。应说“这种做派”，不说“这种的做派”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
